void add_descriptor_batch_tensor_read_counter(bool resident, uint64_t bytes) {
    std::lock_guard<std::mutex> lock(
        g_descriptor_batch_tensor_read_counters_mutex
    );
    if (resident) {
        g_descriptor_batch_tensor_read_counters.resident_read_count +=
            UINT64_C(1);
        g_descriptor_batch_tensor_read_counters.resident_read_bytes += bytes;
    } else {
        g_descriptor_batch_tensor_read_counters.direct_read_count +=
            UINT64_C(1);
        g_descriptor_batch_tensor_read_counters.direct_read_bytes += bytes;
    }
}

struct ScopedDescriptorBatchTensorReadCounters {
    DescriptorBatchTensorReadCounters previous;

    ScopedDescriptorBatchTensorReadCounters() {
        std::lock_guard<std::mutex> lock(
            g_descriptor_batch_tensor_read_counters_mutex
        );
        previous = g_descriptor_batch_tensor_read_counters;
        g_descriptor_batch_tensor_read_counters =
            DescriptorBatchTensorReadCounters{};
    }

    void copy_to_result(
        qrt_qwen36_prefill_descriptor_batch_result_t *result
    ) const {
        if (result == nullptr) {
            return;
        }
        std::lock_guard<std::mutex> lock(
            g_descriptor_batch_tensor_read_counters_mutex
        );
        result->resident_tensor_read_count =
            g_descriptor_batch_tensor_read_counters.resident_read_count;
        result->resident_tensor_read_bytes =
            g_descriptor_batch_tensor_read_counters.resident_read_bytes;
        result->direct_tensor_read_count =
            g_descriptor_batch_tensor_read_counters.direct_read_count;
        result->direct_tensor_read_bytes =
            g_descriptor_batch_tensor_read_counters.direct_read_bytes;
    }

    ~ScopedDescriptorBatchTensorReadCounters() {
        std::lock_guard<std::mutex> lock(
            g_descriptor_batch_tensor_read_counters_mutex
        );
        g_descriptor_batch_tensor_read_counters.resident_read_count +=
            previous.resident_read_count;
        g_descriptor_batch_tensor_read_counters.resident_read_bytes +=
            previous.resident_read_bytes;
        g_descriptor_batch_tensor_read_counters.direct_read_count +=
            previous.direct_read_count;
        g_descriptor_batch_tensor_read_counters.direct_read_bytes +=
            previous.direct_read_bytes;
    }
};

