const Gb10PromptFixture *gb10_prompt_fixture_for_prefill_tokens(
    unsigned int prefill_tokens
) {
    if (prefill_tokens == kGb10ExactOkChatTokenCount) {
        return &gb10_exact_ok_prompt_fixture();
    }
    if (prefill_tokens == kGb10Q8192FirstTokenChatTokenCount) {
        if (raw_env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_GB10_LONG64_FIXTURE"
            ) ||
            raw_env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_SPECULATIVE64_GB10_FIXTURE"
            )) {
            return &gb10_q8192_long64_prompt_fixture();
        }
        return &gb10_q8192_first_token_prompt_fixture();
    }
    if (prefill_tokens == kGb10Q8208Long64ChatTokenCount &&
        raw_env_flag_enabled(
            "QRT_QWEN36_PREFIX_CACHE_PAIRED_FRESH_Q8208_PROBE"
        )) {
        return &gb10_q8208_long64_prompt_fixture();
    }
    if (prefill_tokens == kGb10Q16384Long64ChatTokenCount &&
        raw_env_flag_enabled("QRT_QWEN36_Q16384_COLD_PROBE")) {
        return &gb10_q16384_long64_prompt_fixture();
    }
    if (prefill_tokens == kGb10Q32768Long64ChatTokenCount &&
        raw_env_flag_enabled("QRT_QWEN36_Q32768_COLD_PROBE")) {
        return &gb10_q32768_long64_prompt_fixture();
    }
    if (prefill_tokens == kGb10Q65536Long512ChatTokenCount &&
        raw_env_flag_enabled("QRT_QWEN36_Q65536_COLD_PROBE")) {
        return &gb10_q65536_long512_prompt_fixture();
    }
    if (raw_env_flag_enabled("QRT_QWEN36_Q131072_COLD_PROBE")) {
        if (prefill_tokens == kGb10Q129536PrefixSeedChatTokenCount) {
            return &gb10_q129536_prefix_seed_prompt_fixture();
        }
        if (prefill_tokens == kGb10Q130560Long512ChatTokenCount) {
            return &gb10_q130560_long512_prompt_fixture();
        }
        if (prefill_tokens == kGb10Q131071Long1ChatTokenCount) {
            return &gb10_q131071_long1_prompt_fixture();
        }
        if (prefill_tokens == kGb10Q131072DiagnosticChatTokenCount) {
            return &gb10_q131072_diagnostic_prompt_fixture();
        }
        if (prefill_tokens == kQ262144StructuralChatTokenCount) {
            return &q262144_structural_prompt_fixture();
        }
    }
    return nullptr;
}

void append_gb10_prompt_fixture_tokens(
    const Gb10PromptFixture &fixture,
    std::vector<uint32_t> *out
) {
    out->clear();
    out->reserve(fixture.prompt_token_count);
    out->insert(
        out->end(),
        fixture.prompt_prefix_ids,
        fixture.prompt_prefix_ids +
            static_cast<std::ptrdiff_t>(fixture.prompt_prefix_count)
    );
    out->insert(
        out->end(),
        fixture.prompt_repeat_count,
        fixture.prompt_repeat_token_id
    );
    if (fixture.prompt_suffix_ids != nullptr && fixture.prompt_suffix_count > 0u) {
        out->insert(
            out->end(),
            fixture.prompt_suffix_ids,
            fixture.prompt_suffix_ids +
                static_cast<std::ptrdiff_t>(fixture.prompt_suffix_count)
        );
    }
}
