struct TensorLocation {
    std::string shard;
    uint64_t header_len = 0;
    uint64_t data_begin = 0;
    uint64_t data_end = 0;
};

bool try_resident_model_shard_store_location(
    const std::string &model_dir,
    const std::string &tensor_name,
    TensorLocation *location
);

struct TensorLocationCacheStats {
    uint64_t lookup_count = 0;
    uint64_t hit_count = 0;
    uint64_t miss_count = 0;
    uint64_t store_count = 0;
};

struct TensorLocationCache {
    std::mutex mutex;
    std::unordered_map<std::string, TensorLocation> entries;
    TensorLocationCacheStats stats;
};

struct TensorSliceCacheStats {
    uint64_t lookup_count = 0;
    uint64_t hit_count = 0;
    uint64_t miss_count = 0;
    uint64_t store_count = 0;
    uint64_t store_failure_count = 0;
    uint64_t skipped_large_count = 0;
    uint64_t skipped_capacity_count = 0;
    uint64_t hit_bytes = 0;
    uint64_t miss_bytes = 0;
    uint64_t stored_bytes = 0;
};

struct TensorSliceCache {
    std::mutex mutex;
    std::unordered_map<std::string, std::vector<uint16_t>> entries;
    uint64_t bytes = 0;
    TensorSliceCacheStats stats;
};

constexpr uint64_t kTensorSliceCacheMaxSliceBytes =
    UINT64_C(64) * UINT64_C(1024) * UINT64_C(1024);
constexpr uint64_t kTensorSliceCacheMaxBytes =
    UINT64_C(4) * UINT64_C(1024) * UINT64_C(1024) * UINT64_C(1024);

TensorLocationCache &tensor_location_cache() {
    static TensorLocationCache cache;
    return cache;
}

TensorSliceCache &tensor_slice_cache() {
    static TensorSliceCache cache;
    return cache;
}

std::string tensor_location_cache_key(
    const std::string &model_dir,
    const std::string &tensor_name
) {
    std::string key;
    key.reserve(model_dir.size() + tensor_name.size() + 1u);
    key.append(model_dir);
    key.push_back('\n');
    key.append(tensor_name);
    return key;
}

std::string tensor_slice_cache_key(
    const std::string &model_dir,
    const TensorLocation &location,
    uint64_t relative_begin,
    uint64_t byte_count
) {
    std::ostringstream key;
    key << model_dir << '\n'
        << location.shard << '\n'
        << location.header_len << '\n'
        << location.data_begin << '\n'
        << location.data_end << '\n'
        << relative_begin << '\n'
        << byte_count;
    return key.str();
}

TensorLocationCacheStats reset_tensor_location_cache_stats(size_t *entry_count) {
    TensorLocationCache &cache = tensor_location_cache();
    std::lock_guard<std::mutex> lock(cache.mutex);
    if (entry_count != nullptr) {
        *entry_count = cache.entries.size();
    }
    TensorLocationCacheStats stats = cache.stats;
    cache.stats = TensorLocationCacheStats{};
    return stats;
}

TensorSliceCacheStats release_tensor_slice_cache(size_t *entry_count, uint64_t *bytes) {
    TensorSliceCache &cache = tensor_slice_cache();
    std::lock_guard<std::mutex> lock(cache.mutex);
    if (entry_count != nullptr) {
        *entry_count = cache.entries.size();
    }
    if (bytes != nullptr) {
        *bytes = cache.bytes;
    }
    TensorSliceCacheStats stats = cache.stats;
    cache.entries.clear();
    cache.bytes = 0;
    cache.stats = TensorSliceCacheStats{};
    return stats;
}

bool tensor_slice_cache_enabled(uint64_t byte_count) {
    if (g_descriptor_batch_resident_engine == nullptr || byte_count == 0u) {
        return false;
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_DISABLE_HOST_TENSOR_SLICE_CACHE"
        )) {
        return false;
    }
    if (byte_count > kTensorSliceCacheMaxSliceBytes) {
        TensorSliceCache &cache = tensor_slice_cache();
        std::lock_guard<std::mutex> lock(cache.mutex);
        ++cache.stats.skipped_large_count;
        return false;
    }
    return true;
}

bool try_read_tensor_slice_cache(
    const std::string &cache_key,
    uint64_t byte_count,
    std::vector<uint16_t> *out
) {
    TensorSliceCache &cache = tensor_slice_cache();
    std::lock_guard<std::mutex> lock(cache.mutex);
    ++cache.stats.lookup_count;
    const auto found = cache.entries.find(cache_key);
    if (found == cache.entries.end()) {
        ++cache.stats.miss_count;
        cache.stats.miss_bytes += byte_count;
        return false;
    }
    *out = found->second;
    ++cache.stats.hit_count;
    cache.stats.hit_bytes += byte_count;
    return true;
}

void store_tensor_slice_cache(
    const std::string &cache_key,
    uint64_t byte_count,
    const std::vector<uint16_t> &data
) {
    TensorSliceCache &cache = tensor_slice_cache();
    std::lock_guard<std::mutex> lock(cache.mutex);
    if (cache.entries.find(cache_key) != cache.entries.end()) {
        return;
    }
    if (byte_count > kTensorSliceCacheMaxBytes ||
        cache.bytes > kTensorSliceCacheMaxBytes - byte_count) {
        ++cache.stats.skipped_capacity_count;
        return;
    }
    try {
        cache.entries.emplace(cache_key, data);
        cache.bytes += byte_count;
        ++cache.stats.store_count;
        cache.stats.stored_bytes += byte_count;
    } catch (...) {
        ++cache.stats.store_failure_count;
    }
}

