template <typename T>
void release_vector_capacity(std::vector<T> *values) {
    std::vector<T>().swap(*values);
}

void release_routed_expert_transients(RoutedExpertRun *run) {
    release_vector_capacity(&run->route_expert_slot_indices);
    release_vector_capacity(&run->gate_up_route_indices);
    release_vector_capacity(&run->expert_group_offsets);
    release_vector_capacity(&run->expert_group_tile_expert_slots);
    release_vector_capacity(&run->expert_group_tile_route_offsets);
    release_vector_capacity(&run->down_token_indices);
    release_vector_capacity(&run->down_route_indices);
    release_vector_capacity(&run->unique_expert_ids);
    release_vector_capacity(&run->selected_inputs);
    release_vector_capacity(&run->gate_up_weights);
    release_vector_capacity(&run->gate_up_weight_pairs);
    release_vector_capacity(&run->down_weights);
    release_vector_capacity(&run->down_weight_row_pairs);
}

size_t capped_selected_unique_expert_count(size_t selected_route_count) {
    const size_t expert_count = static_cast<size_t>(QRT_QWEN36_EXPERT_COUNT);
    return selected_route_count < expert_count ? selected_route_count : expert_count;
}

