    uint64_t cpu_reference_validation_count = 0;
    uint64_t trusted_gpu_handoff_count = 0;
    uint64_t direct_packed_weight_count = 0;
    uint64_t device_packed_weight_count = 0;
    uint64_t device_cached_weight_count = 0;
