void apply_routed_expert_gpu_output_contract_report_to_run(
    PrefillLinearAttentionDescriptorBatchRun *run,
    const qrt_engine_report_t &report
) {
    if (run == nullptr) {
        return;
    }
    RoutedExpertGpuOutputContractSummary &summary =
        run->routed_expert_gpu_output_contract;
    summary.call_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_call_count;
    summary.pass_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_pass_count;
    summary.f32_hash_match_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_f32_hash_match_count;
    summary.bf16_hash_match_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_bf16_hash_match_count;
    summary.checked_value_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_checked_value_count;
    summary.expected_value_count =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_expected_value_count;
    summary.worst_layer_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_worst_layer_index;
    summary.max_abs_diff =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_max_abs_diff;
    summary.digest_fnv1a64 =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_digest_fnv1a64;
    summary.f32_pair_digest_fnv1a64 =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_f32_pair_digest_fnv1a64;
    summary.bf16_pair_digest_fnv1a64 =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_bf16_pair_digest_fnv1a64;
    summary.worst_stage =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_worst_stage;
    summary.first_diff_layer_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_layer_index;
    summary.first_diff_element_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_element_index;
    summary.first_diff_token_id =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_token_id;
    summary.first_diff_hidden_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_hidden_index;
    summary.first_diff_cpu_bits =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_cpu_bits;
    summary.first_diff_gpu_bits =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_gpu_bits;
    summary.first_diff_ulp_distance =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_first_diff_ulp_distance;
    summary.max_ulp_layer_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_max_ulp_layer_index;
    summary.max_ulp_token_id =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_max_ulp_token_id;
    summary.max_ulp_hidden_index =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_max_ulp_hidden_index;
    summary.max_ulp_distance =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_max_ulp_distance;
    for (size_t layer_index = 0u; layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        summary.layer_checked_value_count[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_checked_value_count[layer_index];
        summary.layer_mismatch_count[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_mismatch_count[layer_index];
        summary.layer_first_diff_element_index[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_element_index[layer_index];
        summary.layer_first_diff_token_id[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_token_id[layer_index];
        summary.layer_first_diff_hidden_index[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_hidden_index[layer_index];
        summary.layer_first_diff_cpu_bits[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_cpu_bits[layer_index];
        summary.layer_first_diff_gpu_bits[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_gpu_bits[layer_index];
        summary.layer_first_diff_ulp_distance[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_first_diff_ulp_distance[layer_index];
        summary.layer_max_ulp_distance[layer_index] =
            report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_max_ulp_distance[layer_index];
        for (size_t bucket_index = 0u;
             bucket_index < QRT_QWEN36_ROUTED_OUTPUT_ULP_BUCKET_COUNT;
             ++bucket_index) {
            summary.layer_ulp_bucket_counts[
                layer_index * QRT_QWEN36_ROUTED_OUTPUT_ULP_BUCKET_COUNT +
                bucket_index
            ] =
                report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_layer_ulp_bucket_counts[layer_index][bucket_index];
        }
    }
    summary.all_within_tolerance =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_all_within_tolerance !=
        0u;
    summary.all_f32_hash_match =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_all_f32_hash_match !=
        0u;
    summary.all_bf16_hash_match =
        report.baseline_product_q8192_descriptor_batch_routed_expert_gpu_contract_all_bf16_hash_match !=
        0u;
}

