static bool resident_q32768_cold_token_sequence_boundary_pass(
    const ResidentPrefillEntrypointRun &run,
    unsigned int prefill_tokens
) {
    const bool supported_output_shape =
        run.output_token_capacity == 1u ||
        run.output_token_capacity ==
            kGb10Q8192Long64CompletionTokenCount ||
        run.output_token_capacity == 512u;
    const size_t oracle_comparison_count =
        (std::min)(
            static_cast<size_t>(run.output_token_capacity),
            static_cast<size_t>(kGb10Q8192Long64CompletionTokenCount)
        );
    const bool exact_oracle_prefix =
        supported_output_shape &&
        run.output_token_count == run.output_token_capacity &&
        run.output_tokens.size() == run.output_token_capacity &&
        std::equal(
            run.output_tokens.begin(),
            run.output_tokens.begin() + oracle_comparison_count,
            kGb10Q8192Long64CompletionTokens
        );
    return resident_q32768_cold_probe_requested(prefill_tokens) &&
        run.prefill_status == QRT_STATUS_OK &&
        run.report_status == QRT_STATUS_OK &&
        run.request_repeat_count == 1u &&
        run.request_repeat_completed_count == 1u &&
        exact_oracle_prefix &&
        run.input_token_ids_hash ==
            kGb10Q32768Long64InputTokenIdsFnv1a64 &&
        run.report.last_request_output_token_count ==
            run.output_token_capacity &&
        run.report.last_request_ttft_elapsed_ns != UINT64_C(0) &&
        run.report.baseline_output_head_token_emitted != 0 &&
        run.report.baseline_output_head_sampled_token_id ==
            kGb10Q32768Long64ExpectedFirstToken &&
        std::isfinite(run.report.baseline_output_head_topk_logits[0]) &&
        !run.output_head_skipped &&
        !run.resident_prefix_cache_requested &&
        run.internal_continuation_attached &&
        run.internal_continuation_attempted &&
        run.internal_continuation_completed &&
        run.internal_continuation_status == QRT_STATUS_OK &&
        !decode_quantized_route_requested();
}

