// Exact causal verification can re-enter the whole-provider on the serving
// thread while the outer request still owns its marker filter.  The filters
// form a strict stack (each instance restores the previous streambuf), so the
// matching serialization primitive must admit that same-thread nesting.
std::recursive_mutex g_required_batch_marker_filter_mutex;

class ScopedRequiredBatchMarkerFilter final {
public:
    ScopedRequiredBatchMarkerFilter() {
        if (!env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_REQUIRED_MARKERS_ONLY"
            )) {
            return;
        }
        lock_ = std::unique_lock<std::recursive_mutex>(
            g_required_batch_marker_filter_mutex
        );
        previous_ = std::cerr.rdbuf();
        filter_ = std::make_unique<RequiredBatchMarkerStreambuf>(previous_);
        std::cerr.rdbuf(filter_.get());
        active_ = true;
        std::cerr
            << "BATCH_MARK required_marker_filter_activate"
            << " mode=required"
            << " scope=qwen36_whole_provider_inference"
            << std::endl;
    }

    ScopedRequiredBatchMarkerFilter(
        const ScopedRequiredBatchMarkerFilter &
    ) = delete;
    ScopedRequiredBatchMarkerFilter &operator=(
        const ScopedRequiredBatchMarkerFilter &
    ) = delete;

    ~ScopedRequiredBatchMarkerFilter() {
        if (!active_) {
            return;
        }
        filter_->finish();
        std::cerr.rdbuf(previous_);
        filter_.reset();
    }

private:
    std::unique_lock<std::recursive_mutex> lock_;
    std::streambuf *previous_ = nullptr;
    std::unique_ptr<RequiredBatchMarkerStreambuf> filter_;
    bool active_ = false;
};

