bool descriptor_product_q8192_triton_selected_moe_provider_enabled(
    unsigned int layer_index,
    unsigned int prefill_tokens
) {
    const bool supported_prefill_shape =
        qwen36_exact_arbitrary_product_path_enabled(prefill_tokens) ||
        prefill_tokens == kRetainedPrefillTokens ||
        (prefill_tokens == kQ16384ColdProbePrefillTokens &&
         raw_env_flag_enabled("QRT_QWEN36_Q16384_COLD_PROBE")) ||
        (prefill_tokens == kQ32768ColdProbePrefillTokens &&
         raw_env_flag_enabled("QRT_QWEN36_Q32768_COLD_PROBE")) ||
        (prefill_tokens == kQ65536ColdProbePrefillTokens &&
         raw_env_flag_enabled("QRT_QWEN36_Q65536_COLD_PROBE")) ||
        resident_q131072_cold_probe_requested(prefill_tokens);
    return layer_index < QRT_QWEN36_LAYER_COUNT &&
        supported_prefill_shape &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q8192_TRITON_SELECTED_MOE_PROVIDER"
        );
}

bool descriptor_product_q8192_triton_selected_moe_full_provider_enabled(
    unsigned int layer_index,
    unsigned int prefill_tokens
) {
    const bool whole_early_layer =
        layer_index < 2u &&
        g_qwen36_whole_provider_selected_moe_backend_active &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_WHOLE_EARLY_LAYER_PROVIDER"
        ) &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_EARLY_ENTRY_SELECTED_MOE_PRODUCT_SCOPE"
        ) &&
        env_flag_enabled(
            "QRT_QWEN36_WHOLE_PROVIDER_FUSED_LAYER_STACK"
        );
    const bool terminal_prefill_layer =
        layer_index + 2u == QRT_QWEN36_LAYER_COUNT &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q8192_TRITON_SELECTED_MOE_FULL_LAYER38"
        );
    const bool full_prefix_terminal_prefill_layer =
        (maximum_context_streamed_prefill_tokens(prefill_tokens) ||
         qwen36_final_layer_full_prefix_requested(prefill_tokens)) &&
        layer_index == kDescriptorBatchFinalLayer;
    return (layer_index >= 2u || whole_early_layer) &&
        (layer_index + 2u < QRT_QWEN36_LAYER_COUNT || terminal_prefill_layer ||
         full_prefix_terminal_prefill_layer) &&
        descriptor_product_q8192_triton_selected_moe_provider_enabled(
            layer_index,
            prefill_tokens
        ) &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q8192_TRITON_SELECTED_MOE_FULL_PROVIDER"
        );
}

