using TritonSelectedMoePaddedFullLaunchFn =
    TritonSelectedMoeDynamicFullLaunchFn;

// Keep the dense-ceil ladder no wider than 512 tokens through the first
// q8192 tile.  A sparse power-of-two ladder makes a request just above an
// otherwise fast anchor execute thousands of synthetic padding tokens (for
// example q4609 used to run the q8192 provider).  These model-specific
// capacities bound that discontinuity while preserving the existing fixed-
// shape provider ABI.
constexpr std::array<size_t, 19u> kSmoothTailMoeProviderTokenCounts{
    32u,
    64u,
    128u,
    256u,
    512u,
    1024u,
    2048u,
    2560u,
    3072u,
    3328u,
    3584u,
    4096u,
    4608u,
    5120u,
    5632u,
    6144u,
    6656u,
    7168u,
    7680u
};

bool smooth_tail_moe_provider_required_for_profile(
    size_t tile_tokens,
    bool dense_ceil
) {
    // Ordinary/split tails only select powers of two; the extra capacities
    // belong to the explicitly enabled dense-ceil route. Do not require or
    // allocate that experimental ladder when loading the retained package.
    for (const size_t capacity : kSmoothTailMoeProviderTokenCounts) {
        if (capacity == tile_tokens) {
            return dense_ceil ||
                (tile_tokens <= 4096u &&
                 (tile_tokens & (tile_tokens - 1u)) == 0u);
        }
    }
    return false;
}

bool smooth_tail_moe_provider_index(
    size_t tile_tokens,
    size_t *provider_index
) {
    if (provider_index == nullptr) {
        return false;
    }
    for (size_t index = 0u;
         index < kSmoothTailMoeProviderTokenCounts.size();
         ++index) {
        if (kSmoothTailMoeProviderTokenCounts[index] == tile_tokens) {
            *provider_index = index;
            return true;
        }
    }
    return false;
}

