struct Q1MoeVllmTritonModuleState {
    std::mutex mutex;
    std::array<hipModule_t, 4u> modules{};
    std::array<hipFunction_t, 4u> functions{};
    std::string directory;
};

Q1MoeVllmTritonModuleState &q1_moe_vllm_triton_module_state() {
    static Q1MoeVllmTritonModuleState state;
    return state;
}

bool load_q1_moe_vllm_triton_functions(
    hipFunction_t *w13_function,
    hipFunction_t *silu_and_mul_function,
    hipFunction_t *w2_weighted_function,
    hipFunction_t *route_sum_function,
    std::string *failure_stage,
    std::string *failure
) {
    if (w13_function == nullptr || silu_and_mul_function == nullptr ||
        w2_weighted_function == nullptr || route_sum_function == nullptr ||
        failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_VLLM_TRITON_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        directory = std::getenv(
            "QRT_QWEN36_Q2_VLLM_TRITON_ROUTED_MODULE_DIR"
        );
    }
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_moe_vllm_triton_module_dir";
        *failure =
            "neither the q1 nor q2 pinned-vLLM Triton MoE module directory is set";
        return false;
    }

    Q1MoeVllmTritonModuleState &state =
        q1_moe_vllm_triton_module_state();
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage = "q1_moe_vllm_triton_module_dir_change";
        *failure =
            "the q1 pinned-vLLM Triton MoE module directory changed after load";
        return false;
    }
    if (state.functions[0] != nullptr) {
        *w13_function = state.functions[0];
        *silu_and_mul_function = state.functions[1];
        *w2_weighted_function = state.functions[2];
        *route_sum_function = state.functions[3];
        return true;
    }

    constexpr std::array<const char *, 4u> kFiles{{
        "q1_vllm_triton_moe_0724_w13.hsaco",
        "q1_vllm_triton_moe_0724_silu_and_mul.hsaco",
        "q1_vllm_triton_moe_0724_w2_weighted.hsaco",
        "q1_vllm_triton_moe_0724_route_sum_vt4.hsaco",
    }};
    constexpr std::array<const char *, 4u> kSymbols{{
        "_w13_kernel",
        "_silu_and_mul_kernel",
        "_w2_weighted_kernel",
        "_route_sum_vt4_kernel",
    }};
    const auto release_loaded = [&state]() {
        for (size_t index = 0; index < state.modules.size(); ++index) {
            if (state.modules[index] != nullptr) {
                (void)hipModuleUnload(state.modules[index]);
            }
            state.modules[index] = nullptr;
            state.functions[index] = nullptr;
        }
    };

    for (size_t index = 0; index < kFiles.size(); ++index) {
        const std::string path =
            std::string(directory) + "\\" + kFiles[index];
        hipError_t status = hipModuleLoad(
            &state.modules[index],
            path.c_str()
        );
        if (status != hipSuccess) {
            *failure_stage =
                "hipModuleLoad(q1_moe_vllm_triton_" +
                std::to_string(index) + ")";
            *failure =
                path + ": " + std::string(hipGetErrorString(status));
            release_loaded();
            return false;
        }
        status = hipModuleGetFunction(
            &state.functions[index],
            state.modules[index],
            kSymbols[index]
        );
        if (status != hipSuccess) {
            *failure_stage =
                "hipModuleGetFunction(q1_moe_vllm_triton_" +
                std::to_string(index) + ")";
            *failure =
                std::string(kSymbols[index]) + ": " +
                hipGetErrorString(status);
            release_loaded();
            return false;
        }
    }

    state.directory = directory;
    *w13_function = state.functions[0];
    *silu_and_mul_function = state.functions[1];
    *w2_weighted_function = state.functions[2];
    *route_sum_function = state.functions[3];
    return true;
}

bool load_q1_moe_triton_0626_shared_functions(
    hipFunction_t *gate_up_function,
    hipFunction_t *gate_logit_function,
    hipFunction_t *down_function,
    std::string *failure_stage,
    std::string *failure
) {
    if (gate_up_function == nullptr || gate_logit_function == nullptr ||
        down_function == nullptr || failure_stage == nullptr ||
        failure == nullptr) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_moe_triton_0626_module_dir";
        *failure =
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR is empty";
        return false;
    }
    Q1MoeTriton0626ModuleState &state =
        q1_moe_triton_0626_module_state();
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage = "q1_moe_triton_0626_module_dir_change";
        *failure =
            "the q1 Triton 0626 module directory changed after load";
        return false;
    }
    if (state.shared_gate_up_function != nullptr &&
        state.shared_gate_logit_function != nullptr &&
        state.shared_down_function != nullptr) {
        *gate_up_function = state.shared_gate_up_function;
        *gate_logit_function = state.shared_gate_logit_function;
        *down_function = state.shared_down_function;
        return true;
    }

    const std::string gate_up_path = std::string(directory) +
        "\\q1_triton_0626_shared_gate_up_silu.hsaco";
    const std::string gate_logit_path = std::string(directory) +
        "\\q1_triton_0626_shared_gate_logit.hsaco";
    const std::string down_path = std::string(directory) +
        "\\q1_triton_0626_shared_down.hsaco";
    const auto unload_shared = [&state]() {
        if (state.shared_down_module != nullptr) {
            (void)hipModuleUnload(state.shared_down_module);
        }
        if (state.shared_gate_logit_module != nullptr) {
            (void)hipModuleUnload(state.shared_gate_logit_module);
        }
        if (state.shared_gate_up_module != nullptr) {
            (void)hipModuleUnload(state.shared_gate_up_module);
        }
        state.shared_down_module = nullptr;
        state.shared_gate_logit_module = nullptr;
        state.shared_gate_up_module = nullptr;
        state.shared_down_function = nullptr;
        state.shared_gate_logit_function = nullptr;
        state.shared_gate_up_function = nullptr;
    };

    hipError_t status = hipModuleLoad(
        &state.shared_gate_up_module,
        gate_up_path.c_str()
    );
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad(q1_triton_0626_shared_gate_up)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    status = hipModuleGetFunction(
        &state.shared_gate_up_function,
        state.shared_gate_up_module,
        "_shared_gate_up_silu_kernel"
    );
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleGetFunction(q1_triton_0626_shared_gate_up)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    status = hipModuleLoad(
        &state.shared_gate_logit_module,
        gate_logit_path.c_str()
    );
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad(q1_triton_0626_shared_gate_logit)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    status = hipModuleGetFunction(
        &state.shared_gate_logit_function,
        state.shared_gate_logit_module,
        "_shared_gate_logit_kernel"
    );
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleGetFunction(q1_triton_0626_shared_gate_logit)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    status = hipModuleLoad(&state.shared_down_module, down_path.c_str());
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad(q1_triton_0626_shared_down)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    status = hipModuleGetFunction(
        &state.shared_down_function,
        state.shared_down_module,
        "_shared_down_kernel"
    );
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleGetFunction(q1_triton_0626_shared_down)";
        *failure = hipGetErrorString(status);
        unload_shared();
        return false;
    }
    state.directory = directory;
    *gate_up_function = state.shared_gate_up_function;
    *gate_logit_function = state.shared_gate_logit_function;
    *down_function = state.shared_down_function;
    return true;
}

struct Q1MoeTriton0626DualModuleState {
    std::mutex mutex;
    std::array<hipModule_t, 5u> modules{};
    std::array<hipFunction_t, 5u> functions{};
    std::string directory;
    bool route_permutation = false;
    bool fused_route_permutation = false;
};

Q1MoeTriton0626DualModuleState &q1_moe_triton_0626_dual_module_state() {
    static Q1MoeTriton0626DualModuleState state;
    return state;
}

bool load_q1_moe_triton_0626_dual_functions(
    hipFunction_t *gate_up_function,
    hipFunction_t *down_function,
    hipFunction_t *shared_gate_up_function,
    hipFunction_t *shared_gate_logit_function,
    hipFunction_t *shared_down_function,
    std::string *failure_stage,
    std::string *failure
) {
    if (gate_up_function == nullptr || down_function == nullptr ||
        shared_gate_up_function == nullptr ||
        shared_gate_logit_function == nullptr ||
        shared_down_function == nullptr || failure_stage == nullptr ||
        failure == nullptr) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_QWEN36_Q1_MOE_TRITON_0626_DUAL_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_moe_triton_0626_dual_module_dir";
        *failure = "the q1 dual-row MoE Triton module directory is empty";
        return false;
    }
    const bool route_permutation = env_flag_enabled(
        "QRT_QWEN36_Q1_MOE_TRITON_0626_DUAL_ROUTE_PERMUTATION"
    );
    const bool fused_route_permutation =
        route_permutation &&
        env_flag_enabled(
            "QRT_QWEN36_Q1_MOE_TRITON_0626_DUAL_FUSED_ROUTE_PERMUTATION"
        );
    Q1MoeTriton0626DualModuleState &state =
        q1_moe_triton_0626_dual_module_state();
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage = "q1_moe_triton_0626_dual_module_dir_change";
        *failure = "the q1 dual-row MoE Triton module directory changed";
        return false;
    }
    if (!state.directory.empty() &&
        state.route_permutation != route_permutation) {
        *failure_stage =
            "q1_moe_triton_0626_dual_route_permutation_change";
        *failure =
            "the q1 dual-row MoE route-permutation mode changed after module load";
        return false;
    }
    if (!state.directory.empty() &&
        state.fused_route_permutation != fused_route_permutation) {
        *failure_stage =
            "q1_moe_triton_0626_dual_fused_route_permutation_change";
        *failure =
            "the q1 dual-row MoE fused route-permutation mode changed after module load";
        return false;
    }
    if (state.functions[0u] != nullptr) {
        *gate_up_function = state.functions[0u];
        *down_function = state.functions[1u];
        *shared_gate_up_function = state.functions[2u];
        *shared_gate_logit_function = state.functions[3u];
        *shared_down_function = state.functions[4u];
        return true;
    }
    const std::array<const char *, 5u> kFiles{
        fused_route_permutation
            ? "q1_triton_0626_gate_up_silu_dual_fused_permuted_w8.hsaco"
            : route_permutation
            ? "q1_triton_0626_gate_up_silu_dual_permuted_w8.hsaco"
            : "q1_triton_0626_gate_up_silu_dual_w8.hsaco",
        "q1_triton_0626_down_sum_dual.hsaco",
        "q1_triton_0626_shared_gate_up_silu_dual.hsaco",
        "q1_triton_0626_shared_gate_logit_dual.hsaco",
        "q1_triton_0626_shared_down_dual.hsaco",
    };
    const std::array<const char *, 5u> kSymbols{
        fused_route_permutation
            ? "_gate_up_silu_dual_fused_permuted_kernel"
            : route_permutation
            ? "_gate_up_silu_dual_permuted_kernel"
            : "_gate_up_silu_dual_kernel",
        "_down_sum_dual_kernel",
        "_shared_gate_up_silu_dual_kernel",
        "_shared_gate_logit_dual_kernel",
        "_shared_down_dual_kernel",
    };
    const auto unload = [&state]() {
        for (size_t index = 0u; index < state.modules.size(); ++index) {
            if (state.modules[index] != nullptr) {
                (void)hipModuleUnload(state.modules[index]);
            }
            state.modules[index] = nullptr;
            state.functions[index] = nullptr;
        }
    };
    for (size_t index = 0u; index < kFiles.size(); ++index) {
        const std::string path =
            std::string(directory) + "\\" + kFiles[index];
        hipError_t status = hipModuleLoad(
            &state.modules[index],
            path.c_str()
        );
        if (status != hipSuccess) {
            *failure_stage =
                std::string("hipModuleLoad(") + kFiles[index] + ")";
            *failure = hipGetErrorString(status);
            unload();
            return false;
        }
        status = hipModuleGetFunction(
            &state.functions[index],
            state.modules[index],
            kSymbols[index]
        );
        if (status != hipSuccess) {
            *failure_stage =
                std::string("hipModuleGetFunction(") + kSymbols[index] + ")";
            *failure = hipGetErrorString(status);
            unload();
            return false;
        }
    }
    state.directory = directory;
    state.route_permutation = route_permutation;
    state.fused_route_permutation = fused_route_permutation;
    *gate_up_function = state.functions[0u];
    *down_function = state.functions[1u];
    *shared_gate_up_function = state.functions[2u];
    *shared_gate_logit_function = state.functions[3u];
    *shared_down_function = state.functions[4u];
    return true;
}

