bool load_q1_full_attention_triton_0626_qkv_function(
    hipFunction_t *function,
    std::string *failure_stage,
    std::string *failure
) {
    if (function == nullptr || failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    // The retained 0626 MoE and full-attention AOT objects are packaged in
    // one gfx1151 module directory.  Sharing the path contract avoids adding
    // a runtime dependency while each HSACO keeps independent ownership.
    const char *directory = std::getenv(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_full_attention_triton_0626_qkv_module_dir";
        *failure =
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR is empty";
        return false;
    }
    Q1FullAttentionTriton0626QkvModuleState &state =
        q1_full_attention_triton_0626_qkv_module_state();
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage =
            "q1_full_attention_triton_0626_qkv_module_dir_change";
        *failure =
            "the q1 full-attention Triton 0626 module directory changed after load";
        return false;
    }
    if (state.function != nullptr) {
        *function = state.function;
        return true;
    }
    const std::string path = std::string(directory) +
        "\\q1_triton_0626_full_attention_qkv_w8.hsaco";
    hipError_t status = hipModuleLoad(&state.module, path.c_str());
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleLoad(q1_triton_0626_full_attention_qkv_w8)";
        *failure = hipGetErrorString(status);
        state.module = nullptr;
        return false;
    }
    status = hipModuleGetFunction(
        &state.function,
        state.module,
        "_full_attention_qkv_row_kernel"
    );
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleGetFunction(q1_triton_0626_full_attention_qkv_w8)";
        *failure = hipGetErrorString(status);
        (void)hipModuleUnload(state.module);
        state.module = nullptr;
        state.function = nullptr;
        return false;
    }
    state.directory = directory;
    *function = state.function;
    return true;
}

