struct Q1FullAttentionAiterUnifiedModuleState {
    std::mutex mutex;
    hipModule_t main_module = nullptr;
    hipModule_t reduce_module = nullptr;
    hipFunction_t main_function = nullptr;
    hipFunction_t reduce_function = nullptr;
    std::string directory;
};

Q1FullAttentionAiterUnifiedModuleState &
q1_full_attention_aiter_unified_module_state() {
    static Q1FullAttentionAiterUnifiedModuleState state;
    return state;
}

bool load_q1_full_attention_aiter_unified_functions(
    hipFunction_t *main_function,
    hipFunction_t *reduce_function,
    std::string *failure_stage,
    std::string *failure
) {
    if (main_function == nullptr || reduce_function == nullptr ||
        failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_AITER_UNIFIED_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage =
            "q1_full_attention_aiter_unified_module_dir";
        *failure =
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_AITER_UNIFIED_MODULE_DIR is empty";
        return false;
    }
    Q1FullAttentionAiterUnifiedModuleState &state =
        q1_full_attention_aiter_unified_module_state();
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage =
            "q1_full_attention_aiter_unified_module_dir_change";
        *failure =
            "the q1 AITER Unified Attention module directory changed after load";
        return false;
    }
    if (state.main_function != nullptr && state.reduce_function != nullptr) {
        *main_function = state.main_function;
        *reduce_function = state.reduce_function;
        return true;
    }
    const std::string main_path = std::string(directory) +
        "\\kernel_unified_attention_3d.hsaco";
    const std::string reduce_path =
        std::string(directory) + "\\reduce_segments.hsaco";
    hipError_t status = hipModuleLoad(
        &state.main_module,
        main_path.c_str()
    );
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleLoad(q1_aiter_unified_attention_main)";
        *failure = hipGetErrorString(status);
        state.main_module = nullptr;
        return false;
    }
    const bool vllm_triton2d =
        q1_full_attention_vllm_triton2d_requested();
    status = hipModuleGetFunction(
        &state.main_function,
        state.main_module,
        vllm_triton2d
            ? "kernel_unified_attention_2d_abi"
            : "kernel_unified_attention_3d"
    );
    if (status == hipSuccess) {
        status = hipModuleLoad(
            &state.reduce_module,
            reduce_path.c_str()
        );
    }
    if (status == hipSuccess) {
        status = hipModuleGetFunction(
            &state.reduce_function,
            state.reduce_module,
            vllm_triton2d
                ? "reduce_segments_2d_abi"
                : "reduce_segments"
        );
    }
    if (status != hipSuccess) {
        *failure_stage =
            "hipModuleGetFunction(q1_aiter_unified_attention)";
        *failure = hipGetErrorString(status);
        if (state.reduce_module != nullptr) {
            (void)hipModuleUnload(state.reduce_module);
        }
        if (state.main_module != nullptr) {
            (void)hipModuleUnload(state.main_module);
        }
        state.main_module = nullptr;
        state.reduce_module = nullptr;
        state.main_function = nullptr;
        state.reduce_function = nullptr;
        state.directory.clear();
        return false;
    }
    state.directory = directory;
    *main_function = state.main_function;
    *reduce_function = state.reduce_function;
    std::cerr
        << "BATCH_MARK q1_full_attention_aiter_unified_modules"
        << " main=" << main_path
        << " reduce=" << reduce_path
        << " main_kernarg_bytes=184"
        << " reduce_kernarg_bytes=88"
        << " segments=" << q1_full_attention_unified_active_segments()
        << " vllm_triton16="
        << (q1_full_attention_vllm_triton16_requested() ? 1 : 0)
        << " vllm_triton2d="
        << (q1_full_attention_vllm_triton2d_requested() ? 1 : 0)
        << " weight_bits=16 activation_bits=16 kv_cache_bits=16"
        << " accumulation_bits=32 quantized=0 dflash_active=0"
        << " mtp_active=0 speculative_decode=0"
        << std::endl;
    return true;
}

struct Q1FullAttentionTriton0626QkModuleState {
    std::mutex mutex;
    hipModule_t module = nullptr;
    hipFunction_t function = nullptr;
    std::string directory;
};

Q1FullAttentionTriton0626QkModuleState &
q1_full_attention_triton_0626_qk_module_state(
    unsigned int prefix_tokens,
    unsigned int max_tail_tokens
) {
    static Q1FullAttentionTriton0626QkModuleState q8192_short_state;
    static Q1FullAttentionTriton0626QkModuleState q8192_tail512_state;
    static Q1FullAttentionTriton0626QkModuleState q16384_short_state;
    static Q1FullAttentionTriton0626QkModuleState q16384_tail512_state;
    static Q1FullAttentionTriton0626QkModuleState q16384_tail1536_state;
    static Q1FullAttentionTriton0626QkModuleState q32768_short_state;
    static Q1FullAttentionTriton0626QkModuleState q32768_tail512_state;
    static Q1FullAttentionTriton0626QkModuleState q32768_tail1536_state;
    static Q1FullAttentionTriton0626QkModuleState q65536_short_state;
    static Q1FullAttentionTriton0626QkModuleState q65536_tail512_state;
    if (prefix_tokens == kQ65536ColdProbePrefillTokens) {
        return max_tail_tokens == kQ1FullAttentionTriton0626MediumTailTokens
            ? q65536_tail512_state
            : q65536_short_state;
    }
    if (prefix_tokens == kQ32768ColdProbePrefillTokens) {
        if (max_tail_tokens ==
            kQ1FullAttentionTriton0626ProductTailTokens) {
            return q32768_tail1536_state;
        }
        return max_tail_tokens == kQ1FullAttentionTriton0626MediumTailTokens
            ? q32768_tail512_state
            : q32768_short_state;
    }
    if (prefix_tokens == kQ16384ColdProbePrefillTokens) {
        if (max_tail_tokens ==
            kQ1FullAttentionTriton0626ProductTailTokens) {
            return q16384_tail1536_state;
        }
        return max_tail_tokens == kQ1FullAttentionTriton0626MediumTailTokens
            ? q16384_tail512_state
            : q16384_short_state;
    }
    return max_tail_tokens == kQ1FullAttentionTriton0626MediumTailTokens
        ? q8192_tail512_state
        : q8192_short_state;
}

bool load_q1_full_attention_triton_0626_qk_function_variant(
    unsigned int prefix_tokens,
    unsigned int max_tail_tokens,
    hipFunction_t *function,
    std::string *failure_stage,
    std::string *failure
) {
    if (function == nullptr || failure_stage == nullptr || failure == nullptr ||
        (prefix_tokens != kRetainedPrefillTokens &&
         prefix_tokens != kQ16384ColdProbePrefillTokens &&
         prefix_tokens != kQ32768ColdProbePrefillTokens &&
         prefix_tokens != kQ65536ColdProbePrefillTokens) ||
        (max_tail_tokens != kQ1FullAttentionTriton0626ShortTailTokens &&
         max_tail_tokens != kQ1FullAttentionTriton0626MediumTailTokens &&
         (max_tail_tokens !=
              kQ1FullAttentionTriton0626ProductTailTokens ||
          (prefix_tokens != kQ16384ColdProbePrefillTokens &&
           prefix_tokens != kQ32768ColdProbePrefillTokens)))) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_QWEN36_Q1_FULL_ATTENTION_TRITON_0626_QK_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        directory = std::getenv(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR"
        );
    }
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_full_attention_triton_0626_qk_module_dir";
        *failure =
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_MODULE_DIR is empty";
        return false;
    }
    Q1FullAttentionTriton0626QkModuleState &state =
        q1_full_attention_triton_0626_qk_module_state(
            prefix_tokens,
            max_tail_tokens
        );
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage =
            "q1_full_attention_triton_0626_qk_module_dir_change";
        *failure =
            "the q1 full-attention Triton 0626 QK module directory changed after load";
        return false;
    }
    if (state.function != nullptr) {
        *function = state.function;
        return true;
    }
    const std::string module_name =
        std::string("q1_triton_0626_full_attention_qk_n32_w8") +
        (prefix_tokens == kRetainedPrefillTokens
             ? ""
             : "_q" + std::to_string(prefix_tokens)) +
        (max_tail_tokens == kQ1FullAttentionTriton0626ShortTailTokens
             ? ""
             : "_tail" + std::to_string(max_tail_tokens));
    const std::string path =
        std::string(directory) + "\\" + module_name + ".hsaco";
    hipError_t status = hipModuleLoad(&state.module, path.c_str());
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad(" + module_name + ")";
        *failure = hipGetErrorString(status);
        state.module = nullptr;
        return false;
    }
    status = hipModuleGetFunction(
        &state.function,
        state.module,
        "_qk_kernel"
    );
    if (status != hipSuccess) {
        *failure_stage = "hipModuleGetFunction(" + module_name + ")";
        *failure = hipGetErrorString(status);
        (void)hipModuleUnload(state.module);
        state.module = nullptr;
        state.function = nullptr;
        return false;
    }
    state.directory = directory;
    *function = state.function;
    return true;
}

bool load_q1_full_attention_triton_0626_qk_function(
    hipFunction_t *function,
    std::string *failure_stage,
    std::string *failure
) {
    return load_q1_full_attention_triton_0626_qk_function_variant(
        kRetainedPrefillTokens,
        kQ1FullAttentionTriton0626ShortTailTokens,
        function,
        failure_stage,
        failure
    );
}

struct Q1FullAttentionTritonOnlineModuleState {
    std::mutex mutex;
    hipModule_t partial_module = nullptr;
    hipModule_t reduce_module = nullptr;
    hipFunction_t partial_function = nullptr;
    hipFunction_t reduce_function = nullptr;
    std::string directory;
};

bool load_q1_full_attention_triton_online_functions(
    hipFunction_t *partial_function,
    hipFunction_t *reduce_function,
    std::string *failure_stage,
    std::string *failure
) {
    if (partial_function == nullptr || reduce_function == nullptr ||
        failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    const char *directory = std::getenv(
        "QRT_QWEN36_Q1_FULL_ATTENTION_TRITON_ONLINE_MODULE_DIR"
    );
    if (directory == nullptr || directory[0] == '\0') {
        *failure_stage = "q1_full_attention_triton_online_module_dir";
        *failure =
            "QRT_QWEN36_Q1_FULL_ATTENTION_TRITON_ONLINE_MODULE_DIR is empty";
        return false;
    }
    static Q1FullAttentionTritonOnlineModuleState state;
    std::lock_guard<std::mutex> lock(state.mutex);
    if (!state.directory.empty() && state.directory != directory) {
        *failure_stage =
            "q1_full_attention_triton_online_module_dir_change";
        *failure =
            "the q1 full-attention Triton online module directory changed after load";
        return false;
    }
    if (state.partial_function != nullptr &&
        state.reduce_function != nullptr) {
        *partial_function = state.partial_function;
        *reduce_function = state.reduce_function;
        return true;
    }
    const std::string variant =
        "n32_d64_c1024_pv1_w8_q16384_tail1536";
    const std::string partial_name =
        "q1_full_attention_partial_" + variant;
    const std::string reduce_name =
        "q1_full_attention_reduce_" + variant;
    auto unload = [&]() {
        if (state.partial_module != nullptr) {
            (void)hipModuleUnload(state.partial_module);
        }
        if (state.reduce_module != nullptr) {
            (void)hipModuleUnload(state.reduce_module);
        }
        state.partial_module = nullptr;
        state.reduce_module = nullptr;
        state.partial_function = nullptr;
        state.reduce_function = nullptr;
    };
    hipError_t status = hipModuleLoad(
        &state.partial_module,
        (std::string(directory) + "\\" + partial_name + ".hsaco").c_str()
    );
    if (status == hipSuccess) {
        status = hipModuleGetFunction(
            &state.partial_function,
            state.partial_module,
            "_partial_attention_kernel"
        );
    }
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad/GetFunction(" + partial_name + ")";
        *failure = hipGetErrorString(status);
        unload();
        return false;
    }
    status = hipModuleLoad(
        &state.reduce_module,
        (std::string(directory) + "\\" + reduce_name + ".hsaco").c_str()
    );
    if (status == hipSuccess) {
        status = hipModuleGetFunction(
            &state.reduce_function,
            state.reduce_module,
            "_reduce_attention_kernel"
        );
    }
    if (status != hipSuccess) {
        *failure_stage = "hipModuleLoad/GetFunction(" + reduce_name + ")";
        *failure = hipGetErrorString(status);
        unload();
        return false;
    }
    state.directory = directory;
    *partial_function = state.partial_function;
    *reduce_function = state.reduce_function;
    return true;
}

