bool q1_linear_triton_0626_qkvz_ab_overlay_layer_selected(
    unsigned int layer_index
) {
    const uint64_t layer_mask =
        q1_linear_triton_0626_qkvz_ab_overlay_layer_mask();
    return layer_index < 64u &&
        (layer_mask & (UINT64_C(1) << layer_index)) != UINT64_C(0);
}

unsigned int q1_linear_triton_0626_qkvz_ab_warps_for_layer(
    unsigned int layer_index
) {
    const uint64_t alt2_layer_mask =
        q1_linear_triton_0626_qkvz_ab_alt2_layer_mask();
    if (layer_index < 64u &&
        (alt2_layer_mask & (UINT64_C(1) << layer_index)) != UINT64_C(0)) {
        return q1_linear_triton_0626_qkvz_ab_alt2_warps();
    }
    const uint64_t alt_layer_mask =
        q1_linear_triton_0626_qkvz_ab_alt_layer_mask();
    return layer_index < 64u &&
            (alt_layer_mask & (UINT64_C(1) << layer_index)) != UINT64_C(0)
        ? q1_linear_triton_0626_qkvz_ab_alt_warps()
        : q1_linear_triton_0626_qkvz_ab_default_warps();
}

