uint64_t decode_one_request_fnv1a64(
    uint32_t input_token_id,
    float input_logit,
    unsigned int prefill_context_token_count,
    unsigned int decode_input_position,
    unsigned int decode_output_position,
    unsigned int expected_decode_output_token_count,
    uint64_t token_loop_digest,
    uint64_t sampled_output_hash,
    uint64_t sampler_hash,
    uint64_t descriptor_hash,
    uint64_t layer1_product_digest,
    uint64_t layer1_product_last,
    unsigned int decode_one_entrypoint_planned
) {
    uint64_t hash = UINT64_C(1469598103934665603);
    hash = qrt_fnv1a64_update_bytes(hash, &input_token_id, sizeof(input_token_id));
    hash = qrt_fnv1a64_update_bytes(hash, &input_logit, sizeof(input_logit));
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &prefill_context_token_count,
        sizeof(prefill_context_token_count)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &decode_input_position,
        sizeof(decode_input_position)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &decode_output_position,
        sizeof(decode_output_position)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &expected_decode_output_token_count,
        sizeof(expected_decode_output_token_count)
    );
    hash = qrt_fnv1a64_update_bytes(hash, &token_loop_digest, sizeof(token_loop_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &sampled_output_hash, sizeof(sampled_output_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &sampler_hash, sizeof(sampler_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &descriptor_hash, sizeof(descriptor_hash));
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &layer1_product_digest,
        sizeof(layer1_product_digest)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &layer1_product_last,
        sizeof(layer1_product_last)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &decode_one_entrypoint_planned,
        sizeof(decode_one_entrypoint_planned)
    );
    return hash;
}

uint64_t decode_one_digest_fnv1a64(
    uint64_t request_hash,
    uint64_t token_loop_digest,
    uint64_t descriptor_hash,
    uint64_t layer1_product_digest,
    unsigned int decode_input_position,
    unsigned int decode_output_position,
    uint32_t input_token_id
) {
    uint64_t hash = UINT64_C(1469598103934665603);
    hash = qrt_fnv1a64_update_bytes(hash, &request_hash, sizeof(request_hash));
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &token_loop_digest,
        sizeof(token_loop_digest)
    );
    hash = qrt_fnv1a64_update_bytes(hash, &descriptor_hash, sizeof(descriptor_hash));
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &layer1_product_digest,
        sizeof(layer1_product_digest)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &decode_input_position,
        sizeof(decode_input_position)
    );
    hash = qrt_fnv1a64_update_bytes(
        hash,
        &decode_output_position,
        sizeof(decode_output_position)
    );
    hash = qrt_fnv1a64_update_bytes(hash, &input_token_id, sizeof(input_token_id));
    return hash;
}

uint64_t fnv1a64_update_string(uint64_t hash, const std::string &value) {
    const size_t byte_count = value.size();
    hash = qrt_fnv1a64_update_bytes(hash, &byte_count, sizeof(byte_count));
    if (byte_count > 0u) {
        hash = qrt_fnv1a64_update_bytes(hash, value.data(), byte_count);
    }
    return hash;
}

uint64_t fnv1a64_update_u32_vector(
    uint64_t hash,
    const std::vector<uint32_t> &values
) {
    const size_t count = values.size();
    hash = qrt_fnv1a64_update_bytes(hash, &count, sizeof(count));
    if (count > 0u) {
        hash = qrt_fnv1a64_update_bytes(
            hash,
            values.data(),
            count * sizeof(values[0])
        );
    }
    return hash;
}

