void append_unique_u32(std::vector<uint32_t> *values, uint32_t value) {
    if (std::find(values->begin(), values->end(), value) == values->end()) {
        values->push_back(value);
    }
}

uint64_t decode_one_output_correctness_digest_fnv1a64(
    const DecodeOneExecutionRun &run,
    uint32_t output_token_id,
    float output_logit
) {
    uint64_t hash = UINT64_C(1469598103934665603);
    hash = qrt_fnv1a64_update_bytes(hash, &run.input_validation_digest, sizeof(run.input_validation_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &run.request_hash, sizeof(run.request_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.request_handoff_digest, sizeof(run.request_handoff_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &run.request_handoff_output_head_input_hash, sizeof(run.request_handoff_output_head_input_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.decode_input_position, sizeof(run.decode_input_position));
    hash = qrt_fnv1a64_update_bytes(hash, &run.decode_output_position, sizeof(run.decode_output_position));
    hash = qrt_fnv1a64_update_bytes(hash, &run.input_token_id, sizeof(run.input_token_id));
    hash = qrt_fnv1a64_update_bytes(hash, &output_token_id, sizeof(output_token_id));
    hash = qrt_fnv1a64_update_bytes(hash, &output_logit, sizeof(output_logit));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_topk_token_ids_hash, sizeof(run.output_head_topk_token_ids_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_topk_logits_hash, sizeof(run.output_head_topk_logits_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_sampler_hash, sizeof(run.output_head_sampler_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_input_hidden_hash, sizeof(run.output_head_input_hidden_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_final_norm_hash, sizeof(run.output_head_final_norm_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_logits_hash, sizeof(run.output_head_logits_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.output_head_weight_hash, sizeof(run.output_head_weight_hash));
    hash = qrt_fnv1a64_update_bytes(hash, &run.baseline_plain_block_output_hidden_hash, sizeof(run.baseline_plain_block_output_hidden_hash));
    return hash;
}

uint64_t decode_one_prompt_state_digest_fnv1a64(
    const DecodeOneExecutionRun &run
) {
    uint64_t hash = UINT64_C(1469598103934665603);
    hash = qrt_fnv1a64_update_bytes(hash, &run.prefill_context_token_count, sizeof(run.prefill_context_token_count));
    hash = qrt_fnv1a64_update_bytes(hash, &run.decode_input_position, sizeof(run.decode_input_position));
    hash = qrt_fnv1a64_update_bytes(hash, &run.input_token_id, sizeof(run.input_token_id));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_context_token_count, sizeof(run.report_prompt_context_token_count));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_position, sizeof(run.report_prompt_state_position));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_last_input_token, sizeof(run.report_prompt_last_input_token));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_summary_mode, sizeof(run.report_prompt_state_summary_mode));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_sequence_token_loop, sizeof(run.report_prompt_state_sequence_token_loop));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_full_sequence_prefill, sizeof(run.report_prompt_state_full_sequence_prefill));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_linear_attention_state_carried, sizeof(run.report_prompt_state_linear_attention_state_carried));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_state_full_attention_kv_carried, sizeof(run.report_prompt_state_full_attention_kv_carried));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_sequence_processed_token_count, sizeof(run.report_prompt_sequence_processed_token_count));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_sequence_digest, sizeof(run.report_prompt_sequence_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_linear_attention_state_digest, sizeof(run.report_prompt_linear_attention_state_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_full_attention_kv_digest, sizeof(run.report_prompt_full_attention_kv_digest));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_linear_attention_state_update_count, sizeof(run.report_prompt_linear_attention_state_update_count));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_full_attention_kv_update_count, sizeof(run.report_prompt_full_attention_kv_update_count));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_linear_attention_state_bytes, sizeof(run.report_prompt_linear_attention_state_bytes));
    hash = qrt_fnv1a64_update_bytes(hash, &run.report_prompt_full_attention_kv_bytes, sizeof(run.report_prompt_full_attention_kv_bytes));
    return hash;
}

