float selected_conv_window_cpu_value(
    const std::vector<float> &window_qkv,
    const uint16_t *conv_weights,
    const std::vector<uint32_t> &source_window_indices,
    size_t target_index,
    unsigned int feature
) {
    float acc = 0.0f;
    for (unsigned int tap = 0; tap < kConvKernel; ++tap) {
        const uint32_t window_index =
            source_window_indices[target_index * static_cast<size_t>(kConvKernel) + tap];
        if (window_index != UINT32_MAX) {
            const float qkv_value = bf16_round_to_float(
                window_qkv[static_cast<size_t>(window_index) * kQkvRows + feature]
            );
            const float weight = qrt_bf16_to_float(conv_weights[feature * kConvKernel + tap]);
            acc = fmaf(qkv_value, weight, acc);
        }
    }
    return silu_bf16_from_f32_acc(bf16_round_to_float(acc));
}

float decode_conv_cache_cpu_value(
    const std::vector<float> &current_qkv,
    const float *cache_qkv_ring,
    const uint16_t *conv_weights,
    size_t token_position,
    size_t target_index,
    unsigned int feature,
    bool preserve_f32_acc_before_silu
) {
    float acc = 0.0f;
    const size_t absolute_token = token_position + target_index;
    for (unsigned int tap = 0; tap < kConvKernel; ++tap) {
        if (absolute_token + tap >= static_cast<size_t>(kConvKernel - 1u)) {
            const size_t source_token =
                absolute_token + tap - static_cast<size_t>(kConvKernel - 1u);
            float qkv_value = 0.0f;
            if (source_token >= token_position) {
                const size_t current_block_token = source_token - token_position;
                qkv_value =
                    current_qkv[current_block_token * static_cast<size_t>(kQkvRows) +
                                feature];
            } else if (cache_qkv_ring != nullptr) {
                const size_t source_slot =
                    source_token % static_cast<size_t>(kConvKernel);
                qkv_value =
                    cache_qkv_ring[source_slot * static_cast<size_t>(kQkvRows) +
                                   feature];
            }
            qkv_value = bf16_round_to_float(qkv_value);
            const float weight =
                qrt_bf16_to_float(conv_weights[feature * kConvKernel + tap]);
            if (preserve_f32_acc_before_silu) {
                acc += bf16_round_to_float(qkv_value * weight);
            } else {
                acc = fmaf(qkv_value, weight, acc);
            }
        }
    }
    return preserve_f32_acc_before_silu
        ? triton_silu_bf16_from_f32_acc(acc)
        : silu_bf16_from_f32_acc(bf16_round_to_float(acc));
}

float selected_postconv_window_cpu_value(
    const std::vector<float> &conv_values,
    size_t target_index,
    unsigned int row
) {
    const size_t token_base = target_index * static_cast<size_t>(kQkvRows);
    if (row < kKeyFeatures) {
        const unsigned int head_base = (row / kKeyDim) * kKeyDim;
        float q_sumsq = 0.0f;
        for (unsigned int dim = 0; dim < kKeyDim; ++dim) {
            const float q_value = conv_values[token_base + head_base + dim];
            q_sumsq += q_value * q_value;
        }
        const float q_inv = 1.0f / sqrtf(q_sumsq + 1.0e-6f);
        const float q_value = conv_values[token_base + row];
        const float q_norm = bf16_round_to_float(q_value * q_inv);
        return q_norm * kQScale;
    }
    if (row < 2u * kKeyFeatures) {
        const unsigned int key_row = row - kKeyFeatures;
        const unsigned int head_base = (key_row / kKeyDim) * kKeyDim;
        float k_sumsq = 0.0f;
        for (unsigned int dim = 0; dim < kKeyDim; ++dim) {
            const float k_value = conv_values[token_base + kKeyFeatures + head_base + dim];
            k_sumsq += k_value * k_value;
        }
        const float k_inv = 1.0f / sqrtf(k_sumsq + 1.0e-6f);
        const float k_value = conv_values[token_base + row];
        return bf16_round_to_float(k_value * k_inv);
    }
    return bf16_round_to_float(conv_values[token_base + row]);
}

bool materialize_qrt_host_postconv_window_handoff(
    const Layer1ConvWindowRun &conv_window_run,
    Layer1PostconvWindowRun *run
) {
    if (run == nullptr ||
        run->target_token_count == 0u ||
        conv_window_run.gpu_output.size() !=
            run->target_token_count * static_cast<size_t>(kQkvRows) ||
        run->gpu_output.size() !=
            run->target_token_count * static_cast<size_t>(kQkvRows)) {
        return false;
    }

    for (size_t target_index = 0u;
         target_index < run->target_token_count;
         ++target_index) {
        const size_t token_base = target_index * static_cast<size_t>(kQkvRows);
        for (unsigned int head = 0u; head < kKeyHeads; ++head) {
            const unsigned int head_base = head * kKeyDim;
            float q_sumsq = 0.0f;
            float k_sumsq = 0.0f;
            for (unsigned int dim = 0u; dim < kKeyDim; ++dim) {
                const float q_value =
                    conv_window_run.gpu_output[token_base + head_base + dim];
                const float k_value =
                    conv_window_run
                        .gpu_output[token_base + kKeyFeatures + head_base + dim];
                q_sumsq += q_value * q_value;
                k_sumsq += k_value * k_value;
            }
            const float q_inv = 1.0f / sqrtf(q_sumsq + 1.0e-6f);
            const float k_inv = 1.0f / sqrtf(k_sumsq + 1.0e-6f);
            for (unsigned int dim = 0u; dim < kKeyDim; ++dim) {
                const size_t q_index = token_base + head_base + dim;
                const size_t k_index =
                    token_base + kKeyFeatures + head_base + dim;
                run->gpu_output[q_index] =
                    bf16_round_to_float(
                        conv_window_run.gpu_output[q_index] * q_inv
                    ) * kQScale;
                run->gpu_output[k_index] =
                    bf16_round_to_float(
                        conv_window_run.gpu_output[k_index] * k_inv
                    );
            }
        }
        for (unsigned int feature = 0u; feature < kValueFeatures; ++feature) {
            const size_t value_index =
                token_base + 2u * kKeyFeatures + feature;
            run->gpu_output[value_index] =
                bf16_round_to_float(conv_window_run.gpu_output[value_index]);
        }
    }
    return true;
}

std::vector<unsigned int> selected_full_attention_qk_norm_rows() {
    const unsigned int candidates[] = {
        0u,
        127u,
        1024u,
        2047u,
        4095u,
        4096u,
        6143u,
        8191u,
        8192u,
        8319u,
        8703u,
        8704u,
        8831u,
        9215u
    };
    std::vector<unsigned int> selected;
    for (unsigned int row : candidates) {
        if (row < kLayer3FullAttentionQkvRows) {
            selected.push_back(row);
        }
    }
    return selected;
}

float selected_full_attention_qk_norm_cpu_value(
    const std::vector<float> &qkv_values,
    const uint16_t *q_norm_weight,
    const uint16_t *k_norm_weight,
    size_t selected_index,
    unsigned int row
) {
    const size_t token_base =
        selected_index * static_cast<size_t>(kLayer3FullAttentionQkvRows);
    if (row < kLayer3FullAttentionQFeatures) {
        const unsigned int head = row / kLayer3FullAttentionHeadDim;
        const unsigned int dim = row % kLayer3FullAttentionHeadDim;
        const size_t source_base =
            static_cast<size_t>(head) * kLayer3FullAttentionHeadDim * 2u;
        double sumsq = 0.0;
        for (unsigned int i = 0; i < kLayer3FullAttentionHeadDim; ++i) {
            const float value = qkv_values[token_base + source_base + i];
            sumsq += static_cast<double>(value) * static_cast<double>(value);
        }
        const float inv = 1.0f / sqrtf(
            static_cast<float>(sumsq / static_cast<double>(kLayer3FullAttentionHeadDim)) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
        const float value =
            qkv_values[token_base + source_base + dim] *
            inv *
            (1.0f + qrt_bf16_to_float(q_norm_weight[dim]));
        return bf16_round_to_float(value);
    }
    if (row < 2u * kLayer3FullAttentionQFeatures) {
        const unsigned int gate_row = row - kLayer3FullAttentionQFeatures;
        const unsigned int head = gate_row / kLayer3FullAttentionHeadDim;
        const unsigned int dim = gate_row % kLayer3FullAttentionHeadDim;
        const size_t source_base =
            static_cast<size_t>(head) * kLayer3FullAttentionHeadDim * 2u;
        return qkv_values[
            token_base +
            source_base +
            kLayer3FullAttentionHeadDim +
            dim
        ];
    }
    if (row < 2u * kLayer3FullAttentionQFeatures + kLayer3FullAttentionKvFeatures) {
        const unsigned int k_row = row - 2u * kLayer3FullAttentionQFeatures;
        const unsigned int head = k_row / kLayer3FullAttentionHeadDim;
        const unsigned int dim = k_row % kLayer3FullAttentionHeadDim;
        const size_t source_base =
            static_cast<size_t>(head) * kLayer3FullAttentionHeadDim;
        double sumsq = 0.0;
        for (unsigned int i = 0; i < kLayer3FullAttentionHeadDim; ++i) {
            const float value =
                qkv_values[
                    token_base +
                    kLayer3FullAttentionQRows +
                    source_base +
                    i
                ];
            sumsq += static_cast<double>(value) * static_cast<double>(value);
        }
        const float inv = 1.0f / sqrtf(
            static_cast<float>(sumsq / static_cast<double>(kLayer3FullAttentionHeadDim)) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
        const float value =
            qkv_values[
                token_base +
                kLayer3FullAttentionQRows +
                source_base +
                dim
            ] *
            inv *
            (1.0f + qrt_bf16_to_float(k_norm_weight[dim]));
        return bf16_round_to_float(value);
    }

    const unsigned int v_row =
        row - 2u * kLayer3FullAttentionQFeatures - kLayer3FullAttentionKvFeatures;
    return qkv_values[
        token_base +
        kLayer3FullAttentionQRows +
        kLayer3FullAttentionKRows +
        v_row
    ];
}

