    descriptor.core_shape_contract_failure =
        "selected " + human_layer + " core inputs have unexpected shape";
    descriptor.core_correctness_failure =
        "selected CPU/HIP " + human_layer + " zero-state core rows boundary exceeded tolerance";

    descriptor.gated_rmsnorm_name = layer + "_gated_rmsnorm";
    descriptor.gated_rmsnorm_stage = layer + "_selected_gated_rmsnorm_prefill_phase";
    descriptor.out_projection_name = layer + "_out_projection";
