bool token_index_in_window(
    const std::vector<unsigned int> &window_tokens,
    unsigned int token,
    uint32_t *out_index
) {
    if (window_tokens.size() >= 64u &&
        token >= window_tokens.front() &&
        token <= window_tokens.back()) {
        const unsigned int first = window_tokens.front();
        const unsigned int last = window_tokens.back();
        if (last >= first &&
            window_tokens.size() ==
                static_cast<size_t>(last - first) + 1u) {
            const size_t index = static_cast<size_t>(token - first);
            if (window_tokens[index] == token) {
                *out_index = static_cast<uint32_t>(index);
                return true;
            }
        }
        const auto found = std::lower_bound(
            window_tokens.begin(),
            window_tokens.end(),
            token
        );
        if (found != window_tokens.end() && *found == token) {
            *out_index = static_cast<uint32_t>(
                static_cast<size_t>(found - window_tokens.begin())
            );
            return true;
        }
    }
    for (size_t i = 0; i < window_tokens.size(); ++i) {
        if (window_tokens[i] == token) {
            *out_index = static_cast<uint32_t>(i);
            return true;
        }
    }
    return false;
}

bool build_conv_source_window_indices(
    const std::vector<unsigned int> &target_tokens,
    const std::vector<unsigned int> &window_tokens,
    std::vector<uint32_t> *out_indices
) {
    out_indices->assign(
        target_tokens.size() * static_cast<size_t>(kConvKernel),
        UINT32_MAX
    );
    for (size_t target_index = 0; target_index < target_tokens.size(); ++target_index) {
        const unsigned int token = target_tokens[target_index];
        for (unsigned int tap = 0; tap < kConvKernel; ++tap) {
            if (token + tap < kConvKernel - 1u) {
                continue;
            }
            const unsigned int source_token = token + tap - (kConvKernel - 1u);
            uint32_t window_index = UINT32_MAX;
            if (!token_index_in_window(window_tokens, source_token, &window_index)) {
                return false;
            }
            (*out_indices)[target_index * static_cast<size_t>(kConvKernel) + tap] = window_index;
        }
    }
    return true;
}

std::vector<unsigned int> selected_rows(unsigned int rows) {
    const unsigned int candidates[] = {0u, 127u, 1024u, 2047u, 4095u, 4096u, 6143u, 8191u};
    std::vector<unsigned int> selected;
    auto add_row = [&](unsigned int row) {
        if (row >= rows) {
            return;
        }
        bool exists = false;
        for (unsigned int prior : selected) {
            exists = exists || prior == row;
        }
        if (!exists) {
            selected.push_back(row);
        }
    };
    for (unsigned int row : candidates) {
        add_row(row);
    }
    if (selected.size() < 4u) {
        add_row(rows / 3u);
        add_row((rows * 2u) / 3u);
        add_row(rows - 1u);
    }
    return selected;
}

std::vector<unsigned int> selected_lm_head_rows(
    const uint32_t *reference_topk_ids,
    const uint32_t *gpu_topk_ids
) {
    std::vector<unsigned int> selected = selected_rows(QRT_QWEN36_VOCAB_SIZE);
    auto add_row = [&](uint32_t row) {
        if (row >= static_cast<uint32_t>(QRT_QWEN36_VOCAB_SIZE)) {
            return;
        }
        bool exists = false;
        for (unsigned int prior : selected) {
            exists = exists || prior == row;
        }
        if (!exists) {
            selected.push_back(static_cast<unsigned int>(row));
        }
    };
    add_row(static_cast<uint32_t>(QRT_QWEN36_VOCAB_SIZE - 1u));
    for (size_t slot = 0; slot < static_cast<size_t>(QRT_QWEN36_OUTPUT_HEAD_SAMPLER_TOPK); ++slot) {
        add_row(reference_topk_ids[slot]);
        add_row(gpu_topk_ids[slot]);
    }
    return selected;
}

