bool resident_bf16_matrix_plan_ready(
    unsigned int output_features,
    unsigned int input_features,
    unsigned int token_count,
    bool output_f32,
    unsigned int heuristic_index,
    size_t *workspace_bytes
) {
    if (workspace_bytes != nullptr) {
        *workspace_bytes = 0u;
    }
    if (!g_resident_bf16_matrix_provider ||
        g_resident_bf16_matrix_provider->handle == nullptr) {
        return false;
    }
    ResidentBf16MatrixProvider *provider =
        g_resident_bf16_matrix_provider.get();
    const uint64_t key = resident_bf16_matrix_plan_key(
        output_features,
        input_features,
        token_count,
        output_f32,
        heuristic_index
    );
    const auto found = provider->plans.find(key);
    if (found == provider->plans.end() || found->second == nullptr ||
        found->second->workspace_bytes > provider->workspace_bytes ||
        (found->second->workspace_bytes != 0u &&
         provider->workspace == nullptr)) {
        return false;
    }
    if (workspace_bytes != nullptr) {
        *workspace_bytes = found->second->workspace_bytes;
    }
    return true;
}

bool prewarm_q8192_resident_bf16_matrix_plans(
    size_t *plan_count,
    std::string *failure_stage,
    std::string *failure
) {
    struct PlanShape {
        unsigned int output_features;
        unsigned int input_features;
        unsigned int token_count;
        bool output_f32;
    };
    const std::array<PlanShape, 19> shapes = {{
        {kQkvRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, true},
        {kZRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, true},
        {kAbRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, true},
        {kOutProjectionRows, kValueFeatures, kRetainedPrefillTokens, true},
        {kQkvRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, false},
        {kZRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, false},
        {kAbRows, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, false},
        {kOutProjectionRows, kValueFeatures, kRetainedPrefillTokens, false},
        {1u, QRT_QWEN36_HIDDEN_SIZE, kRetainedPrefillTokens, false},
        {QRT_QWEN36_MOE_EXPERT_INTERMEDIATE, QRT_QWEN36_HIDDEN_SIZE,
         kRetainedPrefillTokens, false},
        {QRT_QWEN36_HIDDEN_SIZE, QRT_QWEN36_MOE_EXPERT_INTERMEDIATE,
         kRetainedPrefillTokens, false},
        {kLayer3FullAttentionQRows, QRT_QWEN36_HIDDEN_SIZE,
         kRetainedPrefillTokens, false},
        {kLayer3FullAttentionKRows, QRT_QWEN36_HIDDEN_SIZE,
         kRetainedPrefillTokens, false},
        {kOutProjectionRows, kLayer3FullAttentionQFeatures, 4u, false},
        {QRT_QWEN36_VOCAB_SIZE, QRT_QWEN36_HIDDEN_SIZE, 4u, false},
        {QRT_QWEN36_VOCAB_SIZE, QRT_QWEN36_HIDDEN_SIZE, 1u, false},
        // Decode selected-MoE plans are created outside the guarded token
        // mutation so first-token route setup is not charged to TPOT.
        {1u, QRT_QWEN36_HIDDEN_SIZE, 1u, false},
        {QRT_QWEN36_MOE_EXPERT_INTERMEDIATE,
         QRT_QWEN36_HIDDEN_SIZE, 1u, false},
        {QRT_QWEN36_HIDDEN_SIZE,
         QRT_QWEN36_MOE_EXPERT_INTERMEDIATE, 1u, false}
    }};
    ResidentBf16MatrixProvider *provider = nullptr;
    if (!ensure_resident_bf16_matrix_provider(
            &provider,
            failure_stage,
            failure
        )) {
        return false;
    }
    const unsigned int lm_head_heuristic_index = env_u32_or_default(
        "QRT_PREFILL_DESCRIPTOR_BATCH_LM_HEAD_HIPBLASLT_HEURISTIC_INDEX",
        0u
    );
    for (const PlanShape &shape : shapes) {
        ResidentBf16MatrixPlan *plan = nullptr;
        const unsigned int heuristic_index =
            shape.output_features == QRT_QWEN36_VOCAB_SIZE &&
                    shape.input_features == QRT_QWEN36_HIDDEN_SIZE &&
                    (shape.token_count == 1u || shape.token_count == 4u)
                ? lm_head_heuristic_index
                : 0u;
        if (!create_resident_bf16_matrix_plan(
                provider,
                shape.output_features,
                shape.input_features,
                shape.token_count,
                shape.output_f32,
                heuristic_index,
                &plan,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_HIPBLASLT_QKVZ"
        )) {
        const unsigned int q1_linear_qkvz_heuristic_index =
            env_u32_or_default(
                "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_HIPBLASLT_QKVZ_HEURISTIC_INDEX",
                0u
            );
        ResidentBf16MatrixPlan *plan = nullptr;
        if (!create_resident_bf16_matrix_plan(
                provider,
                kQkvRows + kZRows,
                QRT_QWEN36_HIDDEN_SIZE,
                1u,
                false,
                q1_linear_qkvz_heuristic_index,
                &plan,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_DEVICE_CHAIN"
        )) {
        const unsigned int out_heuristic_index = env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_DEVICE_CHAIN_OUT_HEURISTIC_INDEX",
            15u
        );
        ResidentBf16MatrixPlan *out_plan = nullptr;
        if (!create_resident_bf16_matrix_plan(
                provider,
                kOutProjectionRows,
                kValueFeatures,
                1u,
                false,
                out_heuristic_index,
                &out_plan,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_HIPBLASLT_PROJECTIONS"
        )) {
        const unsigned int q_heuristic_index = env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_HIPBLASLT_Q_HEURISTIC_INDEX",
            3u
        );
        const unsigned int kv_heuristic_index = env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_HIPBLASLT_KV_HEURISTIC_INDEX",
            5u
        );
        const unsigned int out_heuristic_index = env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_HIPBLASLT_OUT_HEURISTIC_INDEX",
            15u
        );
        ResidentBf16MatrixPlan *q_plan = nullptr;
        ResidentBf16MatrixPlan *kv_plan = nullptr;
        ResidentBf16MatrixPlan *out_plan = nullptr;
        if (!create_resident_bf16_matrix_plan(
                provider,
                kLayer3FullAttentionQRows,
                QRT_QWEN36_HIDDEN_SIZE,
                1u,
                false,
                q_heuristic_index,
                &q_plan,
                failure_stage,
                failure
            ) ||
            !create_resident_bf16_matrix_plan(
                provider,
                kLayer3FullAttentionKRows,
                QRT_QWEN36_HIDDEN_SIZE,
                1u,
                false,
                kv_heuristic_index,
                &kv_plan,
                failure_stage,
                failure
            ) ||
            !create_resident_bf16_matrix_plan(
                provider,
                kOutProjectionRows,
                kLayer3FullAttentionQFeatures,
                1u,
                false,
                out_heuristic_index,
                &out_plan,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    const unsigned int full_attention_qkv_heuristic_index = env_u32_or_default(
        "QRT_PREFILL_DESCRIPTOR_BATCH_FULL_ATTENTION_QKV_HIPBLASLT_HEURISTIC_INDEX",
        0u
    );
    if (full_attention_qkv_heuristic_index != 0u &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_FULL_ATTENTION_QKV_HIPBLASLT_PROJECTION"
        )) {
        const std::array<unsigned int, 2> projection_rows = {
            kLayer3FullAttentionQRows,
            kLayer3FullAttentionKRows
        };
        for (unsigned int rows : projection_rows) {
            ResidentBf16MatrixPlan *plan = nullptr;
            if (!create_resident_bf16_matrix_plan(
                    provider,
                    rows,
                    QRT_QWEN36_HIDDEN_SIZE,
                    kRetainedPrefillTokens,
                    false,
                    full_attention_qkv_heuristic_index,
                    &plan,
                    failure_stage,
                    failure
                )) {
                return false;
            }
        }
    }
    if (plan_count != nullptr) {
        *plan_count = provider->plans.size();
    }
    return true;
}

bool prewarm_q262144_resident_bf16_matrix_plans(
    unsigned int prefill_tokens,
    size_t *plan_count,
    std::string *failure_stage,
    std::string *failure
) {
    if (!maximum_context_streamed_prefill_tokens(prefill_tokens)) {
        *failure_stage = "maximum_context_matrix_provider_prewarm_shape";
        *failure = "streamed BF16 matrix prewarm received an unsupported context";
        return false;
    }
    const unsigned int linear_chunk_tokens =
        maximum_context_linear_chunk_tokens(prefill_tokens);
    struct PlanShape {
        unsigned int output_features;
        unsigned int input_features;
        unsigned int token_count;
        unsigned int heuristic_index;
    };
    const unsigned int full_attention_qkv_heuristic_index =
        env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_FULL_ATTENTION_QKV_HIPBLASLT_HEURISTIC_INDEX",
            0u
        );
    const unsigned int full_attention_tail_tokens =
        prefill_tokens % kRetainedPrefillTokens != 0u
            ? prefill_tokens % kRetainedPrefillTokens
            : kRetainedPrefillTokens;
    const unsigned int linear_tail_tokens =
        prefill_tokens % linear_chunk_tokens != 0u
            ? prefill_tokens % linear_chunk_tokens
            : linear_chunk_tokens;
    // Maximum-context linear projections use bounded temporal chunks.  Full
    // attention projects Q and output at the q8192 attention-tile boundary;
    // K/V remain complete-context matrices below the 2^31-element boundary.
    const std::array<PlanShape, 14> shapes = {{
        {kQkvRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_chunk_tokens, 0u},
        {kZRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_chunk_tokens, 0u},
        {kAbRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_chunk_tokens, 0u},
        {kOutProjectionRows, kValueFeatures,
         linear_chunk_tokens, 0u},
        {kQkvRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_tail_tokens, 0u},
        {kZRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_tail_tokens, 0u},
        {kAbRows, QRT_QWEN36_HIDDEN_SIZE,
         linear_tail_tokens, 0u},
        {kOutProjectionRows, kValueFeatures,
         linear_tail_tokens, 0u},
        {kLayer3FullAttentionQRows, QRT_QWEN36_HIDDEN_SIZE,
         kRetainedPrefillTokens,
         full_attention_qkv_heuristic_index},
        {kLayer3FullAttentionKRows, QRT_QWEN36_HIDDEN_SIZE,
         prefill_tokens,
         full_attention_qkv_heuristic_index},
        {kLayer3FullAttentionVRows, QRT_QWEN36_HIDDEN_SIZE,
         prefill_tokens,
         full_attention_qkv_heuristic_index},
        {kOutProjectionRows, kLayer3FullAttentionQFeatures,
         kRetainedPrefillTokens, 0u},
        {kLayer3FullAttentionQRows, QRT_QWEN36_HIDDEN_SIZE,
         full_attention_tail_tokens,
         full_attention_qkv_heuristic_index},
        {kOutProjectionRows, kLayer3FullAttentionQFeatures,
         full_attention_tail_tokens, 0u}
    }};
    ResidentBf16MatrixProvider *provider = nullptr;
    if (!ensure_resident_bf16_matrix_provider(
            &provider,
            failure_stage,
            failure
        )) {
        return false;
    }
    for (size_t shape_index = 0u;
         shape_index < shapes.size();
         ++shape_index) {
        const PlanShape &shape = shapes[shape_index];
        ResidentBf16MatrixPlan *plan = nullptr;
        if (!create_resident_bf16_matrix_plan(
                provider,
                shape.output_features,
                shape.input_features,
                shape.token_count,
                false,
                shape.heuristic_index,
                &plan,
                failure_stage,
                failure
            )) {
            return false;
        }
        std::cerr
            << "BATCH_MARK q262144_matrix_plan_prewarm_shape"
            << " phase=created"
            << " shape=" << shape_index
            << " output_features=" << shape.output_features
            << " input_features=" << shape.input_features
            << " tokens=" << shape.token_count
            << " heuristic_index=" << shape.heuristic_index
            << " workspace_bytes="
            << (plan != nullptr ? plan->workspace_bytes : 0u)
            << std::endl;
        if (!check_hip(
                hipDeviceSynchronize(),
                "sync_q262144_matrix_plan_prewarm_shape_" +
                    std::to_string(shape_index),
                failure_stage,
                failure
            )) {
            return false;
        }
        std::cerr
            << "BATCH_MARK q262144_matrix_plan_prewarm_shape"
            << " phase=ready"
            << " shape=" << shape_index
            << " output_features=" << shape.output_features
            << " input_features=" << shape.input_features
            << " tokens=" << shape.token_count
            << " heuristic_index=" << shape.heuristic_index
            << " workspace_bytes="
            << (plan != nullptr ? plan->workspace_bytes : 0u)
            << std::endl;
    }
    if (plan_count != nullptr) {
        *plan_count = provider->plans.size();
    }
    return true;
}
