struct RepeatedAsyncZProjectionLane {
    hipStream_t stream = nullptr;

    RepeatedAsyncZProjectionLane() = default;
    RepeatedAsyncZProjectionLane(const RepeatedAsyncZProjectionLane &) = delete;
    RepeatedAsyncZProjectionLane &operator=(
        const RepeatedAsyncZProjectionLane &
    ) = delete;

    ~RepeatedAsyncZProjectionLane() {
        if (stream != nullptr) {
            (void)hipStreamSynchronize(stream);
            (void)hipStreamDestroy(stream);
        }
    }
};

thread_local std::unique_ptr<RepeatedAsyncZProjectionLane>
    g_repeated_async_z_projection_lane;

constexpr size_t kQ1TerminalDeviceCorridorWorkspaceBytes =
    128u * 1024u;

struct Q1TerminalDeviceCorridorWorkspace {
    unsigned char *device_base = nullptr;
    size_t bytes = 0u;
    bool preloaded = false;
    bool routed_surface_ready = false;
    uint64_t routed_surface_token_ids_hash = UINT64_C(0);
};

Q1TerminalDeviceCorridorWorkspace g_q1_terminal_device_corridor_workspace;

bool q1_terminal_device_corridor_workspace_contains(const void *ptr) {
    if (ptr == nullptr ||
        g_q1_terminal_device_corridor_workspace.device_base == nullptr ||
        g_q1_terminal_device_corridor_workspace.bytes == 0u) {
        return false;
    }
    const uintptr_t value = reinterpret_cast<uintptr_t>(ptr);
    const uintptr_t begin = reinterpret_cast<uintptr_t>(
        g_q1_terminal_device_corridor_workspace.device_base
    );
    return value >= begin &&
        value - begin < g_q1_terminal_device_corridor_workspace.bytes;
}

void release_q1_terminal_device_corridor_workspace() {
    if (g_q1_terminal_device_corridor_workspace.device_base != nullptr) {
        (void)hipFree(g_q1_terminal_device_corridor_workspace.device_base);
    }
    g_q1_terminal_device_corridor_workspace =
        Q1TerminalDeviceCorridorWorkspace{};
}

bool preload_q1_terminal_device_corridor_workspace(
    std::string *failure_stage,
    std::string *failure
) {
    if (!env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_TERMINAL_DEVICE_CORRIDOR"
        )) {
        return true;
    }
    if (g_q1_terminal_device_corridor_workspace.device_base != nullptr &&
        g_q1_terminal_device_corridor_workspace.bytes >=
            kQ1TerminalDeviceCorridorWorkspaceBytes &&
        g_q1_terminal_device_corridor_workspace.preloaded) {
        return true;
    }

    release_q1_terminal_device_corridor_workspace();
    void *device_base = nullptr;
    const hipError_t status = hipMalloc(
        &device_base,
        kQ1TerminalDeviceCorridorWorkspaceBytes
    );
    if (status != hipSuccess || device_base == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage = "q1_terminal_device_corridor_workspace_preload";
        }
        if (failure != nullptr) {
            *failure = std::string(
                "failed to allocate the q8192 Q1 terminal device corridor workspace: "
            ) + hipGetErrorString(status);
        }
        return false;
    }
    g_q1_terminal_device_corridor_workspace.device_base =
        static_cast<unsigned char *>(device_base);
    g_q1_terminal_device_corridor_workspace.bytes =
        kQ1TerminalDeviceCorridorWorkspaceBytes;
    g_q1_terminal_device_corridor_workspace.preloaded = true;
    std::cerr
        << "BATCH_MARK q1_terminal_device_corridor_workspace_preload"
        << " bytes=" << kQ1TerminalDeviceCorridorWorkspaceBytes
        << " measured_prefill=0"
        << std::endl;
    return true;
}

bool ensure_repeated_async_z_projection_lane(
    hipStream_t *stream,
    std::string *failure_stage,
    std::string *failure
) {
    if (stream == nullptr || failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    if (!g_repeated_async_z_projection_lane) {
        g_repeated_async_z_projection_lane =
            std::make_unique<RepeatedAsyncZProjectionLane>();
    }
    RepeatedAsyncZProjectionLane *lane =
        g_repeated_async_z_projection_lane.get();
    if (lane->stream == nullptr &&
        !check_hip(
            hipStreamCreateWithFlags(&lane->stream, hipStreamNonBlocking),
            "repeated_async_z_projection_stream_create",
            failure_stage,
            failure
        )) {
        return false;
    }
    *stream = lane->stream;
    return true;
}

hipError_t qrt_descriptor_raw_device_malloc(void **ptr, size_t bytes) {
    return hipMalloc(ptr, bytes);
}

hipError_t qrt_descriptor_device_malloc(void **ptr, size_t bytes) {
    if (ptr == nullptr) {
        return hipErrorInvalidValue;
    }
    *ptr = nullptr;
    if (!g_descriptor_product_reuse_device_allocations || bytes == 0u) {
        return hipMalloc(ptr, bytes);
    }

    std::lock_guard<std::mutex> lock(g_descriptor_device_allocation_pool_mutex);
    ++g_descriptor_device_allocation_pool_stats.request_count;
    size_t best_index = (std::numeric_limits<size_t>::max)();
    size_t best_bytes = (std::numeric_limits<size_t>::max)();
    for (size_t index = 0; index < g_descriptor_device_allocation_pool.size(); ++index) {
        const DescriptorDeviceAllocationPoolBlock &block =
            g_descriptor_device_allocation_pool[index];
        if (!block.in_use &&
            block.ptr != nullptr &&
            block.bytes >= bytes &&
            block.bytes < best_bytes) {
            best_index = index;
            best_bytes = block.bytes;
        }
    }
    if (best_index != (std::numeric_limits<size_t>::max)()) {
        DescriptorDeviceAllocationPoolBlock &block =
            g_descriptor_device_allocation_pool[best_index];
        block.in_use = true;
        *ptr = block.ptr;
        ++g_descriptor_device_allocation_pool_stats.reuse_count;
        return hipSuccess;
    }

    void *allocated = nullptr;
    const hipError_t status = hipMalloc(&allocated, bytes);
    if (status != hipSuccess) {
        return status;
    }
    DescriptorDeviceAllocationPoolBlock block;
    block.ptr = allocated;
    block.bytes = bytes;
    block.in_use = true;
    g_descriptor_device_allocation_pool.push_back(block);
    ++g_descriptor_device_allocation_pool_stats.new_allocation_count;
    g_descriptor_device_allocation_pool_stats.peak_cached_bytes = (std::max)(
        g_descriptor_device_allocation_pool_stats.peak_cached_bytes,
        descriptor_device_allocation_pool_cached_bytes()
    );
    *ptr = allocated;
    return hipSuccess;
}

hipError_t qrt_unpooled_device_malloc(void **ptr, size_t bytes) {
    return hipMalloc(ptr, bytes);
}

bool whole_repeated_layer_fixed_weight_contains(const void *ptr);
bool qwen36_resident_decode_activation_workspace_contains(const void *ptr);

void free_device(void *ptr) {
    if (ptr == nullptr) {
        return;
    }
    if (q1_terminal_device_corridor_workspace_contains(ptr)) {
        return;
    }
    if (qwen36_resident_decode_activation_workspace_contains(ptr)) {
        return;
    }
    if (whole_repeated_layer_fixed_weight_contains(ptr)) {
        return;
    }
    if (g_descriptor_product_reuse_device_allocations) {
        std::lock_guard<std::mutex> lock(
            g_descriptor_device_allocation_pool_mutex
        );
        for (DescriptorDeviceAllocationPoolBlock &block :
             g_descriptor_device_allocation_pool) {
            if (block.ptr == ptr) {
                if (block.in_use) {
                    block.in_use = false;
                    ++g_descriptor_device_allocation_pool_stats.release_count;
                }
                return;
            }
        }
    }
    (void)hipFree(ptr);
}

enum class Qwen36ResidentSessionElementKind : uint32_t {
    kNone = 0u,
    kBf16 = 1u,
    kF32 = 2u
};

bool qwen36_q1_full_attention_terminal_bf16_requested() {
    return env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_TERMINAL_BF16"
    );
}

Qwen36ResidentSessionElementKind
qwen36_resident_full_attention_native_kind(unsigned int layer_index) {
    return layer_index + 1u == QRT_QWEN36_LAYER_COUNT &&
            !qwen36_q1_full_attention_terminal_bf16_requested()
        ? Qwen36ResidentSessionElementKind::kF32
        : Qwen36ResidentSessionElementKind::kBf16;
}

constexpr size_t kQwen36ResidentDecodeActivationWorkspaceAlignment = 256u;
constexpr size_t kQ1MoePriorityEventSlotCount =
    QRT_QWEN36_LAYER_COUNT - 2u;
constexpr size_t kQ1LayerProfileBoundaryCount = 19u;
constexpr size_t kQ1CoarseDecodeGpuSpanEventCount = 5u;
constexpr size_t kQ1CoarseDecodeCategoryBoundaryCount = 3u;
constexpr size_t kQ1CoarseDecodeCategoryLayerCount =
    QRT_QWEN36_LAYER_COUNT;
constexpr unsigned int kQ1DecodeLayerPacingAllBoundariesMask = 0x7u;

constexpr size_t q1_decode_layer_pacing_boundary_count(
    unsigned int mask
) {
    return static_cast<size_t>((mask & 0x1u) != 0u) +
        static_cast<size_t>((mask & 0x2u) != 0u) +
        static_cast<size_t>((mask & 0x4u) != 0u);
}

constexpr bool q1_decode_layer_pacing_stride_valid(unsigned int stride) {
    return stride == 1u || stride == 2u || stride == 4u;
}

constexpr bool q1_decode_layer_pacing_layer_selected(
    size_t layer,
    unsigned int stride,
    unsigned int phase
) {
    return q1_decode_layer_pacing_stride_valid(stride) &&
        phase < stride && layer % stride == phase;
}

constexpr size_t q1_decode_layer_pacing_selected_layer_count(
    unsigned int stride,
    unsigned int phase
) {
    size_t count = 0u;
    for (size_t layer = 0u;
         layer < kQ1CoarseDecodeCategoryLayerCount;
         ++layer) {
        count += static_cast<size_t>(
            q1_decode_layer_pacing_layer_selected(layer, stride, phase)
        );
    }
    return count;
}

