constexpr size_t qwen36_resident_decode_activation_workspace_align_up(
    size_t value
) {
    return (value +
            kQwen36ResidentDecodeActivationWorkspaceAlignment - 1u) &
        ~(kQwen36ResidentDecodeActivationWorkspaceAlignment - 1u);
}

constexpr size_t kQwen36ResidentFullAttentionScoreScratchOffset = 0u;
constexpr size_t qwen36_resident_full_attention_score_scratch_bytes(
    size_t token_capacity
) {
    return static_cast<size_t>(kLayer3FullAttentionHeads) *
        token_capacity * sizeof(float);
}
constexpr size_t
qwen36_resident_full_attention_wave32_partial_scalar_bytes(
    size_t token_capacity
) {
        return token_capacity >=
            qwen36_resident_full_attention_score_token_capacity(
                kQ129536ColdProbePrefillTokens
            )
        ? kQ1FullAttentionWave32FullDimensionMaxPartialScalarBytes
        : (token_capacity >=
                   kQwen36ResidentQ32768FullAttentionScoreScratchTokenCapacity
               ? kQ1FullAttentionWave32FullDimensionQ65536PartialScalarBytes
               : kQ1FullAttentionWave32FullDimensionPartialScalarBytes);
}
constexpr size_t
qwen36_resident_full_attention_wave32_partial_acc_bytes(
    size_t token_capacity
) {
        return token_capacity >=
            qwen36_resident_full_attention_score_token_capacity(
                kQ129536ColdProbePrefillTokens
            )
        ? kQ1FullAttentionWave32FullDimensionMaxPartialAccBytes
        : (token_capacity >=
                   kQwen36ResidentQ32768FullAttentionScoreScratchTokenCapacity
               ? kQ1FullAttentionWave32FullDimensionQ65536PartialAccBytes
               : kQ1FullAttentionWave32FullDimensionPartialAccBytes);
}
constexpr size_t
qwen36_resident_full_attention_wave32_partial_max_offset(
    size_t token_capacity
) {
    return qwen36_resident_decode_activation_workspace_align_up(
        kQwen36ResidentFullAttentionScoreScratchOffset +
        qwen36_resident_full_attention_score_scratch_bytes(token_capacity)
    );
}
constexpr size_t
qwen36_resident_full_attention_wave32_partial_sum_offset(
    size_t token_capacity
) {
    return qwen36_resident_decode_activation_workspace_align_up(
        qwen36_resident_full_attention_wave32_partial_max_offset(
            token_capacity
        ) +
        qwen36_resident_full_attention_wave32_partial_scalar_bytes(
            token_capacity
        )
    );
}
constexpr size_t
qwen36_resident_full_attention_wave32_partial_acc_offset(
    size_t token_capacity
) {
    return qwen36_resident_decode_activation_workspace_align_up(
        qwen36_resident_full_attention_wave32_partial_sum_offset(
            token_capacity
        ) +
        qwen36_resident_full_attention_wave32_partial_scalar_bytes(
            token_capacity
        )
    );
}
constexpr size_t qwen36_resident_full_attention_scratch_allocation_bytes(
    size_t token_capacity
) {
    return qwen36_resident_decode_activation_workspace_align_up(
        qwen36_resident_full_attention_wave32_partial_acc_offset(
            token_capacity
        ) +
        qwen36_resident_full_attention_wave32_partial_acc_bytes(
            token_capacity
        )
    );
}
constexpr size_t
    kQwen36ResidentFullAttentionWave32FullDimensionPartialMaxOffset =
        qwen36_resident_full_attention_wave32_partial_max_offset(
            kQwen36ResidentFullAttentionScoreScratchTokenCapacity
        );
constexpr size_t
    kQwen36ResidentFullAttentionWave32FullDimensionPartialSumOffset =
        qwen36_resident_full_attention_wave32_partial_sum_offset(
            kQwen36ResidentFullAttentionScoreScratchTokenCapacity
        );
constexpr size_t
    kQwen36ResidentFullAttentionWave32FullDimensionPartialAccOffset =
        qwen36_resident_full_attention_wave32_partial_acc_offset(
            kQwen36ResidentFullAttentionScoreScratchTokenCapacity
        );
constexpr size_t kQwen36ResidentFullAttentionScratchAllocationBytes =
    qwen36_resident_full_attention_scratch_allocation_bytes(
        kQwen36ResidentFullAttentionScoreScratchTokenCapacity
    );
static_assert(
        kRetainedPrefillTokens ==
            kQ1FullAttentionWave32FullDimensionPrefixChunks *
                kQ1FullAttentionWave32FullDimensionChunkTokens &&
        kQwen36ResidentFullAttentionScratchAllocationBytes == 1712896u,
    "resident full-attention scratch must cover q8192 scores and D73 partials"
);
static_assert(
    kQ1FullAttentionAiterUnifiedSegmentOutputBytes == 1048576u &&
        kQ1FullAttentionAiterUnifiedSegmentScalarBytes == 4096u &&
        kQ1FullAttentionAiterUnifiedBlockTableEntries == 16480u &&
        kQ1FullAttentionAiterUnifiedScratchEnd == 1122700u &&
        kQ1FullAttentionAiterUnifiedScratchEnd <=
            kQwen36ResidentFullAttentionScratchAllocationBytes,
    "Unified Attention maximum-context identity table must fit the smallest resident score allocation"
);
static_assert(
    kQwen36ResidentQ16384FullAttentionScoreScratchTokenCapacity == 17921u &&
        qwen36_resident_full_attention_scratch_allocation_bytes(
            kQwen36ResidentQ16384FullAttentionScoreScratchTokenCapacity
        ) == 2237184u,
    "resident q16384 plus 1536-token tail score scratch must remain bounded"
);
static_assert(
    kQwen36ResidentQ32768FullAttentionScoreScratchTokenCapacity == 34305u &&
        qwen36_resident_full_attention_scratch_allocation_bytes(
            kQwen36ResidentQ32768FullAttentionScoreScratchTokenCapacity
        ) < 7u * 1024u * 1024u,
    "resident q32768 plus 1536-token tail score scratch must remain bounded"
);
static_assert(
    kQwen36ResidentQ65536FullAttentionScoreScratchTokenCapacity == 67073u &&
        qwen36_resident_full_attention_scratch_allocation_bytes(
            kQwen36ResidentQ65536FullAttentionScoreScratchTokenCapacity
        ) < 9u * 1024u * 1024u,
    "resident q65536 plus 1536-token tail score scratch must remain bounded"
);
static_assert(
    kQwen36ResidentQ131072FullAttentionScoreScratchTokenCapacity == 132609u &&
        qwen36_resident_full_attention_scratch_allocation_bytes(
            kQwen36ResidentQ131072FullAttentionScoreScratchTokenCapacity
        ) < 18u * 1024u * 1024u,
    "resident q131072 plus 1536-token tail score scratch must remain bounded"
);
static_assert(
    kQwen36ResidentQ262144FullAttentionScoreScratchTokenCapacity == 263681u &&
        qwen36_resident_full_attention_scratch_allocation_bytes(
            kQwen36ResidentQ262144FullAttentionScoreScratchTokenCapacity
        ) < 36u * 1024u * 1024u,
    "resident q262144 plus 1536-token tail score scratch must remain bounded"
);

