    qwen36_resident_decode_activation_workspace_align_up(
        kQ1DecodeDirectOutputLogitsBf16Offset +
        kQ1DecodeDirectOutputLogitsBf16Bytes
    );
constexpr size_t kQ1DecodeDirectOutputTopkIdsOffset =
    qwen36_resident_decode_activation_workspace_align_up(
        kQ1DecodeDirectOutputLogitsF32Offset +
        kQ1DecodeDirectOutputLogitsF32Bytes
    );
constexpr size_t kQ1DecodeDirectOutputTopkLogitsOffset =
    qwen36_resident_decode_activation_workspace_align_up(
        kQ1DecodeDirectOutputTopkIdsOffset +
        kQ1DecodeDirectOutputTopkIdsBytes
    );
constexpr size_t kQ1DecodeMtpTop2TargetHiddenOffset =
    qwen36_resident_decode_activation_workspace_align_up(
        kQ1DecodeDirectOutputTopkLogitsOffset +
        kQ1DecodeDirectOutputTopkLogitsBytes
    );
constexpr size_t kQ1DecodeDirectOutputAllocationBytes =
    qwen36_resident_decode_activation_workspace_align_up(
        kQ1DecodeMtpTop2TargetHiddenOffset +
        kQ1DecodeMtpTop2TargetHiddenBytes
    );

