struct Qwen36ResidentSessionLinearLayer {
    // One standalone allocation owns both regions. The retained recurrent
    // state is F32 [value_head][value][key], exactly matching AITER's final
    // state layout. The optional q1 decode layout is
    // [value_head][key][value], transposed once during capture. The QKV history is
    // [absolute_token % 4][qkv_row], so a decode step can update one ring slot
    // without rebuilding the prefix projection.  Resident BF16 projection
    // layers retain BF16; the two retained early-F32 layers retain F32 so the
    // existing decode cache kernel can consume their exact projection rows.
    void *device_allocation = nullptr;
    float *device_recurrent_state = nullptr;
    void *device_qkv_ring = nullptr;
    size_t recurrent_state_bytes = 0u;
    size_t qkv_ring_bytes = 0u;
    size_t prefix_tokens = 0u;
    size_t decode_qkv_token_count = 0u;
    size_t decode_recurrent_token_count = 0u;
    Qwen36ResidentSessionElementKind qkv_element_kind =
        Qwen36ResidentSessionElementKind::kNone;
    bool recurrent_state_key_major = false;
    bool valid = false;
};

struct Qwen36ResidentSessionFullAttentionLayer {
    // K immediately precedes V in one standalone allocation.  Both tensors
    // are compact token-major [token][kv_head][head_dim].  Compact CK layers
    // retain their actual BF16 normalized/RoPE K and projected V buffers;
    // the layer-39 q1 path retains the actual F32 K/V slices from its packed
    // RoPE buffer without a precision conversion unless the experimental
    // model-native terminal BF16 corridor rounds them once at capture.
    void *device_allocation = nullptr;
    void *device_k = nullptr;
    void *device_v = nullptr;
    // Decode K/V is deliberately separate from the immutable q8192 prefix so
    // a short continuation never repacks or reallocates the captured history.
    void *device_decode_tail_allocation = nullptr;
    void *device_decode_tail_k = nullptr;
    void *device_decode_tail_v = nullptr;
    size_t k_bytes = 0u;
    size_t v_bytes = 0u;
    size_t decode_tail_k_bytes = 0u;
    size_t decode_tail_v_bytes = 0u;
    size_t decode_tail_capacity_tokens = 0u;
    size_t decode_tail_token_count = 0u;
    size_t history_tokens = 0u;
    bool decode_tail_contiguous = false;
    Qwen36ResidentSessionElementKind element_kind =
        Qwen36ResidentSessionElementKind::kNone;
    bool valid = false;
};

constexpr size_t kQwen36DflashStateCommitTokenCount = 22u;
constexpr size_t kQwen36DflashMultiStateCommitTokenCount = 54u;
constexpr size_t kQwen36DflashPrefetchedQueueCapacity = 64u;

struct Qwen36ResidentPrefixCheckpoint {
    std::array<Qwen36ResidentSessionLinearLayer, QRT_QWEN36_LAYER_COUNT>
        linear_layers{};
    std::array<float *, QRT_QWEN36_LAYER_COUNT> raw_states{};
    std::array<float, QRT_QWEN36_HIDDEN_SIZE> terminal_hidden{};
    uint64_t linear_mask = UINT64_C(0);
    uint64_t raw_ready_mask = UINT64_C(0);
    uint64_t prompt_digest = UINT64_C(0);
    size_t prefix_tokens = 0u;
    bool hidden_valid = false;
    bool valid = false;
};

// Session metadata is copied by shadow transactions. Shared ownership keeps
// immutable checkpoints alive through rollback and failed-stream quarantine.
// Full-attention prefix K/V stays owned by the original session.
struct Qwen36ResidentPrefixCheckpointStore {
    std::array<Qwen36ResidentPrefixCheckpoint, qrt_prefix_checkpoint::kCapacity>
        checkpoints{};
    std::vector<uint32_t> owner_tokens;
    const qrt_engine_t *owner_engine = nullptr;
    uint64_t owner_generation = UINT64_C(0);
    uint64_t owner_digest = UINT64_C(0);
    size_t count = 0u;
    bool failed = false;

    uint64_t owned_bytes() const {
        uint64_t bytes = UINT64_C(0);
        for (const auto &checkpoint : checkpoints) {
            for (size_t layer = 0u; layer < QRT_QWEN36_LAYER_COUNT; ++layer) {
                if (checkpoint.raw_states[layer] != nullptr) {
                    bytes += qrt_fla_checkpoint::kStateBytes;
                }
                const auto &state = checkpoint.linear_layers[layer];
                if (state.device_allocation != nullptr) {
                    bytes += state.recurrent_state_bytes + state.qkv_ring_bytes;
                }
            }
        }
        return bytes;
    }

    ~Qwen36ResidentPrefixCheckpointStore() {
        // The owning session is retired only after its stream cleanup fence.
        for (auto &checkpoint : checkpoints) {
            for (size_t layer = 0u; layer < QRT_QWEN36_LAYER_COUNT; ++layer) {
                if (checkpoint.raw_states[layer] != nullptr) {
                    (void)hipFree(checkpoint.raw_states[layer]);
                }
                if (checkpoint.linear_layers[layer].device_allocation != nullptr) {
                    (void)hipFree(
                        checkpoint.linear_layers[layer].device_allocation
                    );
                }
            }
        }
    }
};

