Qwen36Q1024SuffixCacheState g_qwen36_q1024_suffix_cache;

bool release_qwen36_q1024_suffix_cache_locked() {
    Qwen36Q1024SuffixCacheState &cache =
        g_qwen36_q1024_suffix_cache;
    hipError_t first_status = hipSuccess;
    auto release_allocation = [&](void *&allocation) {
        if (allocation == nullptr) {
            return;
        }
        const hipError_t status = hipFree(allocation);
        if (status == hipSuccess) {
            allocation = nullptr;
        } else if (first_status == hipSuccess) {
            first_status = status;
        }
    };
    for (void *&allocation : cache.linear_allocations) {
        release_allocation(allocation);
    }
    for (void *&allocation : cache.full_attention_tail_allocations) {
        release_allocation(allocation);
    }
    if (first_status == hipSuccess) {
        cache = Qwen36Q1024SuffixCacheState{};
    } else {
        cache.valid = false;
    }
    return first_status == hipSuccess;
}

