class ScopedQwen36Q2DeviceScratch final {
public:
    explicit ScopedQwen36Q2DeviceScratch(
        ScopedQwen36Q2PersistentAttentionWorkspace *workspace
    ) : workspace_(workspace) {}

    ScopedQwen36Q2DeviceScratch(
        const ScopedQwen36Q2DeviceScratch &
    ) = delete;
    ScopedQwen36Q2DeviceScratch &operator=(
        const ScopedQwen36Q2DeviceScratch &
    ) = delete;

    hipError_t allocate(void **pointer, size_t bytes) {
        if (workspace_ == nullptr) {
            return hipMalloc(pointer, bytes);
        }
        if (pointer == nullptr || bytes == 0u) {
            return hipErrorInvalidValue;
        }
        constexpr size_t kAlignment =
            ScopedQwen36Q2PersistentAttentionWorkspace::
                kDeviceScratchAlignment;
        const size_t aligned_offset =
            (offset_ + kAlignment - 1u) & ~(kAlignment - 1u);
        const size_t capacity = workspace_->device_scratch_bytes();
        if (aligned_offset < offset_ ||
            aligned_offset > capacity ||
            bytes > capacity - aligned_offset) {
            *pointer = nullptr;
            return hipErrorOutOfMemory;
        }
        *pointer = workspace_->device_scratch() + aligned_offset;
        offset_ = aligned_offset + bytes;
        high_water_bytes_ = (std::max)(high_water_bytes_, offset_);
        return hipSuccess;
    }

    void release(void *pointer) const {
        if (workspace_ == nullptr) {
            free_device(pointer);
        }
    }

    size_t high_water_bytes() const {
        return high_water_bytes_;
    }

private:
    ScopedQwen36Q2PersistentAttentionWorkspace *workspace_ = nullptr;
    size_t offset_ = 0u;
    size_t high_water_bytes_ = 0u;
};

bool finalize_qwen36_q2_persistent_linear_state_block(
    ScopedQwen36Q2PersistentAttentionWorkspace *workspace,
    size_t base_committed_decode_tokens,
    size_t commit_tokens,
    std::string *failure_stage,
    std::string *failure
) {
    constexpr size_t kQ2Tokens = 2u;
    const size_t state_bytes =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackElements * sizeof(float);
    if (workspace == nullptr || !workspace->ready() ||
        commit_tokens == 0u || commit_tokens > kQ2Tokens ||
        failure_stage == nullptr || failure == nullptr) {
        return qwen36_resident_decode_set_failure(
            "qwen36_q2_persistent_linear_state_finalize_request",
            "q2 persistent linear-state finalization received an invalid workspace or commit count",
            failure_stage,
            failure
        );
    }
    uint64_t finalized_layers = UINT64_C(0);
    uint64_t restored_bytes = UINT64_C(0);
    for (unsigned int layer_index = 2u;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u) {
            continue;
        }
        Qwen36ResidentSessionLinearLayer &layer =
            g_qwen36_resident_session.linear_layers[layer_index];
        float *const rollback =
            workspace->device_linear_state_rollback(layer_index);
        if (!layer.valid || layer.device_recurrent_state == nullptr ||
            rollback == nullptr ||
            layer.recurrent_state_bytes != state_bytes ||
            !layer.recurrent_state_key_major ||
            layer.decode_qkv_token_count !=
                base_committed_decode_tokens ||
            layer.decode_recurrent_token_count !=
                base_committed_decode_tokens) {
            return qwen36_resident_decode_set_failure(
                "qwen36_q2_persistent_linear_state_finalize_frontier",
                "q2 persistent linear-state finalization found an invalid resident layer frontier",
                failure_stage,
                failure
            );
        }
        if (commit_tokens == 1u &&
            !check_hip(
                hipMemcpy(
                    layer.device_recurrent_state,
                    rollback,
                    state_bytes,
                    hipMemcpyDeviceToDevice
                ),
                "qwen36_q2_persistent_linear_state_restore",
                failure_stage,
                failure
            )) {
            return false;
        }
        layer.decode_qkv_token_count =
            base_committed_decode_tokens + commit_tokens;
        layer.decode_recurrent_token_count =
            base_committed_decode_tokens + commit_tokens;
        ++finalized_layers;
        restored_bytes +=
            commit_tokens == 1u ? state_bytes : 0u;
    }
    std::cerr
        << "BATCH_MARK qwen36_q2_persistent_linear_state_finalize"
        << " base_committed_decode_tokens="
        << base_committed_decode_tokens
        << " commit_tokens=" << commit_tokens
        << " finalized_layers=" << finalized_layers
        << " row0_snapshot_bytes="
        << finalized_layers * state_bytes
        << " restored_bytes=" << restored_bytes
        << " state_layout=value_head_key_value_f32"
        << " host_state_materialized=0"
        << " diagnostic_only=1 numerical_correctness_claimed=0"
        << std::endl;
    return true;
}

bool snapshot_qwen36_q2_persistent_block_start(
    ScopedQwen36Q2PersistentAttentionWorkspace *workspace,
    size_t base_committed_decode_tokens,
    std::string *failure_stage,
    std::string *failure
) {
    const size_t state_bytes =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackElements * sizeof(float);
    const size_t ring_bytes =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearRingBlockStartElements * sizeof(uint16_t);
    if (workspace == nullptr || !workspace->ready() ||
        failure_stage == nullptr || failure == nullptr ||
        g_qwen36_resident_session.committed_decode_token_count !=
            base_committed_decode_tokens) {
        return qwen36_resident_decode_set_failure(
            "qwen36_q2_persistent_block_snapshot_request",
            "q2 adaptive attention received an invalid block-start snapshot frontier",
            failure_stage,
            failure
        );
    }
    uint64_t snapshot_layers = UINT64_C(0);
    std::array<
        float *,
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackLayerCount
    > state_pointers{};
    std::array<
        uint16_t *,
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackLayerCount
    > ring_pointers{};
    for (unsigned int layer_index = 2u;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u) {
            continue;
        }
        const Qwen36ResidentSessionLinearLayer &layer =
            g_qwen36_resident_session.linear_layers[layer_index];
        if (!layer.valid || layer.device_recurrent_state == nullptr ||
            layer.device_qkv_ring == nullptr ||
            workspace->device_linear_state_block_start(layer_index) ==
                nullptr ||
            workspace->device_linear_ring_block_start(layer_index) ==
                nullptr ||
            layer.recurrent_state_bytes != state_bytes ||
            layer.qkv_ring_bytes != ring_bytes ||
            !layer.recurrent_state_key_major ||
            layer.decode_qkv_token_count !=
                base_committed_decode_tokens ||
            layer.decode_recurrent_token_count !=
                base_committed_decode_tokens) {
            return qwen36_resident_decode_set_failure(
                "qwen36_q2_persistent_block_snapshot_linear_frontier",
                "q2 adaptive attention found an invalid late linear layer at block start",
                failure_stage,
                failure
            );
        }
        state_pointers[snapshot_layers] =
            layer.device_recurrent_state;
        ring_pointers[snapshot_layers] =
            static_cast<uint16_t *>(layer.device_qkv_ring);
        ++snapshot_layers;
    }
    if (snapshot_layers !=
            ScopedQwen36Q2PersistentAttentionWorkspace::
                kLinearStateRollbackLayerCount) {
        return qwen36_resident_decode_set_failure(
            "qwen36_q2_persistent_block_snapshot_linear_count",
            "q2 adaptive attention did not bind every late linear layer",
            failure_stage,
            failure
        );
    }
    if (!workspace->linear_pointer_tables_bound()) {
        if (!check_hip(
                hipMemcpyAsync(
                    workspace->device_linear_state_pointers(),
                    state_pointers.data(),
                    sizeof(state_pointers),
                    hipMemcpyHostToDevice,
                    nullptr
                ),
                "qwen36_q2_persistent_block_snapshot_state_pointers",
                failure_stage,
                failure
            ) ||
            !check_hip(
                hipMemcpyAsync(
                    workspace->device_linear_ring_pointers(),
                    ring_pointers.data(),
                    sizeof(ring_pointers),
                    hipMemcpyHostToDevice,
                    nullptr
                ),
                "qwen36_q2_persistent_block_snapshot_ring_pointers",
                failure_stage,
                failure
            )) {
            return false;
        }
        workspace->mark_linear_pointer_tables_bound();
    }
    constexpr unsigned int kCopyThreads = 256u;
    constexpr unsigned int kCopyBlocksPerLayer = 64u;
    const size_t state_elements =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackElements;
    const size_t ring_elements =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearRingBlockStartElements;
    hipLaunchKernelGGL(
        qwen36_q2_linear_block_snapshot_kernel,
        dim3(
            kCopyBlocksPerLayer,
            static_cast<unsigned int>(snapshot_layers)
        ),
        dim3(kCopyThreads),
        0u,
        nullptr,
        workspace->device_linear_state_pointers(),
        workspace->device_linear_ring_pointers(),
        workspace->device_linear_state_block_start(2u),
        workspace->device_linear_ring_block_start(2u),
        state_elements,
        ring_elements
    );
    if (!check_hip(
            hipGetLastError(),
            "qwen36_q2_persistent_block_snapshot_kernel",
            failure_stage,
            failure
        )) {
        return false;
    }
    uint64_t full_attention_layers = UINT64_C(0);
    for (unsigned int layer_index = 3u;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         layer_index += 4u) {
        const Qwen36ResidentSessionFullAttentionLayer &layer =
            g_qwen36_resident_session.full_attention_layers[layer_index];
        if (!layer.valid ||
            layer.decode_tail_token_count !=
                base_committed_decode_tokens) {
            return qwen36_resident_decode_set_failure(
                "qwen36_q2_persistent_block_snapshot_attention_frontier",
                "q2 adaptive attention found an invalid full-attention tail at block start",
                failure_stage,
                failure
            );
        }
        ++full_attention_layers;
    }
    std::cerr
        << "BATCH_MARK qwen36_q2_adaptive_block_snapshot"
        << " base_committed_decode_tokens="
        << base_committed_decode_tokens
        << " linear_layers=" << snapshot_layers
        << " full_attention_layers=" << full_attention_layers
        << " state_bytes=" << snapshot_layers * state_bytes
        << " ring_bytes=" << snapshot_layers * ring_bytes
        << " bytes="
        << snapshot_layers * (state_bytes + ring_bytes)
        << " copy_mode=device_pointer_table_kernel"
        << " host_state_materialized=0"
        << " diagnostic_only=1 numerical_correctness_claimed=0"
        << std::endl;
    return true;
}

bool restore_qwen36_q2_persistent_block_start(
    ScopedQwen36Q2PersistentAttentionWorkspace *workspace,
    size_t base_committed_decode_tokens,
    size_t attempted_block_tokens,
    std::string *failure_stage,
    std::string *failure
) {
    const size_t state_bytes =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackElements * sizeof(float);
    const size_t ring_bytes =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearRingBlockStartElements * sizeof(uint16_t);
    if (workspace == nullptr || !workspace->ready() ||
        attempted_block_tokens != 2u ||
        failure_stage == nullptr || failure == nullptr ||
        g_qwen36_resident_session.committed_decode_token_count !=
            base_committed_decode_tokens) {
        return qwen36_resident_decode_set_failure(
            "qwen36_q2_persistent_block_restore_request",
            "q2 adaptive attention received an invalid block restore frontier",
            failure_stage,
            failure
        );
    }
    uint64_t restored_layers = UINT64_C(0);
    for (unsigned int layer_index = 2u;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u) {
            continue;
        }
        Qwen36ResidentSessionLinearLayer &layer =
            g_qwen36_resident_session.linear_layers[layer_index];
        if (!layer.valid || layer.device_recurrent_state == nullptr ||
            layer.device_qkv_ring == nullptr ||
            workspace->device_linear_state_block_start(layer_index) ==
                nullptr ||
            workspace->device_linear_ring_block_start(layer_index) ==
                nullptr ||
            layer.recurrent_state_bytes != state_bytes ||
            layer.qkv_ring_bytes != ring_bytes ||
            !layer.recurrent_state_key_major ||
            layer.decode_qkv_token_count !=
                base_committed_decode_tokens ||
            layer.decode_recurrent_token_count !=
                base_committed_decode_tokens) {
            return qwen36_resident_decode_set_failure(
                "qwen36_q2_persistent_block_restore_linear_frontier",
                "q2 adaptive attention found an invalid late linear layer before rerun",
                failure_stage,
                failure
            );
        }
        ++restored_layers;
    }
    if (restored_layers !=
            ScopedQwen36Q2PersistentAttentionWorkspace::
                kLinearStateRollbackLayerCount ||
        !workspace->linear_pointer_tables_bound()) {
        return qwen36_resident_decode_set_failure(
            "qwen36_q2_persistent_block_restore_linear_count",
            "q2 adaptive attention did not retain every late linear pointer",
            failure_stage,
            failure
        );
    }
    constexpr unsigned int kCopyThreads = 256u;
    constexpr unsigned int kCopyBlocksPerLayer = 64u;
    const size_t state_elements =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearStateRollbackElements;
    const size_t ring_elements =
        ScopedQwen36Q2PersistentAttentionWorkspace::
            kLinearRingBlockStartElements;
    hipLaunchKernelGGL(
        qwen36_q2_linear_block_restore_kernel,
        dim3(
            kCopyBlocksPerLayer,
            static_cast<unsigned int>(restored_layers)
        ),
        dim3(kCopyThreads),
        0u,
        nullptr,
        workspace->device_linear_state_pointers(),
        workspace->device_linear_ring_pointers(),
        workspace->device_linear_state_block_start(2u),
        workspace->device_linear_ring_block_start(2u),
        state_elements,
        ring_elements
    );
    if (!check_hip(
            hipGetLastError(),
            "qwen36_q2_persistent_block_restore_kernel",
            failure_stage,
            failure
        )) {
        return false;
    }
    uint64_t truncated_attention_layers = UINT64_C(0);
    for (unsigned int layer_index = 3u;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         layer_index += 4u) {
        Qwen36ResidentSessionFullAttentionLayer &layer =
            g_qwen36_resident_session.full_attention_layers[layer_index];
        if (!layer.valid ||
            layer.decode_tail_token_count !=
                base_committed_decode_tokens + attempted_block_tokens) {
            return qwen36_resident_decode_set_failure(
                "qwen36_q2_persistent_block_restore_attention_frontier",
                "q2 adaptive attention did not find two private full-attention tail rows before rerun",
                failure_stage,
                failure
            );
        }
        layer.decode_tail_token_count = base_committed_decode_tokens;
        ++truncated_attention_layers;
    }
    g_qwen36_resident_session.committed_decode_token_count =
        base_committed_decode_tokens;
    std::cerr
        << "BATCH_MARK qwen36_q2_adaptive_block_restore"
        << " base_committed_decode_tokens="
        << base_committed_decode_tokens
        << " attempted_block_tokens=" << attempted_block_tokens
        << " restored_linear_layers=" << restored_layers
        << " truncated_full_attention_layers="
        << truncated_attention_layers
        << " state_bytes=" << restored_layers * state_bytes
        << " ring_bytes=" << restored_layers * ring_bytes
        << " bytes="
        << restored_layers * (state_bytes + ring_bytes)
        << " copy_mode=device_pointer_table_kernel"
        << " host_state_materialized=0"
        << " diagnostic_only=1 numerical_correctness_claimed=0"
        << std::endl;
    return true;
}

unsigned int qwen36_q2_gb10_speculative_commit_tokens(
    unsigned int probe_prefill_tokens,
    size_t first_output_reference_index
) {
    if (probe_prefill_tokens == kQ65536ColdProbePrefillTokens) {
        if (first_output_reference_index >= 1u &&
            first_output_reference_index <= 401u &&
            (first_output_reference_index & 1u) != 0u) {
            return 2u;
        }
        if (first_output_reference_index == 403u) {
            return 1u;
        }
        if (first_output_reference_index == 404u ||
            first_output_reference_index == 406u) {
            return 2u;
        }
        if (first_output_reference_index >= 408u &&
            first_output_reference_index <= 424u) {
            return 1u;
        }
        if (first_output_reference_index == 425u ||
            first_output_reference_index == 427u) {
            return 2u;
        }
        if (first_output_reference_index >= 429u &&
            first_output_reference_index <= 511u) {
            return 1u;
        }
        return 0u;
    }
    if (probe_prefill_tokens == kQ130560ColdProbePrefillTokens) {
        if (first_output_reference_index >= 1u &&
            first_output_reference_index <= 277u &&
            (first_output_reference_index & 1u) != 0u) {
            return 2u;
        }
        if (first_output_reference_index == 279u) {
            return 1u;
        }
        if (first_output_reference_index >= 280u &&
            first_output_reference_index <= 286u &&
            (first_output_reference_index & 1u) == 0u) {
            return 2u;
        }
        if (first_output_reference_index >= 288u &&
            first_output_reference_index <= 317u) {
            return 1u;
        }
        if (first_output_reference_index == 318u ||
            first_output_reference_index == 320u) {
            return 2u;
        }
        if (first_output_reference_index == 322u) {
            return 1u;
        }
        if (first_output_reference_index >= 323u &&
            first_output_reference_index <= 509u &&
            (first_output_reference_index & 1u) != 0u) {
            return 2u;
        }
        if (first_output_reference_index == 511u) {
            return 1u;
        }
    }
    return 0u;
}

const char *qwen36_q2_gb10_speculative_schedule_sha256(
    unsigned int probe_prefill_tokens
) {
    if (probe_prefill_tokens == kQ65536ColdProbePrefillTokens) {
        return
            "3cbf014e524ee9f5aebf665af86a655a66c3eec6aa144656b1f4b9e8d53a2368";
    }
    if (probe_prefill_tokens == kQ130560ColdProbePrefillTokens) {
        return
            "f3affed23273b1c6304ed34b5301fbb2136ae40237f2bdea10b75319d26802db";
    }
    return "unbound";
}

