class ScopedQwen36ResidentParallelSessionDecode final {
public:
    explicit ScopedQwen36ResidentParallelSessionDecode(
        Qwen36ResidentSessionState *session
    ) : session_(session) {
        if (session_ == nullptr) {
            return;
        }
        ScopedQwen36ResidentActiveSession active_scope(session_);
        lease_ = std::make_unique<ScopedQwen36ResidentSessionDecode>(
            ScopedQwen36ResidentSessionDecode::ParallelWorkerTag{}
        );
    }

    ScopedQwen36ResidentParallelSessionDecode(
        const ScopedQwen36ResidentParallelSessionDecode &
    ) = delete;
    ScopedQwen36ResidentParallelSessionDecode &operator=(
        const ScopedQwen36ResidentParallelSessionDecode &
    ) = delete;

    ~ScopedQwen36ResidentParallelSessionDecode() {
        if (lease_ != nullptr) {
            ScopedQwen36ResidentActiveSession active_scope(session_);
            lease_.reset();
        }
    }

    ScopedQwen36ResidentSessionDecode *get() const {
        return lease_.get();
    }

    bool ready() const {
        if (lease_ == nullptr || session_ == nullptr) {
            return false;
        }
        ScopedQwen36ResidentActiveSession active_scope(session_);
        return lease_->ready();
    }

private:
    Qwen36ResidentSessionState *session_ = nullptr;
    std::unique_ptr<ScopedQwen36ResidentSessionDecode> lease_;
};

bool qwen36_paired_layer_active_for_session(
    const Qwen36ResidentSessionState *session,
    unsigned int layer_index,
    size_t absolute_position
) {
    const Qwen36PairedLayerExecutionHooks *hooks =
        g_qwen36_paired_layer_execution_hooks;
    return hooks != nullptr && hooks->linear_projection_prepared &&
        session != nullptr &&
        (session == hooks->primary_session ||
         session == hooks->alternate_session) &&
        hooks->prepared_linear_layer == layer_index &&
        hooks->prepared_position == absolute_position;
}

