bool refresh_qwen36_resident_session_immutable_weight_views(
    Qwen36ResidentSessionState *session
) {
    if (session == nullptr) {
        return false;
    }
    if (!q1_moe_fixed_weight_arena_active()) {
        return true;
    }
    Qwen36ResidentDecodeActivationWorkspace &workspace =
        session->activation_workspace;
    if (workspace.direct_output_plan_ready) {
        constexpr uint64_t kLmHeadBytes =
            static_cast<uint64_t>(QRT_QWEN36_VOCAB_SIZE) *
            static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
            sizeof(uint16_t);
        const uint16_t *const lm_head =
            find_whole_repeated_layer_fixed_weight(
                "lm_head.weight",
                kLmHeadBytes
            );
        if (lm_head == nullptr) {
            return false;
        }
        workspace.device_direct_output_lm_head_weights = lm_head;
    }
    if (!workspace.prebound_layer_plan.ready) {
        return true;
    }
    for (Qwen36ResidentDecodePreboundLayer &layer :
         workspace.prebound_layer_plan.layers) {
        if (!layer.valid) {
            continue;
        }
        for (size_t kind_index = 0u;
             kind_index < layer.fixed_weights.size();
             ++kind_index) {
            if (layer.fixed_weights[kind_index] == nullptr) {
                continue;
            }
            const uint64_t bytes = layer.fixed_weight_bytes[kind_index];
            const std::string &tensor_name =
                layer.tensor_names[kind_index];
            if (bytes == UINT64_C(0) || tensor_name.empty()) {
                return false;
            }
            const uint16_t *const weights =
                find_whole_repeated_layer_fixed_weight(
                    tensor_name,
                    bytes
                );
            if (weights == nullptr) {
                return false;
            }
            layer.fixed_weights[kind_index] = weights;
        }
    }
    return true;
}

const Qwen36ResidentPrefixCheckpoint *find_qwen36_prefix_checkpoint(
    const Qwen36ResidentSessionState &session,
    size_t prefix_tokens, const uint32_t *input_tokens, uint64_t digest
) {
    const auto &store = session.prefix_checkpoints;
    if (!session.valid || !session.provider_completed || store == nullptr ||
        store->failed || input_tokens == nullptr || prefix_tokens == 0u ||
        prefix_tokens >= session.prefix_tokens ||
        store->owner_engine != session.owner_engine ||
        store->owner_generation != session.generation ||
        store->owner_digest != session.prompt_token_ids_fnv1a64 ||
        store->owner_tokens.size() != session.prefix_tokens ||
        std::memcmp(store->owner_tokens.data(), input_tokens,
                    prefix_tokens * sizeof(*input_tokens)) != 0) {
        return nullptr;
    }
    for (size_t i = 0u; i < store->count; ++i) {
        const auto &checkpoint = store->checkpoints[i];
        if (checkpoint.valid && checkpoint.prefix_tokens == prefix_tokens &&
            checkpoint.prompt_digest == digest) {
            return &checkpoint;
        }
    }
    return nullptr;
}

class ScopedQwen36ResidentSessionShadowTransaction final {
public:
    explicit ScopedQwen36ResidentSessionShadowTransaction(
        uint64_t expected_generation,
        uint64_t expected_prompt_token_ids_fnv1a64,
        std::string *failure_stage,
        std::string *failure,
        size_t expected_prefix_tokens = 0u,
        const uint32_t *input_prefix_tokens = nullptr
    ) : lock_(g_qwen36_resident_session_mutex) {
        if (!release_qwen36_resident_dual_attention_state_locked()) {
            set_failure(
                "qwen36_resident_shadow_transaction_dual_release",
                "resident shadow transaction could not retire a prior dual-attention branch",
                failure_stage,
                failure
            );
            return;
        }
        original_ = g_qwen36_resident_session;
        original_captured_ = true;
        const bool partial_requested = expected_prefix_tokens != 0u &&
            expected_prefix_tokens != original_.prefix_tokens;
        const auto *checkpoint = partial_requested
            ? find_qwen36_prefix_checkpoint(
                  original_, expected_prefix_tokens, input_prefix_tokens,
                  expected_prompt_token_ids_fnv1a64
              )
            : nullptr;
        if (!original_.valid || !original_.provider_completed ||
            original_.generation == UINT64_C(0) ||
            original_.generation != expected_generation ||
            (partial_requested ? checkpoint == nullptr
                : original_.prompt_token_ids_fnv1a64 !=
                    expected_prompt_token_ids_fnv1a64) ||
            original_.activation_workspace.in_use ||
            original_.activation_workspace.phase !=
                Qwen36ResidentDecodeActivationWorkspacePhase::kIdle) {
            set_failure(
                "qwen36_resident_shadow_transaction_session",
                "resident shadow transaction requires an idle matching session",
                failure_stage,
                failure
            );
            return;
        }
        if (checkpoint != nullptr) {
            partial_checkpoint_ = true;
            auto &session = g_qwen36_resident_session;
            session.prefix_tokens = checkpoint->prefix_tokens;
            session.prompt_token_ids_fnv1a64 = checkpoint->prompt_digest;
            session.committed_decode_token_count = 0u;
            session.current_token_id = 0u;
            session.current_token_valid = false;
            session.last_decode_top2_valid = false;
            session.last_decode_top2_position =
                (std::numeric_limits<size_t>::max)();
            session.q2_prefetched_valid = false;
            session.q2_prefetched_output_token_count = 0u;
            session.q2_prefetched_output_token_cursor = 0u;
            session.dflash_prefetched_valid = false;
            session.dflash_prefetched_output_token_count = 0u;
            session.dflash_decode_transaction_pending = false;
            for (size_t h = 0u; h < QRT_QWEN36_HIDDEN_SIZE; ++h) {
                session.mtp_target_hidden_bf16[h] =
                    qrt_float_to_bf16(checkpoint->terminal_hidden[h]);
            }
            session.mtp_target_hidden_position = checkpoint->prefix_tokens - 1u;
            session.mtp_target_hidden_output_token_id = UINT_MAX;
            session.mtp_target_hidden_valid = true;
            session.mtp_target_hidden_device_only = false;
        }

        hipError_t status = hipSuccess;
        const bool sync_priority_stream = raw_env_flag_enabled(
            "QRT_QWEN36_PREFIX_REQUEST_SYNC_PRIORITY_STREAM"
        );
        if (sync_priority_stream) {
            const Qwen36ResidentDecodeActivationWorkspace &workspace =
                original_.activation_workspace;
            status =
                workspace.q1_moe_priority_stream_requested &&
                        workspace.q1_moe_priority_stream_ready &&
                        workspace.q1_moe_priority_stream != nullptr
                    ? hipStreamSynchronize(workspace.q1_moe_priority_stream)
                    : hipErrorInvalidValue;
            std::cerr
                << "BATCH_MARK qwen36_resident_shadow_priority_stream_sync"
                << " status=" << static_cast<unsigned int>(status)
                << " request_boundary=1 diagnostic_only=1"
                << std::endl;
        }
        for (unsigned int layer_index = 0u;
             layer_index < QRT_QWEN36_LAYER_COUNT && status == hipSuccess;
             ++layer_index) {
            const Qwen36ResidentSessionLinearLayer &source =
                checkpoint != nullptr
                    ? checkpoint->linear_layers[layer_index]
                    : original_.linear_layers[layer_index];
            if (!source.valid) {
                continue;
            }
            const size_t allocation_bytes =
                source.recurrent_state_bytes + source.qkv_ring_bytes;
            void *allocation = nullptr;
            status = hipMalloc(&allocation, allocation_bytes);
            if (status == hipSuccess) {
                status = hipMemcpy(
                    allocation,
                    source.device_allocation,
                    allocation_bytes,
                    hipMemcpyDeviceToDevice
                );
            }
            if (status != hipSuccess) {
                if (allocation != nullptr) {
                    (void)hipFree(allocation);
                }
                break;
            }
            shadow_linear_allocations_[layer_index] = allocation;
            shadow_bytes_ += allocation_bytes;
            Qwen36ResidentSessionLinearLayer &destination =
                g_qwen36_resident_session.linear_layers[layer_index];
            destination = source;
            destination.device_allocation = allocation;
            destination.device_recurrent_state = static_cast<float *>(allocation);
            destination.device_qkv_ring =
                static_cast<unsigned char *>(allocation) +
                source.recurrent_state_bytes;
        }

        for (unsigned int layer_index = 0u;
             layer_index < QRT_QWEN36_LAYER_COUNT && status == hipSuccess;
             ++layer_index) {
            const Qwen36ResidentSessionFullAttentionLayer &source =
                original_.full_attention_layers[layer_index];
            if (!source.valid) {
                continue;
            }
            Qwen36ResidentSessionFullAttentionLayer &destination =
                g_qwen36_resident_session.full_attention_layers[layer_index];
            if (checkpoint != nullptr) {
                destination.k_bytes =
                    source.k_bytes / source.history_tokens * checkpoint->prefix_tokens;
                destination.v_bytes =
                    source.v_bytes / source.history_tokens * checkpoint->prefix_tokens;
                destination.history_tokens = checkpoint->prefix_tokens;
                destination.decode_tail_token_count = 0u;
            }
            const size_t allocation_bytes = source.decode_tail_contiguous
                ? destination.k_bytes + source.decode_tail_k_bytes +
                    destination.v_bytes + source.decode_tail_v_bytes
                : source.decode_tail_k_bytes + source.decode_tail_v_bytes;
            void *allocation = nullptr;
            status = hipMalloc(&allocation, allocation_bytes);
            if (status == hipSuccess && checkpoint != nullptr &&
                source.decode_tail_contiguous) {
                // Preserve the contiguous decoder layout, but copy only the
                // saved prefix. V begins at the owner's original V pointer,
                // never at a shortened offset inside the original K buffer.
                status = hipMemcpy(allocation, source.device_k,
                    destination.k_bytes, hipMemcpyDeviceToDevice);
                if (status == hipSuccess) {
                    status = hipMemcpy(
                        static_cast<unsigned char *>(allocation) +
                            destination.k_bytes + source.decode_tail_k_bytes,
                        source.device_v, destination.v_bytes,
                        hipMemcpyDeviceToDevice
                    );
                }
            } else if (status == hipSuccess) {
                status = hipMemcpy(
                    allocation,
                    source.decode_tail_contiguous
                        ? source.device_allocation
                        : source.device_decode_tail_allocation,
                    allocation_bytes,
                    hipMemcpyDeviceToDevice
                );
            }
            if (status != hipSuccess) {
                if (allocation != nullptr) {
                    (void)hipFree(allocation);
                }
                break;
            }
            shadow_bytes_ += allocation_bytes;
            if (source.decode_tail_contiguous) {
                shadow_full_attention_allocations_[layer_index] = allocation;
                destination.device_allocation = allocation;
                destination.device_k = allocation;
                destination.device_v =
                    static_cast<unsigned char *>(allocation) +
                    destination.k_bytes + source.decode_tail_k_bytes;
                destination.device_decode_tail_allocation = nullptr;
                destination.device_decode_tail_k =
                    static_cast<unsigned char *>(allocation) + destination.k_bytes;
                destination.device_decode_tail_v =
                    static_cast<unsigned char *>(destination.device_v) +
                    destination.v_bytes;
            } else {
                shadow_full_attention_tail_allocations_[layer_index] =
                    allocation;
                destination.device_decode_tail_allocation = allocation;
                destination.device_decode_tail_k = allocation;
                destination.device_decode_tail_v =
                    static_cast<unsigned char *>(allocation) +
                    source.decode_tail_k_bytes;
            }
        }

        const bool legacy_sync_clone_stream_requested = raw_env_flag_enabled(
            "QRT_QWEN36_PREFIX_REQUEST_SYNC_CLONE_STREAM"
        );
        if (status == hipSuccess) {
            status = hipStreamSynchronize(nullptr);
            std::cerr
                << "BATCH_MARK qwen36_resident_shadow_clone_stream_sync"
                << " status=" << static_cast<unsigned int>(status)
                << " shadow_bytes=" << shadow_bytes_
                << " producer_stream=default"
                << " consumer_stream=nonblocking_priority"
                << " request_boundary=1 required=1"
                << " legacy_env_requested="
                << (legacy_sync_clone_stream_requested ? 1 : 0)
                << std::endl;
        }

        const bool zero_activation_scratch = raw_env_flag_enabled(
            "QRT_QWEN36_PREFIX_REQUEST_ZERO_ACTIVATION_SCRATCH"
        );
        if (status == hipSuccess && zero_activation_scratch) {
            Qwen36ResidentDecodeActivationWorkspace &workspace =
                g_qwen36_resident_session.activation_workspace;
            if (!workspace.valid || workspace.device_allocation == nullptr ||
                workspace.layout_bytes == 0u) {
                status = hipErrorInvalidValue;
            } else {
                status = hipMemset(
                    workspace.device_allocation,
                    0,
                    workspace.layout_bytes
                );
            }
            std::cerr
                << "BATCH_MARK qwen36_resident_shadow_activation_scratch_zero"
                << " bytes=" << workspace.layout_bytes
                << " status=" << static_cast<unsigned int>(status)
                << " request_boundary=1 diagnostic_only=1"
                << std::endl;
        }

        if (status != hipSuccess) {
            restore_original_and_free_shadow(false, "clone_failure");
            set_failure(
                "qwen36_resident_shadow_transaction_clone",
                std::string("resident shadow transaction clone failed: ") +
                    hipGetErrorString(status),
                failure_stage,
                failure
            );
            return;
        }
        ready_ = true;
        std::cerr
            << "BATCH_MARK qwen36_resident_shadow_transaction_begin"
            << " generation=" << original_.generation
            << " partial_checkpoint=" << (partial_checkpoint_ ? 1 : 0)
            << " restored_prefix_tokens=" << g_qwen36_resident_session.prefix_tokens
            << " committed_decode_tokens="
            << original_.committed_decode_token_count
            << " shadow_bytes=" << shadow_bytes_
            << " linear_allocations=" << linear_allocation_count()
            << " full_attention_allocations="
            << full_attention_allocation_count()
            << " full_attention_tail_allocations="
            << full_attention_tail_allocation_count()
            << std::endl;
    }

    ScopedQwen36ResidentSessionShadowTransaction(
        const ScopedQwen36ResidentSessionShadowTransaction &
    ) = delete;
    ScopedQwen36ResidentSessionShadowTransaction &operator=(
        const ScopedQwen36ResidentSessionShadowTransaction &
    ) = delete;

    ~ScopedQwen36ResidentSessionShadowTransaction() {
        if (ready_) {
            (void)rollback("destructor");
        }
    }

    bool ready() const {
        return ready_ && g_qwen36_resident_session.valid &&
            g_qwen36_resident_session.generation == original_.generation;
    }

    size_t base_committed_decode_token_count() const {
        return original_.committed_decode_token_count;
    }

    uint64_t shadow_bytes() const {
        return shadow_bytes_;
    }

    bool rollback(const char *reason) {
        if (!original_captured_) {
            return false;
        }
        const size_t mutated_count =
            g_qwen36_resident_session.committed_decode_token_count;
        const bool dual_release_ok =
            release_qwen36_resident_dual_attention_state_locked();
        const hipError_t sync_status = hipStreamSynchronize(nullptr);
        restore_original_and_free_shadow(true, reason);
        const bool unchanged =
            g_qwen36_resident_session.valid == original_.valid &&
            g_qwen36_resident_session.generation == original_.generation &&
            g_qwen36_resident_session.committed_decode_token_count ==
                original_.committed_decode_token_count &&
            g_qwen36_resident_session.current_token_id ==
                original_.current_token_id &&
            g_qwen36_resident_session.current_token_valid ==
                original_.current_token_valid &&
            original_allocations_restored();
        std::cerr
            << "BATCH_MARK qwen36_resident_shadow_transaction_rollback"
            << " generation=" << original_.generation
            << " reason=" << (reason != nullptr ? reason : "unspecified")
            << " base_committed_decode_tokens="
            << original_.committed_decode_token_count
            << " mutated_committed_decode_tokens=" << mutated_count
            << " restored_committed_decode_tokens="
            << g_qwen36_resident_session.committed_decode_token_count
            << " original_allocations_restored="
            << (original_allocations_restored() ? 1 : 0)
            << " live_state_unchanged=" << (unchanged ? 1 : 0)
            << " sync_status=" << static_cast<unsigned int>(sync_status)
            << std::endl;
        ready_ = false;
        return dual_release_ok && sync_status == hipSuccess && unchanged;
    }

    bool commit(std::string *failure_stage, std::string *failure) {
        if (partial_checkpoint_) {
            set_failure(
                "qwen36_resident_shadow_checkpoint_commit",
                "a partial-prefix branch must restore its original owner",
                failure_stage, failure
            );
            return false;
        }
        if (!ready()) {
            set_failure(
                "qwen36_resident_shadow_transaction_commit",
                "resident shadow transaction commit found an invalid shadow session",
                failure_stage,
                failure
            );
            return false;
        }
        if (!release_qwen36_resident_dual_attention_state_locked()) {
            (void)rollback("commit_dual_release_failure");
            set_failure(
                "qwen36_resident_shadow_transaction_commit_dual_release",
                "resident shadow transaction could not retire the alternate attention branch",
                failure_stage,
                failure
            );
            return false;
        }
        const hipError_t sync_status = hipStreamSynchronize(nullptr);
        if (sync_status != hipSuccess) {
            (void)rollback("commit_sync_failure");
            set_failure(
                "qwen36_resident_shadow_transaction_commit_sync",
                std::string("resident shadow transaction commit sync failed: ") +
                    hipGetErrorString(sync_status),
                failure_stage,
                failure
            );
            return false;
        }

        hipError_t free_status = hipSuccess;
        for (unsigned int layer_index = 0u;
             layer_index < QRT_QWEN36_LAYER_COUNT;
             ++layer_index) {
            void *allocation =
                original_.linear_layers[layer_index].device_allocation;
            if (allocation != nullptr) {
                const hipError_t status = hipFree(allocation);
                if (free_status == hipSuccess && status != hipSuccess) {
                    free_status = status;
                }
            }
            const Qwen36ResidentSessionFullAttentionLayer &original_full =
                original_.full_attention_layers[layer_index];
            void *full_allocation = original_full.decode_tail_contiguous
                ? original_full.device_allocation
                : original_full.device_decode_tail_allocation;
            if (full_allocation != nullptr) {
                const hipError_t status = hipFree(full_allocation);
                if (free_status == hipSuccess && status != hipSuccess) {
                    free_status = status;
                }
            }
            shadow_linear_allocations_[layer_index] = nullptr;
            shadow_full_attention_allocations_[layer_index] = nullptr;
            shadow_full_attention_tail_allocations_[layer_index] = nullptr;
        }
        const size_t committed_count =
            g_qwen36_resident_session.committed_decode_token_count;
        ready_ = false;
        committed_ = free_status == hipSuccess;
        if (!committed_) {
            g_qwen36_resident_session.valid = false;
            set_failure(
                "qwen36_resident_shadow_transaction_commit_release",
                std::string("resident shadow transaction could not release original state: ") +
                    hipGetErrorString(free_status),
                failure_stage,
                failure
            );
            return false;
        }
        std::cerr
            << "BATCH_MARK qwen36_resident_shadow_transaction_commit"
            << " generation=" << original_.generation
            << " base_committed_decode_tokens="
            << original_.committed_decode_token_count
            << " committed_decode_tokens=" << committed_count
            << " committed_token_delta="
            << (committed_count - original_.committed_decode_token_count)
            << " shadow_bytes=" << shadow_bytes_
            << " original_release_status=0"
            << std::endl;
        return true;
    }

private:
    static void set_failure(
        const std::string &stage,
        const std::string &message,
        std::string *failure_stage,
        std::string *failure
    ) {
        if (failure_stage != nullptr) {
            *failure_stage = stage;
        }
        if (failure != nullptr) {
            *failure = message;
        }
    }

    size_t linear_allocation_count() const {
        size_t count = 0u;
        for (void *allocation : shadow_linear_allocations_) {
            count += allocation != nullptr ? 1u : 0u;
        }
        return count;
    }

    size_t full_attention_tail_allocation_count() const {
        size_t count = 0u;
        for (void *allocation : shadow_full_attention_tail_allocations_) {
            count += allocation != nullptr ? 1u : 0u;
        }
        return count;
    }

    size_t full_attention_allocation_count() const {
        size_t count = 0u;
        for (void *allocation : shadow_full_attention_allocations_) {
            count += allocation != nullptr ? 1u : 0u;
        }
        return count;
    }

    bool original_allocations_restored() const {
        for (unsigned int layer_index = 0u;
             layer_index < QRT_QWEN36_LAYER_COUNT;
             ++layer_index) {
            if (g_qwen36_resident_session.linear_layers[layer_index]
                    .device_allocation !=
                    original_.linear_layers[layer_index].device_allocation ||
                g_qwen36_resident_session.full_attention_layers[layer_index]
                    .device_allocation !=
                    original_.full_attention_layers[layer_index]
                        .device_allocation ||
                g_qwen36_resident_session.full_attention_layers[layer_index]
                    .device_decode_tail_allocation !=
                    original_.full_attention_layers[layer_index]
                        .device_decode_tail_allocation) {
                return false;
            }
        }
        return true;
    }

    void restore_original_and_free_shadow(bool emit_marker, const char *reason) {
        g_qwen36_resident_session = original_;
        const bool immutable_weight_views_refreshed =
            refresh_qwen36_resident_session_immutable_weight_views(
                &g_qwen36_resident_session
            );
        hipError_t free_status = hipSuccess;
        for (unsigned int layer_index = 0u;
             layer_index < QRT_QWEN36_LAYER_COUNT;
             ++layer_index) {
            if (shadow_linear_allocations_[layer_index] != nullptr) {
                const hipError_t status =
                    hipFree(shadow_linear_allocations_[layer_index]);
                if (free_status == hipSuccess && status != hipSuccess) {
                    free_status = status;
                }
                shadow_linear_allocations_[layer_index] = nullptr;
            }
            if (shadow_full_attention_allocations_[layer_index] != nullptr) {
                const hipError_t status = hipFree(
                    shadow_full_attention_allocations_[layer_index]
                );
                if (free_status == hipSuccess && status != hipSuccess) {
                    free_status = status;
                }
                shadow_full_attention_allocations_[layer_index] = nullptr;
            }
            if (shadow_full_attention_tail_allocations_[layer_index] != nullptr) {
                const hipError_t status = hipFree(
                    shadow_full_attention_tail_allocations_[layer_index]
                );
                if (free_status == hipSuccess && status != hipSuccess) {
                    free_status = status;
                }
                shadow_full_attention_tail_allocations_[layer_index] = nullptr;
            }
        }
        if (free_status != hipSuccess ||
            !immutable_weight_views_refreshed) {
            g_qwen36_resident_session.valid = false;
        }
        if (emit_marker &&
            (free_status != hipSuccess ||
             !immutable_weight_views_refreshed)) {
            std::cerr
                << "BATCH_MARK qwen36_resident_shadow_transaction_release_failure"
                << " generation=" << original_.generation
                << " reason=" << (reason != nullptr ? reason : "unspecified")
                << " status=" << static_cast<unsigned int>(free_status)
                << " immutable_weight_views_refreshed="
                << (immutable_weight_views_refreshed ? 1 : 0)
                << std::endl;
        }
    }

    std::unique_lock<std::recursive_mutex> lock_;
    Qwen36ResidentSessionState original_{};
    std::array<void *, QRT_QWEN36_LAYER_COUNT> shadow_linear_allocations_{};
    std::array<void *, QRT_QWEN36_LAYER_COUNT>
        shadow_full_attention_allocations_{};
    std::array<void *, QRT_QWEN36_LAYER_COUNT>
        shadow_full_attention_tail_allocations_{};
    uint64_t shadow_bytes_ = UINT64_C(0);
    bool original_captured_ = false;
    bool partial_checkpoint_ = false;
    bool ready_ = false;
    bool committed_ = false;
};

bool run_qwen36_q16_serial_transaction_probe_if_requested(
    const std::string &model_dir,
    qrt_engine_t *resident_engine,
    uint64_t expected_generation,
    uint64_t expected_prompt_token_ids_fnv1a64,
    uint32_t initial_token_id,
    std::string *failure_stage,
    std::string *failure
);
bool run_qwen36_q16_layer_major_probe_if_requested(
    const std::string &model_dir,
    qrt_engine_t *resident_engine,
    uint64_t expected_generation,
    uint64_t expected_prompt_token_ids_fnv1a64,
    uint32_t initial_token_id,
    std::string *failure_stage,
    std::string *failure
);

bool qwen36_resident_decode_set_failure(
    const std::string &stage,
    const std::string &message,
    std::string *failure_stage,
    std::string *failure
) {
    if (failure_stage != nullptr) {
        *failure_stage = stage;
    }
    if (failure != nullptr) {
        *failure = message;
    }
    return false;
}

bool prepare_qwen36_resident_linear_bf16_conv_fusion(
    ScopedQwen36ResidentSessionDecode *lease,
    unsigned int layer_index,
    size_t absolute_position,
    uint16_t **device_qkv_ring,
    std::string *failure_stage,
    std::string *failure
) {
    const std::string stage =
        "qwen36_resident_linear_bf16_conv_fusion_prepare";
    if (lease == nullptr || !lease->ready() || device_qkv_ring == nullptr ||
        layer_index >= QRT_QWEN36_LAYER_COUNT || layer_index < 2u ||
        (layer_index % 4u) == 3u) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear BF16 conv fusion received an invalid lease or layer",
            failure_stage,
            failure
        );
    }
    Qwen36ResidentSessionLinearLayer &layer =
        g_qwen36_resident_session.linear_layers[layer_index];
    const size_t expected_ring_elements =
        static_cast<size_t>(kConvKernel) * static_cast<size_t>(kQkvRows);
    const size_t expected_ring_bytes =
        expected_ring_elements * sizeof(uint16_t);
    if (!layer.valid || layer.device_qkv_ring == nullptr ||
        layer.qkv_element_kind !=
            Qwen36ResidentSessionElementKind::kBf16 ||
        layer.qkv_ring_bytes != expected_ring_bytes ||
        layer.decode_qkv_token_count !=
            g_qwen36_resident_session.committed_decode_token_count ||
        absolute_position !=
            layer.prefix_tokens + layer.decode_qkv_token_count) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear BF16 conv fusion did not match the session ring or absolute position",
            failure_stage,
            failure
        );
    }
    *device_qkv_ring = static_cast<uint16_t *>(layer.device_qkv_ring);
    return true;
}

void commit_qwen36_resident_linear_bf16_conv_fusion(
    ScopedQwen36ResidentSessionDecode *lease,
    unsigned int layer_index
) {
    ++g_qwen36_resident_session.linear_layers[layer_index]
          .decode_qkv_token_count;
    lease->mark_work_submitted();
}

bool run_qwen36_resident_linear_keyhead_fused_post_step(
    ScopedQwen36ResidentSessionDecode *lease,
    unsigned int layer_index,
    size_t absolute_position,
    const float *device_current_qkv,
    const float *device_z,
    const float *device_a,
    const float *device_b,
    const uint16_t *device_conv_weights,
    const uint16_t *device_a_log,
    const uint16_t *device_dt_bias,
    const uint16_t *device_norm_weights,
    uint16_t *device_output_bf16,
    std::string *failure_stage,
    std::string *failure,
    hipStream_t stream = nullptr
) {
    const std::string stage =
        "qwen36_resident_linear_keyhead_fused_post";
    if (lease == nullptr || !lease->ready() ||
        layer_index >= QRT_QWEN36_LAYER_COUNT || layer_index < 2u ||
        (layer_index % 4u) == 3u || device_current_qkv == nullptr ||
        device_z == nullptr || device_a == nullptr || device_b == nullptr ||
        device_conv_weights == nullptr || device_a_log == nullptr ||
        device_dt_bias == nullptr || device_norm_weights == nullptr ||
        device_output_bf16 == nullptr) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident key-head fused post owner received an invalid layer or surface",
            failure_stage,
            failure
        );
    }

    Qwen36ResidentSessionLinearLayer &layer =
        g_qwen36_resident_session.linear_layers[layer_index];
    const size_t expected_state_bytes =
        static_cast<size_t>(kValueFeatures) *
        static_cast<size_t>(kKeyDim) * sizeof(float);
    const size_t expected_ring_bytes =
        static_cast<size_t>(kConvKernel) *
        static_cast<size_t>(kQkvRows) * sizeof(uint16_t);
    const size_t committed =
        g_qwen36_resident_session.committed_decode_token_count;
    if (!layer.valid || layer.device_recurrent_state == nullptr ||
        layer.device_qkv_ring == nullptr ||
        layer.recurrent_state_bytes != expected_state_bytes ||
        layer.qkv_ring_bytes != expected_ring_bytes ||
        layer.qkv_element_kind !=
            Qwen36ResidentSessionElementKind::kBf16 ||
        !layer.recurrent_state_key_major ||
        layer.decode_qkv_token_count != committed ||
        layer.decode_recurrent_token_count != committed ||
        absolute_position != layer.prefix_tokens + committed) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident key-head fused post owner did not match the BF16 ring, key-major state, or absolute position",
            failure_stage,
            failure
        );
    }

    hipLaunchKernelGGL(
        q1_linear_keyhead_fused_post_bf16_kernel,
        dim3(kKeyHeads, 1u),
        dim3(2u * kValueDim),
        0u,
        stream,
        device_current_qkv,
        device_z,
        device_a,
        device_b,
        static_cast<uint16_t *>(layer.device_qkv_ring),
        device_conv_weights,
        device_a_log,
        device_dt_bias,
        layer.device_recurrent_state,
        device_norm_weights,
        device_output_bf16,
        nullptr,
        nullptr,
        nullptr,
        nullptr,
        nullptr,
        nullptr,
        nullptr,
        absolute_position,
        1u
    );
    const hipError_t status = hipGetLastError();
    if (status != hipSuccess) {
        return qwen36_resident_decode_set_failure(
            stage,
            std::string("resident key-head fused post kernel failed: ") +
                hipGetErrorString(status),
            failure_stage,
            failure
        );
    }
    ++layer.decode_qkv_token_count;
    ++layer.decode_recurrent_token_count;
    lease->mark_work_submitted();
    return true;
}

bool run_qwen36_resident_linear_keyhead_fused_post_pair_step(
    ScopedQwen36ResidentSessionDecode *primary_lease,
    Qwen36ResidentSessionState *primary_session,
    ScopedQwen36ResidentSessionDecode *alternate_lease,
    Qwen36ResidentSessionState *alternate_session,
    unsigned int layer_index,
    size_t absolute_position,
    const float *primary_current_qkv,
    const float *primary_z,
    const float *primary_a,
    const float *primary_b,
    const float *alternate_current_qkv,
    const float *alternate_z,
    const float *alternate_a,
    const float *alternate_b,
    const uint16_t *device_conv_weights,
    const uint16_t *device_a_log,
    const uint16_t *device_dt_bias,
    const uint16_t *device_norm_weights,
    uint16_t *primary_output_bf16,
    uint16_t *alternate_output_bf16,
    std::string *failure_stage,
    std::string *failure,
    hipStream_t stream
) {
    const std::string stage =
        "qwen36_resident_linear_keyhead_fused_post_pair";
    bool primary_ready = false;
    bool alternate_ready = false;
    if (primary_session != nullptr && primary_lease != nullptr) {
        ScopedQwen36ResidentActiveSession primary_scope(primary_session);
        primary_ready = primary_lease->ready();
    }
    if (alternate_session != nullptr && alternate_lease != nullptr) {
        ScopedQwen36ResidentActiveSession alternate_scope(alternate_session);
        alternate_ready = alternate_lease->ready();
    }
    if (!primary_ready || !alternate_ready ||
        primary_session == alternate_session ||
        layer_index >= QRT_QWEN36_LAYER_COUNT || layer_index < 2u ||
        (layer_index % 4u) == 3u || primary_current_qkv == nullptr ||
        primary_z == nullptr || primary_a == nullptr || primary_b == nullptr ||
        alternate_current_qkv == nullptr || alternate_z == nullptr ||
        alternate_a == nullptr || alternate_b == nullptr ||
        device_conv_weights == nullptr || device_a_log == nullptr ||
        device_dt_bias == nullptr || device_norm_weights == nullptr ||
        primary_output_bf16 == nullptr || alternate_output_bf16 == nullptr) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident paired key-head fused post owner received an invalid session, layer, or surface",
            failure_stage,
            failure
        );
    }

    Qwen36ResidentSessionLinearLayer &primary_layer =
        primary_session->linear_layers[layer_index];
    Qwen36ResidentSessionLinearLayer &alternate_layer =
        alternate_session->linear_layers[layer_index];
    const size_t expected_state_bytes =
        static_cast<size_t>(kValueFeatures) *
        static_cast<size_t>(kKeyDim) * sizeof(float);
    const size_t expected_ring_bytes =
        static_cast<size_t>(kConvKernel) *
        static_cast<size_t>(kQkvRows) * sizeof(uint16_t);
    auto layer_ready = [&](const Qwen36ResidentSessionState *session,
                           const Qwen36ResidentSessionLinearLayer &layer) {
        const size_t committed = session->committed_decode_token_count;
        const Qwen36ResidentDecodeActivationWorkspace &workspace =
            session->activation_workspace;
        return layer.valid && layer.device_recurrent_state != nullptr &&
            layer.device_qkv_ring != nullptr &&
            layer.recurrent_state_bytes == expected_state_bytes &&
            layer.qkv_ring_bytes == expected_ring_bytes &&
            layer.qkv_element_kind ==
                Qwen36ResidentSessionElementKind::kBf16 &&
            layer.recurrent_state_key_major &&
            layer.decode_qkv_token_count == committed &&
            layer.decode_recurrent_token_count == committed &&
            absolute_position == layer.prefix_tokens + committed &&
            workspace.phase ==
                Qwen36ResidentDecodeActivationWorkspacePhase::kLayerActive &&
            workspace.active_layer_index == layer_index &&
            workspace.active_token_position == absolute_position &&
            workspace.active_attention_kind ==
                QRT_QWEN36_BASELINE_ATTENTION_LINEAR;
    };
    if (!layer_ready(primary_session, primary_layer) ||
        !layer_ready(alternate_session, alternate_layer)) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident paired key-head fused post owner did not match both BF16 rings, key-major states, or absolute positions",
            failure_stage,
            failure
        );
    }

    hipLaunchKernelGGL(
        q1_linear_keyhead_fused_post_bf16_kernel,
        dim3(kKeyHeads, 2u),
        dim3(2u * kValueDim),
        0u,
        stream,
        primary_current_qkv,
        primary_z,
        primary_a,
        primary_b,
        static_cast<uint16_t *>(primary_layer.device_qkv_ring),
        device_conv_weights,
        device_a_log,
        device_dt_bias,
        primary_layer.device_recurrent_state,
        device_norm_weights,
        primary_output_bf16,
        alternate_current_qkv,
        alternate_z,
        alternate_a,
        alternate_b,
        static_cast<uint16_t *>(alternate_layer.device_qkv_ring),
        alternate_layer.device_recurrent_state,
        alternate_output_bf16,
        absolute_position,
        2u
    );
    const hipError_t status = hipGetLastError();
    if (status != hipSuccess) {
        return qwen36_resident_decode_set_failure(
            stage,
            std::string("resident paired key-head fused post kernel failed: ") +
                hipGetErrorString(status),
            failure_stage,
            failure
        );
    }
    ++primary_layer.decode_qkv_token_count;
    ++primary_layer.decode_recurrent_token_count;
    ++alternate_layer.decode_qkv_token_count;
    ++alternate_layer.decode_recurrent_token_count;
    primary_lease->mark_work_submitted();
    alternate_lease->mark_work_submitted();
    return true;
}

bool run_qwen36_resident_linear_conv_cache_step(
    ScopedQwen36ResidentSessionDecode *lease,
    unsigned int layer_index,
    size_t absolute_position,
    const float *device_current_qkv,
    const uint16_t *device_conv_weights,
    float *device_conv_output,
    std::string *failure_stage,
    std::string *failure,
    hipStream_t stream = nullptr
) {
    const std::string stage = "qwen36_resident_linear_conv_cache";
    if (lease == nullptr || !lease->ready() ||
        layer_index >= QRT_QWEN36_LAYER_COUNT ||
        (layer_index % 4u) == 3u || device_current_qkv == nullptr ||
        device_conv_weights == nullptr || device_conv_output == nullptr) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear conv-cache step received an invalid lease, layer, or device surface",
            failure_stage,
            failure
        );
    }
    Qwen36ResidentSessionLinearLayer &layer =
        g_qwen36_resident_session.linear_layers[layer_index];
    const Qwen36ResidentSessionElementKind expected_kind = layer_index < 2u
        ? Qwen36ResidentSessionElementKind::kF32
        : Qwen36ResidentSessionElementKind::kBf16;
    const size_t expected_ring_elements =
        static_cast<size_t>(kConvKernel) * static_cast<size_t>(kQkvRows);
    const size_t expected_ring_bytes = expected_ring_elements *
        (expected_kind == Qwen36ResidentSessionElementKind::kF32
             ? sizeof(float)
             : sizeof(uint16_t));
    if (!layer.valid || layer.device_qkv_ring == nullptr ||
        layer.qkv_element_kind != expected_kind ||
        layer.qkv_ring_bytes != expected_ring_bytes ||
        layer.decode_qkv_token_count !=
            g_qwen36_resident_session.committed_decode_token_count ||
        absolute_position != layer.prefix_tokens +
            layer.decode_qkv_token_count) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear conv-cache layer does not match the native ring kind or absolute position",
            failure_stage,
            failure
        );
    }
    const unsigned int q65536_early_conv_f32_silu_layer_mask =
        layer.prefix_tokens ==
                static_cast<size_t>(kQ65536ColdProbePrefillTokens)
            ? env_u32_or_default(
                  "QRT_QWEN36_Q65536_EARLY_CONV_F32_SILU_LAYER_MASK",
                  0u
              )
            : 0u;
    const bool use_q65536_early_conv_f32_silu =
        layer_index < 2u &&
        (q65536_early_conv_f32_silu_layer_mask &
         (1u << layer_index)) != 0u;

    const bool sm121_q1 = env_flag_enabled("QRT_QWEN36_Q1_SM121_GDN");
    qrt_sm121_q1_runtime::Tables tables;
    if (sm121_q1) {
        const hipError_t prepared = qrt_sm121_q1_runtime::prepare(&tables);
        if (prepared != hipSuccess)
            return qwen36_resident_decode_set_failure(stage,
                std::string("SM121 Q1 table preparation: ") + hipGetErrorString(prepared),
                failure_stage, failure);
    }
    const dim3 block(kThreads);
    const dim3 grid((kQkvRows + kThreads - 1u) / kThreads);
    if (sm121_q1) {
        if (expected_kind == Qwen36ResidentSessionElementKind::kF32) {
            hipLaunchKernelGGL(qrt_sm121_q1::convolution<float>, grid, block, 0, stream,
                device_current_qkv, static_cast<float *>(layer.device_qkv_ring),
                device_conv_weights, device_conv_output, absolute_position, tables.silu);
        } else {
            hipLaunchKernelGGL(qrt_sm121_q1::convolution<uint16_t>, grid, block, 0, stream,
                device_current_qkv, static_cast<uint16_t *>(layer.device_qkv_ring),
                device_conv_weights, device_conv_output, absolute_position, tables.silu);
        }
    } else if (expected_kind == Qwen36ResidentSessionElementKind::kF32) {
        hipLaunchKernelGGL(
            qwen36_resident_linear_conv_cache_kernel<float>,
            grid,
            block,
            0,
            stream,
            device_current_qkv,
            static_cast<float *>(layer.device_qkv_ring),
            device_conv_weights,
            device_conv_output,
            absolute_position,
            use_q65536_early_conv_f32_silu ? 1u : 0u
        );
    } else {
        hipLaunchKernelGGL(
            qwen36_resident_linear_conv_cache_kernel<uint16_t>,
            grid,
            block,
            0,
            stream,
            device_current_qkv,
            static_cast<uint16_t *>(layer.device_qkv_ring),
            device_conv_weights,
            device_conv_output,
            absolute_position,
            use_q65536_early_conv_f32_silu ? 1u : 0u
        );
    }
    const hipError_t status = hipGetLastError();
    if (status != hipSuccess) {
        return qwen36_resident_decode_set_failure(
            stage,
            std::string("resident linear conv-cache kernel launch failed: ") +
                hipGetErrorString(status),
            failure_stage,
            failure
        );
    }
    if (use_q65536_early_conv_f32_silu &&
        absolute_position == layer.prefix_tokens) {
        std::cerr
            << "BATCH_MARK q65536_early_conv_f32_silu"
            << " layer=" << layer_index
            << " phase=decode"
            << " absolute_position=" << absolute_position
            << " layer_mask=" << q65536_early_conv_f32_silu_layer_mask
            << " accumulation=f32"
            << " product=amdgcn_fdot2_bf16_bf16"
            << " pre_silu_round=none"
            << " exponential=amdgcn_exp2_log2e"
            << " output_round=bf16_rne"
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    ++layer.decode_qkv_token_count;
    lease->mark_work_submitted();
    return true;
}

// Bound the alternate arithmetic to one real input at a K64 boundary. This
// scope ends before any generated output token is decoded, including errors.
// Limit this probe to the first reference prefill bucket. The qualified q8193
// cold route crosses a scheduler boundary and keeps its existing recurrence.
struct ScopedQwen36PrefixFlaSingleSuffix {
    inline static thread_local ScopedQwen36PrefixFlaSingleSuffix* active = nullptr;
    ScopedQwen36PrefixFlaSingleSuffix* previous;
    bool enabled;
    size_t position;
    uint64_t layers = 0u;
    ScopedQwen36PrefixFlaSingleSuffix(bool requested, size_t prefix, size_t suffix)
        : previous(active), enabled(requested && prefix && prefix < 8192u && prefix % 64u == 0u && suffix == 1u),
          position(prefix) { active = this; }
    ~ScopedQwen36PrefixFlaSingleSuffix() { active = previous; }
    ScopedQwen36PrefixFlaSingleSuffix(const ScopedQwen36PrefixFlaSingleSuffix&) = delete;
    ScopedQwen36PrefixFlaSingleSuffix& operator=(const ScopedQwen36PrefixFlaSingleSuffix&) = delete;
    bool claim(unsigned layer, size_t actual_position) {
        if (!enabled || actual_position != position || layer >= 40u || layer % 4u == 3u ||
            (layers & (UINT64_C(1) << layer))) return false;
        layers |= UINT64_C(1) << layer; return true;
    }
    bool complete() const { return !enabled || layers == UINT64_C(0x7777777777); }
};

bool run_qwen36_resident_linear_sm121_core_step(
    ScopedQwen36ResidentSessionDecode *lease, unsigned int layer_index,
    size_t position, const float *conv, const float *a, const float *b,
    float *postconv, float *gates, float *output,
    std::string *failure_stage, std::string *failure, hipStream_t stream
) {
    const std::string stage = "qwen36_resident_linear_sm121_core";
    if (!lease || !lease->ready() || layer_index >= QRT_QWEN36_LAYER_COUNT ||
        layer_index % 4u == 3u || !conv || !a || !b || !postconv || !gates || !output)
        return qwen36_resident_decode_set_failure(stage, "invalid SM121 Q1 frontier", failure_stage, failure);
    Qwen36ResidentSessionLinearLayer &layer = g_qwen36_resident_session.linear_layers[layer_index];
    if (!layer.valid || !layer.device_recurrent_state || layer.recurrent_state_bytes != 524288u * sizeof(float) ||
        layer.decode_recurrent_token_count != g_qwen36_resident_session.committed_decode_token_count ||
        position != layer.prefix_tokens + layer.decode_recurrent_token_count ||
        layer.decode_qkv_token_count != layer.decode_recurrent_token_count + 1u)
        return qwen36_resident_decode_set_failure(stage, "SM121 Q1 cache does not follow the completed convolution", failure_stage, failure);
    qrt_sm121_q1_runtime::Tables tables;
    const hipError_t prepared = qrt_sm121_q1_runtime::prepare(&tables);
    const float *g_table = nullptr;
    if (prepared != hipSuccess)
        return qwen36_resident_decode_set_failure(stage, hipGetErrorString(prepared), failure_stage, failure);
    if (!load_q1_sm121_gate_table(layer_index, &g_table, failure)) {
        *failure_stage = stage;
        return false;
    }
    auto* suffix = ScopedQwen36PrefixFlaSingleSuffix::active;
    if (suffix && suffix->enabled) {
        if (!suffix->claim(layer_index, position))
            return qwen36_resident_decode_set_failure(stage, "FLA suffix layer or position is outside its single input scope", failure_stage, failure);
#ifndef _WIN32
        return qwen36_resident_decode_set_failure(stage, "FLA suffix provider requires Windows", failure_stage, failure);
#else
        AiterFusedGdnDynamicLaunchFn unused = nullptr;
        if (!load_fla_chunk_gdn_dynamic_provider(&unused, failure_stage, failure)) return false;
        auto& provider = fla_chunk_gdn_dynamic_provider_state();
        const auto launch = layer.recurrent_state_key_major
            ? provider.seeded_key_major_launch : provider.seeded_launch;
        if (!launch)
            return qwen36_resident_decode_set_failure(stage, "FLA provider lacks the required FP32 seeded state layout", failure_stage, failure);
        hipLaunchKernelGGL(qrt_sm121_q1::prepare_fla_suffix, dim3(32), dim3(256), 0, stream,
            conv, a, b, postconv, gates, g_table, tables.beta);
        const hipError_t prepared_inputs = hipGetLastError();
        if (prepared_inputs != hipSuccess)
            return qwen36_resident_decode_set_failure(stage, hipGetErrorString(prepared_inputs), failure_stage, failure);
        lease->mark_work_submitted();
        if (!launch(conv, gates, output, layer.device_recurrent_state, 0, stream, 1))
            return qwen36_resident_decode_set_failure(stage, fla_chunk_gdn_dynamic_provider_last_error(), failure_stage, failure);
        std::cerr << "BATCH_MARK qwen36_prefix_fla_single_suffix layer=" << layer_index
                  << " position=" << position << " state_key_major=" << layer.recurrent_state_key_major
                  << " input_tokens=1 fp32_seed=1" << std::endl;
#endif
    } else {
        hipLaunchKernelGGL(qrt_sm121_q1::recurrent, dim3(32), dim3(128), 0, stream,
            conv, a, b, layer.device_recurrent_state, layer.recurrent_state_key_major,
            output, postconv, gates, nullptr, g_table, tables.beta, tables.exp2, tables.rsqrt);
        const hipError_t launched = hipGetLastError();
        if (launched != hipSuccess)
            return qwen36_resident_decode_set_failure(stage, hipGetErrorString(launched), failure_stage, failure);
    }
    ++layer.decode_recurrent_token_count;
    lease->mark_work_submitted();
    return true;
}

bool run_qwen36_resident_linear_recurrent_core_step(
    ScopedQwen36ResidentSessionDecode *lease,
    unsigned int layer_index,
    size_t absolute_position,
    const float *device_postconv,
    const float *device_gate,
    float *device_core_output,
    bool use_shared_gate_core,
    bool use_key_major_state,
    std::string *failure_stage,
    std::string *failure,
    hipStream_t stream = nullptr
) {
    const std::string stage = "qwen36_resident_linear_recurrent_core";
    if (lease == nullptr || !lease->ready() ||
        layer_index >= QRT_QWEN36_LAYER_COUNT ||
        (layer_index % 4u) == 3u || device_postconv == nullptr ||
        device_gate == nullptr || device_core_output == nullptr) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear recurrent-core step received an invalid lease, layer, or device surface",
            failure_stage,
            failure
        );
    }
    Qwen36ResidentSessionLinearLayer &layer =
        g_qwen36_resident_session.linear_layers[layer_index];
    const size_t expected_state_bytes =
        static_cast<size_t>(kValueFeatures) * static_cast<size_t>(kKeyDim) *
        sizeof(float);
    if (!layer.valid || layer.device_recurrent_state == nullptr ||
        layer.recurrent_state_bytes != expected_state_bytes ||
        layer.decode_recurrent_token_count !=
            g_qwen36_resident_session.committed_decode_token_count ||
        absolute_position != layer.prefix_tokens +
            layer.decode_recurrent_token_count ||
        layer.decode_qkv_token_count !=
            layer.decode_recurrent_token_count + 1u ||
        layer.recurrent_state_key_major != use_key_major_state) {
        return qwen36_resident_decode_set_failure(
            stage,
            "resident linear recurrent state does not match the completed QKV step or absolute position",
            failure_stage,
            failure
        );
    }

    // Each thread owns one value row and reads its complete key row before it
    // overwrites that same row, so the existing exact cache kernel is safe with
    // the resident state passed as both input and output.
    if (use_key_major_state) {
        hipLaunchKernelGGL(
            core_rows_cache_state_key_major_shared_gate_kernel,
            dim3(kValueHeads),
            dim3(kValueDim),
            0,
            stream,
            device_postconv,
            device_gate,
            layer.device_recurrent_state,
            layer.device_recurrent_state,
            device_core_output
        );
    } else if (use_shared_gate_core) {
        hipLaunchKernelGGL(
            core_rows_cache_state_shared_gate_kernel,
            dim3(kValueHeads),
            dim3(kValueDim),
            0,
            stream,
            device_postconv,
            device_gate,
            layer.device_recurrent_state,
            layer.device_recurrent_state,
            device_core_output
        );
    } else {
        hipLaunchKernelGGL(
            core_rows_cache_state_kernel,
            dim3(kValueHeads),
            dim3(kValueDim),
            0,
            stream,
            device_postconv,
            device_gate,
            layer.device_recurrent_state,
            layer.device_recurrent_state,
            device_core_output,
            1u
        );
    }
    const hipError_t status = hipGetLastError();
    if (status != hipSuccess) {
        return qwen36_resident_decode_set_failure(
            stage,
            std::string("resident recurrent-core kernel launch failed: ") +
                hipGetErrorString(status),
            failure_stage,
            failure
        );
    }
    ++layer.decode_recurrent_token_count;
    lease->mark_work_submitted();
    return true;
}

