std::string hex_u64(uint64_t value);

bool invalid_descriptor_token_hash(uint64_t value) {
    return value == UINT64_C(0) ||
        value == UINT64_C(1469598103934665603);
}

uint64_t token_ids_hash_or_compute(
    uint64_t hash,
    const std::vector<unsigned int> &token_ids
) {
    if (!invalid_descriptor_token_hash(hash)) {
        return hash;
    }
    if (token_ids.empty()) {
        return hash;
    }
    return qrt_fnv1a64_bytes(
        token_ids.data(),
        token_ids.size() * sizeof(token_ids[0])
    );
}

enum class DescriptorResidentLayerSurfaceKind {
    kOutputHidden,
    kResidualHidden,
    kPostAttention,
    kVllmUnroundedSumsq,
};

const char *descriptor_resident_layer_surface_kind_name(
    DescriptorResidentLayerSurfaceKind kind
) {
    switch (kind) {
    case DescriptorResidentLayerSurfaceKind::kOutputHidden:
        return "output_hidden";
    case DescriptorResidentLayerSurfaceKind::kResidualHidden:
        return "residual_hidden";
    case DescriptorResidentLayerSurfaceKind::kPostAttention:
        return "post_attention";
    case DescriptorResidentLayerSurfaceKind::kVllmUnroundedSumsq:
        return "vllm_unrounded_sumsq";
    }
    return "unknown";
}

struct DescriptorResidentLayerSurface {
    DescriptorResidentLayerSurfaceKind kind =
        DescriptorResidentLayerSurfaceKind::kOutputHidden;
    float *device_output = nullptr;
    size_t output_bytes = 0u;
    unsigned int layer_index = UINT_MAX;
    uint64_t selected_token_ids_hash = UINT64_C(0);
};

struct DescriptorResidentLayerStackCarrier {
    std::vector<DescriptorResidentLayerSurface> surfaces;
    uint64_t store_count = UINT64_C(0);
    uint64_t take_count = UINT64_C(0);
    uint64_t take_hit_count = UINT64_C(0);
    uint64_t borrow_count = UINT64_C(0);
    uint64_t borrow_hit_count = UINT64_C(0);
    uint64_t release_count = UINT64_C(0);
    uint64_t peak_bytes = UINT64_C(0);
    uint64_t resident_bytes = UINT64_C(0);
    bool active = false;
};

DescriptorResidentLayerStackCarrier
    *g_descriptor_resident_layer_stack_carrier = nullptr;

bool descriptor_resident_layer_stack_carrier_active() {
    return g_descriptor_resident_layer_stack_carrier != nullptr &&
        g_descriptor_resident_layer_stack_carrier->active;
}

void release_descriptor_resident_layer_surface(
    DescriptorResidentLayerSurface *surface
) {
    if (surface == nullptr) {
        return;
    }
    free_device(surface->device_output);
    surface->device_output = nullptr;
    surface->output_bytes = 0u;
    surface->layer_index = UINT_MAX;
    surface->selected_token_ids_hash = UINT64_C(0);
}

void release_descriptor_resident_layer_stack_carrier(
    DescriptorResidentLayerStackCarrier *carrier
) {
    if (carrier == nullptr) {
        return;
    }
    for (DescriptorResidentLayerSurface &surface : carrier->surfaces) {
        release_descriptor_resident_layer_surface(&surface);
    }
    carrier->surfaces.clear();
    carrier->resident_bytes = UINT64_C(0);
    carrier->active = false;
}

struct ScopedDescriptorResidentLayerStackCarrierRuntime {
    DescriptorResidentLayerStackCarrier carrier;
    DescriptorResidentLayerStackCarrier *previous = nullptr;

    explicit ScopedDescriptorResidentLayerStackCarrierRuntime(bool enabled)
        : previous(g_descriptor_resident_layer_stack_carrier) {
        if (enabled) {
            carrier.active = true;
            g_descriptor_resident_layer_stack_carrier = &carrier;
        }
    }

    ~ScopedDescriptorResidentLayerStackCarrierRuntime() {
        if (g_descriptor_resident_layer_stack_carrier == &carrier) {
            g_descriptor_resident_layer_stack_carrier = previous;
        }
        release_descriptor_resident_layer_stack_carrier(&carrier);
    }
};

bool descriptor_resident_layer_surface_matches(
    const DescriptorResidentLayerSurface &surface,
    DescriptorResidentLayerSurfaceKind kind,
    unsigned int layer_index,
    uint64_t selected_token_ids_hash,
    size_t output_bytes
) {
    return surface.device_output != nullptr &&
        surface.kind == kind &&
        surface.layer_index == layer_index &&
        surface.selected_token_ids_hash == selected_token_ids_hash &&
        surface.output_bytes == output_bytes;
}

bool capture_native_dflash_q8192_context_layer(
    unsigned int layer_index,
    const float *device_hidden,
    std::string *failure_stage,
    std::string *failure
);

void remove_descriptor_resident_layer_surface_at(
    DescriptorResidentLayerStackCarrier *carrier,
    size_t index
) {
    if (carrier == nullptr || index >= carrier->surfaces.size()) {
        return;
    }
    DescriptorResidentLayerSurface &surface = carrier->surfaces[index];
    if (surface.device_output != nullptr) {
        if (carrier->resident_bytes >= surface.output_bytes) {
            carrier->resident_bytes -= surface.output_bytes;
        } else {
            carrier->resident_bytes = UINT64_C(0);
        }
        ++carrier->release_count;
    }
    release_descriptor_resident_layer_surface(&surface);
    carrier->surfaces.erase(carrier->surfaces.begin() + index);
}

void store_descriptor_resident_layer_stack_surface(
    DescriptorResidentLayerSurfaceKind kind,
    unsigned int layer_index,
    uint64_t selected_token_ids_hash,
    size_t output_bytes,
    float **device_output
) {
    DescriptorResidentLayerStackCarrier *carrier =
        g_descriptor_resident_layer_stack_carrier;
    if (carrier == nullptr || !carrier->active ||
        device_output == nullptr || *device_output == nullptr ||
        invalid_descriptor_token_hash(selected_token_ids_hash) ||
        output_bytes == 0u) {
        return;
    }
    if (kind == DescriptorResidentLayerSurfaceKind::kOutputHidden &&
        output_bytes ==
            kRetainedPrefillTokens *
                static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) * sizeof(float)) {
        const bool dflash_target_layer =
            layer_index == 1u || layer_index == 10u || layer_index == 19u ||
            layer_index == 28u || layer_index == 37u;
        if (dflash_target_layer &&
            (raw_env_flag_enabled(
                 "QRT_QWEN36_DFLASH_NATIVE_Q8192_CONTEXT"
             ) ||
             raw_env_flag_enabled(
                 "QRT_QWEN36_DFLASH_NATIVE_Q8192_ROUND2_PROBE"
             ))) {
            std::string dflash_failure_stage;
            std::string dflash_failure;
            if (!capture_native_dflash_q8192_context_layer(
                    layer_index,
                    *device_output,
                    &dflash_failure_stage,
                    &dflash_failure
                )) {
                std::cerr
                    << "BATCH_MARK native_dflash_q8192_context_failure"
                    << " layer=" << layer_index
                    << " failure_stage="
                    << (dflash_failure_stage.empty()
                            ? "unknown"
                            : dflash_failure_stage)
                    << " failure="
                    << (dflash_failure.empty() ? "unknown" : dflash_failure)
                    << " numerical_correctness_claimed=0"
                    << std::endl;
            }
        }
        const char *dump_dir = std::getenv(
            "QRT_QWEN36_DFLASH_Q8192_TARGET_HIDDEN_DUMP_DIR"
        );
        if (dflash_target_layer && dump_dir != nullptr &&
            dump_dir[0] != '\0') {
            const uint64_t dump_start_ns = qrt_now_ns();
            std::vector<float> values(output_bytes / sizeof(float), 0.0f);
            const hipError_t copy_status = hipMemcpy(
                values.data(),
                *device_output,
                output_bytes,
                hipMemcpyDeviceToHost
            );
            bool write_ok = false;
            const std::string path = join_path(
                dump_dir,
                "dflash-q8192-target-hidden-layer" +
                    std::to_string(layer_index) + ".f32"
            );
            if (copy_status == hipSuccess) {
                std::ofstream stream(
                    path,
                    std::ios::binary | std::ios::trunc
                );
                if (stream) {
                    stream.write(
                        reinterpret_cast<const char *>(values.data()),
                        static_cast<std::streamsize>(output_bytes)
                    );
                    stream.close();
                    write_ok = static_cast<bool>(stream);
                }
            }
            std::cerr
                << "BATCH_MARK qwen36_dflash_q8192_target_hidden_dump"
                << " layer=" << layer_index
                << " tokens=" << kRetainedPrefillTokens
                << " hidden_size=" << QRT_QWEN36_HIDDEN_SIZE
                << " bytes=" << output_bytes
                << " copy_status=" << static_cast<int>(copy_status)
                << " write_ok=" << (write_ok ? 1 : 0)
                << " fnv1a64="
                << (copy_status == hipSuccess
                        ? hex_u64(qrt_fnv1a64_bytes(
                              values.data(),
                              output_bytes
                          ))
                        : "0000000000000000")
                << " elapsed_ms="
                << (static_cast<double>(
                        qrt_elapsed_ns(dump_start_ns, qrt_now_ns())
                    ) / 1000000.0)
                << " numerical_correctness_claimed=0"
                << std::endl;
        }
    }
    for (size_t index = carrier->surfaces.size(); index > 0u; --index) {
        const DescriptorResidentLayerSurface &surface =
            carrier->surfaces[index - 1u];
        if (surface.kind == kind && surface.layer_index == layer_index) {
            remove_descriptor_resident_layer_surface_at(carrier, index - 1u);
        }
    }
    DescriptorResidentLayerSurface surface;
    surface.kind = kind;
    surface.device_output = *device_output;
    surface.output_bytes = output_bytes;
    surface.layer_index = layer_index;
    surface.selected_token_ids_hash = selected_token_ids_hash;
    carrier->surfaces.push_back(surface);
    *device_output = nullptr;
    ++carrier->store_count;
    carrier->resident_bytes += static_cast<uint64_t>(output_bytes);
    if (carrier->resident_bytes > carrier->peak_bytes) {
        carrier->peak_bytes = carrier->resident_bytes;
    }
    std::cerr << "BATCH_MARK descriptor_resident_layer_stack_carrier_store"
              << " kind=" << descriptor_resident_layer_surface_kind_name(kind)
              << " layer=" << layer_index
              << " output_bytes=" << output_bytes
              << " selected_token_ids_hash="
              << hex_u64(selected_token_ids_hash)
              << " resident_bytes=" << carrier->resident_bytes
              << " surface_count=" << carrier->surfaces.size()
              << std::endl;
}

bool borrow_descriptor_resident_layer_stack_surface(
    DescriptorResidentLayerSurfaceKind kind,
    unsigned int layer_index,
    uint64_t selected_token_ids_hash,
    size_t output_bytes,
    const char *consumer,
    float **device_output
) {
    DescriptorResidentLayerStackCarrier *carrier =
        g_descriptor_resident_layer_stack_carrier;
    if (device_output != nullptr) {
        *device_output = nullptr;
    }
    if (carrier == nullptr || !carrier->active || device_output == nullptr ||
        invalid_descriptor_token_hash(selected_token_ids_hash) ||
        output_bytes == 0u) {
        return false;
    }
    ++carrier->borrow_count;
    for (DescriptorResidentLayerSurface &surface : carrier->surfaces) {
        if (descriptor_resident_layer_surface_matches(
                surface,
                kind,
                layer_index,
                selected_token_ids_hash,
                output_bytes
            )) {
            *device_output = surface.device_output;
            ++carrier->borrow_hit_count;
            std::cerr
                << "BATCH_MARK descriptor_resident_layer_stack_carrier_borrow"
                << " kind="
                << descriptor_resident_layer_surface_kind_name(kind)
                << " consumer=" << (consumer != nullptr ? consumer : "unknown")
                << " layer=" << layer_index
                << " hit=1"
                << " output_bytes=" << output_bytes
                << " selected_token_ids_hash="
                << hex_u64(selected_token_ids_hash)
                << std::endl;
            return true;
        }
    }
    std::cerr << "BATCH_MARK descriptor_resident_layer_stack_carrier_borrow"
              << " kind=" << descriptor_resident_layer_surface_kind_name(kind)
              << " consumer=" << (consumer != nullptr ? consumer : "unknown")
              << " layer=" << layer_index
              << " hit=0"
              << " output_bytes=" << output_bytes
              << " selected_token_ids_hash="
              << hex_u64(selected_token_ids_hash)
              << std::endl;
    return false;
}

bool take_descriptor_resident_layer_stack_surface(
    DescriptorResidentLayerSurfaceKind kind,
    unsigned int layer_index,
    uint64_t selected_token_ids_hash,
    size_t output_bytes,
    const char *consumer,
    float **device_output
) {
    DescriptorResidentLayerStackCarrier *carrier =
        g_descriptor_resident_layer_stack_carrier;
    if (device_output != nullptr) {
        *device_output = nullptr;
    }
    if (carrier == nullptr || !carrier->active || device_output == nullptr ||
        invalid_descriptor_token_hash(selected_token_ids_hash) ||
        output_bytes == 0u) {
        return false;
    }
    ++carrier->take_count;
    for (size_t index = 0u; index < carrier->surfaces.size(); ++index) {
        DescriptorResidentLayerSurface &surface = carrier->surfaces[index];
        if (descriptor_resident_layer_surface_matches(
                surface,
                kind,
                layer_index,
                selected_token_ids_hash,
                output_bytes
            )) {
            *device_output = surface.device_output;
            surface.device_output = nullptr;
            if (carrier->resident_bytes >= output_bytes) {
                carrier->resident_bytes -= static_cast<uint64_t>(output_bytes);
            } else {
                carrier->resident_bytes = UINT64_C(0);
            }
            ++carrier->take_hit_count;
            carrier->surfaces.erase(carrier->surfaces.begin() + index);
            std::cerr
                << "BATCH_MARK descriptor_resident_layer_stack_carrier_take"
                << " kind="
                << descriptor_resident_layer_surface_kind_name(kind)
                << " consumer=" << (consumer != nullptr ? consumer : "unknown")
                << " layer=" << layer_index
                << " hit=1"
                << " output_bytes=" << output_bytes
                << " selected_token_ids_hash="
                << hex_u64(selected_token_ids_hash)
                << " resident_bytes=" << carrier->resident_bytes
                << std::endl;
            return true;
        }
    }
    std::cerr << "BATCH_MARK descriptor_resident_layer_stack_carrier_take"
              << " kind=" << descriptor_resident_layer_surface_kind_name(kind)
              << " consumer=" << (consumer != nullptr ? consumer : "unknown")
              << " layer=" << layer_index
              << " hit=0"
              << " output_bytes=" << output_bytes
              << " selected_token_ids_hash="
              << hex_u64(selected_token_ids_hash)
              << std::endl;
    return false;
}

void release_descriptor_resident_layer_stack_surface(
    DescriptorResidentLayerSurfaceKind kind,
    unsigned int layer_index,
    uint64_t selected_token_ids_hash,
    size_t output_bytes
) {
    DescriptorResidentLayerStackCarrier *carrier =
        g_descriptor_resident_layer_stack_carrier;
    if (carrier == nullptr || !carrier->active ||
        invalid_descriptor_token_hash(selected_token_ids_hash) ||
        output_bytes == 0u) {
        return;
    }
    for (size_t index = carrier->surfaces.size(); index > 0u; --index) {
        const DescriptorResidentLayerSurface &surface =
            carrier->surfaces[index - 1u];
        if (descriptor_resident_layer_surface_matches(
                surface,
                kind,
                layer_index,
                selected_token_ids_hash,
                output_bytes
            )) {
            std::cerr
                << "BATCH_MARK descriptor_resident_layer_stack_carrier_release"
                << " kind="
                << descriptor_resident_layer_surface_kind_name(kind)
                << " layer=" << layer_index
                << " output_bytes=" << output_bytes
                << " selected_token_ids_hash="
                << hex_u64(selected_token_ids_hash)
                << std::endl;
            remove_descriptor_resident_layer_surface_at(carrier, index - 1u);
        }
    }
}

struct ScopedDescriptorResidentLayerSurfaceRelease {
    DescriptorResidentLayerSurfaceKind kind =
        DescriptorResidentLayerSurfaceKind::kOutputHidden;
    unsigned int layer_index = UINT_MAX;
    uint64_t selected_token_ids_hash = UINT64_C(0);
    size_t output_bytes = 0u;
    bool active = false;

    ScopedDescriptorResidentLayerSurfaceRelease(
        DescriptorResidentLayerSurfaceKind surface_kind,
        unsigned int layer,
        uint64_t token_hash,
        size_t bytes,
        bool enabled
    ) : kind(surface_kind),
        layer_index(layer),
        selected_token_ids_hash(token_hash),
        output_bytes(bytes),
        active(enabled) {}

    ~ScopedDescriptorResidentLayerSurfaceRelease() {
        if (active) {
            release_descriptor_resident_layer_stack_surface(
                kind,
                layer_index,
                selected_token_ids_hash,
                output_bytes
            );
        }
    }
};

