std::string hex_u64(uint64_t value);

struct DescriptorDecodeResidentD2DCacheStateSurface {
    std::array<float *, QRT_QWEN36_LAYER_COUNT> linear_core_states{};
    std::array<uint64_t, QRT_QWEN36_LAYER_COUNT> linear_core_state_hashes{};
    size_t linear_core_state_bytes = 0u;
    bool active = false;
};

DescriptorDecodeResidentD2DCacheStateSurface
    *g_descriptor_decode_resident_d2d_cache_state_surface = nullptr;

void release_descriptor_decode_resident_d2d_cache_state_surface(
    DescriptorDecodeResidentD2DCacheStateSurface *surface
) {
    if (surface == nullptr) {
        return;
    }
    for (float *ptr : surface->linear_core_states) {
        free_device(ptr);
    }
    *surface = DescriptorDecodeResidentD2DCacheStateSurface{};
}

struct ScopedDescriptorDecodeResidentD2DCacheStateSurface {
    DescriptorDecodeResidentD2DCacheStateSurface surface;
    DescriptorDecodeResidentD2DCacheStateSurface *previous = nullptr;

    explicit ScopedDescriptorDecodeResidentD2DCacheStateSurface(bool enabled)
        : previous(g_descriptor_decode_resident_d2d_cache_state_surface) {
        if (enabled) {
            surface.active = true;
            g_descriptor_decode_resident_d2d_cache_state_surface = &surface;
        }
    }

    ~ScopedDescriptorDecodeResidentD2DCacheStateSurface() {
        if (g_descriptor_decode_resident_d2d_cache_state_surface == &surface) {
            g_descriptor_decode_resident_d2d_cache_state_surface = previous;
        }
        release_descriptor_decode_resident_d2d_cache_state_surface(&surface);
    }
};

void record_resident_d2d_linear_core_state_lookup(
    bool hit,
    size_t state_bytes
) {
    if (g_layer_stack_wall_clock_buckets == nullptr) {
        return;
    }
    g_layer_stack_wall_clock_buckets
        ->resident_d2d_linear_core_state_lookup_count += UINT64_C(1);
    if (hit) {
        g_layer_stack_wall_clock_buckets
            ->resident_d2d_linear_core_state_hit_count += UINT64_C(1);
        g_layer_stack_wall_clock_buckets
            ->resident_d2d_linear_core_state_h2d_saved_bytes +=
            static_cast<uint64_t>(state_bytes);
    } else {
        g_layer_stack_wall_clock_buckets
            ->resident_d2d_linear_core_state_miss_count += UINT64_C(1);
    }
}

void record_resident_d2d_linear_core_state_store(size_t state_bytes) {
    if (g_layer_stack_wall_clock_buckets == nullptr) {
        return;
    }
    g_layer_stack_wall_clock_buckets
        ->resident_d2d_linear_core_state_store_count += UINT64_C(1);
    g_layer_stack_wall_clock_buckets
        ->resident_d2d_linear_core_state_store_bytes +=
        static_cast<uint64_t>(state_bytes);
}

bool take_descriptor_decode_resident_d2d_linear_core_state(
    unsigned int layer_index,
    uint64_t state_hash,
    size_t state_bytes,
    float **device_state
) {
    if (device_state == nullptr) {
        return false;
    }
    *device_state = nullptr;
    DescriptorDecodeResidentD2DCacheStateSurface *surface =
        g_descriptor_decode_resident_d2d_cache_state_surface;
    if (surface == nullptr || !surface->active) {
        return false;
    }
    if (layer_index >= QRT_QWEN36_LAYER_COUNT ||
        state_hash == UINT64_C(0) ||
        state_hash == UINT64_C(1469598103934665603) ||
        surface->linear_core_state_bytes != state_bytes ||
        surface->linear_core_states[layer_index] == nullptr ||
        surface->linear_core_state_hashes[layer_index] != state_hash) {
        record_resident_d2d_linear_core_state_lookup(false, state_bytes);
        return false;
    }
    *device_state = surface->linear_core_states[layer_index];
    record_resident_d2d_linear_core_state_lookup(true, state_bytes);
    return true;
}

bool store_descriptor_decode_resident_d2d_linear_core_state(
    unsigned int layer_index,
    const float *device_state,
    size_t state_bytes,
    uint64_t state_hash,
    std::string *failure_stage,
    std::string *failure
) {
    DescriptorDecodeResidentD2DCacheStateSurface *surface =
        g_descriptor_decode_resident_d2d_cache_state_surface;
    if (surface == nullptr || !surface->active) {
        return true;
    }
    if (layer_index >= QRT_QWEN36_LAYER_COUNT || device_state == nullptr ||
        state_bytes == 0u || state_hash == UINT64_C(0) ||
        state_hash == UINT64_C(1469598103934665603)) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "prefill_descriptor_batch_resident_d2d_linear_core_state_store";
        }
        if (failure != nullptr) {
            *failure =
                "resident D2D cache-state surface received an invalid linear core state";
        }
        return false;
    }
    if (surface->linear_core_state_bytes != 0u &&
        surface->linear_core_state_bytes != state_bytes) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "prefill_descriptor_batch_resident_d2d_linear_core_state_shape";
        }
        if (failure != nullptr) {
            *failure =
                "resident D2D cache-state surface found an inconsistent linear core state shape";
        }
        return false;
    }
    surface->linear_core_state_bytes = state_bytes;
    if (surface->linear_core_states[layer_index] == nullptr) {
        if (!check_hip(
                hipMalloc(
                    reinterpret_cast<void **>(
                        &surface->linear_core_states[layer_index]
                    ),
                    state_bytes
                ),
                "hipMalloc(resident_d2d_linear_core_state)",
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (!check_hip(
            hipMemcpy(
                surface->linear_core_states[layer_index],
                device_state,
                state_bytes,
                hipMemcpyDeviceToDevice
            ),
            "hipMemcpy(resident_d2d_linear_core_state)",
            failure_stage,
            failure
        )) {
        return false;
    }
    surface->linear_core_state_hashes[layer_index] = state_hash;
    record_resident_d2d_linear_core_state_store(state_bytes);
    std::cerr << "BATCH_MARK resident_d2d_linear_core_state_store"
              << " layer=" << layer_index
              << " state_bytes=" << state_bytes
              << " state_hash=0x" << hex_u64(state_hash)
              << std::endl;
    return true;
}

