bool store_routed_device_packed_weight_cache_entry(
    const std::string &gate_up_tensor_name,
    const std::string &down_tensor_name,
    uint32_t expert_id,
    const uint32_t *source_gate_up_pairs,
    const uint32_t *source_down_row_pairs,
    bool *inserted
) {
    if (inserted != nullptr) {
        *inserted = false;
    }
    if (source_gate_up_pairs == nullptr || source_down_row_pairs == nullptr ||
        gate_up_tensor_name.empty() || down_tensor_name.empty()) {
        ++g_routed_device_packed_weight_cache_stats.store_failure_count;
        return false;
    }
    for (RoutedDevicePackedWeightCacheEntry &cached :
         g_routed_device_packed_weight_cache) {
        if (cached.expert_id == expert_id &&
            cached.gate_up_tensor_name == gate_up_tensor_name &&
            cached.down_tensor_name == down_tensor_name) {
            cached.last_use = ++g_routed_device_packed_weight_cache_clock;
            return true;
        }
    }

    const uint64_t entry_bytes = routed_device_packed_weight_cache_entry_bytes();
    const uint64_t limit = routed_device_packed_weight_cache_limit_bytes();
    if (limit < entry_bytes) {
        ++g_routed_device_packed_weight_cache_stats.store_failure_count;
        return false;
    }
    while (g_routed_device_packed_weight_cache_bytes > limit - entry_bytes) {
        if (!evict_one_routed_device_packed_weight_cache_entry()) {
            ++g_routed_device_packed_weight_cache_stats.store_failure_count;
            return false;
        }
    }

    RoutedDevicePackedWeightCacheEntry entry;
    entry.gate_up_tensor_name = gate_up_tensor_name;
    entry.down_tensor_name = down_tensor_name;
    entry.expert_id = expert_id;
    entry.bytes = entry_bytes;
    entry.last_use = ++g_routed_device_packed_weight_cache_clock;
    const size_t gate_up_bytes =
        kRoutedGateUpPackedPairsPerExpert * sizeof(uint32_t);
    const size_t down_bytes =
        kRoutedDownPackedPairsPerExpert * sizeof(uint32_t);
    if (hipMalloc(
            reinterpret_cast<void **>(&entry.device_gate_up_pairs),
            gate_up_bytes
        ) != hipSuccess ||
        hipMalloc(
            reinterpret_cast<void **>(&entry.device_down_row_pairs),
            down_bytes
        ) != hipSuccess ||
        hipMemcpy(
            entry.device_gate_up_pairs,
            source_gate_up_pairs,
            gate_up_bytes,
            hipMemcpyDeviceToDevice
        ) != hipSuccess ||
        hipMemcpy(
            entry.device_down_row_pairs,
            source_down_row_pairs,
            down_bytes,
            hipMemcpyDeviceToDevice
        ) != hipSuccess) {
        release_routed_device_packed_weight_cache_entry(&entry);
        ++g_routed_device_packed_weight_cache_stats.store_failure_count;
        return false;
    }

    g_routed_device_packed_weight_cache.push_back(entry);
    g_routed_device_packed_weight_cache_bytes += entry_bytes;
    ++g_routed_device_packed_weight_cache_stats.store_count;
    g_routed_device_packed_weight_cache_stats.stored_bytes += entry_bytes;
    g_routed_device_packed_weight_cache_stats.peak_bytes = (std::max)(
        g_routed_device_packed_weight_cache_stats.peak_bytes,
        g_routed_device_packed_weight_cache_bytes
    );
    if (inserted != nullptr) {
        *inserted = true;
    }
    return true;
}

uint64_t routed_compact_device_layout_owned_limit_bytes() {
    return parse_env_u64_or_default(
        "QRT_PREFILL_DESCRIPTOR_BATCH_COMPACT_DEVICE_ROUTED_LAYOUT_CACHE_BYTES",
        UINT64_C(2147483648)
    );
}

bool evict_one_routed_compact_device_layout_owned_entry() {
    size_t lru_index = g_routed_compact_device_layout.size();
    uint64_t lru_clock = (std::numeric_limits<uint64_t>::max)();
    for (size_t index = 0u;
         index < g_routed_compact_device_layout.size();
         ++index) {
        const RoutedDevicePackedWeightCacheEntry &candidate =
            g_routed_compact_device_layout[index];
        // Borrowed entries are only pointer-table aliases into the resident
        // model shard store.  They consume no additional device memory and
        // form the retained q8192 zero-copy layout, so never evict them to
        // make room for request-specific packed copies.
        if (!candidate.borrowed && candidate.last_use < lru_clock) {
            lru_clock = candidate.last_use;
            lru_index = index;
        }
    }
    if (lru_index == g_routed_compact_device_layout.size()) {
        return false;
    }

    RoutedDevicePackedWeightCacheEntry &entry =
        g_routed_compact_device_layout[lru_index];
    if (g_routed_compact_device_layout_owned_bytes >= entry.bytes) {
        g_routed_compact_device_layout_owned_bytes -= entry.bytes;
    } else {
        g_routed_compact_device_layout_owned_bytes = UINT64_C(0);
    }
    if (g_routed_compact_device_layout_bytes >= entry.bytes) {
        g_routed_compact_device_layout_bytes -= entry.bytes;
    } else {
        g_routed_compact_device_layout_bytes = UINT64_C(0);
    }
    release_routed_device_packed_weight_cache_entry(&entry);
    g_routed_compact_device_layout.erase(
        g_routed_compact_device_layout.begin() +
        static_cast<std::ptrdiff_t>(lru_index)
    );
    ++g_routed_compact_device_layout_stats.eviction_count;
    return true;
}

bool store_routed_compact_device_layout_entry(
    const std::string &gate_up_tensor_name,
    const std::string &down_tensor_name,
    uint32_t expert_id,
    const uint32_t *source_gate_up_pairs,
    const uint32_t *source_down_row_pairs,
    bool *inserted
) {
    if (inserted != nullptr) {
        *inserted = false;
    }
    if (source_gate_up_pairs == nullptr || source_down_row_pairs == nullptr ||
        gate_up_tensor_name.empty() || down_tensor_name.empty()) {
        ++g_routed_compact_device_layout_stats.store_failure_count;
        return false;
    }
    for (RoutedDevicePackedWeightCacheEntry &cached :
         g_routed_compact_device_layout) {
        if (cached.expert_id == expert_id &&
            cached.gate_up_tensor_name == gate_up_tensor_name &&
            cached.down_tensor_name == down_tensor_name) {
            cached.last_use = ++g_routed_compact_device_layout_clock;
            return true;
        }
    }

    const uint64_t entry_bytes =
        routed_device_packed_weight_cache_entry_bytes();
    const uint64_t limit =
        routed_compact_device_layout_owned_limit_bytes();
    if (limit < entry_bytes) {
        ++g_routed_compact_device_layout_stats.store_failure_count;
        return false;
    }
    while (g_routed_compact_device_layout_owned_bytes >
           limit - entry_bytes) {
        if (!evict_one_routed_compact_device_layout_owned_entry()) {
            ++g_routed_compact_device_layout_stats.store_failure_count;
            return false;
        }
    }

    RoutedDevicePackedWeightCacheEntry entry;
    entry.gate_up_tensor_name = gate_up_tensor_name;
    entry.down_tensor_name = down_tensor_name;
    entry.expert_id = expert_id;
    entry.bytes = entry_bytes;
    entry.last_use = ++g_routed_compact_device_layout_clock;
    const size_t gate_up_bytes =
        kRoutedGateUpPackedPairsPerExpert * sizeof(uint32_t);
    const size_t down_bytes =
        kRoutedDownPackedPairsPerExpert * sizeof(uint32_t);
    if (hipMalloc(
            reinterpret_cast<void **>(&entry.device_gate_up_pairs),
            gate_up_bytes
        ) != hipSuccess ||
        hipMalloc(
            reinterpret_cast<void **>(&entry.device_down_row_pairs),
            down_bytes
        ) != hipSuccess ||
        hipMemcpy(
            entry.device_gate_up_pairs,
            source_gate_up_pairs,
            gate_up_bytes,
            hipMemcpyDeviceToDevice
        ) != hipSuccess ||
        hipMemcpy(
            entry.device_down_row_pairs,
            source_down_row_pairs,
            down_bytes,
            hipMemcpyDeviceToDevice
        ) != hipSuccess) {
        release_routed_device_packed_weight_cache_entry(&entry);
        ++g_routed_compact_device_layout_stats.store_failure_count;
        return false;
    }

    g_routed_compact_device_layout.push_back(entry);
    g_routed_compact_device_layout_bytes += entry.bytes;
    g_routed_compact_device_layout_owned_bytes += entry.bytes;
    ++g_routed_compact_device_layout_stats.store_count;
    g_routed_compact_device_layout_stats.stored_bytes += entry.bytes;
    g_routed_compact_device_layout_stats.peak_bytes = (std::max)(
        g_routed_compact_device_layout_stats.peak_bytes,
        g_routed_compact_device_layout_bytes
    );
    if (inserted != nullptr) {
        *inserted = true;
    }
    return true;
}

bool store_routed_compact_device_layout_gb10_alias_entry(
    const std::string &gate_up_tensor_name,
    const std::string &down_tensor_name,
    uint32_t expert_id,
    const uint16_t *source_gate_up,
    const uint16_t *source_down,
    bool *inserted
) {
    if (inserted != nullptr) {
        *inserted = false;
    }
    if (source_gate_up == nullptr || source_down == nullptr ||
        gate_up_tensor_name.empty() || down_tensor_name.empty()) {
        ++g_routed_compact_device_layout_stats.store_failure_count;
        return false;
    }
    for (RoutedDevicePackedWeightCacheEntry &cached :
         g_routed_compact_device_layout) {
        if (cached.expert_id == expert_id &&
            cached.gate_up_tensor_name == gate_up_tensor_name &&
            cached.down_tensor_name == down_tensor_name) {
            cached.last_use = ++g_routed_compact_device_layout_clock;
            return true;
        }
    }

    RoutedDevicePackedWeightCacheEntry entry;
    entry.gate_up_tensor_name = gate_up_tensor_name;
    entry.down_tensor_name = down_tensor_name;
    entry.expert_id = expert_id;
    entry.device_gate_up_pairs = reinterpret_cast<uint32_t *>(
        const_cast<uint16_t *>(source_gate_up)
    );
    entry.device_down_row_pairs = reinterpret_cast<uint32_t *>(
        const_cast<uint16_t *>(source_down)
    );
    entry.bytes = routed_device_packed_weight_cache_entry_bytes();
    entry.last_use = ++g_routed_compact_device_layout_clock;
    entry.borrowed = true;
    g_routed_compact_device_layout.push_back(entry);
    g_routed_compact_device_layout_bytes += entry.bytes;
    ++g_routed_compact_device_layout_stats.store_count;
    g_routed_compact_device_layout_stats.stored_bytes += entry.bytes;
    g_routed_compact_device_layout_stats.peak_bytes = (std::max)(
        g_routed_compact_device_layout_stats.peak_bytes,
        g_routed_compact_device_layout_bytes
    );
    if (inserted != nullptr) {
        *inserted = true;
    }
    return true;
}

bool get_routed_mapped_raw_weight_view(
    const uint16_t *host_weight,
    size_t byte_count,
    const uint16_t **out_device_weight
) {
    if (out_device_weight != nullptr) {
        *out_device_weight = nullptr;
    }
    if (host_weight == nullptr || byte_count == 0u ||
        out_device_weight == nullptr) {
        return false;
    }
    for (const RoutedMappedRawWeightView &view :
         g_routed_mapped_raw_weight_views) {
        if (view.host == host_weight && view.bytes == byte_count &&
            view.device != nullptr) {
            *out_device_weight = view.device;
            return true;
        }
    }

    void *host_ptr = const_cast<uint16_t *>(host_weight);
    hipError_t status = hipHostRegister(
        host_ptr,
        byte_count,
        hipHostRegisterMapped
    );
    if (status != hipSuccess) {
        (void)hipGetLastError();
        return false;
    }

    void *device_ptr = nullptr;
    status = hipHostGetDevicePointer(&device_ptr, host_ptr, 0);
    if (status != hipSuccess || device_ptr == nullptr) {
        (void)hipHostUnregister(host_ptr);
        (void)hipGetLastError();
        return false;
    }

    RoutedMappedRawWeightView view;
    view.host = host_weight;
    view.device = static_cast<const uint16_t *>(device_ptr);
    view.bytes = byte_count;
    g_routed_mapped_raw_weight_views.push_back(view);
    *out_device_weight = view.device;
    return true;
}

void release_routed_mapped_raw_weight_views() {
    for (const RoutedMappedRawWeightView &view :
         g_routed_mapped_raw_weight_views) {
        if (view.host != nullptr) {
            (void)hipHostUnregister(const_cast<uint16_t *>(view.host));
        }
    }
    g_routed_mapped_raw_weight_views.clear();
}

