    g_q1_moe_w8a8_cache_bytes = UINT64_C(0);
    g_q1_moe_w8a8_cache_layer_count = 0u;
    g_q1_moe_w8a8_full_weight_bytes = UINT64_C(0);
    g_q1_moe_w8a8_full_layer_count = 0u;
    g_q1_moe_w8a8_full_active = false;
    g_q1_moe_packed_w6_full_weight_bytes = UINT64_C(0);
