const uint16_t *find_whole_repeated_layer_fixed_weight(
    const std::string &tensor_name,
    uint64_t bytes
) {
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.tensor_name == tensor_name && entry.bytes == bytes &&
            entry.device_weights != nullptr) {
            return entry.device_weights;
        }
    }
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_qwen36_mtp_fixed_weight_aliases) {
        if (entry.tensor_name == tensor_name && entry.bytes == bytes &&
            entry.device_weights != nullptr) {
            return entry.device_weights;
        }
    }
    return nullptr;
}

const uint16_t *find_whole_repeated_layer_fixed_weight_by_kind(
    unsigned int layer_index,
    qrt_qwen36_tensor_kind_t tensor_kind,
    uint64_t bytes
) {
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.layer_index == layer_index &&
            entry.tensor_kind == tensor_kind && entry.bytes == bytes &&
            entry.device_weights != nullptr) {
            return entry.device_weights;
        }
    }
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_qwen36_mtp_fixed_weight_aliases) {
        if (entry.layer_index == layer_index &&
            entry.tensor_kind == tensor_kind && entry.bytes == bytes &&
            entry.device_weights != nullptr) {
            return entry.device_weights;
        }
    }
    return nullptr;
}

const uint16_t *find_q1_linear_rocblas_qkvz_ab_weight(
    unsigned int layer_index
) {
    if (!g_q1_linear_rocblas_qkvz_ab_active ||
        layer_index >= g_q1_linear_rocblas_qkvz_ab_layer_weights.size()) {
        return nullptr;
    }
    return g_q1_linear_rocblas_qkvz_ab_layer_weights[layer_index];
}

bool prepack_q1_linear_rocblas_qkvz_ab_weights(
    std::string *failure_stage,
    std::string *failure
) {
    if (!env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_ROCBLAS_QKVZ_AB"
        )) {
        return true;
    }
    const bool q1_decode_early_layer_bf16_projection_requested =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DECODE_EARLY_LAYER_BF16_PROJECTION"
        );
    const unsigned int q1_decode_early_layer_bf16_projection_layer_mask =
        env_u32_or_default(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DECODE_EARLY_LAYER_BF16_PROJECTION_LAYER_MASK",
            3u
        ) & 3u;
    const uint32_t selected_early_layer_count =
        (q1_decode_early_layer_bf16_projection_layer_mask & 1u ? 1u : 0u) +
        (q1_decode_early_layer_bf16_projection_layer_mask & 2u ? 1u : 0u);
    const unsigned int first_layer_index =
        q1_decode_early_layer_bf16_projection_requested ? 0u : 2u;
    const uint32_t expected_layer_count =
        28u + (q1_decode_early_layer_bf16_projection_requested
                   ? selected_early_layer_count
                   : 0u);

    constexpr uint64_t kHidden = QRT_QWEN36_HIDDEN_SIZE;
    constexpr uint64_t kQkvBytes =
        static_cast<uint64_t>(kQkvRows) * kHidden * sizeof(uint16_t);
    constexpr uint64_t kZBytes =
        static_cast<uint64_t>(kZRows) * kHidden * sizeof(uint16_t);
    constexpr uint64_t kAbBytes =
        static_cast<uint64_t>(kAbRows) * kHidden * sizeof(uint16_t);
    constexpr uint64_t kLayerBytes =
        static_cast<uint64_t>(kQ1LinearRocblasQkvzAbRows) * kHidden *
        sizeof(uint16_t);
    constexpr size_t kQkvWords =
        static_cast<size_t>(kQkvBytes / sizeof(uint16_t));
    constexpr size_t kZWords =
        static_cast<size_t>(kZBytes / sizeof(uint16_t));
    constexpr size_t kAbWords =
        static_cast<size_t>(kAbBytes / sizeof(uint16_t));
    constexpr size_t kLayerWords =
        static_cast<size_t>(kLayerBytes / sizeof(uint16_t));

    struct LayerSources {
        const uint16_t *qkv = nullptr;
        const uint16_t *z = nullptr;
        const uint16_t *a = nullptr;
        const uint16_t *b = nullptr;
    };
    std::array<LayerSources, QRT_QWEN36_LAYER_COUNT> sources{};
    uint32_t layer_count = 0u;
    for (unsigned int layer_index = first_layer_index;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u) {
            continue;
        }
        if (layer_index < 2u &&
            (q1_decode_early_layer_bf16_projection_layer_mask &
                (1u << layer_index)) == 0u) {
            continue;
        }
        LayerSources &layer = sources[layer_index];
        layer.qkv = find_whole_repeated_layer_fixed_weight_by_kind(
            layer_index,
            QRT_QWEN36_TENSOR_LINEAR_ATTN_QKV,
            kQkvBytes
        );
        layer.z = find_whole_repeated_layer_fixed_weight_by_kind(
            layer_index,
            QRT_QWEN36_TENSOR_LINEAR_ATTN_Z,
            kZBytes
        );
        layer.a = find_whole_repeated_layer_fixed_weight_by_kind(
            layer_index,
            QRT_QWEN36_TENSOR_LINEAR_ATTN_A,
            kAbBytes
        );
        layer.b = find_whole_repeated_layer_fixed_weight_by_kind(
            layer_index,
            QRT_QWEN36_TENSOR_LINEAR_ATTN_B,
            kAbBytes
        );
        if (layer.qkv == nullptr || layer.z == nullptr ||
            layer.a == nullptr || layer.b == nullptr) {
            if (failure_stage != nullptr) {
                *failure_stage =
                    "q1_linear_rocblas_qkvz_ab_source_weights";
            }
            if (failure != nullptr) {
                *failure =
                    "combined BF16 QKVZ+A/B prepack requires all " +
                    std::to_string(expected_layer_count) +
                    " requested resident linear-attention weight quartets";
            }
            return false;
        }
        ++layer_count;
    }
    if (layer_count != expected_layer_count) {
        if (failure_stage != nullptr) {
            *failure_stage = "q1_linear_rocblas_qkvz_ab_layer_count";
        }
        if (failure != nullptr) {
            *failure =
                "combined BF16 QKVZ+A/B prepack did not find exactly " +
                std::to_string(expected_layer_count) +
                " linear-attention layers";
        }
        return false;
    }

    const uint64_t total_bytes =
        static_cast<uint64_t>(layer_count) * kLayerBytes;

    // The decode-order arena stores each linear layer as input norm followed
    // by QKV, Z, A, and B.  All four matrix sizes are 256-byte aligned, so the
    // requested combined QKVZ+A/B view is already byte-for-byte contiguous.
    // Bind that view directly instead of retaining a second 1.4 GiB copy.
    const uintptr_t arena_begin = reinterpret_cast<uintptr_t>(
        g_q1_decode_order_fixed_bf16_storage
    );
    const uintptr_t arena_end =
        arena_begin <= (std::numeric_limits<uintptr_t>::max)() -
                g_q1_decode_order_fixed_bf16_storage_bytes
            ? arena_begin +
                static_cast<uintptr_t>(
                    g_q1_decode_order_fixed_bf16_storage_bytes
                )
            : (std::numeric_limits<uintptr_t>::max)();
    auto arena_contains = [&](const uint16_t *pointer,
                              uint64_t bytes) -> bool {
        const uintptr_t address = reinterpret_cast<uintptr_t>(pointer);
        return arena_begin != 0u && address >= arena_begin &&
            address <= arena_end && bytes <= arena_end - address;
    };
    auto immediately_follows = [](const uint16_t *first,
                                  uint64_t first_bytes,
                                  const uint16_t *second) -> bool {
        const uintptr_t first_address =
            reinterpret_cast<uintptr_t>(first);
        const uintptr_t second_address =
            reinterpret_cast<uintptr_t>(second);
        return first_address <=
                (std::numeric_limits<uintptr_t>::max)() - first_bytes &&
            second_address == first_address + first_bytes;
    };
    bool decode_order_arena_alias =
        g_q1_decode_order_fixed_bf16_active &&
        g_q1_decode_order_fixed_bf16_storage != nullptr;
    for (unsigned int layer_index = first_layer_index;
         decode_order_arena_alias && layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u ||
            (layer_index < 2u &&
             (q1_decode_early_layer_bf16_projection_layer_mask &
                 (1u << layer_index)) == 0u)) {
            continue;
        }
        const LayerSources &layer = sources[layer_index];
        decode_order_arena_alias =
            arena_contains(layer.qkv, kLayerBytes) &&
            immediately_follows(layer.qkv, kQkvBytes, layer.z) &&
            immediately_follows(layer.z, kZBytes, layer.a) &&
            immediately_follows(layer.a, kAbBytes, layer.b);
    }
    if (decode_order_arena_alias) {
        for (unsigned int layer_index = first_layer_index;
             layer_index < QRT_QWEN36_LAYER_COUNT;
             ++layer_index) {
            if ((layer_index % 4u) == 3u ||
                (layer_index < 2u &&
                 (q1_decode_early_layer_bf16_projection_layer_mask &
                     (1u << layer_index)) == 0u)) {
                continue;
            }
            g_q1_linear_rocblas_qkvz_ab_layer_weights[layer_index] =
                sources[layer_index].qkv;
        }
        g_q1_linear_rocblas_qkvz_ab_weight_storage = nullptr;
        g_q1_linear_rocblas_qkvz_ab_weight_bytes = total_bytes;
        g_q1_linear_rocblas_qkvz_ab_owned_weight_bytes = UINT64_C(0);
        g_q1_linear_rocblas_qkvz_ab_layer_count = layer_count;
        g_q1_linear_rocblas_qkvz_ab_active = true;
        g_q1_linear_rocblas_qkvz_ab_decode_order_arena_alias = true;
        return true;
    }

    uint16_t *storage = nullptr;
    hipError_t status = hipMalloc(
        reinterpret_cast<void **>(&storage),
        static_cast<size_t>(total_bytes)
    );
    if (status != hipSuccess || storage == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage = "q1_linear_rocblas_qkvz_ab_allocate";
        }
        if (failure != nullptr) {
            *failure = std::string(
                "combined BF16 QKVZ+A/B allocation failed: "
            ) + hipGetErrorString(status);
        }
        return false;
    }

    uint32_t packed_layer = 0u;
    for (unsigned int layer_index = first_layer_index;
         layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if ((layer_index % 4u) == 3u) {
            continue;
        }
        if (layer_index < 2u &&
            (q1_decode_early_layer_bf16_projection_layer_mask &
                (1u << layer_index)) == 0u) {
            continue;
        }
        uint16_t *destination =
            storage + static_cast<size_t>(packed_layer) * kLayerWords;
        const LayerSources &layer = sources[layer_index];
        const std::array<const uint16_t *, 4> source = {
            layer.qkv, layer.z, layer.a, layer.b
        };
        const std::array<size_t, 4> words = {
            kQkvWords, kZWords, kAbWords, kAbWords
        };
        size_t destination_offset = 0u;
        for (size_t part = 0u; part < source.size(); ++part) {
            status = hipMemcpyAsync(
                destination + destination_offset,
                source[part],
                words[part] * sizeof(uint16_t),
                hipMemcpyDeviceToDevice,
                nullptr
            );
            if (status != hipSuccess) {
                (void)hipFree(storage);
                if (failure_stage != nullptr) {
                    *failure_stage = "q1_linear_rocblas_qkvz_ab_copy";
                }
                if (failure != nullptr) {
                    *failure = std::string(
                        "combined BF16 QKVZ+A/B device copy failed: "
                    ) + hipGetErrorString(status);
                }
                return false;
            }
            destination_offset += words[part];
        }
        g_q1_linear_rocblas_qkvz_ab_layer_weights[layer_index] =
            destination;
        ++packed_layer;
    }
    g_q1_linear_rocblas_qkvz_ab_weight_storage = storage;
    g_q1_linear_rocblas_qkvz_ab_weight_bytes = total_bytes;
    g_q1_linear_rocblas_qkvz_ab_owned_weight_bytes = total_bytes;
    g_q1_linear_rocblas_qkvz_ab_layer_count = layer_count;
    g_q1_linear_rocblas_qkvz_ab_active = true;
    g_q1_linear_rocblas_qkvz_ab_decode_order_arena_alias = false;
    return true;
}

bool q1_decode_order_fixed_bf16_arena_requested() {
    return env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DECODE_ORDER_FIXED_BF16_ARENA"
    );
}

void print_q1_decode_order_fixed_bf16_arena_marker(
    bool requested,
    bool active,
    uint32_t entry_count,
    uint64_t source_bytes,
    uint64_t arena_bytes,
    double elapsed_ms,
    bool pass,
    const std::string &failure_stage
) {
    std::cerr << "BATCH_MARK q1_decode_order_fixed_bf16_arena_preload"
              << " requested=" << (requested ? 1 : 0)
              << " active=" << (active ? 1 : 0)
              << " entries=" << entry_count
              << " source_bytes=" << source_bytes
              << " arena_bytes=" << arena_bytes
              << " entry_alignment_bytes=256"
              << " copy_kind=device_to_device"
              << " tensor_order=layer_then_runtime_kind_then_lm_head"
              << " routed_expert_weights_reordered=0"
              << " elapsed_ms=" << elapsed_ms
              << " pass=" << (pass ? 1 : 0)
              << " failure_stage="
              << (failure_stage.empty() ? "none" : failure_stage)
              << " weight_bits=16"
              << " quantized=0"
              << " dflash_active=0"
              << " mtp_active=0"
              << " speculative_decode=0"
              << std::endl;
}

bool prepare_q1_decode_order_fixed_bf16_arena(
    std::string *failure_stage,
    std::string *failure
) {
    const bool requested = q1_decode_order_fixed_bf16_arena_requested();
    if (!requested) {
        print_q1_decode_order_fixed_bf16_arena_marker(
            false,
            false,
            0u,
            UINT64_C(0),
            UINT64_C(0),
            0.0,
            true,
            ""
        );
        return true;
    }
    const uint64_t start_ns = qrt_now_ns();
    auto fail = [&](const std::string &stage,
                    const std::string &message) -> bool {
        if (failure_stage != nullptr) {
            *failure_stage = stage;
        }
        if (failure != nullptr) {
            *failure = message;
        }
        print_q1_decode_order_fixed_bf16_arena_marker(
            true,
            false,
            0u,
            UINT64_C(0),
            UINT64_C(0),
            static_cast<double>(qrt_elapsed_ns(start_ns, qrt_now_ns())) /
                1000000.0,
            false,
            stage
        );
        return false;
    };
    if (!env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_MODEL_SHARD_STORE"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_MODEL_SINGLE_DEVICE_ARENA"
        )) {
        return fail(
            "q1_decode_order_fixed_bf16_arena_ownership",
            "decode-order fixed BF16 arena requires the resident shard store and excludes the offset-preserving single-shard arena experiment"
        );
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_W8A8_DYNAMIC"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_W8A8_CACHE"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_W8A8_FULL"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_PACKED_W6_FULL"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DENSE_W8A8_FULL"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DENSE_PACKED_W6_FULL"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LM_HEAD_W8A8"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_W8A8_FUSED_BF16_QUANTIZE"
        ) ||
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_W8A8_FUSED_RMSNORM_QUANTIZE"
        )) {
        return fail(
            "q1_decode_order_fixed_bf16_arena_quantized_conflict",
            "decode-order fixed BF16 arena excludes every quantized decode surface"
        );
    }
    if (g_whole_repeated_layer_fixed_weights.empty() ||
        g_q1_decode_order_fixed_bf16_storage != nullptr ||
        g_q1_decode_order_fixed_bf16_active) {
        return fail(
            "q1_decode_order_fixed_bf16_arena_state",
            "decode-order fixed BF16 arena requires a fresh non-empty fixed-weight set"
        );
    }

    constexpr uint64_t kEntryAlignment = UINT64_C(256);
    std::vector<uint64_t> offsets;
    offsets.reserve(g_whole_repeated_layer_fixed_weights.size());
    uint64_t arena_bytes = UINT64_C(0);
    uint64_t source_bytes = UINT64_C(0);
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (!entry.borrowed || entry.device_weights == nullptr ||
            entry.bytes == UINT64_C(0)) {
            return fail(
                "q1_decode_order_fixed_bf16_arena_source",
                "decode-order fixed BF16 arena requires every fixed tensor to borrow a non-empty resident BF16 view"
            );
        }
        if (arena_bytes > UINT64_MAX - (kEntryAlignment - UINT64_C(1)) ||
            source_bytes > UINT64_MAX - entry.bytes) {
            return fail(
                "q1_decode_order_fixed_bf16_arena_size",
                "decode-order fixed BF16 arena size overflowed"
            );
        }
        arena_bytes =
            (arena_bytes + kEntryAlignment - UINT64_C(1)) &
            ~(kEntryAlignment - UINT64_C(1));
        offsets.push_back(arena_bytes);
        if (entry.bytes > UINT64_MAX - arena_bytes) {
            return fail(
                "q1_decode_order_fixed_bf16_arena_size",
                "decode-order fixed BF16 arena size overflowed"
            );
        }
        arena_bytes += entry.bytes;
        source_bytes += entry.bytes;
    }
    if (arena_bytes == UINT64_C(0) ||
        arena_bytes > static_cast<uint64_t>(
            (std::numeric_limits<size_t>::max)()
        )) {
        return fail(
            "q1_decode_order_fixed_bf16_arena_size",
            "decode-order fixed BF16 arena size is invalid"
        );
    }

    uint8_t *storage = nullptr;
    hipError_t status = hipMalloc(
        reinterpret_cast<void **>(&storage),
        static_cast<size_t>(arena_bytes)
    );
    if (status != hipSuccess || storage == nullptr) {
        return fail(
            "q1_decode_order_fixed_bf16_arena_allocate",
            std::string("decode-order fixed BF16 arena allocation failed: ") +
                hipGetErrorString(status)
        );
    }
    for (size_t index = 0u;
         index < g_whole_repeated_layer_fixed_weights.size();
         ++index) {
        const WholeRepeatedLayerFixedWeightEntry &entry =
            g_whole_repeated_layer_fixed_weights[index];
        status = hipMemcpyAsync(
            storage + offsets[index],
            entry.device_weights,
            static_cast<size_t>(entry.bytes),
            hipMemcpyDeviceToDevice,
            nullptr
        );
        if (status != hipSuccess) {
            (void)hipFree(storage);
            return fail(
                "q1_decode_order_fixed_bf16_arena_copy",
                std::string("decode-order fixed BF16 arena copy failed: ") +
                    hipGetErrorString(status)
            );
        }
    }
    status = hipDeviceSynchronize();
    if (status != hipSuccess) {
        (void)hipFree(storage);
        return fail(
            "q1_decode_order_fixed_bf16_arena_sync",
            std::string("decode-order fixed BF16 arena sync failed: ") +
                hipGetErrorString(status)
        );
    }
    for (size_t index = 0u;
         index < g_whole_repeated_layer_fixed_weights.size();
         ++index) {
        g_whole_repeated_layer_fixed_weights[index].device_weights =
            reinterpret_cast<uint16_t *>(storage + offsets[index]);
    }
    g_q1_decode_order_fixed_bf16_storage = storage;
    g_q1_decode_order_fixed_bf16_storage_bytes = arena_bytes;
    g_q1_decode_order_fixed_bf16_entry_count = static_cast<uint32_t>(
        g_whole_repeated_layer_fixed_weights.size()
    );
    g_q1_decode_order_fixed_bf16_active = true;
    print_q1_decode_order_fixed_bf16_arena_marker(
        true,
        true,
        g_q1_decode_order_fixed_bf16_entry_count,
        source_bytes,
        arena_bytes,
        static_cast<double>(qrt_elapsed_ns(start_ns, qrt_now_ns())) /
            1000000.0,
        true,
        ""
    );
    return true;
}

bool find_q1_dense_w8a8_weight(
    const std::string &tensor_name,
    uint64_t source_bytes,
    uint32_t mask_bit,
    unsigned int row_size,
    unsigned int row_count,
    const int8_t **out_weights,
    const float **out_scales
) {
    if (out_weights == nullptr || out_scales == nullptr ||
        (g_q1_dense_w8a8_active_mask & mask_bit) == 0u) {
        return false;
    }
    *out_weights = nullptr;
    *out_scales = nullptr;
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.tensor_name == tensor_name && entry.bytes == source_bytes &&
            entry.dense_w8a8_mask_bit == mask_bit &&
            entry.dense_w8a8_row_size == row_size &&
            entry.dense_w8a8_row_count == row_count &&
            entry.device_dense_w8a8 != nullptr &&
            entry.device_dense_w8a8_scales != nullptr) {
            *out_weights = entry.device_dense_w8a8;
            *out_scales = entry.device_dense_w8a8_scales;
            return true;
        }
    }
    return false;
}

