bool q1_dense_w8a8_entry_shape(
    const WholeRepeatedLayerFixedWeightEntry &entry,
    uint32_t requested_mask,
    uint32_t *mask_bit,
    unsigned int *row_size,
    unsigned int *row_count
) {
    if ((entry.layer_index < 2u &&
         entry.tensor_kind != QRT_QWEN36_TENSOR_LM_HEAD) ||
        mask_bit == nullptr ||
        row_size == nullptr || row_count == nullptr) {
        return false;
    }
    uint32_t candidate_bit = 0u;
    unsigned int candidate_row_size = 0u;
    unsigned int candidate_row_count = 0u;
    switch (entry.tensor_kind) {
        case QRT_QWEN36_TENSOR_LINEAR_ATTN_QKV:
            candidate_bit = kQ1DenseW8A8LinearInputMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kQkvRows;
            break;
        case QRT_QWEN36_TENSOR_LINEAR_ATTN_Z:
            candidate_bit = kQ1DenseW8A8LinearInputMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kZRows;
            break;
        case QRT_QWEN36_TENSOR_LINEAR_ATTN_OUT_PROJ:
            candidate_bit = kQ1DenseW8A8LinearOutputMask;
            candidate_row_size = kValueFeatures;
            candidate_row_count = kOutProjectionRows;
            break;
        case QRT_QWEN36_TENSOR_LINEAR_ATTN_A:
        case QRT_QWEN36_TENSOR_LINEAR_ATTN_B:
            candidate_bit = kQ1DenseW8A8LinearAbMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kAbRows;
            break;
        case QRT_QWEN36_TENSOR_FULL_ATTN_Q:
            candidate_bit = kQ1DenseW8A8FullInputMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kLayer3FullAttentionQRows;
            break;
        case QRT_QWEN36_TENSOR_FULL_ATTN_K:
            candidate_bit = kQ1DenseW8A8FullInputMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kLayer3FullAttentionKRows;
            break;
        case QRT_QWEN36_TENSOR_FULL_ATTN_V:
            candidate_bit = kQ1DenseW8A8FullInputMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = kLayer3FullAttentionVRows;
            break;
        case QRT_QWEN36_TENSOR_FULL_ATTN_O:
            // Layer 39 intentionally retains its F32 output endpoint.
            if (entry.layer_index + 1u >= QRT_QWEN36_LAYER_COUNT) {
                return false;
            }
            candidate_bit = kQ1DenseW8A8FullOutputMask;
            candidate_row_size = kLayer3FullAttentionQFeatures;
            candidate_row_count = kOutProjectionRows;
            break;
        case QRT_QWEN36_TENSOR_MOE_ROUTER:
            candidate_bit = kQ1DenseW8A8RouterMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = QRT_QWEN36_EXPERT_COUNT;
            break;
        case QRT_QWEN36_TENSOR_LM_HEAD:
            candidate_bit = kQ1DenseW8A8LmHeadMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = QRT_QWEN36_VOCAB_SIZE;
            break;
        case QRT_QWEN36_TENSOR_MOE_SHARED_GATE_PROJ:
        case QRT_QWEN36_TENSOR_MOE_SHARED_UP_PROJ:
            candidate_bit = kQ1DenseW8A8SharedExpertMask;
            candidate_row_size = QRT_QWEN36_HIDDEN_SIZE;
            candidate_row_count = QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            break;
        case QRT_QWEN36_TENSOR_MOE_SHARED_DOWN:
            candidate_bit = kQ1DenseW8A8SharedExpertMask;
            candidate_row_size = QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            candidate_row_count = QRT_QWEN36_HIDDEN_SIZE;
            break;
        default:
            return false;
    }
    const uint64_t expected_bytes =
        static_cast<uint64_t>(candidate_row_size) *
        candidate_row_count * sizeof(uint16_t);
    if ((requested_mask & candidate_bit) == 0u ||
        entry.bytes != expected_bytes ||
        candidate_row_size % kQ1MoeW8A8GroupSize != 0u) {
        return false;
    }
    *mask_bit = candidate_bit;
    *row_size = candidate_row_size;
    *row_count = candidate_row_count;
    return true;
}

const uint16_t *find_q1_moe_transposed_router_weight(
    const std::string &tensor_name,
    uint64_t bytes
) {
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.tensor_name == tensor_name && entry.bytes == bytes &&
            entry.device_router_transposed != nullptr) {
            return entry.device_router_transposed;
        }
    }
    return nullptr;
}

const std::vector<uint16_t> *find_whole_layer_fixed_host_weight(
    const std::string &tensor_name,
    uint64_t bytes
) {
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.tensor_name == tensor_name && entry.bytes == bytes &&
            entry.host_weights.size() * sizeof(uint16_t) == bytes) {
            return &entry.host_weights;
        }
    }
    return nullptr;
}

bool whole_repeated_layer_fixed_weight_contains(const void *ptr) {
    if (ptr == nullptr) {
        return false;
    }
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_whole_repeated_layer_fixed_weights) {
        if (entry.device_weights == ptr) {
            return true;
        }
    }
    for (const WholeRepeatedLayerFixedWeightEntry &entry :
         g_qwen36_mtp_fixed_weight_aliases) {
        if (entry.device_weights == ptr) {
            return true;
        }
    }
    return false;
}

WholeRepeatedRoutedMatrixWeightEntry *
find_whole_repeated_routed_matrix_weights(
    const std::string &gate_up_tensor_name,
    const std::string &down_tensor_name
) {
    for (WholeRepeatedRoutedMatrixWeightEntry &entry :
         g_whole_repeated_routed_matrix_weights) {
        if (entry.gate_up_tensor_name == gate_up_tensor_name &&
            entry.down_tensor_name == down_tensor_name &&
            ((entry.device_gate_up != nullptr &&
              entry.device_down != nullptr) ||
             (entry.device_w8a8_full_gate_up != nullptr &&
              entry.device_w8a8_full_gate_up_scales != nullptr &&
              entry.device_w8a8_full_down != nullptr &&
              entry.device_w8a8_full_down_scales != nullptr) ||
             (entry.device_packed_w6_full_gate_up != nullptr &&
              entry.device_packed_w6_full_gate_up_scales != nullptr &&
              entry.device_packed_w6_full_down != nullptr &&
              entry.device_packed_w6_full_down_scales != nullptr) ||
             (q1_moe_lossless_palette_device_weight_complete(
                  entry.lossless_palette_gate_up
              ) &&
              q1_moe_lossless_palette_device_weight_complete(
                  entry.lossless_palette_down
              )) ||
             (q8192_moe_lossless_row_palette_device_weight_complete(
                  entry.q8192_lossless_row_palette_gate_up
              ) &&
              q8192_moe_lossless_row_palette_device_weight_complete(
                  entry.q8192_lossless_row_palette_down
              )))) {
            return &entry;
        }
    }
    if (g_qwen36_mtp_routed_weight_alias_valid &&
        g_qwen36_mtp_routed_weight_alias.gate_up_tensor_name ==
            gate_up_tensor_name &&
        g_qwen36_mtp_routed_weight_alias.down_tensor_name ==
            down_tensor_name &&
        g_qwen36_mtp_routed_weight_alias.device_gate_up != nullptr &&
        g_qwen36_mtp_routed_weight_alias.device_down != nullptr) {
        return &g_qwen36_mtp_routed_weight_alias;
    }
    return nullptr;
}

bool store_whole_repeated_routed_matrix_weights(
    unsigned int layer_index,
    const std::string &gate_up_tensor_name,
    const std::string &down_tensor_name,
    uint64_t gate_up_bytes,
    uint64_t down_bytes,
    uint16_t **device_gate_up,
    uint16_t **device_down,
    bool borrowed
) {
    if (device_gate_up == nullptr || device_down == nullptr ||
        *device_gate_up == nullptr || *device_down == nullptr ||
        gate_up_bytes == 0u || down_bytes == 0u) {
        return false;
    }
    WholeRepeatedRoutedMatrixWeightEntry entry;
    entry.layer_index = layer_index;
    entry.gate_up_tensor_name = gate_up_tensor_name;
    entry.down_tensor_name = down_tensor_name;
    entry.device_gate_up = *device_gate_up;
    entry.device_down = *device_down;
    entry.gate_up_bytes = gate_up_bytes;
    entry.down_bytes = down_bytes;
    entry.borrowed = borrowed;
    g_whole_repeated_routed_matrix_weights.push_back(entry);
    *device_gate_up = nullptr;
    *device_down = nullptr;
    return true;
}

constexpr uint64_t kResidentModelShardStoreIoChunkBytes =
    UINT64_C(32) * UINT64_C(1024) * UINT64_C(1024);
constexpr size_t kResidentModelShardStoreQueueDepth = 4u;
constexpr uint64_t kResidentModelShardStoreAlignmentBytes = UINT64_C(4096);
constexpr uint64_t kResidentModelShardStoreSingleArenaAlignmentBytes =
    UINT64_C(2) * UINT64_C(1024) * UINT64_C(1024);
constexpr size_t kResidentModelShardStoreVerifyBytes = 4096u;
constexpr uint64_t kResidentModelShardStoreTimeoutNs =
    UINT64_C(55) * UINT64_C(1000000000);
constexpr uint64_t kQ262144ResidentModelGpuReserveBytes =
    UINT64_C(20) * UINT64_C(1024) * UINT64_C(1024) * UINT64_C(1024);

uint64_t resident_model_shard_store_available_physical_bytes() {
#ifdef _WIN32
    MEMORYSTATUSEX status{};
    status.dwLength = sizeof(status);
    if (GlobalMemoryStatusEx(&status)) {
        return static_cast<uint64_t>(status.ullAvailPhys);
    }
#endif
    return UINT64_C(0);
}

