ResidentModelShardStore g_resident_model_shard_store;

// Keep every long-context kernel and allocation below the Windows watchdog /
// large-allocation boundary.  The q262144 linear stack consumes one temporal
// chunk at a time and carries convolution/recurrent state across chunks.
struct Q262144DeviceActivationWorkspace {
    std::mutex mutex;
    uint16_t *qkv = nullptr;
    uint16_t *core = nullptr;
    uint16_t *previous = nullptr;
    uint16_t *input = nullptr;
    uint16_t *upload_host = nullptr;
    uint32_t *prompt_token_ids = nullptr;
    size_t arena_bytes = 0u;
    size_t qkv_bytes = 0u;
    size_t core_bytes = 0u;
    size_t hidden_bytes = 0u;
    size_t upload_bytes = 0u;
    size_t prompt_token_id_bytes = 0u;
    bool borrowed = false;
    bool valid = false;
};

Q262144DeviceActivationWorkspace
    g_q262144_device_activation_workspace;

struct Q262144Bf16LayerHandoff {
    uint16_t *residual_hidden = nullptr;
    uint16_t *post_attention = nullptr;
    uint16_t *output_hidden = nullptr;
    size_t hidden_elements = 0u;
    unsigned int linear_layer_index = UINT_MAX;
    unsigned int output_layer_index = UINT_MAX;
    uint64_t selected_token_ids_hash = UINT64_C(0);
    bool linear_valid = false;
    bool output_valid = false;
};

Q262144Bf16LayerHandoff g_q262144_bf16_layer_handoff;

void reset_q262144_bf16_layer_handoff() {
    g_q262144_bf16_layer_handoff = Q262144Bf16LayerHandoff{};
}

bool q262144_bf16_output_handoff_matches(
    unsigned int layer_index,
    const OutputResidualRun &output,
    unsigned int prefill_tokens
) {
    const size_t expected_hidden_elements =
        static_cast<size_t>(prefill_tokens) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const Q262144Bf16LayerHandoff &handoff =
        g_q262144_bf16_layer_handoff;
    return maximum_context_streamed_prefill_tokens(prefill_tokens) &&
        handoff.output_valid && !handoff.linear_valid &&
        handoff.output_layer_index == layer_index &&
        handoff.output_hidden != nullptr &&
        handoff.hidden_elements == expected_hidden_elements &&
        output.correctness_pass && output.gpu_output.empty() &&
        output.selected_token_count ==
            static_cast<size_t>(prefill_tokens) &&
        output.selected_token_ids.size() ==
            static_cast<size_t>(prefill_tokens) &&
        token_ids_are_zero_based_prefix(
            output.selected_token_ids,
            prefill_tokens
        ) &&
        output.selected_token_ids_hash == handoff.selected_token_ids_hash &&
        output.output_elements == expected_hidden_elements &&
        output.output_bytes == expected_hidden_elements * sizeof(float);
}

constexpr size_t q262144_device_qkv_workspace_bytes() {
    return static_cast<size_t>(kQ262144LinearChunkTokens) *
        static_cast<size_t>(kQkvRows) * sizeof(uint16_t);
}

constexpr size_t q262144_device_hidden_workspace_bytes() {
    return static_cast<size_t>(kQ262144ColdProbePrefillTokens) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) * sizeof(uint16_t);
}

constexpr size_t q262144_device_core_workspace_bytes() {
    return 2u * static_cast<size_t>(kQ262144ColdProbePrefillTokens) *
        static_cast<size_t>(kValueFeatures) * sizeof(uint16_t);
}

constexpr size_t q262144_device_upload_workspace_bytes() {
    return 32u * 1024u * 1024u;
}

constexpr size_t q262144_prompt_token_id_workspace_bytes() {
    return static_cast<size_t>(kQ262144ColdProbePrefillTokens) *
        sizeof(uint32_t);
}

bool q262144_qkv_device_state_complete(
    const Q262144DeviceActivationWorkspace &workspace,
    size_t expected_qkv_bytes
) {
    return expected_qkv_bytes != 0u && workspace.qkv != nullptr &&
        workspace.qkv_bytes == expected_qkv_bytes;
}

bool q262144_qkv_device_state_empty(
    const Q262144DeviceActivationWorkspace &workspace
) {
    return workspace.qkv == nullptr;
}

bool q262144_activation_post_model_requested() {
    const uint64_t requested_prefill_tokens = parse_env_u64_or_default(
               "QRT_PREFILL_DESCRIPTOR_BATCH_REQUEST_PREFILL_TOKENS",
               UINT64_C(0)
           );
    return requested_prefill_tokens <= UINT32_MAX &&
        maximum_context_streamed_prefill_tokens(
            static_cast<unsigned int>(requested_prefill_tokens)
        ) &&
        !raw_env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_COMPACT_DEVICE_ROUTED_LAYOUT_FULL_PRELOAD"
        );
}

bool ensure_q262144_device_activation_workspace(
    std::string *failure_stage,
    std::string *failure,
    bool before_model_store
) {
    if (failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    Q262144DeviceActivationWorkspace &workspace =
        g_q262144_device_activation_workspace;
    std::lock_guard<std::mutex> lock(workspace.mutex);
    const size_t qkv_bytes =
        q262144_device_qkv_workspace_bytes();
    const size_t core_bytes =
        q262144_device_core_workspace_bytes();
    const size_t hidden_bytes =
        q262144_device_hidden_workspace_bytes();
    const size_t arena_bytes =
        qkv_bytes + core_bytes;
    if (workspace.valid &&
        q262144_qkv_device_state_complete(workspace, qkv_bytes) &&
        workspace.core != nullptr &&
        workspace.previous != nullptr && workspace.input != nullptr &&
        workspace.input == workspace.core &&
        workspace.upload_host != nullptr &&
        workspace.prompt_token_ids != nullptr &&
        workspace.arena_bytes == arena_bytes &&
        workspace.qkv_bytes == qkv_bytes &&
        workspace.core_bytes == core_bytes &&
        workspace.hidden_bytes == hidden_bytes &&
        workspace.upload_bytes ==
            q262144_device_upload_workspace_bytes() &&
        workspace.prompt_token_id_bytes ==
            q262144_prompt_token_id_workspace_bytes()) {
        return true;
    }
    if (workspace.valid ||
        !q262144_qkv_device_state_empty(workspace) ||
        workspace.core != nullptr ||
        workspace.previous != nullptr ||
        workspace.input != nullptr || workspace.upload_host != nullptr ||
        workspace.prompt_token_ids != nullptr ||
        workspace.arena_bytes != 0u ||
        workspace.qkv_bytes != 0u || workspace.core_bytes != 0u ||
        workspace.hidden_bytes != 0u ||
        workspace.upload_bytes != 0u ||
        workspace.prompt_token_id_bytes != 0u || workspace.borrowed) {
        *failure_stage =
            "q262144_device_activation_workspace_state";
        *failure =
            "q262144 device activation workspace has a partial prior state";
        return false;
    }
    size_t free_before_bytes = 0u;
    size_t total_before_bytes = 0u;
    const hipError_t info_before_status =
        hipMemGetInfo(&free_before_bytes, &total_before_bytes);
    uint16_t *qkv = nullptr;
    uint16_t *core = nullptr;
    uint16_t *previous = nullptr;
    uint16_t *input = nullptr;
    uint16_t *upload_host = nullptr;
    uint32_t *prompt_token_ids = nullptr;
    auto print_allocation_stage = [&](const char *phase,
                                      const char *surface,
                                      size_t requested_bytes,
                                      hipError_t status) {
        size_t free_bytes = 0u;
        size_t total_bytes = 0u;
        const hipError_t info_status =
            hipMemGetInfo(&free_bytes, &total_bytes);
        std::cerr
            << "BATCH_MARK q262144_activation_device_allocation"
            << " phase=" << phase
            << " surface=" << surface
            << " requested_bytes=" << requested_bytes
            << " allocation_status=" << static_cast<int>(status)
            << " free_device_bytes="
            << (info_status == hipSuccess ? free_bytes : 0u)
            << " total_device_bytes="
            << (info_status == hipSuccess ? total_bytes : 0u)
            << " windows_available_physical_bytes="
            << resident_model_shard_store_available_physical_bytes()
            << " numerical_correctness_claimed=0"
            << std::endl;
    };
    const char *allocation_surface = "qkv_chunk";
    print_allocation_stage(
        "before_allocate",
        allocation_surface,
        qkv_bytes,
        hipSuccess
    );
    hipError_t allocation_status = hipMalloc(
        reinterpret_cast<void **>(&qkv),
        qkv_bytes
    );
    print_allocation_stage(
        "allocated",
        allocation_surface,
        qkv_bytes,
        allocation_status
    );
    if (allocation_status == hipSuccess) {
        allocation_surface = "core";
        print_allocation_stage(
            "before_allocate",
            allocation_surface,
            core_bytes,
            hipSuccess
        );
        allocation_status = hipMalloc(
            reinterpret_cast<void **>(&core),
            core_bytes
        );
        print_allocation_stage(
            "allocated",
            allocation_surface,
            core_bytes,
            allocation_status
        );
        if (allocation_status == hipSuccess) {
            input = core;
        }
    }
    if (allocation_status == hipSuccess) {
        allocation_surface = "previous";
        print_allocation_stage(
            "before_allocate",
            allocation_surface,
            hidden_bytes,
            hipSuccess
        );
        allocation_status = hipMalloc(
            reinterpret_cast<void **>(&previous),
            hidden_bytes
        );
        print_allocation_stage(
            "allocated",
            allocation_surface,
            hidden_bytes,
            allocation_status
        );
    }
    if (allocation_status == hipSuccess) {
        allocation_surface = "upload_host";
        upload_host = static_cast<uint16_t *>(
            std::malloc(q262144_device_upload_workspace_bytes())
        );
        if (upload_host == nullptr) {
            allocation_status = hipErrorOutOfMemory;
        }
    }
    if (allocation_status == hipSuccess) {
        allocation_surface = "prompt_token_ids";
        allocation_status = hipMallocManaged(
            reinterpret_cast<void **>(&prompt_token_ids),
            q262144_prompt_token_id_workspace_bytes(),
            hipMemAttachGlobal
        );
    }
    if (allocation_status != hipSuccess || qkv == nullptr ||
        core == nullptr ||
        previous == nullptr || input == nullptr ||
        upload_host == nullptr || prompt_token_ids == nullptr) {
        size_t free_failure_bytes = 0u;
        size_t total_failure_bytes = 0u;
        const hipError_t info_failure_status =
            hipMemGetInfo(&free_failure_bytes, &total_failure_bytes);
        std::cerr
            << "BATCH_MARK q262144_activation_device_preload"
            << " phase=failure"
            << " before_model_store=" << (before_model_store ? 1 : 0)
            << " surface=" << allocation_surface
            << " status=" << static_cast<int>(allocation_status)
            << " requested_activation_arena_bytes="
            << arena_bytes
            << " requested_qkv_core_bytes=" << qkv_bytes + core_bytes
            << " requested_hidden_bytes=" << hidden_bytes
            << " free_before_bytes="
            << (info_before_status == hipSuccess ? free_before_bytes : 0u)
            << " free_failure_bytes="
            << (info_failure_status == hipSuccess
                    ? free_failure_bytes
                    : 0u)
            << " total_bytes="
            << (info_failure_status == hipSuccess
                    ? total_failure_bytes
                    : (info_before_status == hipSuccess
                           ? total_before_bytes
                           : 0u))
            << " numerical_correctness_claimed=0"
            << std::endl;
        if (prompt_token_ids != nullptr) {
            (void)hipFree(prompt_token_ids);
        }
        if (upload_host != nullptr) {
            std::free(upload_host);
        }
        if (previous != nullptr) {
            (void)hipFree(previous);
        }
        if (core != nullptr) {
            (void)hipFree(core);
        }
        if (qkv != nullptr) {
            (void)hipFree(qkv);
        }
        *failure_stage =
            "q262144_device_activation_workspace_allocate_" +
            std::string(allocation_surface);
        *failure = hipGetErrorString(allocation_status);
        return false;
    }
    workspace.qkv = qkv;
    workspace.core = core;
    workspace.previous = previous;
    workspace.input = input;
    workspace.upload_host = upload_host;
    workspace.prompt_token_ids = prompt_token_ids;
    workspace.arena_bytes = arena_bytes;
    workspace.qkv_bytes = qkv_bytes;
    workspace.core_bytes = core_bytes;
    workspace.hidden_bytes = hidden_bytes;
    workspace.upload_bytes =
        q262144_device_upload_workspace_bytes();
    workspace.prompt_token_id_bytes =
        q262144_prompt_token_id_workspace_bytes();
    workspace.borrowed = false;
    workspace.valid = true;
    size_t free_after_bytes = 0u;
    size_t total_after_bytes = 0u;
    const hipError_t info_after_status =
        hipMemGetInfo(&free_after_bytes, &total_after_bytes);
    std::cerr
        << "BATCH_MARK q262144_activation_device_preload"
        << " phase=ready"
        << " before_model_store=" << (before_model_store ? 1 : 0)
        << " qkv_bf16_bytes=" << qkv_bytes
        << " core_bf16_bytes=" << core_bytes
        << " qkv_core_arena_bytes=" << qkv_bytes + core_bytes
        << " activation_arena_bytes=" << arena_bytes
        << " separate_device_allocations=3"
        << " qkv_vmm=0"
        << " qkv_temporal_chunk_tokens=" << kQ262144LinearChunkTokens
        << " qkv_temporal_chunks="
        << kQ262144ColdProbePrefillTokens / kQ262144LinearChunkTokens
        << " max_single_allocation_bytes="
        << (std::max)(
               qkv_bytes,
               (std::max)(core_bytes, hidden_bytes)
           )
        << " previous_bf16_bytes=" << hidden_bytes
        << " input_bf16_bytes=" << hidden_bytes
        << " input_core_alias=1"
        << " total_device_bytes="
        << arena_bytes + hidden_bytes
        << " pageable_upload_bytes="
        << q262144_device_upload_workspace_bytes()
        << " managed_prompt_token_id_bytes="
        << q262144_prompt_token_id_workspace_bytes()
        << " free_before_bytes="
        << (info_before_status == hipSuccess ? free_before_bytes : 0u)
        << " free_after_bytes="
        << (info_after_status == hipSuccess ? free_after_bytes : 0u)
        << " total_bytes="
        << (info_after_status == hipSuccess
                ? total_after_bytes
                : (info_before_status == hipSuccess
                       ? total_before_bytes
                       : 0u))
        << " allocation_status=" << static_cast<int>(allocation_status)
        << " initialized=0"
        << " lazy_full_overwrite=1"
        << " preclear_bytes=0"
        << " initialization_ms=0"
        << " carrier=device_bf16"
        << " quantized=0 dflash_active=0 mtp_active=0"
        << " speculative_decode=0 numerical_correctness_claimed=0"
        << std::endl;
    return true;
}

bool borrow_q262144_device_activation_workspace(
    size_t qkv_bytes,
    size_t hidden_bytes,
    uint16_t **qkv,
    uint16_t **core,
    uint16_t **previous,
    uint16_t **input,
    uint16_t **upload_host,
    uint32_t **prompt_token_ids
) {
    if (qkv == nullptr || core == nullptr || previous == nullptr ||
        input == nullptr ||
        upload_host == nullptr || prompt_token_ids == nullptr) {
        return false;
    }
    *qkv = nullptr;
    *core = nullptr;
    *previous = nullptr;
    *input = nullptr;
    *upload_host = nullptr;
    *prompt_token_ids = nullptr;
    Q262144DeviceActivationWorkspace &workspace =
        g_q262144_device_activation_workspace;
    std::lock_guard<std::mutex> lock(workspace.mutex);
    if (!workspace.valid || workspace.borrowed ||
        !q262144_qkv_device_state_complete(workspace, qkv_bytes) ||
        workspace.core == nullptr ||
        workspace.previous == nullptr ||
        workspace.input == nullptr || workspace.upload_host == nullptr ||
        workspace.prompt_token_ids == nullptr ||
        workspace.input != workspace.core ||
        workspace.qkv_bytes != qkv_bytes ||
        workspace.core_bytes !=
            q262144_device_core_workspace_bytes() ||
        workspace.hidden_bytes != hidden_bytes ||
        workspace.upload_bytes !=
            q262144_device_upload_workspace_bytes() ||
        workspace.prompt_token_id_bytes !=
            q262144_prompt_token_id_workspace_bytes()) {
        return false;
    }
    workspace.borrowed = true;
    *qkv = workspace.qkv;
    *core = workspace.core;
    *previous = workspace.previous;
    *input = workspace.input;
    *upload_host = workspace.upload_host;
    *prompt_token_ids = workspace.prompt_token_ids;
    return true;
}

void return_q262144_device_activation_workspace(
    uint16_t *qkv
) {
    Q262144DeviceActivationWorkspace &workspace =
        g_q262144_device_activation_workspace;
    std::lock_guard<std::mutex> lock(workspace.mutex);
    if (workspace.valid && workspace.borrowed &&
        workspace.qkv == qkv) {
        workspace.borrowed = false;
    }
}

void release_q262144_device_activation_workspace() {
    Q262144DeviceActivationWorkspace &workspace =
        g_q262144_device_activation_workspace;
    std::lock_guard<std::mutex> lock(workspace.mutex);
    reset_q262144_bf16_layer_handoff();
    if (!workspace.valid && q262144_qkv_device_state_empty(workspace) &&
        workspace.core == nullptr && workspace.previous == nullptr &&
        workspace.input == nullptr &&
        workspace.upload_host == nullptr &&
        workspace.prompt_token_ids == nullptr) {
        return;
    }
    (void)hipDeviceSynchronize();
    if (workspace.prompt_token_ids != nullptr) {
        (void)hipFree(workspace.prompt_token_ids);
    }
    if (workspace.upload_host != nullptr) {
        std::free(workspace.upload_host);
    }
    if (workspace.previous != nullptr) {
        (void)hipFree(workspace.previous);
    }
    if (workspace.core != nullptr) {
        (void)hipFree(workspace.core);
    }
    if (workspace.qkv != nullptr) {
        (void)hipFree(workspace.qkv);
    }
    workspace.qkv = nullptr;
    workspace.core = nullptr;
    workspace.previous = nullptr;
    workspace.input = nullptr;
    workspace.upload_host = nullptr;
    workspace.prompt_token_ids = nullptr;
    workspace.arena_bytes = 0u;
    workspace.qkv_bytes = 0u;
    workspace.core_bytes = 0u;
    workspace.hidden_bytes = 0u;
    workspace.upload_bytes = 0u;
    workspace.prompt_token_id_bytes = 0u;
    workspace.borrowed = false;
    workspace.valid = false;
}

