uint64_t product_path_stage_digest_from_hashes(
    const std::vector<unsigned int> &token_ids,
    const std::vector<uint64_t> &stage_hashes,
    unsigned int layer_index,
    uint64_t *last_fnv1a64
) {
    uint64_t digest = UINT64_C(1469598103934665603);

    if (last_fnv1a64 == nullptr || token_ids.size() != stage_hashes.size()) {
        return UINT64_C(0);
    }
    *last_fnv1a64 = UINT64_C(0);
    for (size_t index = 0; index < token_ids.size(); ++index) {
        const size_t token_position = static_cast<size_t>(token_ids[index]);
        const uint64_t stage_hash = stage_hashes[index];
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &layer_index,
            sizeof(layer_index)
        );
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &token_position,
            sizeof(token_position)
        );
        digest = qrt_fnv1a64_update_bytes(
            digest,
            &stage_hash,
            sizeof(stage_hash)
        );
        *last_fnv1a64 = stage_hash;
    }
    return digest;
}

bool product_path_stage_digest_f32_slice(
    const std::vector<unsigned int> &token_ids,
    const std::vector<float> &values,
    size_t rows_per_token,
    size_t row_offset,
    size_t row_count,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index = 1u
) {
    std::vector<uint64_t> stage_hashes;

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || row_count == 0 ||
        row_offset + row_count > rows_per_token ||
        values.size() != token_ids.size() * rows_per_token) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (size_t token_index = 0; token_index < token_ids.size(); ++token_index) {
        const float *token_values =
            values.data() + token_index * rows_per_token + row_offset;
        stage_hashes.push_back(qrt_fnv1a64_f32(token_values, row_count));
    }
    *digest_fnv1a64 =
        product_path_stage_digest_from_hashes(
            token_ids,
            stage_hashes,
            layer_index,
            last_fnv1a64
        );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_f32(
    const std::vector<unsigned int> &token_ids,
    const std::vector<float> &values,
    size_t rows_per_token,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index = 1u
) {
    return product_path_stage_digest_f32_slice(
        token_ids,
        values,
        rows_per_token,
        0u,
        rows_per_token,
        digest_fnv1a64,
        last_fnv1a64,
        layer_index
    );
}

bool product_path_stage_digest_f32_indexed(
    const std::vector<unsigned int> &token_ids,
    const std::vector<float> &values,
    size_t full_token_count,
    size_t rows_per_token,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index
) {
    std::vector<uint64_t> stage_hashes;

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || full_token_count == 0 || rows_per_token == 0 ||
        values.size() != full_token_count * rows_per_token) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (unsigned int token_id : token_ids) {
        if (static_cast<size_t>(token_id) >= full_token_count) {
            return false;
        }
        const float *token_values =
            values.data() + static_cast<size_t>(token_id) * rows_per_token;
        stage_hashes.push_back(qrt_fnv1a64_f32(token_values, rows_per_token));
    }
    *digest_fnv1a64 = product_path_stage_digest_from_hashes(
        token_ids,
        stage_hashes,
        layer_index,
        last_fnv1a64
    );
    return *digest_fnv1a64 != UINT64_C(0);
}

