bool product_path_stage_digest_f32_indexed_slice_bf16_round(
    const std::vector<unsigned int> &token_ids,
    const std::vector<float> &values,
    size_t full_token_count,
    size_t rows_per_token,
    size_t row_offset,
    size_t row_count,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index
) {
    std::vector<uint64_t> stage_hashes;
    std::vector<float> rounded(row_count, 0.0f);

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || full_token_count == 0 || rows_per_token == 0 ||
        row_count == 0 || row_offset + row_count > rows_per_token ||
        values.size() != full_token_count * rows_per_token) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (unsigned int token_id : token_ids) {
        if (static_cast<size_t>(token_id) >= full_token_count) {
            return false;
        }
        const float *token_values =
            values.data() + static_cast<size_t>(token_id) * rows_per_token +
            row_offset;
        for (size_t row = 0u; row < row_count; ++row) {
            rounded[row] = bf16_round_to_float(token_values[row]);
        }
        stage_hashes.push_back(qrt_fnv1a64_f32(rounded.data(), row_count));
    }
    *digest_fnv1a64 = product_path_stage_digest_from_hashes(
        token_ids,
        stage_hashes,
        layer_index,
        last_fnv1a64
    );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_layer0_qkv_ring(
    const std::vector<unsigned int> &token_ids,
    const std::vector<float> &qkv_values,
    size_t full_token_count,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64
) {
    std::vector<uint64_t> stage_hashes;
    std::vector<float> ring(
        static_cast<size_t>(kConvKernel) * static_cast<size_t>(kQkvRows),
        0.0f
    );

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || full_token_count == 0 ||
        qkv_values.size() != full_token_count * static_cast<size_t>(kQkvRows)) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (unsigned int token_id : token_ids) {
        const size_t token = static_cast<size_t>(token_id);
        if (token >= full_token_count) {
            return false;
        }
        std::fill(ring.begin(), ring.end(), 0.0f);
        for (size_t offset = 0u; offset < static_cast<size_t>(kConvKernel);
             ++offset) {
            if (offset > token) {
                continue;
            }
            const size_t source_token = token - offset;
            const size_t slot =
                source_token % static_cast<size_t>(kConvKernel);
            const float *source =
                qkv_values.data() + source_token * static_cast<size_t>(kQkvRows);
            std::copy(
                source,
                source + static_cast<size_t>(kQkvRows),
                ring.begin() + slot * static_cast<size_t>(kQkvRows)
            );
        }
        stage_hashes.push_back(qrt_fnv1a64_f32(ring.data(), ring.size()));
    }
    *digest_fnv1a64 = product_path_stage_digest_from_hashes(
        token_ids,
        stage_hashes,
        0u,
        last_fnv1a64
    );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_synthetic_seed(
    const std::vector<unsigned int> &token_ids,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index
) {
    std::vector<uint64_t> stage_hashes;
    std::vector<float> hidden(QRT_QWEN36_HIDDEN_SIZE, 0.0f);

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty()) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (unsigned int token : token_ids) {
        for (unsigned int col = 0; col < QRT_QWEN36_HIDDEN_SIZE; ++col) {
            const int pattern =
                static_cast<int>((token * 17u + col * 13u + 7u) % 127u) - 63;
            const float value = static_cast<float>(pattern) * 0.00390625f;
            hidden[col] = qrt_bf16_to_float(qrt_float_to_bf16(value));
        }
        stage_hashes.push_back(qrt_fnv1a64_f32(
            hidden.data(),
            static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
        ));
    }
    *digest_fnv1a64 = product_path_stage_digest_from_hashes(
        token_ids,
        stage_hashes,
        layer_index,
        last_fnv1a64
    );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_u32(
    const std::vector<unsigned int> &token_ids,
    const std::vector<uint32_t> &values,
    size_t values_per_token,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index = 1u
) {
    std::vector<uint64_t> stage_hashes;

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || values_per_token == 0 ||
        values.size() != token_ids.size() * values_per_token) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (size_t token_index = 0; token_index < token_ids.size(); ++token_index) {
        const uint32_t *token_values =
            values.data() + token_index * values_per_token;
        stage_hashes.push_back(fnv1a64_bytes_seeded(
            token_values,
            values_per_token * sizeof(token_values[0])
        ));
    }
    *digest_fnv1a64 =
        product_path_stage_digest_from_hashes(
            token_ids,
            stage_hashes,
            layer_index,
            last_fnv1a64
        );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_u32_indexed(
    const std::vector<unsigned int> &token_ids,
    const std::vector<uint32_t> &values,
    size_t full_token_count,
    size_t values_per_token,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index
) {
    std::vector<uint64_t> stage_hashes;

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty() || full_token_count == 0 || values_per_token == 0 ||
        values.size() != full_token_count * values_per_token) {
        return false;
    }
    stage_hashes.reserve(token_ids.size());
    for (unsigned int token_id : token_ids) {
        if (static_cast<size_t>(token_id) >= full_token_count) {
            return false;
        }
        const uint32_t *token_values =
            values.data() + static_cast<size_t>(token_id) * values_per_token;
        stage_hashes.push_back(fnv1a64_bytes_seeded(
            token_values,
            values_per_token * sizeof(token_values[0])
        ));
    }
    *digest_fnv1a64 = product_path_stage_digest_from_hashes(
        token_ids,
        stage_hashes,
        layer_index,
        last_fnv1a64
    );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool product_path_stage_digest_repeated_hash(
    const std::vector<unsigned int> &token_ids,
    uint64_t repeated_hash,
    uint64_t *digest_fnv1a64,
    uint64_t *last_fnv1a64,
    unsigned int layer_index = 1u
) {
    std::vector<uint64_t> stage_hashes(token_ids.size(), repeated_hash);

    if (digest_fnv1a64 == nullptr || last_fnv1a64 == nullptr ||
        token_ids.empty()) {
        return false;
    }
    *digest_fnv1a64 =
        product_path_stage_digest_from_hashes(
            token_ids,
            stage_hashes,
            layer_index,
            last_fnv1a64
        );
    return *digest_fnv1a64 != UINT64_C(0);
}

bool append_product_path_stage_digest(
    std::vector<ProductPathStageDigest> *out,
    size_t stage_index,
    const std::vector<unsigned int> &token_ids,
    uint64_t digest_fnv1a64,
    uint64_t last_fnv1a64
) {
    if (out == nullptr ||
        stage_index >= QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT ||
        digest_fnv1a64 == UINT64_C(0)) {
        return false;
    }
    ProductPathStageDigest row;
    row.index = stage_index;
    row.name = product_q8192_layer1_stage_name(stage_index);
    row.scope =
        product_q8192_layer1_stage_is_source(stage_index)
            ? "source_window"
            : "target_frontier";
    row.token_count = token_ids.size();
    row.digest_fnv1a64 = digest_fnv1a64;
    row.last_fnv1a64 = last_fnv1a64;
    out->push_back(row);
    return true;
}

bool append_product_path_layer0_source_stage_digest(
    std::vector<ProductPathStageDigest> *out,
    size_t stage_index,
    const std::vector<unsigned int> &token_ids,
    uint64_t digest_fnv1a64,
    uint64_t last_fnv1a64
) {
    if (out == nullptr ||
        stage_index >= QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT ||
        digest_fnv1a64 == UINT64_C(0)) {
        return false;
    }
    ProductPathStageDigest row;
    row.index = stage_index;
    row.name = product_q8192_layer0_source_stage_name(stage_index);
    row.scope = "source_window";
    row.token_count = token_ids.size();
    row.digest_fnv1a64 = digest_fnv1a64;
    row.last_fnv1a64 = last_fnv1a64;
    out->push_back(row);
    return true;
}

bool capture_product_path_layer0_source_stage_digests(
    const std::vector<unsigned int> &source_token_ids,
    unsigned int prefill_tokens,
    const Layer0PreResidualStageRuns *pre_residual_runs,
    const ResidualHiddenRun &residual_hidden_run,
    const PostAttentionRmsnormRun &post_attention_rmsnorm_run,
    const MoeRouterRun &moe_router_run,
    const RoutedExpertRun &routed_expert_run,
    const SharedExpertRun &shared_expert_run,
    const OutputResidualRun &source_layer0_output_residual_run,
    std::vector<ProductPathStageDigest> *out
) {
    if (out == nullptr || source_token_ids.empty() || prefill_tokens == 0u) {
        return false;
    }
    if (pre_residual_runs != nullptr &&
        pre_residual_runs->precomputed_product_path_digests != nullptr) {
        const std::vector<ProductPathStageDigest> &digests =
            *pre_residual_runs->precomputed_product_path_digests;
        if (digests.size() !=
            QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT) {
            return false;
        }
        for (size_t stage_index = 0u; stage_index < digests.size();
             ++stage_index) {
            const ProductPathStageDigest &row = digests[stage_index];
            if (row.index != stage_index ||
                row.token_count != source_token_ids.size() ||
                row.digest_fnv1a64 == UINT64_C(0)) {
                return false;
            }
        }
        *out = digests;
        return true;
    }
    if (pre_residual_runs == nullptr ||
        pre_residual_runs->qkv_projection == nullptr ||
        pre_residual_runs->z_projection == nullptr ||
        pre_residual_runs->a_projection == nullptr ||
        pre_residual_runs->b_projection == nullptr ||
        pre_residual_runs->conv == nullptr ||
        pre_residual_runs->postconv == nullptr ||
        pre_residual_runs->gate == nullptr ||
        pre_residual_runs->core == nullptr ||
        pre_residual_runs->gated == nullptr ||
        pre_residual_runs->out == nullptr) {
        return false;
    }
    out->clear();

    auto append_digest =
        [&](size_t stage_index,
            uint64_t digest,
            uint64_t last) -> bool {
            return append_product_path_layer0_source_stage_digest(
                out,
                stage_index,
                source_token_ids,
                digest,
                last
            );
        };
    auto append_seed = [&](size_t stage_index) -> bool {
        uint64_t digest = UINT64_C(0);
        uint64_t last = UINT64_C(0);
        return product_path_stage_digest_synthetic_seed(
                   source_token_ids,
                   &digest,
                   &last,
                   0u
               ) &&
               append_digest(stage_index, digest, last);
    };
    auto append_f32_indexed =
        [&](size_t stage_index,
            const std::vector<float> &values,
            size_t rows_per_token) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_f32_indexed(
                       source_token_ids,
                       values,
                       static_cast<size_t>(prefill_tokens),
                       rows_per_token,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    auto append_f32_indexed_slice =
        [&](size_t stage_index,
            const std::vector<float> &values,
            size_t rows_per_token,
            size_t row_offset,
            size_t row_count) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_f32_indexed_slice(
                       source_token_ids,
                       values,
                       static_cast<size_t>(prefill_tokens),
                       rows_per_token,
                       row_offset,
                       row_count,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    auto append_f32_indexed_slice_bf16_round =
        [&](size_t stage_index,
            const std::vector<float> &values,
            size_t rows_per_token,
            size_t row_offset,
            size_t row_count) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_f32_indexed_slice_bf16_round(
                       source_token_ids,
                       values,
                       static_cast<size_t>(prefill_tokens),
                       rows_per_token,
                       row_offset,
                       row_count,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    auto append_qkv_ring = [&](size_t stage_index) -> bool {
        uint64_t digest = UINT64_C(0);
        uint64_t last = UINT64_C(0);
        return product_path_stage_digest_layer0_qkv_ring(
                   source_token_ids,
                   pre_residual_runs->qkv_projection->gpu_output,
                   static_cast<size_t>(prefill_tokens),
                   &digest,
                   &last
               ) &&
               append_digest(stage_index, digest, last);
    };
    auto append_repeated_zero_f32 =
        [&](size_t stage_index,
            size_t value_count) -> bool {
            std::vector<float> zero_values(value_count, 0.0f);
            const uint64_t zero_hash =
                qrt_fnv1a64_f32(zero_values.data(), zero_values.size());
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_repeated_hash(
                       source_token_ids,
                       zero_hash,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    auto append_f32_compact =
        [&](size_t stage_index,
            const std::vector<float> &values,
            size_t rows_per_token) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_f32(
                       source_token_ids,
                       values,
                       rows_per_token,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    auto append_u32_indexed =
        [&](size_t stage_index,
            const std::vector<uint32_t> &values,
            size_t values_per_token) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_u32_indexed(
                       source_token_ids,
                       values,
                       static_cast<size_t>(prefill_tokens),
                       values_per_token,
                       &digest,
                       &last,
                       0u
                   ) &&
                   append_digest(stage_index, digest, last);
        };
    const bool ok =
        append_seed(kProductQ8192Layer0SourceStageSeedInputHidden) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageQkv,
                           pre_residual_runs->qkv_projection->gpu_output,
                           kQkvRows) &&
        append_qkv_ring(kProductQ8192Layer0SourceStageQkvRing) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageZ,
                           pre_residual_runs->z_projection->gpu_output,
                           kZRows) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageA,
                           pre_residual_runs->a_projection->gpu_output,
                           kAbRows) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageB,
                           pre_residual_runs->b_projection->gpu_output,
                           kAbRows) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageConv,
                           pre_residual_runs->conv->gpu_output,
                           kQkvRows) &&
        append_f32_indexed_slice(kProductQ8192Layer0SourceStagePostconvQ,
                                 pre_residual_runs->postconv->gpu_output,
                                 kQkvRows,
                                 0u,
                                 kKeyFeatures) &&
        append_f32_indexed_slice(kProductQ8192Layer0SourceStagePostconvK,
                                 pre_residual_runs->postconv->gpu_output,
                                 kQkvRows,
                                 kKeyFeatures,
                                 kKeyFeatures) &&
        append_f32_indexed_slice(kProductQ8192Layer0SourceStagePostconvV,
                                 pre_residual_runs->postconv->gpu_output,
                                 kQkvRows,
                                 2u * kKeyFeatures,
                                 kValueFeatures) &&
        append_f32_indexed_slice(kProductQ8192Layer0SourceStageGateG,
                                 pre_residual_runs->gate->gpu_output,
                                 kGateOutputRows,
                                 0u,
                                 kGateRows) &&
        append_f32_indexed_slice_bf16_round(
            kProductQ8192Layer0SourceStageGateGBf16,
            pre_residual_runs->gate->gpu_output,
            kGateOutputRows,
            0u,
            kGateRows
        ) &&
        append_f32_indexed_slice(kProductQ8192Layer0SourceStageGateBeta,
                                 pre_residual_runs->gate->gpu_output,
                                 kGateOutputRows,
                                 kGateRows,
                                 kGateRows) &&
        append_repeated_zero_f32(
            kProductQ8192Layer0SourceStageCoreStateInput,
            static_cast<size_t>(kValueFeatures) * static_cast<size_t>(kKeyDim)
        ) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageCore,
                           pre_residual_runs->core->gpu_output,
                           kValueFeatures) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageGated,
                           pre_residual_runs->gated->gpu_output,
                           kValueFeatures) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageOut,
                           pre_residual_runs->out->gpu_output,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageResidualHidden,
                           residual_hidden_run.gpu_output,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_indexed(kProductQ8192Layer0SourceStagePostAttention,
                           post_attention_rmsnorm_run.gpu_output,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageRouterLogits,
                           moe_router_run.gpu_logits,
                           QRT_QWEN36_EXPERT_COUNT) &&
        append_u32_indexed(kProductQ8192Layer0SourceStageRouterTopkIds,
                           moe_router_run.gpu_topk_ids,
                           QRT_QWEN36_EXPERTS_PER_TOKEN) &&
        append_f32_indexed(kProductQ8192Layer0SourceStageRouterTopkWeights,
                           moe_router_run.gpu_topk_weights,
                           QRT_QWEN36_EXPERTS_PER_TOKEN) &&
        append_f32_compact(kProductQ8192Layer0SourceStageRoutedOutput,
                           routed_expert_run.cpu_output.empty()
                               ? routed_expert_run.gpu_output
                               : routed_expert_run.cpu_output,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_compact(kProductQ8192Layer0SourceStageSharedOutput,
                           shared_expert_run.cpu_shared_output.empty()
                               ? shared_expert_run.gpu_shared_output
                               : shared_expert_run.cpu_shared_output,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_compact(kProductQ8192Layer0SourceStageCombinedMoe,
                           source_layer0_output_residual_run.moe_inputs,
                           QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32_compact(kProductQ8192Layer0SourceStageOutputHidden,
                           source_layer0_output_residual_run.gpu_output,
                           QRT_QWEN36_HIDDEN_SIZE);

    return ok &&
           out->size() == QRT_QWEN36_PRODUCT_Q8192_LAYER0_SOURCE_STAGE_COUNT;
}

bool capture_product_path_layer1_stage_digests(
    const std::vector<unsigned int> &source_token_ids,
    const std::vector<unsigned int> &target_token_ids,
    const OutputResidualRun &source_layer0_output_residual_run,
    const Layer1InputRmsnormRun &source_layer1_input_rmsnorm_run,
    const Layer1SelectedProjectionRun &source_layer1_qkv_projection_run,
    const OutputResidualRun &target_layer0_output_residual_run,
    const Layer1InputRmsnormRun &target_layer1_input_rmsnorm_run,
    const Layer1SelectedProjectionRun &target_layer1_z_projection_run,
    const Layer1SelectedProjectionRun &target_layer1_a_projection_run,
    const Layer1SelectedProjectionRun &target_layer1_b_projection_run,
    const Layer1ConvWindowRun &layer1_conv_window_run,
    const Layer1PostconvWindowRun &layer1_postconv_window_run,
    const Layer1GateWindowRun &layer1_gate_window_run,
    const Layer1CoreWindowRun &layer1_core_window_run,
    const Layer1GatedRmsnormWindowRun &layer1_gated_rmsnorm_window_run,
    const Layer1OutProjectionWindowRun &layer1_out_projection_window_run,
    const Layer1ResidualHiddenWindowRun &layer1_residual_hidden_window_run,
    const Layer1PostAttentionRmsnormWindowRun &layer1_post_attention_rmsnorm_window_run,
    const Layer1MoeRouterWindowRun &layer1_moe_router_window_run,
    const RoutedExpertRun &layer1_routed_expert_window_run,
    const SharedExpertRun &layer1_shared_expert_window_run,
    const OutputResidualRun &layer1_output_residual_run,
    std::vector<ProductPathStageDigest> *out
) {
    if (out == nullptr || source_token_ids.empty() || target_token_ids.empty()) {
        return false;
    }
    out->clear();

    auto append_f32_slice =
        [&](size_t stage_index,
            const std::vector<unsigned int> &token_ids,
            const std::vector<float> &values,
            size_t rows_per_token,
            size_t row_offset,
            size_t row_count) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_f32_slice(
                       token_ids,
                       values,
                       rows_per_token,
                       row_offset,
                       row_count,
                       &digest,
                       &last
                   ) &&
                   append_product_path_stage_digest(
                       out,
                       stage_index,
                       token_ids,
                       digest,
                       last
                   );
        };
    auto append_f32 =
        [&](size_t stage_index,
            const std::vector<unsigned int> &token_ids,
            const std::vector<float> &values,
            size_t rows_per_token) -> bool {
            return append_f32_slice(
                stage_index,
                token_ids,
                values,
                rows_per_token,
                0u,
                rows_per_token
            );
        };
    auto append_u32 =
        [&](size_t stage_index,
            const std::vector<unsigned int> &token_ids,
            const std::vector<uint32_t> &values,
            size_t values_per_token) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_u32(
                       token_ids,
                       values,
                       values_per_token,
                       &digest,
                       &last
                   ) &&
                   append_product_path_stage_digest(
                       out,
                       stage_index,
                       token_ids,
                       digest,
                       last
                   );
        };
    auto append_repeated_hash =
        [&](size_t stage_index,
            const std::vector<unsigned int> &token_ids,
            uint64_t repeated_hash) -> bool {
            uint64_t digest = UINT64_C(0);
            uint64_t last = UINT64_C(0);
            return product_path_stage_digest_repeated_hash(
                       token_ids,
                       repeated_hash,
                       &digest,
                       &last
                   ) &&
                   append_product_path_stage_digest(
                       out,
                       stage_index,
                       token_ids,
                       digest,
                       last
                   );
        };

    const size_t zero_core_state_elements =
        static_cast<size_t>(kValueFeatures) * static_cast<size_t>(kKeyDim);
    std::vector<float> zero_core_state(zero_core_state_elements, 0.0f);
    const uint64_t zero_core_state_hash =
        qrt_fnv1a64_f32(zero_core_state.data(), zero_core_state.size());

    const bool ok =
        append_f32(kProductQ8192Layer1StageSourceInputHidden,
                   source_token_ids,
                   source_layer0_output_residual_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageSourceInputNorm,
                   source_token_ids,
                   source_layer1_input_rmsnorm_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageSourceQkv,
                   source_token_ids,
                   source_layer1_qkv_projection_run.gpu_output,
                   kQkvRows) &&
        append_f32(kProductQ8192Layer1StageTargetInputHidden,
                   target_token_ids,
                   target_layer0_output_residual_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetInputNorm,
                   target_token_ids,
                   target_layer1_input_rmsnorm_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetZ,
                   target_token_ids,
                   target_layer1_z_projection_run.gpu_output,
                   kZRows) &&
        append_f32(kProductQ8192Layer1StageTargetA,
                   target_token_ids,
                   target_layer1_a_projection_run.gpu_output,
                   kAbRows) &&
        append_f32(kProductQ8192Layer1StageTargetB,
                   target_token_ids,
                   target_layer1_b_projection_run.gpu_output,
                   kAbRows) &&
        append_f32(kProductQ8192Layer1StageTargetConv,
                   target_token_ids,
                   layer1_conv_window_run.gpu_output,
                   kQkvRows) &&
        append_f32_slice(kProductQ8192Layer1StageTargetPostconvQ,
                         target_token_ids,
                         layer1_postconv_window_run.gpu_output,
                         kQkvRows,
                         0u,
                         kKeyFeatures) &&
        append_f32_slice(kProductQ8192Layer1StageTargetPostconvK,
                         target_token_ids,
                         layer1_postconv_window_run.gpu_output,
                         kQkvRows,
                         kKeyFeatures,
                         kKeyFeatures) &&
        append_f32_slice(kProductQ8192Layer1StageTargetPostconvV,
                         target_token_ids,
                         layer1_postconv_window_run.gpu_output,
                         kQkvRows,
                         2u * static_cast<size_t>(kKeyFeatures),
                         kValueFeatures) &&
        append_f32_slice(kProductQ8192Layer1StageTargetGateG,
                         target_token_ids,
                         layer1_gate_window_run.gpu_output,
                         kGateOutputRows,
                         0u,
                         kGateRows) &&
        append_f32_slice(kProductQ8192Layer1StageTargetGateBeta,
                         target_token_ids,
                         layer1_gate_window_run.gpu_output,
                         kGateOutputRows,
                         kGateRows,
                         kGateRows) &&
        append_repeated_hash(kProductQ8192Layer1StageTargetCoreStateInput,
                             target_token_ids,
                             zero_core_state_hash) &&
        append_f32(kProductQ8192Layer1StageTargetCore,
                   target_token_ids,
                   layer1_core_window_run.gpu_output,
                   kValueFeatures) &&
        append_f32(kProductQ8192Layer1StageTargetGated,
                   target_token_ids,
                   layer1_gated_rmsnorm_window_run.gpu_output,
                   kValueFeatures) &&
        append_f32(kProductQ8192Layer1StageTargetOut,
                   target_token_ids,
                   layer1_out_projection_window_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetResidual,
                   target_token_ids,
                   layer1_residual_hidden_window_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetPostAttention,
                   target_token_ids,
                   layer1_post_attention_rmsnorm_window_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetRouterLogits,
                   target_token_ids,
                   layer1_moe_router_window_run.gpu_logits,
                   QRT_QWEN36_EXPERT_COUNT) &&
        append_u32(kProductQ8192Layer1StageTargetRouterTopkIds,
                   target_token_ids,
                   layer1_moe_router_window_run.gpu_topk_ids,
                   QRT_QWEN36_EXPERTS_PER_TOKEN) &&
        append_f32(kProductQ8192Layer1StageTargetRouterTopkWeights,
                   target_token_ids,
                   layer1_moe_router_window_run.gpu_topk_weights,
                   QRT_QWEN36_EXPERTS_PER_TOKEN) &&
        append_f32(kProductQ8192Layer1StageTargetRoutedOutput,
                   target_token_ids,
                   layer1_routed_expert_window_run.cpu_output.empty()
                       ? layer1_routed_expert_window_run.gpu_output
                       : layer1_routed_expert_window_run.cpu_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_u32(kProductQ8192Layer1StageTargetSelectedIds,
                   target_token_ids,
                   layer1_routed_expert_window_run.selected_expert_ids,
                   QRT_QWEN36_EXPERTS_PER_TOKEN) &&
        append_f32(kProductQ8192Layer1StageTargetSharedOutput,
                   target_token_ids,
                   layer1_shared_expert_window_run.cpu_shared_output.empty()
                       ? layer1_shared_expert_window_run.gpu_shared_output
                       : layer1_shared_expert_window_run.cpu_shared_output,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetCombined,
                   target_token_ids,
                   layer1_output_residual_run.moe_inputs.empty()
                       ? layer1_shared_expert_window_run.gpu_combined_output
                       : layer1_output_residual_run.moe_inputs,
                   QRT_QWEN36_HIDDEN_SIZE) &&
        append_f32(kProductQ8192Layer1StageTargetOutputHidden,
                   target_token_ids,
                   layer1_output_residual_run.gpu_output,
                   QRT_QWEN36_HIDDEN_SIZE);

    return ok &&
           out->size() == QRT_QWEN36_PRODUCT_Q8192_LAYER1_STAGE_COUNT;
}

void rewrite_qwen36_mtp_tensor_name(
    unsigned int layer,
    qrt_qwen36_tensor_kind_t kind,
    std::string *name
) {
    if (!g_qwen36_mtp_tensor_namespace_active || name == nullptr) {
        return;
    }
    if (kind == QRT_QWEN36_TENSOR_FINAL_NORM) {
        *name = "mtp.norm.weight";
        return;
    }
    if (layer != 3u ||
        kind == QRT_QWEN36_TENSOR_TOKEN_EMBEDDING ||
        kind == QRT_QWEN36_TENSOR_LM_HEAD) {
        return;
    }
    static const std::string kTargetPrefix =
        "model.language_model.layers.3.";
    static const std::string kMtpPrefix = "mtp.layers.0.";
    if (name->compare(0u, kTargetPrefix.size(), kTargetPrefix) == 0) {
        name->replace(0u, kTargetPrefix.size(), kMtpPrefix);
    }
}

class ScopedQwen36MtpTensorNamespace final {
public:
    explicit ScopedQwen36MtpTensorNamespace(bool active)
        : prior_(g_qwen36_mtp_tensor_namespace_active) {
        g_qwen36_mtp_tensor_namespace_active = active;
    }

    ScopedQwen36MtpTensorNamespace(
        const ScopedQwen36MtpTensorNamespace &
    ) = delete;
    ScopedQwen36MtpTensorNamespace &operator=(
        const ScopedQwen36MtpTensorNamespace &
    ) = delete;

    ~ScopedQwen36MtpTensorNamespace() {
        g_qwen36_mtp_tensor_namespace_active = prior_;
    }

private:
    bool prior_ = false;
};

bool tensor_name_for_kind(const ProjectionSpec &spec, std::string *name, std::string *failure) {
    char buffer[QRT_QWEN36_TENSOR_NAME_CAPACITY] = {};
    const qrt_status_t status = qrt_qwen36_tensor_name(kLayer, spec.tensor_kind, buffer, sizeof(buffer));
    if (status != QRT_STATUS_OK) {
        *failure = "qrt_qwen36_tensor_name failed";
        return false;
    }
    *name = buffer;
    rewrite_qwen36_mtp_tensor_name(kLayer, spec.tensor_kind, name);
    return true;
}

bool tensor_name_for_kind(qrt_qwen36_tensor_kind_t kind, std::string *name, std::string *failure) {
    char buffer[QRT_QWEN36_TENSOR_NAME_CAPACITY] = {};
    const qrt_status_t status = qrt_qwen36_tensor_name(kLayer, kind, buffer, sizeof(buffer));
    if (status != QRT_STATUS_OK) {
        *failure = "qrt_qwen36_tensor_name failed";
        return false;
    }
    *name = buffer;
    rewrite_qwen36_mtp_tensor_name(kLayer, kind, name);
    return true;
}

bool tensor_name_for_layer_kind(
    unsigned int layer,
    qrt_qwen36_tensor_kind_t kind,
    std::string *name,
    std::string *failure
) {
    char buffer[QRT_QWEN36_TENSOR_NAME_CAPACITY] = {};
    const qrt_status_t status = qrt_qwen36_tensor_name(layer, kind, buffer, sizeof(buffer));
    if (status != QRT_STATUS_OK) {
        *failure = "qrt_qwen36_tensor_name failed";
        return false;
    }
    *name = buffer;
    rewrite_qwen36_mtp_tensor_name(layer, kind, name);
    return true;
}

bool run_layer0_input_rmsnorm(
    const std::vector<uint16_t> &hidden,
    uint16_t *device_hidden,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    Layer1InputRmsnormRun *run
) {
    run->name = "layer0_input_rmsnorm";
    run->stage = "layer0_input_rmsnorm_prefill_phase";
    run->weight_bytes =
        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) * sizeof(uint16_t);
    run->selected_token_ids.clear();
    run->selected_token_ids.reserve(prefill_tokens);
    for (unsigned int token = 0u; token < prefill_tokens; ++token) {
        run->selected_token_ids.push_back(token);
    }
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements =
        static_cast<size_t>(prefill_tokens) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);

    if (device_hidden == nullptr || prefill_tokens == 0u ||
        hidden.size() != run->output_elements) {
        run->failure_stage = "layer0_input_rmsnorm_input_contract";
        run->failure = "layer-0 input RMSNorm received missing hidden input";
        return false;
    }
    if (!tensor_name_for_layer_kind(
            0u,
            QRT_QWEN36_TENSOR_INPUT_NORM,
            &run->tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_layer0_input_rmsnorm_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_input_rmsnorm_prefill_phase";
        return false;
    }
    if (run->location.data_end < run->location.data_begin ||
        run->location.data_end - run->location.data_begin != run->weight_bytes) {
        run->failure_stage = "shape_layer0_input_rmsnorm_prefill_phase";
        run->failure =
            "layer-0 input RMSNorm tensor does not match expected byte shape";
        return false;
    }
    if (!read_safetensors_bytes(
            model_dir,
            run->location,
            0,
            run->weight_bytes,
            &run->weights,
            &run->failure
        )) {
        run->failure_stage = "read_layer0_input_rmsnorm_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid(prefill_tokens);

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(layer0_input_rmsnorm_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(layer0_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(layer0_input_rmsnorm_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(layer0_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            layer0_input_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_hidden,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_input_rmsnorm_prefill_phase",
            "warmup_sync_layer0_input_rmsnorm_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            layer0_input_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_hidden,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_input_rmsnorm_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_input_rmsnorm_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(layer0_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference =
                    layer0_input_rmsnorm_cpu_value(hidden, run->weights.data(), token, row);
                const size_t output_index =
                    static_cast<size_t>(token) *
                        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) +
                    row;
                const float gpu = run->gpu_output[output_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->input_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            hidden.data(),
            hidden.size() * sizeof(hidden[0])
        );
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms =
            static_cast<double>(run->elapsed_ms) /
            static_cast<double>(kTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) /
                    (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_input_rmsnorm_prefill_phase";
            run->failure =
                "selected CPU/HIP layer-0 input RMSNorm boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool materialize_real_prompt_token_embedding_hidden(
    const std::string &model_dir,
    const Gb10PromptFixture &fixture,
    RealPromptTokenEmbeddingPrefillSurfaceRun *run,
    std::vector<uint16_t> *hidden,
    bool capture_embedding_diagnostics = true,
    bool materialize_embedding_hidden = true,
    const uint32_t *input_tokens_override = nullptr,
    size_t input_token_count_override = 0u
) {
    *run = RealPromptTokenEmbeddingPrefillSurfaceRun{};
    run->attempted = true;
    run->case_id = fixture.case_id;
    run->stage = fixture.stage;
    run->tokenizer_reference_id = fixture.tokenizer_reference_id;
    run->chat_tokenize_sha256 = fixture.chat_tokenize_sha256;
    run->response_sha256 = fixture.response_sha256;
    if (input_tokens_override != nullptr) {
        run->prompt_token_ids.assign(
            input_tokens_override,
            input_tokens_override + input_token_count_override
        );
    } else {
        append_gb10_prompt_fixture_tokens(fixture, &run->prompt_token_ids);
    }
    run->prompt_token_count = run->prompt_token_ids.size();
    run->expected_token_embedding_tensor_bytes =
        static_cast<uint64_t>(QRT_QWEN36_VOCAB_SIZE) *
        static_cast<uint64_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES);
    run->input_embeddings_fnv1a64 = capture_embedding_diagnostics
        ? UINT64_C(1469598103934665603)
        : UINT64_C(0);
    run->prompt_token_ids_fnv1a64 = qrt_fnv1a64_bytes(
        run->prompt_token_ids.data(),
        run->prompt_token_ids.size() * sizeof(run->prompt_token_ids[0])
    );

    if (run->prompt_token_ids.empty()) {
        run->failure_stage = "real_prompt_token_ids_contract";
        run->failure = "real prompt token fixture is empty";
        run->next_unclosed_boundary = "real_prompt_token_ids";
        return false;
    }
    if (input_tokens_override == nullptr &&
        run->prompt_token_ids.size() != fixture.prompt_token_count) {
        run->failure_stage = "real_prompt_token_count_contract";
        run->failure = "real prompt token fixture did not materialize the expected token count";
        run->next_unclosed_boundary = "real_prompt_token_ids";
        return false;
    }
    if (!tensor_name_for_kind(
            QRT_QWEN36_TENSOR_TOKEN_EMBEDDING,
            &run->token_embedding_tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_real_prompt_token_embedding";
        run->next_unclosed_boundary = "real_prompt_token_embedding_tensor_name";
        return false;
    }
    if (!locate_tensor(
            model_dir,
            run->token_embedding_tensor_name,
            &run->token_embedding_location,
            &run->failure
        )) {
        run->failure_stage = "locate_real_prompt_token_embedding";
        run->next_unclosed_boundary = "real_prompt_token_embedding_tensor";
        return false;
    }
    if (run->token_embedding_location.data_end < run->token_embedding_location.data_begin) {
        run->failure_stage = "shape_real_prompt_token_embedding";
        run->failure = "token embedding tensor has invalid data offsets";
        run->next_unclosed_boundary = "real_prompt_token_embedding_tensor";
        return false;
    }
    run->actual_token_embedding_tensor_bytes =
        run->token_embedding_location.data_end -
        run->token_embedding_location.data_begin;
    if (run->actual_token_embedding_tensor_bytes !=
        run->expected_token_embedding_tensor_bytes) {
        run->failure_stage = "shape_real_prompt_token_embedding";
        run->failure = "token embedding tensor byte shape does not match Qwen3.6 vocab and hidden size";
        run->next_unclosed_boundary = "real_prompt_token_embedding_tensor";
        return false;
    }

    if (!materialize_embedding_hidden) {
        for (const uint32_t token : run->prompt_token_ids) {
            if (token >= static_cast<uint32_t>(QRT_QWEN36_VOCAB_SIZE)) {
                run->failure_stage = "real_prompt_token_range";
                run->failure =
                    "gb10 prompt token id is outside Qwen3.6 vocab size";
                run->next_unclosed_boundary = "real_prompt_token_ids";
                return false;
            }
        }
        hidden->clear();
        std::cerr
            << "BATCH_MARK real_prompt_token_embedding_materialization"
            << " tokens=" << run->prompt_token_ids.size()
            << " host_hidden_bytes=0"
            << " source=resident_device_embedding_gather"
            << " numerical_correctness_claimed=0"
            << std::endl;
        return true;
    }

    hidden->assign(
        run->prompt_token_ids.size() * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE),
        0u
    );
    uint32_t cached_embedding_token = UINT32_MAX;
    std::vector<uint16_t> cached_embedding;
    for (size_t token_index = 0; token_index < run->prompt_token_ids.size(); ++token_index) {
        const uint32_t token = run->prompt_token_ids[token_index];
        if (token >= static_cast<uint32_t>(QRT_QWEN36_VOCAB_SIZE)) {
            run->failure_stage = "real_prompt_token_range";
            run->failure = "gb10 prompt token id is outside Qwen3.6 vocab size";
            run->next_unclosed_boundary = "real_prompt_token_ids";
            return false;
        }
        if (token != cached_embedding_token) {
            const uint64_t relative_begin =
                static_cast<uint64_t>(token) *
                static_cast<uint64_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES);
            if (!read_safetensors_bytes(
                    model_dir,
                    run->token_embedding_location,
                    relative_begin,
                    QRT_QWEN36_TOKEN_EMBEDDING_BYTES,
                    &cached_embedding,
                    &run->failure
                )) {
                run->failure_stage = "read_real_prompt_token_embedding";
                run->next_unclosed_boundary = "real_prompt_token_embedding_read";
                return false;
            }
            cached_embedding_token = token;
        }
        if (cached_embedding.size() != static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
            run->failure_stage = "shape_real_prompt_token_embedding_slice";
            run->failure = "token embedding row did not materialize hidden-size BF16 elements";
            run->next_unclosed_boundary = "real_prompt_token_embedding_read";
            return false;
        }
        if (capture_embedding_diagnostics) {
            run->last_token_embedding_fnv1a64 = qrt_fnv1a64_bytes(
                cached_embedding.data(),
                static_cast<size_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES)
            );
        }
        run->token_embedding_bytes_read +=
            static_cast<uint64_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES);
        if (capture_embedding_diagnostics) {
            run->input_embeddings_fnv1a64 = qrt_fnv1a64_update_bytes(
                run->input_embeddings_fnv1a64,
                &token_index,
                sizeof(token_index)
            );
            run->input_embeddings_fnv1a64 = qrt_fnv1a64_update_bytes(
                run->input_embeddings_fnv1a64,
                &token,
                sizeof(token)
            );
            run->input_embeddings_fnv1a64 = qrt_fnv1a64_update_bytes(
                run->input_embeddings_fnv1a64,
                cached_embedding.data(),
                static_cast<size_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES)
            );
        }
        ++run->input_embeddings_materialized_count;
        std::copy(
            cached_embedding.begin(),
            cached_embedding.end(),
            hidden->begin() +
                static_cast<std::ptrdiff_t>(
                    token_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
                )
        );
    }
    if (capture_embedding_diagnostics) {
        run->hidden_bf16_fnv1a64 = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            hidden->data(),
            hidden->size() * sizeof((*hidden)[0])
        );
    }
    return true;
}

bool run_real_prompt_token_embedding_prefill_surface(
    const std::string &model_dir,
    const Gb10PromptFixture &fixture,
    RealPromptTokenEmbeddingPrefillSurfaceRun *run
) {
    std::vector<uint16_t> hidden;
    if (!materialize_real_prompt_token_embedding_hidden(
            model_dir,
            fixture,
            run,
            &hidden
        )) {
        return false;
    }

    uint16_t *device_hidden = nullptr;
    const size_t hidden_bytes = hidden.size() * sizeof(hidden[0]);
    if (!check_hip(
            hipMalloc(reinterpret_cast<void **>(&device_hidden), hidden_bytes),
            "hipMalloc(real_prompt_token_embedding_hidden)",
            &run->failure_stage,
            &run->failure
        )) {
        run->next_unclosed_boundary = "real_prompt_token_embedding_device_hidden";
        free_device(device_hidden);
        return false;
    }
    if (!check_hip(
            hipMemcpy(device_hidden, hidden.data(), hidden_bytes, hipMemcpyHostToDevice),
            "hipMemcpy(real_prompt_token_embedding_hidden)",
            &run->failure_stage,
            &run->failure
        )) {
        run->next_unclosed_boundary = "real_prompt_token_embedding_device_hidden";
        free_device(device_hidden);
        return false;
    }

    run->first_comparable_stage_attempted = true;
    const bool stage_ok = run_layer0_input_rmsnorm(
        hidden,
        device_hidden,
        model_dir,
        static_cast<unsigned int>(run->prompt_token_ids.size()),
        &run->first_comparable_stage
    );
    free_device(device_hidden);
    run->checked_values = run->first_comparable_stage.checked_values;
    run->max_abs_diff = run->first_comparable_stage.max_abs_diff;
    run->avg_ms = run->first_comparable_stage.avg_ms;
    if (!stage_ok) {
        run->failure_stage = run->first_comparable_stage.failure_stage;
        run->failure = run->first_comparable_stage.failure;
        run->next_unclosed_boundary =
            run->failure_stage.empty()
                ? "real_prompt_first_comparable_stage"
                : run->failure_stage;
        return false;
    }

    const bool materialized_all_embeddings =
        run->input_embeddings_materialized_count == run->prompt_token_ids.size() &&
        run->token_embedding_bytes_read ==
            static_cast<uint64_t>(run->prompt_token_ids.size()) *
            static_cast<uint64_t>(QRT_QWEN36_TOKEN_EMBEDDING_BYTES) &&
        run->input_embeddings_fnv1a64 != 0u &&
        run->last_token_embedding_fnv1a64 != 0u &&
        run->hidden_bf16_fnv1a64 != 0u;
    run->correctness_pass =
        materialized_all_embeddings &&
        run->first_comparable_stage.correctness_pass &&
        run->checked_values > 0u &&
        std::isfinite(run->max_abs_diff) &&
        run->max_abs_diff <= kTolerance &&
        !run->inference_success_claimed &&
        !run->product_performance_accepted;
    if (!run->correctness_pass) {
        run->failure_stage = "correctness_real_prompt_token_embedding_prefill_surface";
        run->failure =
            "real prompt token embedding prefill surface failed materialization or first comparable stage checks";
        run->next_unclosed_boundary = "real_prompt_token_embedding_prefill_surface";
        return false;
    }
    run->output_boundary = "real_prompt_token_embedding_prefill_surface";
    run->next_unclosed_boundary = "decode_one_gb10_output_correctness";
    return true;
}

bool run_projection(
    const ProjectionSpec &spec,
    const std::string &model_dir,
    const std::vector<float> &input_norm,
    unsigned int prefill_tokens,
    ProjectionRun *run
) {
    run->spec = spec;
    run->weight_bytes = static_cast<uint64_t>(spec.rows) *
                        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
                        sizeof(uint16_t);
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(spec.rows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (input_norm.size() !=
        static_cast<size_t>(prefill_tokens) *
            static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
        run->failure_stage = std::string("input_norm_contract_") + spec.stage;
        run->failure =
            "layer-0 projection received missing or mismatched input RMSNorm output";
        return false;
    }
    if (!tensor_name_for_kind(spec, &run->tensor_name, &run->failure)) {
        run->failure_stage = std::string("tensor_name_") + spec.stage;
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = std::string("locate_") + spec.stage;
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = std::string("read_") + spec.stage;
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_input = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), std::string("hipMalloc(weights_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_input), input_norm.size() * sizeof(input_norm[0])), std::string("hipMalloc(input_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), std::string("hipMalloc(output_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), std::string("hipMemcpy(weights_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_input, input_norm.data(), input_norm.size() * sizeof(input_norm[0]), hipMemcpyHostToDevice), std::string("hipMemcpy(input_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), std::string("hipMemset(output_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            selected_float_projection_kernel,
            dim3(spec.rows, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_weights,
            device_input,
            device_output,
            spec.rows,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            std::string("warmup_kernel_launch_") + spec.stage,
            std::string("warmup_sync_") + spec.stage,
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), std::string("hipEventCreate(start_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), std::string("hipEventCreate(stop_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), std::string("hipEventRecord(start_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            selected_float_projection_kernel,
            dim3(spec.rows, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_weights,
            device_input,
            device_output,
            spec.rows,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), std::string("timed_kernel_launch_") + spec.stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), std::string("hipEventRecord(stop_") + spec.stage + ")", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), std::string("hipEventSynchronize(stop_") + spec.stage + ")", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), std::string("hipEventElapsedTime_") + spec.stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), std::string("hipMemcpy(output_") + spec.stage + ")", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_rows(spec.rows)) {
                const float reference = selected_float_projection_cpu_value(
                    run->weights.data(),
                    input_norm,
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * spec.rows + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = std::string("correctness_") + spec.stage;
            run->failure = "selected CPU/HIP projection boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_input);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_conv_qkv(
    const ProjectionRun &qkv_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    ConvRun *run
) {
    run->weight_bytes = static_cast<uint64_t>(kQkvRows) *
                        static_cast<uint64_t>(kConvKernel) *
                        sizeof(uint16_t);
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kQkvRows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (qkv_run.spec.rows != kQkvRows || qkv_run.gpu_output.size() != run->output_elements) {
        run->failure_stage = "conv_qkv_input_contract";
        run->failure = "QKV projection output is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_LINEAR_ATTN_CONV, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_conv_qkv_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_conv_qkv_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer0_conv_qkv_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_qkv = nullptr;
    uint16_t *device_weights = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_qkv), run->output_bytes), "hipMalloc(conv_qkv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(conv_qkv_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(conv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_qkv, qkv_run.gpu_output.data(), run->output_bytes, hipMemcpyHostToDevice), "hipMemcpy(conv_qkv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(conv_qkv_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(conv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            conv_qkv_depthwise_silu_kernel,
            dim3((kQkvRows + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_qkv,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_conv_qkv_prefill_phase",
            "warmup_sync_layer0_conv_qkv_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_conv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_conv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_conv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            conv_qkv_depthwise_silu_kernel,
            dim3((kQkvRows + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_qkv,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_conv_qkv_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_conv_qkv_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_conv_qkv_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_conv_qkv_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(conv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_rows(kQkvRows)) {
                const float reference = conv_qkv_cpu_value(qkv_run, run->weights.data(), token, row);
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kQkvRows + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->qkv_input_hash = qrt_fnv1a64_f32(qkv_run.gpu_output.data(), qkv_run.gpu_output.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_conv_qkv_prefill_phase";
            run->failure = "selected CPU/HIP conv_qkv boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_weights);
    free_device(device_qkv);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_postconv_qkv(
    const ConvRun &conv_run,
    unsigned int prefill_tokens,
    PostconvRun *run
) {
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kQkvRows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!conv_run.correctness_pass || conv_run.gpu_output.size() != run->output_elements) {
        run->failure_stage = "postconv_qkv_input_contract";
        run->failure = "conv_qkv output is missing or has unexpected shape";
        return false;
    }
    if (kQkvRows != 2u * kKeyFeatures + kValueFeatures) {
        run->failure_stage = "postconv_qkv_shape_contract";
        run->failure = "QKV rows do not match q/k/value postconv split";
        return false;
    }

    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_conv = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_conv), run->output_bytes), "hipMalloc(postconv_qkv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(postconv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_conv, conv_run.gpu_output.data(), run->output_bytes, hipMemcpyHostToDevice), "hipMemcpy(postconv_qkv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(postconv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            postconv_qk_kernel,
            dim3(prefill_tokens, kKeyHeads),
            dim3(kKeyDim),
            0,
            0,
            device_conv,
            device_output,
            prefill_tokens
        );
        hipLaunchKernelGGL(
            postconv_value_kernel,
            dim3((kValueFeatures + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_conv,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_postconv_qkv_prefill_phase",
            "warmup_sync_layer0_postconv_qkv_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_postconv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_postconv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_postconv_qkv_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            postconv_qk_kernel,
            dim3(prefill_tokens, kKeyHeads),
            dim3(kKeyDim),
            0,
            0,
            device_conv,
            device_output,
            prefill_tokens
        );
        hipLaunchKernelGGL(
            postconv_value_kernel,
            dim3((kValueFeatures + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_conv,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_postconv_qkv_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_postconv_qkv_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_postconv_qkv_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_postconv_qkv_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(postconv_qkv_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_postconv_rows()) {
                const float reference = postconv_cpu_value(conv_run, token, row);
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kQkvRows + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->conv_input_hash = qrt_fnv1a64_f32(conv_run.gpu_output.data(), conv_run.gpu_output.size());
        std::vector<float> q_scaled_surface;
        std::vector<float> k_norm_surface;
        std::vector<float> value_surface;
        q_scaled_surface.reserve(static_cast<size_t>(prefill_tokens) * kKeyFeatures);
        k_norm_surface.reserve(static_cast<size_t>(prefill_tokens) * kKeyFeatures);
        value_surface.reserve(static_cast<size_t>(prefill_tokens) * kValueFeatures);
        for (unsigned int token = 0; token < prefill_tokens; ++token) {
            const size_t token_base = static_cast<size_t>(token) * kQkvRows;
            q_scaled_surface.insert(
                q_scaled_surface.end(),
                run->gpu_output.data() + token_base,
                run->gpu_output.data() + token_base + kKeyFeatures
            );
            k_norm_surface.insert(
                k_norm_surface.end(),
                run->gpu_output.data() + token_base + kKeyFeatures,
                run->gpu_output.data() + token_base + 2u * kKeyFeatures
            );
            value_surface.insert(
                value_surface.end(),
                run->gpu_output.data() + token_base + 2u * kKeyFeatures,
                run->gpu_output.data() + token_base + kQkvRows
            );
        }
        run->q_scaled_hash = qrt_fnv1a64_f32(q_scaled_surface.data(), q_scaled_surface.size());
        run->k_norm_hash = qrt_fnv1a64_f32(k_norm_surface.data(), k_norm_surface.size());
        run->value_hash = qrt_fnv1a64_f32(value_surface.data(), value_surface.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_postconv_qkv_prefill_phase";
            run->failure = "selected CPU/HIP postconv_qkv boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_conv);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_gate_rows(
    const ProjectionRun &a_run,
    const ProjectionRun &b_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    GateRun *run
) {
    const uint64_t single_weight_bytes = static_cast<uint64_t>(kGateRows) * sizeof(uint16_t);
    run->weight_bytes = 2u * single_weight_bytes;
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kGateOutputRows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (a_run.spec.rows != kGateRows || b_run.spec.rows != kGateRows ||
        a_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kGateRows ||
        b_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kGateRows) {
        run->failure_stage = "gate_rows_input_contract";
        run->failure = "A/B projection outputs are missing or have unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_LINEAR_ATTN_A_LOG, &run->a_log_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_gate_rows_a_log_prefill_phase";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_LINEAR_ATTN_DT_BIAS, &run->dt_bias_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_gate_rows_dt_bias_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->a_log_tensor_name, &run->a_log_location, &run->failure)) {
        run->failure_stage = "locate_layer0_gate_rows_a_log_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->dt_bias_tensor_name, &run->dt_bias_location, &run->failure)) {
        run->failure_stage = "locate_layer0_gate_rows_dt_bias_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->a_log_location, 0, single_weight_bytes, &run->a_log, &run->failure)) {
        run->failure_stage = "read_layer0_gate_rows_a_log_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->dt_bias_location, 0, single_weight_bytes, &run->dt_bias, &run->failure)) {
        run->failure_stage = "read_layer0_gate_rows_dt_bias_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_a = nullptr;
    float *device_b = nullptr;
    uint16_t *device_a_log = nullptr;
    uint16_t *device_dt_bias = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_a), a_run.output_bytes), "hipMalloc(gate_rows_a_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_b), b_run.output_bytes), "hipMalloc(gate_rows_b_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_a_log), single_weight_bytes), "hipMalloc(gate_rows_a_log)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_dt_bias), single_weight_bytes), "hipMalloc(gate_rows_dt_bias)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(gate_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_a, a_run.gpu_output.data(), a_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(gate_rows_a_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_b, b_run.gpu_output.data(), b_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(gate_rows_b_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_a_log, run->a_log.data(), single_weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(gate_rows_a_log)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_dt_bias, run->dt_bias.data(), single_weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(gate_rows_dt_bias)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(gate_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            gate_rows_kernel,
            dim3((kGateRows + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_a,
            device_b,
            device_a_log,
            device_dt_bias,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_gate_rows_prefill_phase",
            "warmup_sync_layer0_gate_rows_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_gate_rows_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_gate_rows_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_gate_rows_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            gate_rows_kernel,
            dim3((kGateRows + kThreads - 1) / kThreads, prefill_tokens),
            dim3(kThreads),
            0,
            0,
            device_a,
            device_b,
            device_a_log,
            device_dt_bias,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_gate_rows_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_gate_rows_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_gate_rows_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_gate_rows_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(gate_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row = 0; row < kGateOutputRows; ++row) {
                const float reference = gate_cpu_value(a_run, b_run, run->a_log.data(), run->dt_bias.data(), token, row);
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kGateOutputRows + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->a_input_hash = qrt_fnv1a64_f32(a_run.gpu_output.data(), a_run.gpu_output.size());
        run->b_input_hash = qrt_fnv1a64_f32(b_run.gpu_output.data(), b_run.gpu_output.size());
        run->a_log_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->a_log.data(),
            static_cast<size_t>(single_weight_bytes)
        );
        run->dt_bias_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->dt_bias.data(),
            static_cast<size_t>(single_weight_bytes)
        );
        std::vector<float> gate_g_surface;
        std::vector<float> gate_beta_surface;
        gate_g_surface.reserve(static_cast<size_t>(prefill_tokens) * kGateRows);
        gate_beta_surface.reserve(static_cast<size_t>(prefill_tokens) * kGateRows);
        for (unsigned int token = 0; token < prefill_tokens; ++token) {
            const size_t token_base = static_cast<size_t>(token) * kGateOutputRows;
            gate_g_surface.insert(
                gate_g_surface.end(),
                run->gpu_output.data() + token_base,
                run->gpu_output.data() + token_base + kGateRows
            );
            gate_beta_surface.insert(
                gate_beta_surface.end(),
                run->gpu_output.data() + token_base + kGateRows,
                run->gpu_output.data() + token_base + kGateOutputRows
            );
        }
        run->gate_g_hash = qrt_fnv1a64_f32(gate_g_surface.data(), gate_g_surface.size());
        run->gate_beta_hash = qrt_fnv1a64_f32(gate_beta_surface.data(), gate_beta_surface.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_gate_rows_prefill_phase";
            run->failure = "selected CPU/HIP gate_rows boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_dt_bias);
    free_device(device_a_log);
    free_device(device_b);
    free_device(device_a);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool materialize_qrt_host_gate_rows_handoff(
    const ProjectionRun &a_run,
    const ProjectionRun &b_run,
    const GateRun &source,
    unsigned int prefill_tokens,
    GateRun *run
) {
    if (run == nullptr) {
        return false;
    }
    *run = source;
    run->name = "gate_rows_qrt_host_handoff";
    run->stage = "layer0_gate_rows_qrt_host_handoff_prefill_phase";
    run->samples.clear();
    run->checked_values = 0u;
    run->max_abs_diff = 0.0f;
    run->selected_reference_hash = 0u;
    run->selected_gpu_hash = 0u;
    run->gate_g_hash = 0u;
    run->gate_beta_hash = 0u;
    run->gpu_output_hash = 0u;
    run->correctness_pass = false;
    run->failure_stage.clear();
    run->failure.clear();

    const size_t expected_gate_rows =
        static_cast<size_t>(prefill_tokens) * kGateRows;
    const size_t expected_output_rows =
        static_cast<size_t>(prefill_tokens) * kGateOutputRows;
    if (a_run.gpu_output.size() != expected_gate_rows ||
        b_run.gpu_output.size() != expected_gate_rows ||
        source.a_log.size() != kGateRows ||
        source.dt_bias.size() != kGateRows ||
        source.output_elements != expected_output_rows) {
        run->failure_stage = "gate_rows_qrt_host_handoff_input_contract";
        run->failure =
            "qrt-compatible gate handoff received mismatched A/B or gate weight shapes";
        return false;
    }

    run->output_elements = expected_output_rows;
    run->output_bytes = run->output_elements * sizeof(float);
    run->gpu_output.assign(run->output_elements, 0.0f);
    std::vector<float> gate_g(kGateRows, 0.0f);
    std::vector<float> gate_beta(kGateRows, 0.0f);
    for (unsigned int token = 0u; token < prefill_tokens; ++token) {
        const size_t gate_base = static_cast<size_t>(token) * kGateRows;
        const size_t output_base =
            static_cast<size_t>(token) * kGateOutputRows;
        if (!qrt_layer0_gate_rows_cpu(
                a_run.gpu_output.data() + gate_base,
                b_run.gpu_output.data() + gate_base,
                source.a_log.data(),
                source.dt_bias.data(),
                gate_g.data(),
                gate_beta.data()
            )) {
            run->failure_stage = "gate_rows_qrt_host_handoff_compute";
            run->failure =
                "qrt-compatible gate handoff failed to materialize host gate rows";
            return false;
        }
        std::copy(
            gate_g.begin(),
            gate_g.end(),
            run->gpu_output.begin() + output_base
        );
        std::copy(
            gate_beta.begin(),
            gate_beta.end(),
            run->gpu_output.begin() + output_base + kGateRows
        );
    }

    std::vector<float> selected_values;
    for (unsigned int token : selected_tokens(prefill_tokens)) {
        for (unsigned int row = 0u; row < kGateOutputRows; ++row) {
            const float value =
                run->gpu_output[
                    static_cast<size_t>(token) * kGateOutputRows + row
                ];
            run->samples.push_back({token, row, value, value, 0.0f});
            selected_values.push_back(value);
            ++run->checked_values;
        }
    }
    run->selected_reference_hash =
        qrt_fnv1a64_f32(selected_values.data(), selected_values.size());
    run->selected_gpu_hash = run->selected_reference_hash;
    run->a_input_hash =
        qrt_fnv1a64_f32(a_run.gpu_output.data(), a_run.gpu_output.size());
    run->b_input_hash =
        qrt_fnv1a64_f32(b_run.gpu_output.data(), b_run.gpu_output.size());
    run->a_log_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->a_log.data(),
        run->a_log.size() * sizeof(run->a_log[0])
    );
    run->dt_bias_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->dt_bias.data(),
        run->dt_bias.size() * sizeof(run->dt_bias[0])
    );

    std::vector<float> gate_g_surface;
    std::vector<float> gate_beta_surface;
    gate_g_surface.reserve(expected_gate_rows);
    gate_beta_surface.reserve(expected_gate_rows);
    for (unsigned int token = 0u; token < prefill_tokens; ++token) {
        const size_t output_base =
            static_cast<size_t>(token) * kGateOutputRows;
        gate_g_surface.insert(
            gate_g_surface.end(),
            run->gpu_output.data() + output_base,
            run->gpu_output.data() + output_base + kGateRows
        );
        gate_beta_surface.insert(
            gate_beta_surface.end(),
            run->gpu_output.data() + output_base + kGateRows,
            run->gpu_output.data() + output_base + kGateOutputRows
        );
    }
    run->gate_g_hash =
        qrt_fnv1a64_f32(gate_g_surface.data(), gate_g_surface.size());
    run->gate_beta_hash =
        qrt_fnv1a64_f32(gate_beta_surface.data(), gate_beta_surface.size());
    run->gpu_output_hash =
        qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
    run->correctness_pass = run->checked_values > 0u;
    return run->correctness_pass;
}

bool materialize_qrt_host_gate_decay_handoff(
    const GateRun &source,
    unsigned int prefill_tokens,
    GateRun *run
) {
    if (run == nullptr) {
        return false;
    }
    *run = source;
    run->name = "gate_rows_qrt_host_decay_handoff";
    run->stage = "layer0_gate_rows_qrt_host_decay_handoff_prefill_phase";
    run->samples.clear();
    run->checked_values = 0u;
    run->max_abs_diff = 0.0f;
    run->selected_reference_hash = 0u;
    run->selected_gpu_hash = 0u;
    run->gate_g_hash = 0u;
    run->gate_beta_hash = 0u;
    run->gpu_output_hash = 0u;
    run->correctness_pass = false;
    run->failure_stage.clear();
    run->failure.clear();

    const size_t expected_output_rows =
        static_cast<size_t>(prefill_tokens) * kGateOutputRows;
    if (!source.correctness_pass ||
        source.gpu_output.size() != expected_output_rows) {
        run->failure_stage = "gate_rows_qrt_host_decay_input_contract";
        run->failure =
            "qrt-compatible gate decay handoff received mismatched gate rows";
        return false;
    }

    run->gpu_output = source.gpu_output;
    for (unsigned int token = 0u; token < prefill_tokens; ++token) {
        const size_t output_base =
            static_cast<size_t>(token) * kGateOutputRows;
        for (unsigned int head = 0u; head < kGateRows; ++head) {
            run->gpu_output[output_base + head] =
                expf(source.gpu_output[output_base + head]);
        }
    }

    std::vector<float> selected_values;
    for (unsigned int token : selected_tokens(prefill_tokens)) {
        for (unsigned int row = 0u; row < kGateOutputRows; ++row) {
            const float value =
                run->gpu_output[
                    static_cast<size_t>(token) * kGateOutputRows + row
                ];
            run->samples.push_back({token, row, value, value, 0.0f});
            selected_values.push_back(value);
            ++run->checked_values;
        }
    }
    run->selected_reference_hash =
        qrt_fnv1a64_f32(selected_values.data(), selected_values.size());
    run->selected_gpu_hash = run->selected_reference_hash;
    run->gate_g_hash =
        qrt_fnv1a64_f32(run->gpu_output.data(), expected_output_rows);
    run->gate_beta_hash = source.gate_beta_hash;
    run->gpu_output_hash =
        qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
    run->correctness_pass = run->checked_values > 0u;
    return run->correctness_pass;
}

bool run_core_rows_zero_state(
    const PostconvRun &postconv_run,
    const GateRun &gate_run,
    unsigned int prefill_tokens,
    CoreRun *run
) {
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kValueFeatures);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!postconv_run.correctness_pass ||
        postconv_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kQkvRows) {
        run->failure_stage = "core_rows_postconv_input_contract";
        run->failure = "postconv_qkv output is missing or has unexpected shape";
        return false;
    }
    if (!gate_run.correctness_pass ||
        gate_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kGateOutputRows) {
        run->failure_stage = "core_rows_gate_input_contract";
        run->failure = "gate_rows output is missing or has unexpected shape";
        return false;
    }
    if (kValueHeadsPerKeyHead == 0u || kValueHeads % kKeyHeads != 0u) {
        run->failure_stage = "core_rows_shape_contract";
        run->failure = "value heads do not map cleanly to key heads";
        return false;
    }

    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_postconv = nullptr;
    float *device_gate = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_postconv), postconv_run.output_bytes), "hipMalloc(core_rows_postconv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate), gate_run.output_bytes), "hipMalloc(core_rows_gate_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(core_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_postconv, postconv_run.gpu_output.data(), postconv_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(core_rows_postconv_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_gate, gate_run.gpu_output.data(), gate_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(core_rows_gate_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(core_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            core_rows_zero_state_kernel,
            dim3(kValueHeads, prefill_tokens),
            dim3(kValueDim),
            0,
            0,
            device_postconv,
            device_gate,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_core_rows_zero_state_prefill_phase",
            "warmup_sync_layer0_core_rows_zero_state_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_core_rows_zero_state_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_core_rows_zero_state_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_core_rows_zero_state_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            core_rows_zero_state_kernel,
            dim3(kValueHeads, prefill_tokens),
            dim3(kValueDim),
            0,
            0,
            device_postconv,
            device_gate,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_core_rows_zero_state_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_core_rows_zero_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_core_rows_zero_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_core_rows_zero_state_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(core_rows_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_core_rows()) {
                const float reference = core_zero_state_cpu_value(
                    postconv_run,
                    gate_run,
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kValueFeatures + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->postconv_input_hash = qrt_fnv1a64_f32(postconv_run.gpu_output.data(), postconv_run.gpu_output.size());
        run->gate_input_hash = qrt_fnv1a64_f32(gate_run.gpu_output.data(), gate_run.gpu_output.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_core_rows_zero_state_prefill_phase";
            run->failure = "selected CPU/HIP zero-state core rows boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_gate);
    free_device(device_postconv);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_core_rows_sequence_state(
    const PostconvRun &postconv_run,
    const GateRun &gate_run,
    unsigned int prefill_tokens,
    CoreRun *run,
    bool use_cpu_order_kernel = false,
    bool gate_values_are_decay = false
) {
    run->name = "core_rows_sequence_state";
    run->stage = "layer0_core_rows_sequence_state_prefill_phase";
    run->output_elements =
        static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kValueFeatures);
    run->output_bytes = run->output_elements * sizeof(float);

    if (prefill_tokens == 0u ||
        !postconv_run.correctness_pass ||
        postconv_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * kQkvRows) {
        run->failure_stage = "core_rows_sequence_state_postconv_input_contract";
        run->failure = "postconv_qkv output is missing or has unexpected shape";
        return false;
    }
    if (!gate_run.correctness_pass ||
        gate_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * kGateOutputRows) {
        run->failure_stage = "core_rows_sequence_state_gate_input_contract";
        run->failure = "gate_rows output is missing or has unexpected shape";
        return false;
    }
    if (kValueHeadsPerKeyHead == 0u || kValueHeads % kKeyHeads != 0u) {
        run->failure_stage = "core_rows_sequence_state_shape_contract";
        run->failure = "value heads do not map cleanly to key heads";
        return false;
    }

    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_postconv = nullptr;
    float *device_gate = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_postconv), postconv_run.output_bytes), "hipMalloc(core_rows_sequence_state_postconv_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate), gate_run.output_bytes), "hipMalloc(core_rows_sequence_state_gate_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(core_rows_sequence_state_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_postconv, postconv_run.gpu_output.data(), postconv_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(core_rows_sequence_state_postconv_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_gate, gate_run.gpu_output.data(), gate_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(core_rows_sequence_state_gate_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(core_rows_sequence_state_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_core_rows_sequence_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_core_rows_sequence_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_core_rows_sequence_state_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (use_cpu_order_kernel) {
        hipLaunchKernelGGL(
            core_rows_sequence_state_cpu_order_kernel,
            dim3(kValueHeads),
            dim3(kValueDim),
            0,
            0,
            device_postconv,
            device_gate,
            nullptr,
            device_output,
            prefill_tokens,
            gate_values_are_decay
        );
    } else {
        hipLaunchKernelGGL(
            core_rows_sequence_state_kernel,
            dim3(kValueHeads),
            dim3(kValueDim),
            0,
            0,
            device_postconv,
            device_gate,
            nullptr,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "kernel_launch_layer0_core_rows_sequence_state_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_core_rows_sequence_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_core_rows_sequence_state_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_core_rows_sequence_state_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(core_rows_sequence_state_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        const std::vector<unsigned int> reference_rows = selected_core_rows();
        const std::vector<unsigned int> sample_tokens = selected_tokens(prefill_tokens);
        std::vector<float> selected_state(
            reference_rows.size() * static_cast<size_t>(kKeyDim),
            0.0f
        );
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token = 0; token < prefill_tokens; ++token) {
            const size_t postconv_base = static_cast<size_t>(token) * kQkvRows;
            const size_t gate_base = static_cast<size_t>(token) * kGateOutputRows;
            const bool sample_token = contains_token(sample_tokens, token);
            for (size_t row_index = 0; row_index < reference_rows.size(); ++row_index) {
                const unsigned int value_index = reference_rows[row_index];
                const unsigned int value_head = value_index / kValueDim;
                const unsigned int key_head = value_head / kValueHeadsPerKeyHead;
                const unsigned int key_base = key_head * kKeyDim;
                float *state =
                    selected_state.data() + row_index * static_cast<size_t>(kKeyDim);
                const float value =
                    postconv_run.gpu_output[
                        postconv_base + 2u * kKeyFeatures + value_index
                    ];
                const float beta =
                    gate_run.gpu_output[gate_base + kGateRows + value_head];
                const float decay =
                    gate_values_are_decay
                        ? gate_run.gpu_output[gate_base + value_head]
                        : expf(gate_run.gpu_output[gate_base + value_head]);
                float projected = 0.0f;
                float output_acc = 0.0f;
                for (unsigned int key_index = 0; key_index < kKeyDim; ++key_index) {
                    const float decayed = state[key_index] * decay;
                    state[key_index] = decayed;
                    const float k_value =
                        postconv_run.gpu_output[
                            postconv_base + kKeyFeatures + key_base + key_index
                        ];
                    projected += decayed * k_value;
                }
                const float residual_update = (value - projected) * beta;
                for (unsigned int key_index = 0; key_index < kKeyDim; ++key_index) {
                    const float k_value =
                        postconv_run.gpu_output[
                            postconv_base + kKeyFeatures + key_base + key_index
                        ];
                    const float q_value =
                        postconv_run.gpu_output[postconv_base + key_base + key_index];
                    const float updated = state[key_index] + residual_update * k_value;
                    state[key_index] = updated;
                    output_acc += updated * q_value;
                }
                if (!sample_token) {
                    continue;
                }
                const float reference = bf16_round_to_float(output_acc);
                const float gpu =
                    run->gpu_output[static_cast<size_t>(token) * kValueFeatures + value_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, value_index, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->postconv_input_hash =
            qrt_fnv1a64_f32(postconv_run.gpu_output.data(), postconv_run.gpu_output.size());
        run->gate_input_hash =
            qrt_fnv1a64_f32(gate_run.gpu_output.data(), gate_run.gpu_output.size());
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms);
        run->prefill_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage =
                "correctness_layer0_core_rows_sequence_state_prefill_phase";
            run->failure =
                "selected CPU/HIP sequence-state core rows boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_gate);
    free_device(device_postconv);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_gated_rmsnorm(
    const ProjectionRun &z_run,
    const CoreRun &core_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    GatedRmsnormRun *run
) {
    run->weight_bytes = static_cast<uint64_t>(kGatedRmsnormWeightElements) * sizeof(uint16_t);
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kValueFeatures);
    run->output_bytes = run->output_elements * sizeof(float);

    if (z_run.spec.rows != kZRows ||
        z_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kZRows) {
        run->failure_stage = "gated_rmsnorm_z_input_contract";
        run->failure = "Z projection output is missing or has unexpected shape";
        return false;
    }
    if (!core_run.correctness_pass ||
        core_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kValueFeatures) {
        run->failure_stage = "gated_rmsnorm_core_input_contract";
        run->failure = "core_rows output is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_LINEAR_ATTN_NORM, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_gated_rmsnorm_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_gated_rmsnorm_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer0_gated_rmsnorm_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_core = nullptr;
    float *device_z = nullptr;
    uint16_t *device_norm = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_core), core_run.output_bytes), "hipMalloc(gated_rmsnorm_core_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_z), z_run.output_bytes), "hipMalloc(gated_rmsnorm_z_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_norm), run->weight_bytes), "hipMalloc(gated_rmsnorm_norm_weight)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(gated_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_core, core_run.gpu_output.data(), core_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(gated_rmsnorm_core_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_z, z_run.gpu_output.data(), z_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(gated_rmsnorm_z_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_norm, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(gated_rmsnorm_norm_weight)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(gated_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            gated_rmsnorm_kernel,
            dim3(kValueHeads, prefill_tokens),
            dim3(kValueDim),
            0,
            0,
            device_core,
            device_z,
            device_norm,
            device_output,
            prefill_tokens,
            0u,
            nullptr,
            nullptr
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_gated_rmsnorm_prefill_phase",
            "warmup_sync_layer0_gated_rmsnorm_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_gated_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_gated_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_gated_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            gated_rmsnorm_kernel,
            dim3(kValueHeads, prefill_tokens),
            dim3(kValueDim),
            0,
            0,
            device_core,
            device_z,
            device_norm,
            device_output,
            prefill_tokens,
            0u,
            nullptr,
            nullptr
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_gated_rmsnorm_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_gated_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_gated_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_gated_rmsnorm_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(gated_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_core_rows()) {
                const float reference = gated_rmsnorm_cpu_value(
                    core_run.gpu_output,
                    z_run.gpu_output,
                    run->weights.data(),
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kValueFeatures + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->core_input_hash = qrt_fnv1a64_f32(core_run.gpu_output.data(), core_run.gpu_output.size());
        run->z_input_hash = qrt_fnv1a64_f32(z_run.gpu_output.data(), z_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_gated_rmsnorm_prefill_phase";
            run->failure = "selected CPU/HIP gated RMSNorm boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_norm);
    free_device(device_z);
    free_device(device_core);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_out_projection(
    const GatedRmsnormRun &gated_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    OutProjectionRun *run
) {
    run->weight_bytes = static_cast<uint64_t>(kOutProjectionRows) *
                        static_cast<uint64_t>(kValueFeatures) *
                        sizeof(uint16_t);
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(kOutProjectionRows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!gated_rmsnorm_run.correctness_pass ||
        gated_rmsnorm_run.gpu_output.size() != static_cast<size_t>(prefill_tokens) * kValueFeatures) {
        run->failure_stage = "out_projection_gated_rmsnorm_input_contract";
        run->failure = "gated_rmsnorm output is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_LINEAR_ATTN_OUT_PROJ, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_out_projection_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_out_projection_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer0_out_projection_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_input = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(out_projection_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_input), gated_rmsnorm_run.output_bytes), "hipMalloc(out_projection_gated_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(out_projection_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(out_projection_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_input, gated_rmsnorm_run.gpu_output.data(), gated_rmsnorm_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(out_projection_gated_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(out_projection_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            out_projection_tiled_kernel,
            dim3((kOutProjectionRows + kTileRows - 1) / kTileRows, (prefill_tokens + kTileTokens - 1) / kTileTokens),
            dim3(kThreadTileRows, kThreadTileTokens),
            0,
            0,
            device_weights,
            device_input,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_out_projection_prefill_phase",
            "warmup_sync_layer0_out_projection_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_out_projection_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_out_projection_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_out_projection_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            out_projection_tiled_kernel,
            dim3((kOutProjectionRows + kTileRows - 1) / kTileRows, (prefill_tokens + kTileTokens - 1) / kTileTokens),
            dim3(kThreadTileRows, kThreadTileTokens),
            0,
            0,
            device_weights,
            device_input,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_out_projection_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_out_projection_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_out_projection_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_out_projection_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(out_projection_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference = out_projection_cpu_value(
                    run->weights.data(),
                    gated_rmsnorm_run.gpu_output,
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * kOutProjectionRows + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->gated_input_hash = qrt_fnv1a64_f32(gated_rmsnorm_run.gpu_output.data(), gated_rmsnorm_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_out_projection_prefill_phase";
            run->failure = "selected CPU/HIP output projection boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_input);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_residual_hidden(
    const std::vector<uint16_t> &hidden,
    const OutProjectionRun &out_projection_run,
    unsigned int prefill_tokens,
    ResidualHiddenRun *run
) {
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);
    const size_t hidden_bytes = run->output_elements * sizeof(uint16_t);

    if (hidden.size() != run->output_elements) {
        run->failure_stage = "residual_hidden_seed_input_contract";
        run->failure = "seed hidden input is missing or has unexpected shape";
        return false;
    }
    if (!out_projection_run.correctness_pass || out_projection_run.gpu_output.size() != run->output_elements) {
        run->failure_stage = "residual_hidden_out_projection_input_contract";
        run->failure = "out_projection output is missing or has unexpected shape";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_hidden = nullptr;
    float *device_attention_update = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid((run->output_elements + kThreads - 1u) / kThreads);

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_hidden), hidden_bytes), "hipMalloc(residual_hidden_seed_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_attention_update), out_projection_run.output_bytes), "hipMalloc(residual_hidden_attention_update)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(residual_hidden_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_hidden, hidden.data(), hidden_bytes, hipMemcpyHostToDevice), "hipMemcpy(residual_hidden_seed_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_attention_update, out_projection_run.gpu_output.data(), out_projection_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(residual_hidden_attention_update)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(residual_hidden_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            residual_hidden_add_kernel,
            grid,
            block,
            0,
            0,
            device_hidden,
            device_attention_update,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_residual_hidden_prefill_phase",
            "warmup_sync_layer0_residual_hidden_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_residual_hidden_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_residual_hidden_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_residual_hidden_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            residual_hidden_add_kernel,
            grid,
            block,
            0,
            0,
            device_hidden,
            device_attention_update,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_residual_hidden_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_residual_hidden_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_residual_hidden_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_residual_hidden_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(residual_hidden_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference = residual_hidden_cpu_value(
                    hidden,
                    out_projection_run.gpu_output,
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->hidden_input_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            hidden.data(),
            hidden_bytes
        );
        run->attention_update_hash = qrt_fnv1a64_f32(out_projection_run.gpu_output.data(), out_projection_run.gpu_output.size());
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_residual_hidden_prefill_phase";
            run->failure = "selected CPU/HIP residual hidden boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_attention_update);
    free_device(device_hidden);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_post_attention_rmsnorm(
    const ResidualHiddenRun &residual_hidden_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    PostAttentionRmsnormRun *run
) {
    run->weight_bytes = static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) * sizeof(uint16_t);
    run->output_elements = static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!residual_hidden_run.correctness_pass || residual_hidden_run.gpu_output.size() != run->output_elements) {
        run->failure_stage = "post_attention_rmsnorm_residual_input_contract";
        run->failure = "residual_hidden output is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_POST_ATTENTION_NORM, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_post_attention_rmsnorm_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_post_attention_rmsnorm_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer0_post_attention_rmsnorm_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_residual = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid(prefill_tokens);

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(post_attention_rmsnorm_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_residual), residual_hidden_run.output_bytes), "hipMalloc(post_attention_rmsnorm_residual_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(post_attention_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(post_attention_rmsnorm_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_residual, residual_hidden_run.gpu_output.data(), residual_hidden_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(post_attention_rmsnorm_residual_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(post_attention_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            post_attention_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_residual,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_post_attention_rmsnorm_prefill_phase",
            "warmup_sync_layer0_post_attention_rmsnorm_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_post_attention_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_post_attention_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_post_attention_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            post_attention_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_residual,
            device_weights,
            device_output,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_post_attention_rmsnorm_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_post_attention_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_post_attention_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_post_attention_rmsnorm_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(post_attention_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (unsigned int token : selected_tokens(prefill_tokens)) {
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference = post_attention_rmsnorm_cpu_value(
                    residual_hidden_run.gpu_output,
                    run->weights.data(),
                    token,
                    row
                );
                const float gpu = run->gpu_output[static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->residual_input_hash = qrt_fnv1a64_f32(residual_hidden_run.gpu_output.data(), residual_hidden_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                std::isfinite(run->max_abs_diff) &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_post_attention_rmsnorm_prefill_phase";
            run->failure = "selected CPU/HIP post-attention RMSNorm boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_residual);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_moe_router(
    const PostAttentionRmsnormRun &post_attention_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    MoeRouterRun *run
) {
    run->weight_bytes = static_cast<uint64_t>(QRT_QWEN36_EXPERT_COUNT) *
                        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
                        sizeof(uint16_t);
    run->logits_elements = static_cast<size_t>(prefill_tokens) *
                           static_cast<size_t>(QRT_QWEN36_EXPERT_COUNT);
    run->logits_bytes = run->logits_elements * sizeof(float);
    run->topk_elements = static_cast<size_t>(prefill_tokens) *
                         static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN);
    run->topk_ids_bytes = run->topk_elements * sizeof(uint32_t);
    run->topk_weights_bytes = run->topk_elements * sizeof(float);
    run->output_bytes = run->logits_bytes + run->topk_ids_bytes + run->topk_weights_bytes;

    if (!post_attention_rmsnorm_run.correctness_pass ||
        post_attention_rmsnorm_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
        run->failure_stage = "moe_router_post_attention_input_contract";
        run->failure = "post_attention_rmsnorm output is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_ROUTER, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_router_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_router_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer0_moe_router_prefill_phase";
        return false;
    }
    run->gpu_logits.assign(run->logits_elements, 0.0f);
    run->gpu_topk_ids.assign(run->topk_elements, 0u);
    run->gpu_topk_weights.assign(run->topk_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_input = nullptr;
    float *device_logits = nullptr;
    uint32_t *device_topk_ids = nullptr;
    float *device_topk_weights = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(QRT_QWEN36_EXPERT_COUNT);
    const dim3 grid(prefill_tokens);

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(moe_router_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_input), post_attention_rmsnorm_run.output_bytes), "hipMalloc(moe_router_post_attention_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_logits), run->logits_bytes), "hipMalloc(moe_router_logits)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_topk_ids), run->topk_ids_bytes), "hipMalloc(moe_router_topk_ids)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_topk_weights), run->topk_weights_bytes), "hipMalloc(moe_router_topk_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(moe_router_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_input, post_attention_rmsnorm_run.gpu_output.data(), post_attention_rmsnorm_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(moe_router_post_attention_input)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemset(device_logits, 0, run->logits_bytes), "hipMemset(moe_router_logits)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_topk_ids, 0, run->topk_ids_bytes), "hipMemset(moe_router_topk_ids)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_topk_weights, 0, run->topk_weights_bytes), "hipMemset(moe_router_topk_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            moe_router_kernel,
            grid,
            block,
            0,
            0,
            device_input,
            device_weights,
            device_logits,
            device_topk_ids,
            device_topk_weights,
            prefill_tokens
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_moe_router_prefill_phase",
            "warmup_sync_layer0_moe_router_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_moe_router_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_moe_router_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_moe_router_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            moe_router_kernel,
            grid,
            block,
            0,
            0,
            device_input,
            device_weights,
            device_logits,
            device_topk_ids,
            device_topk_weights,
            prefill_tokens
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_moe_router_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_moe_router_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_moe_router_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_moe_router_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_logits.data(), device_logits, run->logits_bytes, hipMemcpyDeviceToHost), "hipMemcpy(moe_router_logits)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(run->gpu_topk_ids.data(), device_topk_ids, run->topk_ids_bytes, hipMemcpyDeviceToHost), "hipMemcpy(moe_router_topk_ids)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(run->gpu_topk_weights.data(), device_topk_weights, run->topk_weights_bytes, hipMemcpyDeviceToHost), "hipMemcpy(moe_router_topk_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_logits_reference;
        std::vector<float> selected_logits_gpu;
        std::vector<uint32_t> selected_topk_ids_reference;
        std::vector<uint32_t> selected_topk_ids_gpu;
        std::vector<float> selected_topk_weights_reference;
        std::vector<float> selected_topk_weights_gpu;
        std::vector<float> reference_logits(QRT_QWEN36_EXPERT_COUNT, 0.0f);
        uint32_t reference_topk_ids[QRT_QWEN36_EXPERTS_PER_TOKEN] = {};
        float reference_topk_weights[QRT_QWEN36_EXPERTS_PER_TOKEN] = {};

        for (unsigned int token : selected_tokens(prefill_tokens)) {
            const float *input = post_attention_rmsnorm_run.gpu_output.data() +
                                 static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
            if (!qrt_layer0_moe_router_cpu(
                    run->weights.data(),
                    input,
                    reference_logits.data(),
                    reference_topk_ids,
                    reference_topk_weights
                )) {
                run->failure_stage = "cpu_reference_layer0_moe_router_prefill_phase";
                run->failure = "CPU MoE router reference produced an invalid value";
                goto cleanup;
            }

            for (unsigned int row : selected_router_rows(reference_topk_ids)) {
                const float reference = reference_logits[row];
                const float gpu = run->gpu_logits[static_cast<size_t>(token) * QRT_QWEN36_EXPERT_COUNT + row];
                const float diff = std::fabs(reference - gpu);
                run->logit_samples.push_back({token, row, reference, gpu, diff});
                selected_logits_reference.push_back(reference);
                selected_logits_gpu.push_back(gpu);
                if (run->checked_logit_values == 0 || diff > run->max_logit_abs_diff) {
                    run->max_logit_abs_diff = diff;
                }
                ++run->checked_logit_values;
            }

            for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
                const size_t topk_index = static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
                const uint32_t reference_id = reference_topk_ids[route];
                const uint32_t gpu_id = run->gpu_topk_ids[topk_index];
                const float reference_weight = reference_topk_weights[route];
                const float gpu_weight = run->gpu_topk_weights[topk_index];
                const float diff = std::fabs(reference_weight - gpu_weight);
                const bool id_match = reference_id == gpu_id;
                run->topk_samples.push_back({token, route, reference_id, gpu_id, reference_weight, gpu_weight, diff, id_match});
                selected_topk_ids_reference.push_back(reference_id);
                selected_topk_ids_gpu.push_back(gpu_id);
                selected_topk_weights_reference.push_back(reference_weight);
                selected_topk_weights_gpu.push_back(gpu_weight);
                if (!id_match) {
                    ++run->topk_id_mismatches;
                }
                if (run->checked_topk_values == 0 || diff > run->max_topk_weight_abs_diff) {
                    run->max_topk_weight_abs_diff = diff;
                }
                ++run->checked_topk_values;
            }
        }
        run->selected_logits_reference_hash = qrt_fnv1a64_f32(selected_logits_reference.data(), selected_logits_reference.size());
        run->selected_logits_gpu_hash = qrt_fnv1a64_f32(selected_logits_gpu.data(), selected_logits_gpu.size());
        run->selected_topk_ids_reference_hash = qrt_fnv1a64_bytes(
            selected_topk_ids_reference.data(),
            selected_topk_ids_reference.size() * sizeof(selected_topk_ids_reference[0])
        );
        run->selected_topk_ids_gpu_hash = qrt_fnv1a64_bytes(
            selected_topk_ids_gpu.data(),
            selected_topk_ids_gpu.size() * sizeof(selected_topk_ids_gpu[0])
        );
        run->selected_topk_weights_reference_hash = qrt_fnv1a64_f32(selected_topk_weights_reference.data(), selected_topk_weights_reference.size());
        run->selected_topk_weights_gpu_hash = qrt_fnv1a64_f32(selected_topk_weights_gpu.data(), selected_topk_weights_gpu.size());
        run->post_attention_input_hash = qrt_fnv1a64_f32(post_attention_rmsnorm_run.gpu_output.data(), post_attention_rmsnorm_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_logits_hash = qrt_fnv1a64_f32(run->gpu_logits.data(), run->gpu_logits.size());
        run->gpu_topk_ids_hash = qrt_fnv1a64_bytes(run->gpu_topk_ids.data(), run->topk_ids_bytes);
        run->gpu_topk_weights_hash = qrt_fnv1a64_f32(run->gpu_topk_weights.data(), run->gpu_topk_weights.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->prefill_tokens_per_second = run->avg_ms > 0.0 ? static_cast<double>(prefill_tokens) / (run->avg_ms / 1000.0) : 0.0;
        run->correctness_pass = run->checked_logit_values > 0 &&
                                run->checked_topk_values > 0 &&
                                run->topk_id_mismatches == 0 &&
                                std::isfinite(run->max_logit_abs_diff) &&
                                std::isfinite(run->max_topk_weight_abs_diff) &&
                                run->max_logit_abs_diff <= kTolerance &&
                                run->max_topk_weight_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_moe_router_prefill_phase";
            run->failure = "selected CPU/HIP MoE router logits/top-k boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_topk_weights);
    free_device(device_topk_ids);
    free_device(device_logits);
    free_device(device_input);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_routed_expert(
    const PostAttentionRmsnormRun &post_attention_rmsnorm_run,
    const MoeRouterRun &moe_router_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    const std::vector<unsigned int> &selected_token_ids,
    RoutedExpertRun *run
) {
    const uint64_t gate_up_bytes_per_route =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_BYTES_PER_EXPERT);
    const uint64_t down_bytes_per_route =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_BYTES_PER_EXPERT);

    if (!post_attention_rmsnorm_run.correctness_pass ||
        !moe_router_run.correctness_pass ||
        post_attention_rmsnorm_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) ||
        moe_router_run.gpu_topk_ids.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) ||
        moe_router_run.gpu_topk_weights.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN)) {
        run->failure_stage = "routed_expert_input_contract";
        run->failure = "post-attention RMSNorm or MoE router output is missing or has unexpected shape";
        return false;
    }

    run->selected_token_ids = selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->selected_route_count =
        run->selected_token_count * static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN);
    run->gate_up_weight_bytes = 0;
    run->gate_up_weight_pair_bytes = 0;
    run->down_weight_bytes = 0;
    run->down_weight_row_pair_bytes = 0;
    run->weight_bytes = 0;
    run->output_elements = run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);

    if (run->selected_token_count == 0 || run->selected_route_count == 0) {
        run->failure_stage = "selected_tokens_layer0_routed_expert_prefill_phase";
        run->failure = "no selected tokens available for routed expert boundary";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_EXPERT_GATE_UP, &run->gate_up_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_expert_gate_up_prefill_phase";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_EXPERT_DOWN, &run->down_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_expert_down_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->gate_up_tensor_name, &run->gate_up_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_expert_gate_up_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->down_tensor_name, &run->down_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_expert_down_prefill_phase";
        return false;
    }
    if (run->gate_up_location.data_end < run->gate_up_location.data_begin ||
        run->gate_up_location.data_end - run->gate_up_location.data_begin !=
            static_cast<uint64_t>(QRT_QWEN36_EXPERT_COUNT) * gate_up_bytes_per_route ||
        run->down_location.data_end < run->down_location.data_begin ||
        run->down_location.data_end - run->down_location.data_begin !=
            static_cast<uint64_t>(QRT_QWEN36_EXPERT_COUNT) * down_bytes_per_route) {
        run->failure_stage = "shape_layer0_routed_expert_prefill_phase";
        run->failure = "layer-0 routed expert tensors do not match expected byte shape";
        return false;
    }

    run->selected_inputs.assign(
        run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE),
        0.0f
    );
    const size_t max_selected_unique_experts =
        capped_selected_unique_expert_count(run->selected_route_count);
    run->selected_expert_ids.reserve(run->selected_route_count);
    run->route_expert_slot_indices.reserve(run->selected_route_count);
    run->unique_expert_ids.reserve(max_selected_unique_experts);
    run->selected_topk_weights.reserve(run->selected_route_count);
    run->gate_up_weights.reserve(
        max_selected_unique_experts *
        static_cast<size_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT)
    );
    run->down_weights.reserve(
        max_selected_unique_experts *
        static_cast<size_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT)
    );
    std::vector<int> expert_slots(QRT_QWEN36_EXPERT_COUNT, -1);
    for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
        const unsigned int token = run->selected_token_ids[selected_index];
        const float *input =
            post_attention_rmsnorm_run.gpu_output.data() +
            static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
        std::copy(
            input,
            input + QRT_QWEN36_HIDDEN_SIZE,
            run->selected_inputs.data() +
                selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
        );
        for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
            const size_t topk_index =
                static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const uint32_t expert_id = moe_router_run.gpu_topk_ids[topk_index];
            if (expert_id >= QRT_QWEN36_EXPERT_COUNT) {
                run->failure_stage = "selected_expert_id_layer0_routed_expert_prefill_phase";
                run->failure = "MoE router selected an out-of-range expert id";
                return false;
            }
            int expert_slot = expert_slots[expert_id];
            if (expert_slot < 0) {
                expert_slot = static_cast<int>(run->unique_expert_ids.size());
                expert_slots[expert_id] = expert_slot;
                run->unique_expert_ids.push_back(expert_id);

                std::vector<uint16_t> gate_up_slice;
                std::vector<uint16_t> down_slice;
                if (!read_safetensors_bytes(
                        model_dir,
                        run->gate_up_location,
                        static_cast<uint64_t>(expert_id) * gate_up_bytes_per_route,
                        gate_up_bytes_per_route,
                        &gate_up_slice,
                        &run->failure
                    )) {
                    run->failure_stage = "read_layer0_moe_expert_gate_up_prefill_phase";
                    return false;
                }
                if (!read_safetensors_bytes(
                        model_dir,
                        run->down_location,
                        static_cast<uint64_t>(expert_id) * down_bytes_per_route,
                        down_bytes_per_route,
                        &down_slice,
                        &run->failure
                    )) {
                    run->failure_stage = "read_layer0_moe_expert_down_prefill_phase";
                    return false;
                }
                run->gate_up_weights.insert(run->gate_up_weights.end(), gate_up_slice.begin(), gate_up_slice.end());
                run->down_weights.insert(run->down_weights.end(), down_slice.begin(), down_slice.end());
            }
            run->selected_expert_ids.push_back(expert_id);
            run->route_expert_slot_indices.push_back(static_cast<uint32_t>(expert_slot));
            run->selected_topk_weights.push_back(moe_router_run.gpu_topk_weights[topk_index]);
        }
    }
    run->unique_expert_count = run->unique_expert_ids.size();
    run->gate_up_weight_bytes = static_cast<uint64_t>(run->gate_up_weights.size() * sizeof(uint16_t));
    run->down_weight_bytes = static_cast<uint64_t>(run->down_weights.size() * sizeof(uint16_t));
    run->weight_bytes = run->gate_up_weight_bytes + run->down_weight_bytes;
    if (run->route_expert_slot_indices.size() != run->selected_route_count ||
        run->unique_expert_count == 0 ||
        run->gate_up_weight_bytes != gate_up_bytes_per_route * static_cast<uint64_t>(run->unique_expert_count) ||
        run->down_weight_bytes != down_bytes_per_route * static_cast<uint64_t>(run->unique_expert_count)) {
        run->failure_stage = "unique_expert_pack_layer0_routed_expert_prefill_phase";
        run->failure = "layer-0 routed expert unique-expert pack has an unexpected shape";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);
    run->cpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_gate_up = nullptr;
    uint16_t *device_down = nullptr;
    uint32_t *device_route_expert_slot_indices = nullptr;
    float *device_inputs = nullptr;
    float *device_topk_weights = nullptr;
    float *device_activated = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const size_t activated_elements =
        run->selected_route_count * static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE);
    const size_t activated_bytes = activated_elements * sizeof(float);
    const dim3 activation_grid(
        static_cast<unsigned int>(run->selected_route_count),
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    const dim3 down_grid(
        static_cast<unsigned int>(run->selected_token_count),
        QRT_QWEN36_HIDDEN_SIZE
    );
    const dim3 block(kThreads);
    const int routed_scale_after_down = 0;
    const int routed_cpu_reference_arithmetic = 0;
    const int routed_disable_fma = 0;

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate_up), run->gate_up_weight_bytes), "hipMalloc(routed_expert_gate_up_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_down), run->down_weight_bytes), "hipMalloc(routed_expert_down_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_route_expert_slot_indices), run->route_expert_slot_indices.size() * sizeof(uint32_t)), "hipMalloc(routed_expert_route_expert_slot_indices)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_inputs), run->selected_inputs.size() * sizeof(float)), "hipMalloc(routed_expert_selected_inputs)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_topk_weights), run->selected_topk_weights.size() * sizeof(float)), "hipMalloc(routed_expert_topk_weights)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_activated), activated_bytes), "hipMalloc(routed_expert_activated)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(routed_expert_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_gate_up, run->gate_up_weights.data(), run->gate_up_weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(routed_expert_gate_up_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_down, run->down_weights.data(), run->down_weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(routed_expert_down_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_route_expert_slot_indices, run->route_expert_slot_indices.data(), run->route_expert_slot_indices.size() * sizeof(uint32_t), hipMemcpyHostToDevice), "hipMemcpy(routed_expert_route_expert_slot_indices)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_inputs, run->selected_inputs.data(), run->selected_inputs.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(routed_expert_selected_inputs)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_topk_weights, run->selected_topk_weights.data(), run->selected_topk_weights.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(routed_expert_topk_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_activated, 0, activated_bytes), "hipMemset(routed_expert_activated)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(routed_expert_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            routed_expert_gate_up_activation_kernel,
            activation_grid,
            block,
            0,
            0,
            device_inputs,
            device_gate_up,
            device_route_expert_slot_indices,
            device_topk_weights,
            device_activated,
            static_cast<unsigned int>(run->selected_route_count),
            routed_scale_after_down,
            routed_cpu_reference_arithmetic,
            routed_disable_fma
        );
        hipLaunchKernelGGL(
            routed_expert_down_accumulate_kernel,
            down_grid,
            block,
            0,
            0,
            device_activated,
            device_down,
            device_route_expert_slot_indices,
            device_topk_weights,
            device_output,
            static_cast<unsigned int>(run->selected_token_count),
            routed_scale_after_down,
            routed_cpu_reference_arithmetic,
            routed_disable_fma
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_routed_expert_prefill_phase",
            "warmup_sync_layer0_routed_expert_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_routed_expert_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_routed_expert_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_routed_expert_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            routed_expert_gate_up_activation_kernel,
            activation_grid,
            block,
            0,
            0,
            device_inputs,
            device_gate_up,
            device_route_expert_slot_indices,
            device_topk_weights,
            device_activated,
            static_cast<unsigned int>(run->selected_route_count),
            routed_scale_after_down,
            routed_cpu_reference_arithmetic,
            routed_disable_fma
        );
        hipLaunchKernelGGL(
            routed_expert_down_accumulate_kernel,
            down_grid,
            block,
            0,
            0,
            device_activated,
            device_down,
            device_route_expert_slot_indices,
            device_topk_weights,
            device_output,
            static_cast<unsigned int>(run->selected_token_count),
            routed_scale_after_down,
            routed_cpu_reference_arithmetic,
            routed_disable_fma
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_routed_expert_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_routed_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_routed_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_routed_expert_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(routed_expert_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        std::vector<float> reference_output(QRT_QWEN36_HIDDEN_SIZE, 0.0f);
        const bool cpu_reference_parallel =
            g_descriptor_product_parallel_routed_cpu_reference;
        if (cpu_reference_parallel &&
            !compute_repeated_routed_cpu_output_parallel(run, &run->failure)) {
            run->failure_stage = "cpu_reference_layer0_routed_expert_prefill_phase";
            if (run->failure.empty()) {
                run->failure =
                    "parallel CPU routed expert reference produced an invalid value";
            }
            goto cleanup;
        }
        for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
            std::fill(reference_output.begin(), reference_output.end(), 0.0f);
            if (cpu_reference_parallel) {
                const float *parallel_reference =
                    run->cpu_output.data() +
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
                std::copy(
                    parallel_reference,
                    parallel_reference + QRT_QWEN36_HIDDEN_SIZE,
                    reference_output.begin()
                );
            } else {
                const float *input =
                    run->selected_inputs.data() +
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
                for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
                    const size_t route_index =
                        selected_index * static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) + route;
                    const uint32_t expert_slot = run->route_expert_slot_indices[route_index];
                    const uint16_t *gate_up =
                        run->gate_up_weights.data() +
                        static_cast<size_t>(expert_slot) *
                            static_cast<size_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT);
                    const uint16_t *down =
                        run->down_weights.data() +
                        static_cast<size_t>(expert_slot) *
                            static_cast<size_t>(QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT);
                    if (!qrt_layer0_moe_expert_accumulate_cpu(
                            gate_up,
                            down,
                            input,
                            run->selected_topk_weights[route_index],
                            reference_output.data()
                        )) {
                        run->failure_stage = "cpu_reference_layer0_routed_expert_prefill_phase";
                        run->failure = "CPU routed expert reference produced an invalid value";
                        goto cleanup;
                    }
                }
                std::copy(
                    reference_output.begin(),
                    reference_output.end(),
                    run->cpu_output.data() +
                        selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
                );
            }
            for (unsigned int row = 0; row < QRT_QWEN36_HIDDEN_SIZE; ++row) {
                const size_t output_index =
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
                const float diff =
                    std::fabs(reference_output[row] - run->gpu_output[output_index]);
                if (run->full_checked_values == 0 || diff > run->full_max_abs_diff) {
                    run->full_max_abs_diff = diff;
                }
                ++run->full_checked_values;
            }
            const unsigned int token = run->selected_token_ids[selected_index];
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference = reference_output[row];
                const float gpu =
                    run->gpu_output[selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash = qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash = qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->selected_expert_ids_hash = qrt_fnv1a64_bytes(
            run->selected_expert_ids.data(),
            run->selected_expert_ids.size() * sizeof(run->selected_expert_ids[0])
        );
        run->route_expert_slot_indices_hash = qrt_fnv1a64_bytes(
            run->route_expert_slot_indices.data(),
            run->route_expert_slot_indices.size() * sizeof(run->route_expert_slot_indices[0])
        );
        run->unique_expert_ids_hash = qrt_fnv1a64_bytes(
            run->unique_expert_ids.data(),
            run->unique_expert_ids.size() * sizeof(run->unique_expert_ids[0])
        );
        run->selected_topk_weights_hash =
            qrt_fnv1a64_f32(run->selected_topk_weights.data(), run->selected_topk_weights.size());
        run->post_attention_input_hash =
            qrt_fnv1a64_f32(run->selected_inputs.data(), run->selected_inputs.size());
        if (!run->gate_up_weights.empty()) {
            run->gate_up_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->gate_up_weights.data(),
                static_cast<size_t>(run->gate_up_weight_bytes)
            );
        } else if (run->gate_up_weight_hash == UINT64_C(0) &&
                   !run->gate_up_weight_pairs.empty()) {
            run->gate_up_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->gate_up_weight_pairs.data(),
                run->gate_up_weight_pairs.size() *
                    sizeof(run->gate_up_weight_pairs[0])
            );
        }
        if (!run->down_weights.empty()) {
            run->down_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->down_weights.data(),
                static_cast<size_t>(run->down_weight_bytes)
            );
        } else if (run->down_weight_hash == UINT64_C(0) &&
                   !run->down_weight_row_pairs.empty()) {
            run->down_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->down_weight_row_pairs.data(),
                run->down_weight_row_pairs.size() *
                    sizeof(run->down_weight_row_pairs[0])
            );
        }
        run->gpu_output_hash = qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->cpu_output_hash = qrt_fnv1a64_f32(run->cpu_output.data(), run->cpu_output.size());
        run->gpu_output_bf16_hash =
            qrt_fnv1a64_f32_bf16_round(run->gpu_output.data(), run->gpu_output.size());
        run->cpu_output_bf16_hash =
            qrt_fnv1a64_f32_bf16_round(run->cpu_output.data(), run->cpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) / (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass = run->checked_values > 0 &&
                                run->full_checked_values == run->output_elements &&
                                std::isfinite(run->max_abs_diff) &&
                                std::isfinite(run->full_max_abs_diff) &&
                                run->full_max_abs_diff <= kTolerance &&
                                run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_routed_expert_prefill_phase";
            run->failure = "selected CPU/HIP routed expert boundary exceeded tolerance";
        }
    }
    release_routed_expert_transients(run);

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_activated);
    free_device(device_topk_weights);
    free_device(device_inputs);
    free_device(device_route_expert_slot_indices);
    free_device(device_down);
    free_device(device_gate_up);
    return run->failure_stage.empty() && run->correctness_pass;
}

unsigned int shared_cpu_reference_worker_count(size_t selected_token_count) {
    const char *env = std::getenv("QRT_PREFILL_DESCRIPTOR_BATCH_PARALLEL_SHARED_CPU_REFERENCE_WORKERS");
    unsigned long requested = 0ul;
    if (env != nullptr && env[0] != '\0') {
        char *end = nullptr;
        requested = std::strtoul(env, &end, 10);
        if (end == env) {
            requested = 0ul;
        }
    }
    if (requested == 0ul) {
        requested = std::thread::hardware_concurrency();
    }
    if (requested == 0ul) {
        requested = 8ul;
    }
    if (requested > 32ul) {
        requested = 32ul;
    }
    if (requested > selected_token_count) {
        requested = static_cast<unsigned long>(selected_token_count);
    }
    return requested == 0ul ? 1u : static_cast<unsigned int>(requested);
}

bool compute_shared_expert_cpu_reference_range(
    SharedExpertRun *run,
    size_t begin_selected_index,
    size_t end_selected_index,
    std::string *failure
) {
    if (run == nullptr ||
        begin_selected_index > end_selected_index ||
        end_selected_index > run->selected_token_count ||
        run->selected_inputs.size() != run->output_elements ||
        run->routed_inputs.size() != run->output_elements ||
        run->cpu_shared_output.size() != run->output_elements ||
        run->cpu_combined_output.size() != run->output_elements ||
        run->cpu_gate_logits.size() != run->selected_token_count) {
        if (failure != nullptr) {
            *failure = "shared CPU reference input layout is incomplete";
        }
        return false;
    }

    for (size_t selected_index = begin_selected_index;
         selected_index < end_selected_index;
         ++selected_index) {
        const float *input =
            run->selected_inputs.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        const float *routed =
            run->routed_inputs.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float *shared =
            run->cpu_shared_output.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float *combined =
            run->cpu_combined_output.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        if (!qrt_layer0_moe_shared_expert_cpu(
                run->gate_weight.data(),
                run->gate_proj_weight.data(),
                run->up_proj_weight.data(),
                run->down_weight.data(),
                input,
                routed,
                shared,
                combined,
                &run->cpu_gate_logits[selected_index]
            )) {
            if (failure != nullptr) {
                *failure = "CPU shared expert reference produced an invalid value";
            }
            return false;
        }
    }
    return true;
}

bool compute_shared_expert_cpu_shared_only_range(
    SharedExpertRun *run,
    size_t begin_selected_index,
    size_t end_selected_index,
    std::string *failure
) {
    if (run == nullptr ||
        begin_selected_index > end_selected_index ||
        end_selected_index > run->selected_token_count ||
        run->selected_inputs.size() != run->output_elements ||
        run->cpu_shared_output.size() != run->output_elements ||
        run->cpu_gate_logits.size() != run->selected_token_count) {
        if (failure != nullptr) {
            *failure = "shared-only CPU reference input layout is incomplete";
        }
        return false;
    }

    for (size_t selected_index = begin_selected_index;
         selected_index < end_selected_index;
         ++selected_index) {
        const float *input =
            run->selected_inputs.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float *shared =
            run->cpu_shared_output.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float activated[QRT_QWEN36_MOE_EXPERT_INTERMEDIATE];
        float gate_logit = 0.0f;
        for (size_t col = 0u;
             col < static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
             ++col) {
            gate_logit +=
                input[col] * qrt_bf16_to_float(run->gate_weight[col]);
        }
        if (gate_logit != gate_logit) {
            if (failure != nullptr) {
                *failure = "shared-only CPU gate logit produced NaN";
            }
            return false;
        }
        const float scale = 1.0f / (1.0f + expf(-gate_logit));
        if (scale != scale) {
            if (failure != nullptr) {
                *failure = "shared-only CPU gate scale produced NaN";
            }
            return false;
        }

        for (size_t inter = 0u;
             inter < static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE);
             ++inter) {
            float gate = 0.0f;
            float up = 0.0f;
            const uint16_t *gate_row =
                run->gate_proj_weight.data() +
                inter * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
            const uint16_t *up_row =
                run->up_proj_weight.data() +
                inter * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
            for (size_t col = 0u;
                 col < static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
                 ++col) {
                const float input_value = input[col];
                gate += input_value * qrt_bf16_to_float(gate_row[col]);
                up += input_value * qrt_bf16_to_float(up_row[col]);
            }
            if (gate != gate || up != up) {
                if (failure != nullptr) {
                    *failure = "shared-only CPU gate/up projection produced NaN";
                }
                return false;
            }
            activated[inter] = qrt_silu_f32(gate) * up;
            if (activated[inter] != activated[inter]) {
                if (failure != nullptr) {
                    *failure = "shared-only CPU activation produced NaN";
                }
                return false;
            }
        }

        for (size_t row = 0u;
             row < static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
             ++row) {
            float value = 0.0f;
            const uint16_t *down_row =
                run->down_weight.data() +
                row * static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE);
            for (size_t col = 0u;
                 col < static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE);
                 ++col) {
                value += activated[col] * qrt_bf16_to_float(down_row[col]);
            }
            if (value != value) {
                if (failure != nullptr) {
                    *failure = "shared-only CPU down projection produced NaN";
                }
                return false;
            }
            shared[row] = scale * value;
            if (shared[row] != shared[row]) {
                if (failure != nullptr) {
                    *failure = "shared-only CPU output produced NaN";
                }
                return false;
            }
        }
        run->cpu_gate_logits[selected_index] = gate_logit;
    }
    return true;
}

bool compute_shared_expert_cpu_shared_only_parallel(
    SharedExpertRun *run,
    std::string *failure
) {
    if (run == nullptr || run->selected_token_count == 0u) {
        if (failure != nullptr) {
            *failure = "parallel shared-only CPU reference received no selected tokens";
        }
        return false;
    }
    const unsigned int worker_count =
        shared_cpu_reference_worker_count(run->selected_token_count);
    if (worker_count <= 1u) {
        return compute_shared_expert_cpu_shared_only_range(
            run,
            0u,
            run->selected_token_count,
            failure
        );
    }

    std::vector<std::thread> threads;
    std::vector<int> worker_ok(worker_count, 1);
    std::vector<std::string> worker_failure(worker_count);
    threads.reserve(worker_count);
    for (unsigned int worker = 0; worker < worker_count; ++worker) {
        const size_t begin =
            run->selected_token_count * static_cast<size_t>(worker) /
            static_cast<size_t>(worker_count);
        const size_t end =
            run->selected_token_count * static_cast<size_t>(worker + 1u) /
            static_cast<size_t>(worker_count);
        threads.emplace_back([run, begin, end, &worker_ok, &worker_failure, worker]() {
            if (!compute_shared_expert_cpu_shared_only_range(
                    run,
                    begin,
                    end,
                    &worker_failure[worker]
                )) {
                worker_ok[worker] = 0;
            }
        });
    }
    for (std::thread &thread : threads) {
        thread.join();
    }
    for (unsigned int worker = 0; worker < worker_count; ++worker) {
        if (worker_ok[worker] == 0) {
            if (failure != nullptr) {
                *failure = worker_failure[worker].empty()
                    ? "parallel shared-only CPU reference worker failed"
                    : worker_failure[worker];
            }
            return false;
        }
    }
    return true;
}

bool combine_shared_expert_cpu_reference_range(
    SharedExpertRun *run,
    size_t begin_selected_index,
    size_t end_selected_index,
    std::string *failure
) {
    if (run == nullptr ||
        begin_selected_index > end_selected_index ||
        end_selected_index > run->selected_token_count ||
        run->routed_inputs.size() != run->output_elements ||
        run->cpu_shared_output.size() != run->output_elements ||
        run->cpu_combined_output.size() != run->output_elements) {
        if (failure != nullptr) {
            *failure = "shared CPU combine input layout is incomplete";
        }
        return false;
    }

    for (size_t selected_index = begin_selected_index;
         selected_index < end_selected_index;
         ++selected_index) {
        const size_t base =
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        for (size_t row = 0u;
             row < static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
             ++row) {
            const size_t index = base + row;
            const float value =
                run->routed_inputs[index] + run->cpu_shared_output[index];
            if (value != value) {
                if (failure != nullptr) {
                    *failure = "shared CPU combine produced NaN";
                }
                return false;
            }
            run->cpu_combined_output[index] = value;
        }
    }
    return true;
}

