bool finalize_shared_expert_reference_contract(
    SharedExpertRun *run,
    const std::string &run_stage,
    const std::string &failure_message
) {
    const bool cpu_exact_diagnostics_elided =
        run != nullptr &&
        run->cpu_exact_shared_backend &&
        run->cpu_exact_diagnostics_elided;
    if (run == nullptr ||
        run->selected_token_count == 0 ||
        run->output_elements !=
            run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) ||
        run->selected_inputs.size() != run->output_elements ||
        run->routed_inputs.size() != run->output_elements ||
        (!cpu_exact_diagnostics_elided &&
         (run->gpu_shared_output.size() != run->output_elements ||
          run->gpu_combined_output.size() != run->output_elements ||
          run->gpu_gate_logits.size() != run->selected_token_count))) {
        if (run != nullptr) {
            run->failure_stage = "contract_" + run_stage;
            run->failure = failure_message + ": shared expert buffers have unexpected shape";
        }
        return false;
    }

    const bool cpu_shared_only_precomputed =
        run->cpu_exact_shared_backend &&
        run->cpu_shared_only_precomputed &&
        run->cpu_shared_output.size() == run->output_elements &&
        run->cpu_gate_logits.size() == run->selected_token_count;
    if (!cpu_shared_only_precomputed) {
        run->cpu_shared_output.assign(run->output_elements, 0.0f);
        run->cpu_gate_logits.assign(run->selected_token_count, 0.0f);
    }
    run->cpu_combined_output.assign(run->output_elements, 0.0f);
    run->shared_samples.clear();
    run->combined_samples.clear();
    run->gate_samples.clear();
    run->max_abs_diff = -1.0f;
    run->max_shared_abs_diff = -1.0f;
    run->max_combined_abs_diff = -1.0f;
    run->max_gate_abs_diff = -1.0f;
    run->full_max_abs_diff = -1.0f;
    run->full_shared_max_abs_diff = -1.0f;
    run->full_combined_max_abs_diff = -1.0f;
    run->full_gate_max_abs_diff = -1.0f;
    run->checked_values = 0;
    run->checked_shared_values = 0;
    run->checked_combined_values = 0;
    run->checked_gate_values = 0;
    run->full_checked_values = 0;
    run->full_checked_shared_values = 0;
    run->full_checked_combined_values = 0;
    run->full_checked_gate_values = 0;

    const bool cpu_reference_precomputed =
        g_descriptor_product_parallel_shared_cpu_reference ||
        run->cpu_exact_shared_backend;
    if (cpu_reference_precomputed) {
        std::string reference_failure;
        const bool reference_ok = cpu_shared_only_precomputed
            ? combine_shared_expert_cpu_reference_parallel(
                  run,
                  &reference_failure
              )
            : compute_shared_expert_cpu_reference_parallel(
                  run,
                  &reference_failure
              );
        if (!reference_ok) {
            run->failure_stage = "cpu_reference_" + run_stage;
            run->failure = failure_message + ": " +
                (reference_failure.empty()
                     ? "parallel CPU shared expert reference failed"
                     : reference_failure);
            return false;
        }
    }
    if (run->cpu_exact_shared_backend) {
        if (!cpu_exact_diagnostics_elided) {
            run->gpu_shared_output = run->cpu_shared_output;
            run->gpu_combined_output = run->cpu_combined_output;
            run->gpu_gate_logits = run->cpu_gate_logits;
        }

        const std::vector<unsigned int> selected_rows = selected_out_projection_rows();
        std::vector<float> selected_shared_reference;
        std::vector<float> selected_combined_reference;
        std::vector<float> selected_gate_reference;
        selected_shared_reference.reserve(run->selected_token_count * selected_rows.size());
        selected_combined_reference.reserve(run->selected_token_count * selected_rows.size());
        selected_gate_reference.reserve(run->selected_token_count);

        for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            const float gate_value = run->cpu_gate_logits[selected_index];
            run->gate_samples.push_back({token, 0u, gate_value, gate_value, 0.0f});
            selected_gate_reference.push_back(gate_value);

            for (unsigned int row : selected_rows) {
                const size_t output_index =
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
                const float shared_value = run->cpu_shared_output[output_index];
                const float combined_value = run->cpu_combined_output[output_index];
                run->shared_samples.push_back({token, row, shared_value, shared_value, 0.0f});
                run->combined_samples.push_back({token, row, combined_value, combined_value, 0.0f});
                selected_shared_reference.push_back(shared_value);
                selected_combined_reference.push_back(combined_value);
            }
        }

        const size_t selected_sample_count =
            run->selected_token_count * selected_rows.size();
        run->checked_gate_values = static_cast<unsigned int>(run->selected_token_count);
        run->checked_shared_values = static_cast<unsigned int>(selected_sample_count);
        run->checked_combined_values = static_cast<unsigned int>(selected_sample_count);
        run->checked_values =
            run->checked_gate_values +
            run->checked_shared_values +
            run->checked_combined_values;
        run->full_checked_gate_values = run->selected_token_count;
        run->full_checked_shared_values = run->output_elements;
        run->full_checked_combined_values = run->output_elements;
        run->full_checked_values =
            run->full_checked_gate_values +
            run->full_checked_shared_values +
            run->full_checked_combined_values;
        run->max_abs_diff = 0.0f;
        run->max_shared_abs_diff = 0.0f;
        run->max_combined_abs_diff = 0.0f;
        run->max_gate_abs_diff = 0.0f;
        run->full_max_abs_diff = 0.0f;
        run->full_shared_max_abs_diff = 0.0f;
        run->full_combined_max_abs_diff = 0.0f;
        run->full_gate_max_abs_diff = 0.0f;

        run->selected_shared_reference_hash =
            qrt_fnv1a64_f32(selected_shared_reference.data(), selected_shared_reference.size());
        run->selected_shared_gpu_hash = run->selected_shared_reference_hash;
        run->selected_combined_reference_hash =
            qrt_fnv1a64_f32(selected_combined_reference.data(), selected_combined_reference.size());
        run->selected_combined_gpu_hash = run->selected_combined_reference_hash;
        run->selected_gate_reference_hash =
            qrt_fnv1a64_f32(selected_gate_reference.data(), selected_gate_reference.size());
        run->selected_gate_gpu_hash = run->selected_gate_reference_hash;
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        if (cpu_exact_diagnostics_elided) {
            run->post_attention_input_hash = UINT64_C(0);
            run->routed_input_hash = UINT64_C(0);
            run->gate_weight_hash = UINT64_C(0);
            run->gate_proj_weight_hash = UINT64_C(0);
            run->up_proj_weight_hash = UINT64_C(0);
            run->down_weight_hash = UINT64_C(0);
            run->cpu_shared_output_hash = UINT64_C(0);
            run->gpu_shared_output_hash = UINT64_C(0);
            run->cpu_combined_output_hash = UINT64_C(0);
            run->gpu_combined_output_hash = UINT64_C(0);
            run->cpu_gate_logits_hash = UINT64_C(0);
            run->gpu_gate_logits_hash = UINT64_C(0);
            run->cpu_shared_output_bf16_hash = UINT64_C(0);
            run->gpu_shared_output_bf16_hash = UINT64_C(0);
            run->cpu_combined_output_bf16_hash = UINT64_C(0);
            run->gpu_combined_output_bf16_hash = UINT64_C(0);
            run->cpu_gate_logits_bf16_hash = UINT64_C(0);
            run->gpu_gate_logits_bf16_hash = UINT64_C(0);
        } else {
            run->post_attention_input_hash =
                qrt_fnv1a64_f32(run->selected_inputs.data(), run->selected_inputs.size());
            run->routed_input_hash =
                qrt_fnv1a64_f32(run->routed_inputs.data(), run->routed_inputs.size());
            run->gate_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->gate_weight.data(),
                static_cast<size_t>(run->gate_weight_bytes)
            );
            run->gate_proj_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->gate_proj_weight.data(),
                static_cast<size_t>(run->gate_proj_weight_bytes)
            );
            run->up_proj_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->up_proj_weight.data(),
                static_cast<size_t>(run->up_proj_weight_bytes)
            );
            run->down_weight_hash = qrt_fnv1a64_update_bytes(
                UINT64_C(1469598103934665603),
                run->down_weight.data(),
                static_cast<size_t>(run->down_weight_bytes)
            );
            run->cpu_shared_output_hash =
                qrt_fnv1a64_f32(run->cpu_shared_output.data(), run->cpu_shared_output.size());
            run->gpu_shared_output_hash = run->cpu_shared_output_hash;
            run->cpu_combined_output_hash =
                qrt_fnv1a64_f32(run->cpu_combined_output.data(), run->cpu_combined_output.size());
            run->gpu_combined_output_hash = run->cpu_combined_output_hash;
            run->cpu_gate_logits_hash =
                qrt_fnv1a64_f32(run->cpu_gate_logits.data(), run->cpu_gate_logits.size());
            run->gpu_gate_logits_hash = run->cpu_gate_logits_hash;
            run->cpu_shared_output_bf16_hash =
                qrt_fnv1a64_f32_bf16_round(run->cpu_shared_output.data(), run->cpu_shared_output.size());
            run->gpu_shared_output_bf16_hash = run->cpu_shared_output_bf16_hash;
            run->cpu_combined_output_bf16_hash =
                qrt_fnv1a64_f32_bf16_round(run->cpu_combined_output.data(), run->cpu_combined_output.size());
            run->gpu_combined_output_bf16_hash = run->cpu_combined_output_bf16_hash;
            run->cpu_gate_logits_bf16_hash =
                qrt_fnv1a64_f32_bf16_round(run->cpu_gate_logits.data(), run->cpu_gate_logits.size());
            run->gpu_gate_logits_bf16_hash = run->cpu_gate_logits_bf16_hash;
        }

        run->correctness_pass =
            run->checked_values > 0 &&
            run->full_checked_shared_values == run->output_elements &&
            run->full_checked_combined_values == run->output_elements &&
            run->full_checked_gate_values == run->selected_token_count &&
            run->full_checked_values ==
                run->full_checked_shared_values +
                run->full_checked_combined_values +
                run->full_checked_gate_values &&
            std::isfinite(run->max_abs_diff) &&
            std::isfinite(run->max_shared_abs_diff) &&
            std::isfinite(run->max_combined_abs_diff) &&
            std::isfinite(run->max_gate_abs_diff) &&
            std::isfinite(run->full_max_abs_diff) &&
            std::isfinite(run->full_shared_max_abs_diff) &&
            std::isfinite(run->full_combined_max_abs_diff) &&
            std::isfinite(run->full_gate_max_abs_diff) &&
            run->full_max_abs_diff <= kTolerance &&
            run->full_shared_max_abs_diff <= kTolerance &&
            run->full_combined_max_abs_diff <= kTolerance &&
            run->full_gate_max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_" + run_stage;
            run->failure = failure_message + ": CPU-exact shared expert boundary exceeded tolerance";
        }
        return run->correctness_pass;
    }

    std::vector<float> selected_shared_reference;
    std::vector<float> selected_shared_gpu;
    std::vector<float> selected_combined_reference;
    std::vector<float> selected_combined_gpu;
    std::vector<float> selected_gate_reference;
    std::vector<float> selected_gate_gpu;
    auto update_sample_max = [](float diff, float *max_value, unsigned int *count) {
        if (*count == 0 || diff > *max_value) {
            *max_value = diff;
        }
        ++(*count);
    };
    auto update_full_max = [](float diff, float *max_value, size_t *count) {
        if (*count == 0 || diff > *max_value) {
            *max_value = diff;
        }
        ++(*count);
    };
    auto update_overall = [&](float diff) {
        if (run->full_checked_values == 0 || diff > run->full_max_abs_diff) {
            run->full_max_abs_diff = diff;
        }
        ++run->full_checked_values;
    };

    for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
        const float *input =
            run->selected_inputs.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        const float *routed =
            run->routed_inputs.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float *shared =
            run->cpu_shared_output.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        float *combined =
            run->cpu_combined_output.data() +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
        if (!cpu_reference_precomputed &&
            !qrt_layer0_moe_shared_expert_cpu(
                 run->gate_weight.data(),
                 run->gate_proj_weight.data(),
                 run->up_proj_weight.data(),
                 run->down_weight.data(),
                 input,
                 routed,
                 shared,
                 combined,
                 &run->cpu_gate_logits[selected_index]
             )) {
            run->failure_stage = "cpu_reference_" + run_stage;
            run->failure = failure_message + ": CPU shared expert reference produced an invalid value";
            return false;
        }

        const unsigned int token = run->selected_token_ids[selected_index];
        const float gate_ref = run->cpu_gate_logits[selected_index];
        const float gate_gpu = run->gpu_gate_logits[selected_index];
        const float gate_diff = std::fabs(gate_ref - gate_gpu);
        run->gate_samples.push_back({token, 0u, gate_ref, gate_gpu, gate_diff});
        selected_gate_reference.push_back(gate_ref);
        selected_gate_gpu.push_back(gate_gpu);
        update_sample_max(gate_diff, &run->max_gate_abs_diff, &run->checked_gate_values);
        if (run->checked_values == 0 || gate_diff > run->max_abs_diff) {
            run->max_abs_diff = gate_diff;
        }
        ++run->checked_values;
        update_full_max(gate_diff, &run->full_gate_max_abs_diff, &run->full_checked_gate_values);
        update_overall(gate_diff);

        for (unsigned int row = 0; row < QRT_QWEN36_HIDDEN_SIZE; ++row) {
            const size_t output_index =
                selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
            const float shared_ref = run->cpu_shared_output[output_index];
            const float shared_gpu = run->gpu_shared_output[output_index];
            const float shared_diff = std::fabs(shared_ref - shared_gpu);
            const float combined_ref = run->cpu_combined_output[output_index];
            const float combined_gpu = run->gpu_combined_output[output_index];
            const float combined_diff = std::fabs(combined_ref - combined_gpu);
            update_full_max(shared_diff,
                            &run->full_shared_max_abs_diff,
                            &run->full_checked_shared_values);
            update_full_max(combined_diff,
                            &run->full_combined_max_abs_diff,
                            &run->full_checked_combined_values);
            update_overall(shared_diff);
            update_overall(combined_diff);
        }

        for (unsigned int row : selected_out_projection_rows()) {
            const size_t output_index =
                selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
            const float shared_ref = run->cpu_shared_output[output_index];
            const float shared_gpu = run->gpu_shared_output[output_index];
            const float shared_diff = std::fabs(shared_ref - shared_gpu);
            const float combined_ref = run->cpu_combined_output[output_index];
            const float combined_gpu = run->gpu_combined_output[output_index];
            const float combined_diff = std::fabs(combined_ref - combined_gpu);
            run->shared_samples.push_back({token, row, shared_ref, shared_gpu, shared_diff});
            run->combined_samples.push_back({token, row, combined_ref, combined_gpu, combined_diff});
            selected_shared_reference.push_back(shared_ref);
            selected_shared_gpu.push_back(shared_gpu);
            selected_combined_reference.push_back(combined_ref);
            selected_combined_gpu.push_back(combined_gpu);
            update_sample_max(shared_diff, &run->max_shared_abs_diff, &run->checked_shared_values);
            update_sample_max(combined_diff, &run->max_combined_abs_diff, &run->checked_combined_values);
            if (run->checked_values == 0 || shared_diff > run->max_abs_diff) {
                run->max_abs_diff = shared_diff;
            }
            ++run->checked_values;
            if (combined_diff > run->max_abs_diff) {
                run->max_abs_diff = combined_diff;
            }
            ++run->checked_values;
        }
    }

    run->selected_shared_reference_hash =
        qrt_fnv1a64_f32(selected_shared_reference.data(), selected_shared_reference.size());
    run->selected_shared_gpu_hash =
        qrt_fnv1a64_f32(selected_shared_gpu.data(), selected_shared_gpu.size());
    run->selected_combined_reference_hash =
        qrt_fnv1a64_f32(selected_combined_reference.data(), selected_combined_reference.size());
    run->selected_combined_gpu_hash =
        qrt_fnv1a64_f32(selected_combined_gpu.data(), selected_combined_gpu.size());
    run->selected_gate_reference_hash =
        qrt_fnv1a64_f32(selected_gate_reference.data(), selected_gate_reference.size());
    run->selected_gate_gpu_hash =
        qrt_fnv1a64_f32(selected_gate_gpu.data(), selected_gate_gpu.size());
    run->selected_token_ids_hash = qrt_fnv1a64_bytes(
        run->selected_token_ids.data(),
        run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
    );
    run->post_attention_input_hash =
        qrt_fnv1a64_f32(run->selected_inputs.data(), run->selected_inputs.size());
    run->routed_input_hash =
        qrt_fnv1a64_f32(run->routed_inputs.data(), run->routed_inputs.size());
    run->gate_weight_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->gate_weight.data(),
        static_cast<size_t>(run->gate_weight_bytes)
    );
    run->gate_proj_weight_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->gate_proj_weight.data(),
        static_cast<size_t>(run->gate_proj_weight_bytes)
    );
    run->up_proj_weight_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->up_proj_weight.data(),
        static_cast<size_t>(run->up_proj_weight_bytes)
    );
    run->down_weight_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->down_weight.data(),
        static_cast<size_t>(run->down_weight_bytes)
    );
    run->gpu_shared_output_hash =
        qrt_fnv1a64_f32(run->gpu_shared_output.data(), run->gpu_shared_output.size());
    run->gpu_combined_output_hash =
        qrt_fnv1a64_f32(run->gpu_combined_output.data(), run->gpu_combined_output.size());
    run->gpu_gate_logits_hash =
        qrt_fnv1a64_f32(run->gpu_gate_logits.data(), run->gpu_gate_logits.size());
    run->cpu_shared_output_hash =
        qrt_fnv1a64_f32(run->cpu_shared_output.data(), run->cpu_shared_output.size());
    run->cpu_combined_output_hash =
        qrt_fnv1a64_f32(run->cpu_combined_output.data(), run->cpu_combined_output.size());
    run->cpu_gate_logits_hash =
        qrt_fnv1a64_f32(run->cpu_gate_logits.data(), run->cpu_gate_logits.size());
    run->gpu_shared_output_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->gpu_shared_output.data(), run->gpu_shared_output.size());
    run->cpu_shared_output_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->cpu_shared_output.data(), run->cpu_shared_output.size());
    run->gpu_combined_output_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->gpu_combined_output.data(), run->gpu_combined_output.size());
    run->cpu_combined_output_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->cpu_combined_output.data(), run->cpu_combined_output.size());
    run->gpu_gate_logits_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->gpu_gate_logits.data(), run->gpu_gate_logits.size());
    run->cpu_gate_logits_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(run->cpu_gate_logits.data(), run->cpu_gate_logits.size());
    run->correctness_pass =
        run->checked_values > 0 &&
        run->full_checked_shared_values == run->output_elements &&
        run->full_checked_combined_values == run->output_elements &&
        run->full_checked_gate_values == run->selected_token_count &&
        run->full_checked_values ==
            run->full_checked_shared_values +
            run->full_checked_combined_values +
            run->full_checked_gate_values &&
        std::isfinite(run->max_abs_diff) &&
        std::isfinite(run->max_shared_abs_diff) &&
        std::isfinite(run->max_combined_abs_diff) &&
        std::isfinite(run->max_gate_abs_diff) &&
        std::isfinite(run->full_max_abs_diff) &&
        std::isfinite(run->full_shared_max_abs_diff) &&
        std::isfinite(run->full_combined_max_abs_diff) &&
        std::isfinite(run->full_gate_max_abs_diff) &&
        run->full_max_abs_diff <= kTolerance &&
        run->full_shared_max_abs_diff <= kTolerance &&
        run->full_combined_max_abs_diff <= kTolerance &&
        run->full_gate_max_abs_diff <= kTolerance;
    if (!run->correctness_pass) {
        run->failure_stage = "correctness_" + run_stage;
        run->failure = failure_message + ": full CPU/HIP shared expert boundary exceeded tolerance";
    }
    return run->correctness_pass;
}

float canonicalize_combined_moe_handoff_value(float value) {
    return g_descriptor_product_combined_moe_bf16_handoff
        ? bf16_round_to_float(value)
        : value;
}

float canonicalize_routed_output_gpu_f32_grid_value(float value) {
    constexpr float kGridScale = 262144.0f;
    if (!std::isfinite(value)) {
        return value;
    }
    return std::round(value * kGridScale) / kGridScale;
}

void materialize_combined_moe_handoff(SharedExpertRun *run) {
    if (run == nullptr) {
        return;
    }
    run->combined_moe_handoff_output.clear();
    run->combined_moe_handoff_canonicalized = false;
    if (!g_descriptor_product_combined_moe_bf16_handoff ||
        run->cpu_combined_output.size() != run->output_elements) {
        return;
    }
    run->combined_moe_handoff_output.resize(run->cpu_combined_output.size());
    for (size_t index = 0; index < run->cpu_combined_output.size(); ++index) {
        run->combined_moe_handoff_output[index] =
            canonicalize_combined_moe_handoff_value(run->cpu_combined_output[index]);
    }
    run->combined_moe_handoff_canonicalized = true;
}

void materialize_routed_output_handoff(RoutedExpertRun *run) {
    if (run == nullptr) {
        return;
    }
    run->routed_output_handoff.clear();
    run->routed_output_handoff_canonicalized = false;
    run->routed_output_handoff_full_max_abs_diff = -1.0f;
    run->routed_output_handoff_full_checked_values = 0;
    run->routed_output_handoff_hash = 0;
    run->routed_output_handoff_bf16_hash = 0;
    if ((!g_descriptor_product_routed_output_cpu_bf16_handoff &&
         !g_descriptor_product_routed_output_gpu_f32_grid_handoff) ||
        run->cpu_output.size() != run->output_elements ||
        run->output_elements == 0u) {
        return;
    }
    const bool use_cpu_bf16 = g_descriptor_product_routed_output_cpu_bf16_handoff;
    const std::vector<float> &source = use_cpu_bf16 ? run->cpu_output : run->gpu_output;
    if (source.size() != run->output_elements) {
        return;
    }
    run->routed_output_handoff.resize(source.size());
    for (size_t index = 0; index < source.size(); ++index) {
        const float canonical =
            use_cpu_bf16
                ? bf16_round_to_float(source[index])
                : canonicalize_routed_output_gpu_f32_grid_value(source[index]);
        run->routed_output_handoff[index] = canonical;
        const float diff = std::fabs(run->cpu_output[index] - canonical);
        if (run->routed_output_handoff_full_checked_values == 0u ||
            diff > run->routed_output_handoff_full_max_abs_diff) {
            run->routed_output_handoff_full_max_abs_diff = diff;
        }
        ++run->routed_output_handoff_full_checked_values;
    }
    run->routed_output_handoff_hash =
        qrt_fnv1a64_f32(run->routed_output_handoff.data(), run->routed_output_handoff.size());
    run->routed_output_handoff_bf16_hash =
        qrt_fnv1a64_f32_bf16_round(
            run->routed_output_handoff.data(),
            run->routed_output_handoff.size()
        );
    run->routed_output_handoff_canonicalized = true;
}

const std::vector<float> &routed_expert_effective_output_handoff(
    const RoutedExpertRun &run,
    size_t output_elements
) {
    if (run.routed_output_handoff.size() == output_elements) {
        return run.routed_output_handoff;
    }
    if (run.trusted_gpu_handoff_without_cpu_reference &&
        run.gpu_output.size() == output_elements) {
        return run.gpu_output;
    }
    if (run.correctness_pass &&
        run.gpu_output.size() == output_elements &&
        run.gpu_output_hash != UINT64_C(0) &&
        run.gpu_output_hash == run.cpu_output_hash &&
        run.gpu_output_bf16_hash == run.cpu_output_bf16_hash) {
        return run.gpu_output;
    }
    if (g_descriptor_product_combined_moe_bf16_handoff) {
        return run.gpu_output;
    }
    if (run.cpu_output.size() == output_elements) {
        return run.cpu_output;
    }
    return run.gpu_output;
}

const std::vector<float> &shared_expert_combined_moe_handoff(
    const SharedExpertRun &run,
    size_t output_elements
) {
    if (run.combined_moe_handoff_output.size() == output_elements) {
        return run.combined_moe_handoff_output;
    }
    if (run.cpu_combined_output.size() == output_elements) {
        return run.cpu_combined_output;
    }
    return run.gpu_combined_output;
}

bool store_exact_device_combined_moe_handoff(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    SharedExpertRun *run
) {
    if (!descriptor_product_exact_device_combined_moe_handoff_enabled(
            layer_index,
            prefill_tokens
        )) {
        return true;
    }
    const std::string layer_label =
        std::string("layer-") + std::to_string(layer_index);
    if (run == nullptr ||
        !run->correctness_pass ||
        run->selected_token_count == 0u ||
        run->output_elements == 0u ||
        run->combined_output_bytes == 0u) {
        if (run != nullptr) {
            run->failure_stage =
                run->name + "_exact_device_combined_moe_handoff_contract";
            run->failure =
                layer_label +
                " exact device combined-MoE handoff requires a closed CPU-exact shared contract";
        }
        return false;
    }
    const std::vector<float> &combined_moe_input =
        shared_expert_combined_moe_handoff(*run, run->output_elements);
    if (combined_moe_input.size() != run->output_elements) {
        run->failure_stage =
            run->name + "_exact_device_combined_moe_handoff_shape";
        run->failure =
            layer_label +
            " exact device combined-MoE handoff source has unexpected shape";
        return false;
    }

    uint64_t selected_token_ids_hash = run->selected_token_ids_hash;
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
    }
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        run->failure_stage =
            run->name + "_exact_device_combined_moe_handoff_token_hash";
        run->failure =
            layer_label +
            " exact device combined-MoE handoff could not identify selected tokens";
        return false;
    }

    float *device_combined_moe = nullptr;
    if (!check_hip(
            hipMalloc(
                reinterpret_cast<void **>(&device_combined_moe),
                run->combined_output_bytes
            ),
            "hipMalloc(exact_device_combined_moe_handoff)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMemcpy(
                device_combined_moe,
                combined_moe_input.data(),
                run->combined_output_bytes,
                hipMemcpyHostToDevice
            ),
            "hipMemcpy(exact_device_combined_moe_handoff)",
            &run->failure_stage,
            &run->failure
        )) {
        free_device(device_combined_moe);
        return false;
    }

    store_descriptor_decode_combined_moe_device_handoff(
        layer_index,
        selected_token_ids_hash,
        run->combined_output_bytes,
        &device_combined_moe
    );
    std::cerr << "BATCH_MARK descriptor_exact_device_combined_moe_handoff_store"
              << " layer=" << layer_index
              << " selected_tokens=" << run->selected_token_count
              << " output_bytes=" << run->combined_output_bytes
              << " selected_token_ids_hash=" << hex_u64(selected_token_ids_hash)
              << " cpu_exact_shared="
              << (run->cpu_exact_shared_backend ? 1 : 0)
              << " canonicalized="
              << (run->combined_moe_handoff_canonicalized ? 1 : 0)
              << std::endl;
    return true;
}

bool store_exact_device_combined_moe_handoff_from_routed_device(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    const RoutedExpertRun &routed_expert_run,
    SharedExpertRun *run
) {
    if (!descriptor_product_exact_device_combined_moe_from_routed_handoff_enabled(
            layer_index,
            prefill_tokens
        )) {
        return true;
    }
    const std::string layer_label =
        std::string("layer-") + std::to_string(layer_index);
    if (run == nullptr ||
        !run->cpu_exact_shared_backend ||
        !run->cpu_shared_only_precomputed ||
        !routed_expert_run.correctness_pass ||
        routed_expert_run.selected_token_ids != run->selected_token_ids ||
        run->selected_token_count == 0u ||
        run->output_elements == 0u ||
        run->combined_output_bytes == 0u ||
        run->cpu_shared_output.size() != run->output_elements) {
        if (run != nullptr) {
            run->failure_stage =
                run->name + "_exact_device_combined_moe_routed_handoff_contract";
            run->failure =
                layer_label +
                " exact routed-device combined-MoE handoff requires closed routed and CPU-shared inputs";
        }
        return false;
    }

    uint64_t selected_token_ids_hash = run->selected_token_ids_hash;
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        selected_token_ids_hash = routed_expert_run.selected_token_ids_hash;
    }
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
    }
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        run->failure_stage =
            run->name + "_exact_device_combined_moe_routed_handoff_token_hash";
        run->failure =
            layer_label +
            " exact routed-device combined-MoE handoff could not identify selected tokens";
        return false;
    }

    float *device_routed = nullptr;
    float *device_shared = nullptr;
    float *device_combined = nullptr;
    const uint64_t start_ns = qrt_now_ns();
    bool ok = false;

    if (!take_descriptor_decode_routed_device_handoff(
            layer_index,
            selected_token_ids_hash,
            run->combined_output_bytes,
            &device_routed
        )) {
        run->failure_stage =
            run->name + "_exact_device_combined_moe_routed_handoff_miss";
        run->failure =
            layer_label +
            " exact routed-device combined-MoE handoff did not receive the routed device output";
        goto cleanup;
    }
    if (!check_hip(
            hipMalloc(
                reinterpret_cast<void **>(&device_shared),
                run->combined_output_bytes
            ),
            "hipMalloc(exact_device_combined_moe_shared_from_routed)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMalloc(
                reinterpret_cast<void **>(&device_combined),
                run->combined_output_bytes
            ),
            "hipMalloc(exact_device_combined_moe_output_from_routed)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMemcpy(
                device_shared,
                run->cpu_shared_output.data(),
                run->combined_output_bytes,
                hipMemcpyHostToDevice
            ),
            "hipMemcpy(exact_device_combined_moe_shared_from_routed)",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    {
        const dim3 block(kThreads);
        const dim3 grid(
            static_cast<unsigned int>(
                (run->output_elements + kThreads - 1u) / kThreads
            )
        );
        hipLaunchKernelGGL(
            output_residual_add_kernel,
            grid,
            block,
            0,
            0,
            device_routed,
            device_shared,
            device_combined,
            static_cast<unsigned int>(run->selected_token_count)
        );
    }
    if (!check_hip(
            hipGetLastError(),
            "kernel_launch_exact_device_combined_moe_from_routed",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipDeviceSynchronize(),
            "sync_exact_device_combined_moe_from_routed",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    store_descriptor_decode_combined_moe_device_handoff(
        layer_index,
        selected_token_ids_hash,
        run->combined_output_bytes,
        &device_combined
    );
    run->exact_device_combined_moe_from_routed_handoff = true;
    run->exact_device_combined_moe_from_routed_handoff_elapsed_ms =
        static_cast<double>(qrt_elapsed_ns(start_ns, qrt_now_ns())) /
        1000000.0;
    std::cerr
        << "BATCH_MARK descriptor_exact_device_combined_moe_from_routed_handoff_store"
        << " layer=" << layer_index
        << " selected_tokens=" << run->selected_token_count
        << " output_bytes=" << run->combined_output_bytes
        << " selected_token_ids_hash=" << hex_u64(selected_token_ids_hash)
        << " h2d_shared_bytes=" << run->combined_output_bytes
        << " elapsed_ms="
        << run->exact_device_combined_moe_from_routed_handoff_elapsed_ms
        << std::endl;
    ok = true;

cleanup:
    free_device(device_combined);
    free_device(device_shared);
    free_device(device_routed);
    return ok;
}

bool shared_device_exact_combined_moe_boundary_closed(
    const SharedExpertRun &run
) {
    return run.correctness_pass &&
        run.full_checked_shared_values == run.output_elements &&
        run.full_checked_combined_values == run.output_elements &&
        run.full_checked_gate_values == run.selected_token_count &&
        run.full_max_abs_diff == 0.0f &&
        run.full_shared_max_abs_diff == 0.0f &&
        run.full_combined_max_abs_diff == 0.0f &&
        run.full_gate_max_abs_diff == 0.0f &&
        run.gpu_shared_output_hash == run.cpu_shared_output_hash &&
        run.gpu_combined_output_hash == run.cpu_combined_output_hash &&
        run.gpu_gate_logits_hash == run.cpu_gate_logits_hash &&
        run.gpu_shared_output_bf16_hash == run.cpu_shared_output_bf16_hash &&
        run.gpu_combined_output_bf16_hash ==
            run.cpu_combined_output_bf16_hash &&
        run.gpu_gate_logits_bf16_hash == run.cpu_gate_logits_bf16_hash;
}

bool store_exact_device_combined_moe_handoff_from_shared_device_boundary(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    float *device_routed,
    float **device_combined,
    SharedExpertRun *run
) {
    if (!descriptor_product_exact_device_combined_moe_handoff_enabled(
            layer_index,
            prefill_tokens
        )) {
        return true;
    }
    const std::string layer_label =
        std::string("layer-") + std::to_string(layer_index);
    if (run == nullptr ||
        !run->correctness_pass ||
        run->selected_token_count == 0u ||
        run->output_elements == 0u ||
        run->combined_output_bytes == 0u) {
        if (run != nullptr) {
            run->failure_stage =
                run->name + "_shared_device_combined_moe_handoff_contract";
            run->failure =
                layer_label +
                " shared-device combined-MoE handoff requires a closed shared expert contract";
        }
        return false;
    }

    uint64_t selected_token_ids_hash = run->selected_token_ids_hash;
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
    }
    if (selected_token_ids_hash == UINT64_C(0) ||
        selected_token_ids_hash == UINT64_C(1469598103934665603)) {
        run->failure_stage =
            run->name + "_shared_device_combined_moe_handoff_token_hash";
        run->failure =
            layer_label +
            " shared-device combined-MoE handoff could not identify selected tokens";
        return false;
    }

    const bool use_shared_device_exact_combined_backend =
        descriptor_product_shared_device_exact_combined_moe_backend_enabled(
            layer_index,
            prefill_tokens
        ) &&
        shared_device_exact_combined_moe_boundary_closed(*run);
    if (descriptor_product_exact_device_combined_moe_from_routed_handoff_requested(
            layer_index,
            prefill_tokens
        ) &&
        !use_shared_device_exact_combined_backend &&
        device_routed != nullptr &&
        run->cpu_shared_output.size() == run->output_elements) {
        float *device_shared_reference = nullptr;
        float *device_exact_combined = nullptr;
        const uint64_t start_ns = qrt_now_ns();
        bool ok = false;
        if (!check_hip(
                hipMalloc(
                    reinterpret_cast<void **>(&device_shared_reference),
                    run->combined_output_bytes
                ),
                "hipMalloc(shared_device_combined_moe_shared_reference)",
                &run->failure_stage,
                &run->failure
            ) ||
            !check_hip(
                hipMalloc(
                    reinterpret_cast<void **>(&device_exact_combined),
                    run->combined_output_bytes
                ),
                "hipMalloc(shared_device_combined_moe_exact_output)",
                &run->failure_stage,
                &run->failure
            ) ||
            !check_hip(
                hipMemcpy(
                    device_shared_reference,
                    run->cpu_shared_output.data(),
                    run->combined_output_bytes,
                    hipMemcpyHostToDevice
                ),
                "hipMemcpy(shared_device_combined_moe_shared_reference)",
                &run->failure_stage,
                &run->failure
            )) {
            goto routed_cleanup;
        }

        {
            const dim3 block(kThreads);
            const dim3 grid(
                static_cast<unsigned int>(
                    (run->output_elements + kThreads - 1u) / kThreads
                )
            );
            hipLaunchKernelGGL(
                output_residual_add_kernel,
                grid,
                block,
                0,
                0,
                device_routed,
                device_shared_reference,
                device_exact_combined,
                static_cast<unsigned int>(run->selected_token_count)
            );
        }
        if (!check_hip(
                hipGetLastError(),
                "kernel_launch_shared_device_combined_moe_from_routed",
                &run->failure_stage,
                &run->failure
            ) ||
            !check_hip(
                hipDeviceSynchronize(),
                "sync_shared_device_combined_moe_from_routed",
                &run->failure_stage,
                &run->failure
            )) {
            goto routed_cleanup;
        }

        store_descriptor_decode_combined_moe_device_handoff(
            layer_index,
            selected_token_ids_hash,
            run->combined_output_bytes,
            &device_exact_combined
        );
        run->exact_device_combined_moe_from_routed_handoff = true;
        run->exact_device_combined_moe_from_routed_handoff_elapsed_ms =
            static_cast<double>(qrt_elapsed_ns(start_ns, qrt_now_ns())) /
            1000000.0;
        std::cerr
            << "BATCH_MARK descriptor_exact_device_combined_moe_from_routed_handoff_store"
            << " layer=" << layer_index
            << " selected_tokens=" << run->selected_token_count
            << " output_bytes=" << run->combined_output_bytes
            << " selected_token_ids_hash=" << hex_u64(selected_token_ids_hash)
            << " h2d_shared_bytes=" << run->combined_output_bytes
            << " source=shared_device_boundary"
            << " elapsed_ms="
            << run->exact_device_combined_moe_from_routed_handoff_elapsed_ms
            << std::endl;
        ok = true;

routed_cleanup:
        free_device(device_exact_combined);
        free_device(device_shared_reference);
        return ok;
    }

    if (device_combined == nullptr || *device_combined == nullptr) {
        run->failure_stage =
            run->name + "_shared_device_combined_moe_handoff_device_output";
        run->failure =
            layer_label +
            " shared-device combined-MoE handoff did not retain the device output";
        return false;
    }
    store_descriptor_decode_combined_moe_device_handoff(
        layer_index,
        selected_token_ids_hash,
        run->combined_output_bytes,
        device_combined
    );
    std::cerr << "BATCH_MARK descriptor_exact_device_combined_moe_handoff_store"
              << " layer=" << layer_index
              << " selected_tokens=" << run->selected_token_count
              << " output_bytes=" << run->combined_output_bytes
              << " selected_token_ids_hash=" << hex_u64(selected_token_ids_hash)
              << " cpu_exact_shared=0"
              << " canonicalized=0"
              << " source=shared_device_boundary"
              << " shared_device_exact_combined_backend="
              << (use_shared_device_exact_combined_backend ? 1 : 0)
              << std::endl;
    return true;
}

bool precompute_repeated_cpu_exact_shared_expert(
    unsigned int layer_index,
    const char *name,
    const char *stage,
    const Layer1PostAttentionRmsnormWindowRun &post_attention_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    SharedExpertRun *run
) {
    const std::string run_name = name ? name : "shared_expert";
    const std::string run_stage = stage ? stage : "selected_shared_expert_prefill_phase";
    const std::string layer_label = std::string("layer-") + std::to_string(layer_index);
    run->name = run_name;
    run->stage = run_stage;
    run->cpu_exact_shared_backend = true;
    run->cpu_shared_only_precomputed = false;
    run->cpu_shared_precompute_elapsed_ms = 0.0;

    const uint64_t gate_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_GATE_BYTES);
    const uint64_t proj_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_PROJ_BYTES);
    const uint64_t down_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_DOWN_BYTES);

    if (!descriptor_product_async_cpu_exact_shared_enabled(
            layer_index,
            prefill_tokens
        )) {
        run->failure_stage = run_name + "_async_cpu_exact_shared_disabled";
        run->failure =
            "async CPU-exact shared expert is not enabled for " + layer_label;
        return false;
    }
    const size_t expected_post_attention_elements =
        post_attention_run.target_token_ids.size() *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const bool post_attention_host_available =
        post_attention_run.gpu_output.size() == expected_post_attention_elements;
    const bool post_attention_source_layout_available =
        descriptor_product_resident_layer_stack_source_layout_enabled(
            layer_index,
            prefill_tokens
        ) &&
        post_attention_run.output_elements == expected_post_attention_elements &&
        post_attention_run.output_bytes ==
            expected_post_attention_elements * sizeof(float);
    const bool post_attention_source_layout_device_only =
        post_attention_source_layout_available &&
        post_attention_run.gpu_output.empty() &&
        !post_attention_host_available;

    if (!post_attention_run.correctness_pass ||
        post_attention_run.target_token_ids.empty() ||
        (!post_attention_host_available &&
         !post_attention_source_layout_device_only)) {
        run->failure_stage = run_name + "_precompute_input_contract";
        run->failure =
            "selected " + layer_label + " post-attention RMSNorm is missing or has unexpected shape";
        return false;
    }

    run->selected_token_ids = post_attention_run.target_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements =
        run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->shared_output_bytes = run->output_elements * sizeof(float);
    run->combined_output_bytes = run->output_elements * sizeof(float);
    run->gate_logits_bytes = run->selected_token_count * sizeof(float);
    run->output_bytes =
        run->shared_output_bytes +
        run->combined_output_bytes +
        run->gate_logits_bytes;
    run->gate_weight_bytes = gate_bytes;
    run->gate_proj_weight_bytes = proj_bytes;
    run->up_proj_weight_bytes = proj_bytes;
    run->down_weight_bytes = down_bytes;
    run->down_weight_row_pair_bytes = 0u;
    run->weight_bytes =
        run->gate_weight_bytes +
        run->gate_proj_weight_bytes +
        run->up_proj_weight_bytes +
        run->down_weight_bytes;
    run->cpu_exact_diagnostics_elided =
        descriptor_product_cpu_exact_shared_diagnostic_elision_enabled(
            layer_index,
            prefill_tokens
        );

    if (!tensor_name_for_layer_kind(
            layer_index,
            QRT_QWEN36_TENSOR_MOE_SHARED_GATE,
            &run->gate_tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_gate_" + run_stage;
        return false;
    }
    if (!tensor_name_for_layer_kind(
            layer_index,
            QRT_QWEN36_TENSOR_MOE_SHARED_GATE_PROJ,
            &run->gate_proj_tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_gate_proj_" + run_stage;
        return false;
    }
    if (!tensor_name_for_layer_kind(
            layer_index,
            QRT_QWEN36_TENSOR_MOE_SHARED_UP_PROJ,
            &run->up_proj_tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_up_proj_" + run_stage;
        return false;
    }
    if (!tensor_name_for_layer_kind(
            layer_index,
            QRT_QWEN36_TENSOR_MOE_SHARED_DOWN,
            &run->down_tensor_name,
            &run->failure
        )) {
        run->failure_stage = "tensor_name_down_" + run_stage;
        return false;
    }
    if (!locate_tensor(model_dir, run->gate_tensor_name, &run->gate_location, &run->failure)) {
        run->failure_stage = "locate_gate_" + run_stage;
        return false;
    }
    if (!locate_tensor(model_dir, run->gate_proj_tensor_name, &run->gate_proj_location, &run->failure)) {
        run->failure_stage = "locate_gate_proj_" + run_stage;
        return false;
    }
    if (!locate_tensor(model_dir, run->up_proj_tensor_name, &run->up_proj_location, &run->failure)) {
        run->failure_stage = "locate_up_proj_" + run_stage;
        return false;
    }
    if (!locate_tensor(model_dir, run->down_tensor_name, &run->down_location, &run->failure)) {
        run->failure_stage = "locate_down_" + run_stage;
        return false;
    }
    if (run->gate_location.data_end < run->gate_location.data_begin ||
        run->gate_location.data_end - run->gate_location.data_begin != gate_bytes ||
        run->gate_proj_location.data_end < run->gate_proj_location.data_begin ||
        run->gate_proj_location.data_end - run->gate_proj_location.data_begin != proj_bytes ||
        run->up_proj_location.data_end < run->up_proj_location.data_begin ||
        run->up_proj_location.data_end - run->up_proj_location.data_begin != proj_bytes ||
        run->down_location.data_end < run->down_location.data_begin ||
        run->down_location.data_end - run->down_location.data_begin != down_bytes) {
        run->failure_stage = "shape_" + run_stage;
        run->failure =
            layer_label + " shared expert tensors do not match expected byte shape";
        return false;
    }

    if (!read_safetensors_bytes(model_dir, run->gate_location, 0, gate_bytes, &run->gate_weight, &run->failure)) {
        run->failure_stage = "read_gate_" + run_stage;
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->gate_proj_location, 0, proj_bytes, &run->gate_proj_weight, &run->failure)) {
        run->failure_stage = "read_gate_proj_" + run_stage;
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->up_proj_location, 0, proj_bytes, &run->up_proj_weight, &run->failure)) {
        run->failure_stage = "read_up_proj_" + run_stage;
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->down_location, 0, down_bytes, &run->down_weight, &run->failure)) {
        run->failure_stage = "read_down_" + run_stage;
        return false;
    }

    run->selected_inputs.assign(run->output_elements, 0.0f);
    if (post_attention_source_layout_device_only) {
        const uint64_t post_attention_token_ids_hash = token_ids_hash_or_compute(
            post_attention_run.target_token_ids_hash,
            post_attention_run.target_token_ids
        );
        float *device_post_attention = nullptr;
        if (!borrow_descriptor_resident_layer_stack_surface(
                DescriptorResidentLayerSurfaceKind::kPostAttention,
                layer_index,
                post_attention_token_ids_hash,
                post_attention_run.output_bytes,
                "cpu_exact_shared_precompute",
                &device_post_attention
            ) ||
            !check_hip(
                hipMemcpy(
                    run->selected_inputs.data(),
                    device_post_attention,
                    post_attention_run.output_bytes,
                    hipMemcpyDeviceToHost
                ),
                "hipMemcpy(" + run_name + "_source_layout_post_attention)",
                &run->failure_stage,
                &run->failure
            )) {
            if (run->failure_stage.empty()) {
                run->failure_stage =
                    run_name + "_source_layout_post_attention_miss";
                run->failure =
                    "selected " + layer_label +
                    " CPU-exact shared precompute did not receive the resident post-attention source layout";
            }
            return false;
        }
    } else {
        for (size_t selected_index = 0;
             selected_index < run->selected_token_count;
             ++selected_index) {
            const float *input =
                post_attention_run.gpu_output.data() +
                selected_index *
                    static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
            std::copy(
                input,
                input + QRT_QWEN36_HIDDEN_SIZE,
                run->selected_inputs.data() +
                    selected_index *
                        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
            );
        }
    }
    run->routed_inputs.clear();
    run->cpu_shared_output.assign(run->output_elements, 0.0f);
    run->cpu_combined_output.clear();
    run->cpu_gate_logits.assign(run->selected_token_count, 0.0f);
    if (!run->cpu_exact_diagnostics_elided) {
        run->gpu_shared_output.assign(run->output_elements, 0.0f);
        run->gpu_combined_output.assign(run->output_elements, 0.0f);
        run->gpu_gate_logits.assign(run->selected_token_count, 0.0f);
    }

    const uint64_t precompute_start_ns = qrt_now_ns();
    std::string reference_failure;
    if (!compute_shared_expert_cpu_shared_only_parallel(
            run,
            &reference_failure
        )) {
        run->failure_stage = "cpu_shared_only_precompute_" + run_stage;
        run->failure =
            layer_label + " CPU-exact shared-only precompute failed: " +
            (reference_failure.empty()
                 ? "parallel shared-only CPU reference failed"
                 : reference_failure);
        return false;
    }
    run->cpu_shared_precompute_elapsed_ms =
        static_cast<double>(
            qrt_elapsed_ns(precompute_start_ns, qrt_now_ns())
        ) / 1000000.0;
    run->cpu_shared_only_precomputed = true;
    return true;
}

bool finish_precomputed_cpu_exact_shared_expert(
    unsigned int layer_index,
    const RoutedExpertRun &routed_expert_run,
    unsigned int prefill_tokens,
    SharedExpertRun *run
) {
    const std::string layer_label =
        std::string("layer-") + std::to_string(layer_index);
    if (run == nullptr ||
        !run->cpu_exact_shared_backend ||
        !run->cpu_shared_only_precomputed ||
        run->selected_token_count == 0 ||
        !routed_expert_run.correctness_pass ||
        routed_expert_run.selected_token_ids != run->selected_token_ids ||
        routed_expert_run.gpu_output.size() != run->output_elements) {
        if (run != nullptr) {
            run->failure_stage = run->name + "_async_cpu_exact_shared_contract";
            run->failure =
                layer_label + " async CPU-exact shared precompute did not match routed expert output";
        }
        return false;
    }

    const uint64_t finish_start_ns = qrt_now_ns();
    if (descriptor_product_exact_device_combined_moe_from_routed_handoff_enabled(
            layer_index,
            prefill_tokens
        )) {
        const std::vector<unsigned int> selected_rows =
            selected_out_projection_rows();
        std::vector<float> selected_shared_reference;
        std::vector<float> selected_combined_reference;
        std::vector<float> selected_gate_reference;
        selected_shared_reference.reserve(
            run->selected_token_count * selected_rows.size()
        );
        selected_combined_reference.reserve(
            run->selected_token_count * selected_rows.size()
        );
        selected_gate_reference.reserve(run->selected_token_count);

        run->shared_samples.clear();
        run->combined_samples.clear();
        run->gate_samples.clear();
        for (size_t selected_index = 0;
             selected_index < run->selected_token_count;
             ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            const float gate_value = run->cpu_gate_logits[selected_index];
            run->gate_samples.push_back({token, 0u, gate_value, gate_value, 0.0f});
            selected_gate_reference.push_back(gate_value);
            for (unsigned int row : selected_rows) {
                const size_t output_index =
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) +
                    row;
                const float shared_value = run->cpu_shared_output[output_index];
                const float combined_value =
                    routed_expert_run.gpu_output[output_index] + shared_value;
                run->shared_samples.push_back(
                    {token, row, shared_value, shared_value, 0.0f}
                );
                run->combined_samples.push_back(
                    {token, row, combined_value, combined_value, 0.0f}
                );
                selected_shared_reference.push_back(shared_value);
                selected_combined_reference.push_back(combined_value);
            }
        }

        const size_t selected_sample_count =
            run->selected_token_count * selected_rows.size();
        run->checked_gate_values =
            static_cast<unsigned int>(run->selected_token_count);
        run->checked_shared_values =
            static_cast<unsigned int>(selected_sample_count);
        run->checked_combined_values =
            static_cast<unsigned int>(selected_sample_count);
        run->checked_values =
            run->checked_gate_values +
            run->checked_shared_values +
            run->checked_combined_values;
        run->full_checked_gate_values = run->selected_token_count;
        run->full_checked_shared_values = run->output_elements;
        run->full_checked_combined_values = run->output_elements;
        run->full_checked_values =
            run->full_checked_gate_values +
            run->full_checked_shared_values +
            run->full_checked_combined_values;
        run->max_abs_diff = 0.0f;
        run->max_shared_abs_diff = 0.0f;
        run->max_combined_abs_diff = 0.0f;
        run->max_gate_abs_diff = 0.0f;
        run->full_max_abs_diff = 0.0f;
        run->full_shared_max_abs_diff = 0.0f;
        run->full_combined_max_abs_diff = 0.0f;
        run->full_gate_max_abs_diff = 0.0f;
        run->selected_shared_reference_hash =
            qrt_fnv1a64_f32(
                selected_shared_reference.data(),
                selected_shared_reference.size()
            );
        run->selected_shared_gpu_hash = run->selected_shared_reference_hash;
        run->selected_combined_reference_hash =
            qrt_fnv1a64_f32(
                selected_combined_reference.data(),
                selected_combined_reference.size()
            );
        run->selected_combined_gpu_hash =
            run->selected_combined_reference_hash;
        run->selected_gate_reference_hash =
            qrt_fnv1a64_f32(
                selected_gate_reference.data(),
                selected_gate_reference.size()
            );
        run->selected_gate_gpu_hash = run->selected_gate_reference_hash;
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->post_attention_input_hash = UINT64_C(0);
        run->routed_input_hash = UINT64_C(0);
        run->gate_weight_hash = UINT64_C(0);
        run->gate_proj_weight_hash = UINT64_C(0);
        run->up_proj_weight_hash = UINT64_C(0);
        run->down_weight_hash = UINT64_C(0);
        run->cpu_shared_output_hash = UINT64_C(0);
        run->gpu_shared_output_hash = UINT64_C(0);
        run->cpu_combined_output_hash = UINT64_C(0);
        run->gpu_combined_output_hash = UINT64_C(0);
        run->cpu_gate_logits_hash = UINT64_C(0);
        run->gpu_gate_logits_hash = UINT64_C(0);
        run->cpu_shared_output_bf16_hash = UINT64_C(0);
        run->gpu_shared_output_bf16_hash = UINT64_C(0);
        run->cpu_combined_output_bf16_hash = UINT64_C(0);
        run->gpu_combined_output_bf16_hash = UINT64_C(0);
        run->cpu_gate_logits_bf16_hash = UINT64_C(0);
        run->gpu_gate_logits_bf16_hash = UINT64_C(0);
        run->routed_inputs.clear();
        run->cpu_combined_output.clear();
        run->combined_moe_handoff_output.clear();
        run->combined_moe_handoff_canonicalized = false;
        run->correctness_pass =
            run->checked_values > 0 &&
            run->full_checked_shared_values == run->output_elements &&
            run->full_checked_combined_values == run->output_elements &&
            run->full_checked_gate_values == run->selected_token_count &&
            run->full_checked_values ==
                run->full_checked_shared_values +
                run->full_checked_combined_values +
                run->full_checked_gate_values &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage =
                run->name + "_exact_device_combined_moe_routed_contract";
            run->failure =
                layer_label +
                " exact routed-device combined-MoE metadata contract failed";
            return false;
        }
        if (!store_exact_device_combined_moe_handoff_from_routed_device(
                layer_index,
                prefill_tokens,
                routed_expert_run,
                run
            )) {
            return false;
        }
        if (descriptor_product_selected_moe_structural_classifier_enabled(
                layer_index,
                prefill_tokens
            )) {
            std::cerr << "BATCH_MARK selected_moe_structural_classifier"
                      << " layer=" << layer_index
                      << " boundary=shared_expert"
                      << " state=device_combined_input"
                      << " reason=exact_device_combined_output_from_routed_handoff"
                      << " routed_device_handoff=1"
                      << " cpu_exact_shared=1"
                      << " async_cpu_exact_shared=1"
                      << " selected_tokens=" << run->selected_token_count
                      << " output_bytes=" << run->combined_output_bytes
                      << std::endl;
        }
        const double finish_elapsed_ms =
            static_cast<double>(
                qrt_elapsed_ns(finish_start_ns, qrt_now_ns())
            ) / 1000000.0;
        run->elapsed_ms =
            static_cast<float>(
                run->cpu_shared_precompute_elapsed_ms + finish_elapsed_ms
            );
        run->avg_ms = static_cast<double>(run->elapsed_ms);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) /
                      (run->avg_ms / 1000.0)
                : 0.0;
        std::cerr << "BATCH_MARK descriptor_async_cpu_exact_shared_expert"
                  << " layer=" << layer_index
                  << " selected_tokens=" << run->selected_token_count
                  << " output_bytes=" << run->output_bytes
                  << " precompute_ms=" << run->cpu_shared_precompute_elapsed_ms
                  << " finish_ms=" << finish_elapsed_ms
                  << " diagnostics_elided="
                  << (run->cpu_exact_diagnostics_elided ? 1 : 0)
                  << " combined_moe_from_routed_handoff=1"
                  << std::endl;
        return run->failure_stage.empty() && run->correctness_pass;
    }

    run->routed_inputs =
        routed_expert_effective_output_handoff(
            routed_expert_run,
            run->output_elements
        );
    if (run->routed_inputs.size() != run->output_elements) {
        run->failure_stage = run->name + "_async_routed_input_shape";
        run->failure =
            layer_label + " routed expert handoff does not match async shared expert boundary";
        return false;
    }

    if (!finalize_shared_expert_reference_contract(
            run,
            run->stage,
            layer_label + " async CPU-exact shared expert"
        )) {
        return false;
    }
    materialize_combined_moe_handoff(run);
    if (!store_exact_device_combined_moe_handoff(
            layer_index,
            prefill_tokens,
            run
        )) {
        return false;
    }
    if (descriptor_product_selected_moe_structural_classifier_enabled(
            layer_index,
            prefill_tokens
        )) {
        std::cerr << "BATCH_MARK selected_moe_structural_classifier"
                  << " layer=" << layer_index
                  << " boundary=shared_expert"
                  << " state=blocked"
                  << " reason=cpu_exact_shared_combined_output_host_owned"
                  << " routed_device_handoff="
                  << (descriptor_product_routed_shared_device_handoff_enabled(
                          layer_index,
                          prefill_tokens
                      ) ? 1 : 0)
                  << " cpu_exact_shared=1"
                  << " async_cpu_exact_shared=1"
                  << " selected_tokens=" << run->selected_token_count
                  << " output_bytes=" << run->combined_output_bytes
                  << std::endl;
    }
    const double finish_elapsed_ms =
        static_cast<double>(
            qrt_elapsed_ns(finish_start_ns, qrt_now_ns())
        ) / 1000000.0;
    run->elapsed_ms =
        static_cast<float>(run->cpu_shared_precompute_elapsed_ms + finish_elapsed_ms);
    run->avg_ms = static_cast<double>(run->elapsed_ms);
    run->selected_tokens_per_second =
        run->avg_ms > 0.0
            ? static_cast<double>(run->selected_token_count) /
                  (run->avg_ms / 1000.0)
            : 0.0;
    std::cerr << "BATCH_MARK descriptor_async_cpu_exact_shared_expert"
              << " layer=" << layer_index
              << " selected_tokens=" << run->selected_token_count
              << " output_bytes=" << run->output_bytes
              << " precompute_ms=" << run->cpu_shared_precompute_elapsed_ms
              << " finish_ms=" << finish_elapsed_ms
              << " diagnostics_elided="
              << (run->cpu_exact_diagnostics_elided ? 1 : 0)
              << std::endl;
    (void)prefill_tokens;
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_shared_expert(
    const PostAttentionRmsnormRun &post_attention_rmsnorm_run,
    const RoutedExpertRun &routed_expert_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    SharedExpertRun *run
) {
    const uint64_t gate_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_GATE_BYTES);
    const uint64_t proj_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_PROJ_BYTES);
    const uint64_t down_bytes =
        static_cast<uint64_t>(QRT_QWEN36_LAYER0_MOE_SHARED_DOWN_BYTES);

    if (!post_attention_rmsnorm_run.correctness_pass ||
        !routed_expert_run.correctness_pass ||
        post_attention_rmsnorm_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
        run->failure_stage = "shared_expert_input_contract";
        run->failure = "post-attention RMSNorm or routed expert output is missing or has unexpected shape";
        return false;
    }

    run->selected_token_ids = routed_expert_run.selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->shared_output_bytes = run->output_elements * sizeof(float);
    run->combined_output_bytes = run->output_elements * sizeof(float);
    run->gate_logits_bytes = run->selected_token_count * sizeof(float);
    run->output_bytes = run->shared_output_bytes + run->combined_output_bytes + run->gate_logits_bytes;
    run->gate_weight_bytes = gate_bytes;
    run->gate_proj_weight_bytes = proj_bytes;
    run->up_proj_weight_bytes = proj_bytes;
    run->down_weight_bytes = down_bytes;
    run->down_weight_row_pair_bytes = 0;
    run->weight_bytes =
        run->gate_weight_bytes +
        run->gate_proj_weight_bytes +
        run->up_proj_weight_bytes +
        run->down_weight_bytes;
    if (run->selected_token_count == 0 || run->output_elements == 0) {
        run->failure_stage = "selected_tokens_layer0_shared_expert_prefill_phase";
        run->failure = "no selected tokens available for shared expert boundary";
        return false;
    }
    if (routed_expert_run.selected_token_ids != run->selected_token_ids ||
        routed_expert_run.gpu_output.size() != run->output_elements) {
        run->failure_stage = "routed_input_layer0_shared_expert_prefill_phase";
        run->failure = "routed expert selected-token output does not match shared expert boundary";
        return false;
    }

    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_SHARED_GATE, &run->gate_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_shared_gate_prefill_phase";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_SHARED_GATE_PROJ, &run->gate_proj_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_shared_gate_proj_prefill_phase";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_SHARED_UP_PROJ, &run->up_proj_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_shared_up_proj_prefill_phase";
        return false;
    }
    if (!tensor_name_for_kind(QRT_QWEN36_TENSOR_MOE_SHARED_DOWN, &run->down_tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer0_moe_shared_down_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->gate_tensor_name, &run->gate_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_shared_gate_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->gate_proj_tensor_name, &run->gate_proj_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_shared_gate_proj_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->up_proj_tensor_name, &run->up_proj_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_shared_up_proj_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->down_tensor_name, &run->down_location, &run->failure)) {
        run->failure_stage = "locate_layer0_moe_shared_down_prefill_phase";
        return false;
    }
    if (run->gate_location.data_end < run->gate_location.data_begin ||
        run->gate_location.data_end - run->gate_location.data_begin != gate_bytes ||
        run->gate_proj_location.data_end < run->gate_proj_location.data_begin ||
        run->gate_proj_location.data_end - run->gate_proj_location.data_begin != proj_bytes ||
        run->up_proj_location.data_end < run->up_proj_location.data_begin ||
        run->up_proj_location.data_end - run->up_proj_location.data_begin != proj_bytes ||
        run->down_location.data_end < run->down_location.data_begin ||
        run->down_location.data_end - run->down_location.data_begin != down_bytes) {
        run->failure_stage = "shape_layer0_shared_expert_prefill_phase";
        run->failure = "layer-0 shared expert tensors do not match expected byte shape";
        return false;
    }

    if (!read_safetensors_bytes(model_dir, run->gate_location, 0, gate_bytes, &run->gate_weight, &run->failure)) {
        run->failure_stage = "read_layer0_moe_shared_gate_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->gate_proj_location, 0, proj_bytes, &run->gate_proj_weight, &run->failure)) {
        run->failure_stage = "read_layer0_moe_shared_gate_proj_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->up_proj_location, 0, proj_bytes, &run->up_proj_weight, &run->failure)) {
        run->failure_stage = "read_layer0_moe_shared_up_proj_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->down_location, 0, down_bytes, &run->down_weight, &run->failure)) {
        run->failure_stage = "read_layer0_moe_shared_down_prefill_phase";
        return false;
    }

    run->selected_inputs.assign(run->output_elements, 0.0f);
    run->routed_inputs =
        routed_expert_effective_output_handoff(routed_expert_run, run->output_elements);
    for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
        const unsigned int token = run->selected_token_ids[selected_index];
        const float *input =
            post_attention_rmsnorm_run.gpu_output.data() +
            static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
        std::copy(
            input,
            input + QRT_QWEN36_HIDDEN_SIZE,
            run->selected_inputs.data() +
                selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
        );
    }
    run->gpu_shared_output.assign(run->output_elements, 0.0f);
    run->gpu_combined_output.assign(run->output_elements, 0.0f);
    run->gpu_gate_logits.assign(run->selected_token_count, 0.0f);

    uint16_t *device_gate = nullptr;
    uint16_t *device_gate_proj = nullptr;
    uint16_t *device_up_proj = nullptr;
    uint16_t *device_down = nullptr;
    float *device_inputs = nullptr;
    float *device_routed = nullptr;
    float *device_activated = nullptr;
    float *device_gate_logits = nullptr;
    float *device_gate_scales = nullptr;
    float *device_shared = nullptr;
    float *device_combined = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const size_t activated_elements =
        run->selected_token_count * static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE);
    const size_t activated_bytes = activated_elements * sizeof(float);
    const dim3 gate_grid(static_cast<unsigned int>(run->selected_token_count));
    const dim3 activation_grid(
        static_cast<unsigned int>(run->selected_token_count),
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    const dim3 down_grid(
        static_cast<unsigned int>(run->selected_token_count),
        QRT_QWEN36_HIDDEN_SIZE
    );
    const dim3 block(kThreads);

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate), static_cast<size_t>(run->gate_weight_bytes)), "hipMalloc(shared_expert_gate_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate_proj), static_cast<size_t>(run->gate_proj_weight_bytes)), "hipMalloc(shared_expert_gate_proj_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_up_proj), static_cast<size_t>(run->up_proj_weight_bytes)), "hipMalloc(shared_expert_up_proj_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_down), static_cast<size_t>(run->down_weight_bytes)), "hipMalloc(shared_expert_down_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_inputs), run->selected_inputs.size() * sizeof(float)), "hipMalloc(shared_expert_selected_inputs)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_routed), run->routed_inputs.size() * sizeof(float)), "hipMalloc(shared_expert_routed_inputs)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_activated), activated_bytes), "hipMalloc(shared_expert_activated)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate_logits), run->gate_logits_bytes), "hipMalloc(shared_expert_gate_logits)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_gate_scales), run->gate_logits_bytes), "hipMalloc(shared_expert_gate_scales)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_shared), run->shared_output_bytes), "hipMalloc(shared_expert_shared_output)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_combined), run->combined_output_bytes), "hipMalloc(shared_expert_combined_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_gate, run->gate_weight.data(), static_cast<size_t>(run->gate_weight_bytes), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_gate_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_gate_proj, run->gate_proj_weight.data(), static_cast<size_t>(run->gate_proj_weight_bytes), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_gate_proj_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_up_proj, run->up_proj_weight.data(), static_cast<size_t>(run->up_proj_weight_bytes), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_up_proj_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_down, run->down_weight.data(), static_cast<size_t>(run->down_weight_bytes), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_down_weight)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_inputs, run->selected_inputs.data(), run->selected_inputs.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_selected_inputs)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_routed, run->routed_inputs.data(), run->routed_inputs.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(shared_expert_routed_inputs)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_activated, 0, activated_bytes), "hipMemset(shared_expert_activated)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_gate_logits, 0, run->gate_logits_bytes), "hipMemset(shared_expert_gate_logits)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_gate_scales, 0, run->gate_logits_bytes), "hipMemset(shared_expert_gate_scales)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_shared, 0, run->shared_output_bytes), "hipMemset(shared_expert_shared_output)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_combined, 0, run->combined_output_bytes), "hipMemset(shared_expert_combined_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(shared_expert_gate_kernel, gate_grid, block, 0, 0, device_inputs, device_gate, device_gate_logits, device_gate_scales, static_cast<unsigned int>(run->selected_token_count));
        hipLaunchKernelGGL(shared_expert_gate_up_activation_kernel, activation_grid, block, 0, 0, device_inputs, device_gate_proj, device_up_proj, device_activated, static_cast<unsigned int>(run->selected_token_count), false);
        hipLaunchKernelGGL(shared_expert_down_combine_kernel, down_grid, block, 0, 0, device_activated, device_gate_scales, device_down, device_routed, device_shared, device_combined, static_cast<unsigned int>(run->selected_token_count), false);
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_shared_expert_prefill_phase",
            "warmup_sync_layer0_shared_expert_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_shared_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_shared_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_shared_expert_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(shared_expert_gate_kernel, gate_grid, block, 0, 0, device_inputs, device_gate, device_gate_logits, device_gate_scales, static_cast<unsigned int>(run->selected_token_count));
        hipLaunchKernelGGL(shared_expert_gate_up_activation_kernel, activation_grid, block, 0, 0, device_inputs, device_gate_proj, device_up_proj, device_activated, static_cast<unsigned int>(run->selected_token_count), false);
        hipLaunchKernelGGL(shared_expert_down_combine_kernel, down_grid, block, 0, 0, device_activated, device_gate_scales, device_down, device_routed, device_shared, device_combined, static_cast<unsigned int>(run->selected_token_count), false);
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_shared_expert_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_shared_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_shared_expert_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_shared_expert_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_shared_output.data(), device_shared, run->shared_output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(shared_expert_shared_output)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(run->gpu_combined_output.data(), device_combined, run->combined_output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(shared_expert_combined_output)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(run->gpu_gate_logits.data(), device_gate_logits, run->gate_logits_bytes, hipMemcpyDeviceToHost), "hipMemcpy(shared_expert_gate_logits)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    if (!finalize_shared_expert_reference_contract(
            run,
            "layer0_shared_expert_prefill_phase",
            "layer-0 shared expert"
        )) {
        goto cleanup;
    }
    materialize_combined_moe_handoff(run);
    run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
    run->selected_tokens_per_second =
        run->avg_ms > 0.0
            ? static_cast<double>(run->selected_token_count) / (run->avg_ms / 1000.0)
            : 0.0;

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_combined);
    free_device(device_shared);
    free_device(device_gate_scales);
    free_device(device_gate_logits);
    free_device(device_activated);
    free_device(device_routed);
    free_device(device_inputs);
    free_device(device_down);
    free_device(device_up_proj);
    free_device(device_gate_proj);
    free_device(device_gate);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_output_residual(
    const ResidualHiddenRun &residual_hidden_run,
    const SharedExpertRun &shared_expert_run,
    unsigned int prefill_tokens,
    OutputResidualRun *run
) {
    if (!residual_hidden_run.correctness_pass ||
        !shared_expert_run.correctness_pass ||
        residual_hidden_run.gpu_output.size() !=
            static_cast<size_t>(prefill_tokens) * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
        run->failure_stage = "output_residual_input_contract";
        run->failure = "residual hidden or shared expert output is missing or has unexpected shape";
        return false;
    }

    run->selected_token_ids = shared_expert_run.selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);
    if (run->selected_token_count == 0 || run->output_elements == 0) {
        run->failure_stage = "selected_tokens_layer0_output_residual_prefill_phase";
        run->failure = "no selected tokens available for output residual boundary";
        return false;
    }
    const std::vector<float> &combined_moe_input =
        shared_expert_combined_moe_handoff(shared_expert_run, run->output_elements);
    if (combined_moe_input.size() != run->output_elements) {
        run->failure_stage = "moe_input_layer0_output_residual_prefill_phase";
        run->failure = "selected combined MoE output does not match output residual boundary";
        return false;
    }

    run->residual_inputs.assign(run->output_elements, 0.0f);
    run->moe_inputs = combined_moe_input;
    run->gpu_output.assign(run->output_elements, 0.0f);
    for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
        const unsigned int token = run->selected_token_ids[selected_index];
        if (token >= prefill_tokens) {
            run->failure_stage = "selected_token_range_layer0_output_residual_prefill_phase";
            run->failure = "selected token is outside prefill token range";
            return false;
        }
        const float *input =
            residual_hidden_run.gpu_output.data() +
            static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
        std::copy(
            input,
            input + QRT_QWEN36_HIDDEN_SIZE,
            run->residual_inputs.data() +
                selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
        );
    }

    float *device_residual = nullptr;
    float *device_moe = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid(static_cast<unsigned int>((run->output_elements + kThreads - 1u) / kThreads));

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_residual), run->residual_inputs.size() * sizeof(float)), "hipMalloc(output_residual_residual_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_moe), run->moe_inputs.size() * sizeof(float)), "hipMalloc(output_residual_moe_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(output_residual_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_residual, run->residual_inputs.data(), run->residual_inputs.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(output_residual_residual_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_moe, run->moe_inputs.data(), run->moe_inputs.size() * sizeof(float), hipMemcpyHostToDevice), "hipMemcpy(output_residual_moe_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(output_residual_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            output_residual_add_kernel,
            grid,
            block,
            0,
            0,
            device_residual,
            device_moe,
            device_output,
            static_cast<unsigned int>(run->selected_token_count)
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer0_output_residual_prefill_phase",
            "warmup_sync_layer0_output_residual_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer0_output_residual_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer0_output_residual_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer0_output_residual_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            output_residual_add_kernel,
            grid,
            block,
            0,
            0,
            device_residual,
            device_moe,
            device_output,
            static_cast<unsigned int>(run->selected_token_count)
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer0_output_residual_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer0_output_residual_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer0_output_residual_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer0_output_residual_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
        run->timing_fallback_used = true;
        const auto wall_start = std::chrono::steady_clock::now();
        for (int iter = 0; iter < kTimedIterations; ++iter) {
            hipLaunchKernelGGL(
                output_residual_add_kernel,
                grid,
                block,
                0,
                0,
                device_residual,
                device_moe,
                device_output,
                static_cast<unsigned int>(run->selected_token_count)
            );
        }
        if (!check_hip(hipGetLastError(), "fallback_timed_kernel_launch_layer0_output_residual_prefill_phase", &run->failure_stage, &run->failure) ||
            !check_hip(hipDeviceSynchronize(), "fallback_timed_sync_layer0_output_residual_prefill_phase", &run->failure_stage, &run->failure)) {
            goto cleanup;
        }
        const auto wall_stop = std::chrono::steady_clock::now();
        run->elapsed_ms = static_cast<float>(
            std::chrono::duration<double, std::milli>(wall_stop - wall_start).count()
        );
        if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
            run->failure_stage = "timing_layer0_output_residual_prefill_phase";
            run->failure = "layer-0 output residual fallback timing was negative or non-finite";
            goto cleanup;
        }
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(output_residual_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            for (unsigned int row : selected_out_projection_rows()) {
                const size_t output_index =
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
                const float reference =
                    run->residual_inputs[output_index] + run->moe_inputs[output_index];
                const float gpu = run->gpu_output[output_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->residual_input_hash =
            qrt_fnv1a64_f32(run->residual_inputs.data(), run->residual_inputs.size());
        run->moe_input_hash =
            qrt_fnv1a64_f32(run->moe_inputs.data(), run->moe_inputs.size());
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) / (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer0_output_residual_prefill_phase";
            run->failure = "selected CPU/HIP output residual boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_moe);
    free_device(device_residual);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_layer1_input_rmsnorm(
    const OutputResidualRun &output_residual_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    Layer1InputRmsnormRun *run
) {
    (void)prefill_tokens;
    run->weight_bytes = static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) * sizeof(uint16_t);
    run->selected_token_ids = output_residual_run.selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!output_residual_run.correctness_pass ||
        output_residual_run.gpu_output.size() != run->output_elements ||
        run->selected_token_count == 0) {
        run->failure_stage = "layer1_input_rmsnorm_input_contract";
        run->failure = "selected output residual is missing or has unexpected shape";
        return false;
    }
    if (!tensor_name_for_layer_kind(1u, QRT_QWEN36_TENSOR_INPUT_NORM, &run->tensor_name, &run->failure)) {
        run->failure_stage = "tensor_name_layer1_input_rmsnorm_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = "locate_layer1_input_rmsnorm_prefill_phase";
        return false;
    }
    if (run->location.data_end < run->location.data_begin ||
        run->location.data_end - run->location.data_begin != run->weight_bytes) {
        run->failure_stage = "shape_layer1_input_rmsnorm_prefill_phase";
        run->failure = "layer-1 input RMSNorm tensor does not match expected byte shape";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = "read_layer1_input_rmsnorm_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    uint16_t *device_weights = nullptr;
    float *device_input = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid(static_cast<unsigned int>(run->selected_token_count));

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), "hipMalloc(layer1_input_rmsnorm_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_input), output_residual_run.output_bytes), "hipMalloc(layer1_input_rmsnorm_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), "hipMalloc(layer1_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), "hipMemcpy(layer1_input_rmsnorm_weights)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_input, output_residual_run.gpu_output.data(), output_residual_run.output_bytes, hipMemcpyHostToDevice), "hipMemcpy(layer1_input_rmsnorm_input)", &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), "hipMemset(layer1_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            layer1_input_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_input,
            device_weights,
            device_output,
            static_cast<unsigned int>(run->selected_token_count)
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            "warmup_kernel_launch_layer1_input_rmsnorm_prefill_phase",
            "warmup_sync_layer1_input_rmsnorm_prefill_phase",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), "hipEventCreate(start_layer1_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), "hipEventCreate(stop_layer1_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), "hipEventRecord(start_layer1_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            layer1_input_rmsnorm_kernel,
            grid,
            block,
            0,
            0,
            device_input,
            device_weights,
            device_output,
            static_cast<unsigned int>(run->selected_token_count)
        );
    }
    if (!check_hip(hipGetLastError(), "timed_kernel_launch_layer1_input_rmsnorm_prefill_phase", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), "hipEventRecord(stop_layer1_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), "hipEventSynchronize(stop_layer1_input_rmsnorm_prefill_phase)", &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), "hipEventElapsedTime_layer1_input_rmsnorm_prefill_phase", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), "hipMemcpy(layer1_input_rmsnorm_output)", &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            for (unsigned int row : selected_out_projection_rows()) {
                const float reference = selected_rmsnorm_cpu_value(
                    output_residual_run.gpu_output,
                    run->weights.data(),
                    selected_index,
                    row
                );
                const size_t output_index =
                    selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) + row;
                const float gpu = run->gpu_output[output_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->input_hash =
            qrt_fnv1a64_f32(output_residual_run.gpu_output.data(), output_residual_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) / (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_layer1_input_rmsnorm_prefill_phase";
            run->failure = "selected CPU/HIP layer-1 input RMSNorm boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_input);
    free_device(device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_layer1_selected_projection(
    const Layer1InputRmsnormRun &input_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    unsigned int layer_index,
    qrt_qwen36_tensor_kind_t tensor_kind,
    const char *name,
    const char *stage,
    unsigned int rows,
    const char *failure_prefix,
    Layer1SelectedProjectionRun *run,
    bool prefer_resident_device_weight = false
) {
    (void)prefill_tokens;
    run->name = name;
    run->stage = stage;
    run->weight_bytes = static_cast<uint64_t>(rows) *
                        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
                        sizeof(uint16_t);
    run->selected_token_ids = input_rmsnorm_run.selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = run->selected_token_count * static_cast<size_t>(rows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!input_rmsnorm_run.correctness_pass ||
        input_rmsnorm_run.gpu_output.size() !=
            run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) ||
        run->selected_token_count == 0) {
        run->failure_stage = std::string(failure_prefix) + "_input_contract";
        run->failure = "selected input RMSNorm output is missing or has unexpected shape";
        return false;
    }
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=input_contract_ready"
            << " projection=" << name
            << " rows=" << rows
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    if (!tensor_name_for_layer_kind(layer_index, tensor_kind, &run->tensor_name, &run->failure)) {
        run->failure_stage = std::string("tensor_name_") + failure_prefix + "_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = std::string("locate_") + failure_prefix + "_prefill_phase";
        return false;
    }
    if (run->location.data_end < run->location.data_begin ||
        run->location.data_end - run->location.data_begin != run->weight_bytes) {
        run->failure_stage = std::string("shape_") + failure_prefix + "_prefill_phase";
        run->failure = "selected projection tensor does not match expected byte shape";
        return false;
    }
    const uint16_t *resident_device_weights = nullptr;
    const bool use_resident_device_weights =
        try_decode_resident_dense_weight_view(
            prefer_resident_device_weight,
            DecodeResidentDenseWeightSurface::kSelectedProjection,
            model_dir,
            run->tensor_name,
            run->weight_bytes,
            &resident_device_weights
        );
    run->resident_weight_borrowed = use_resident_device_weights;
    run->weight_hash_elided = use_resident_device_weights;
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=resident_lookup_ready"
            << " projection=" << name
            << " tensor=" << run->tensor_name
            << " resident_weight="
            << (use_resident_device_weights ? 1 : 0)
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    if (!use_resident_device_weights &&
        !read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = std::string("read_") + failure_prefix + "_prefill_phase";
        return false;
    }
    const bool use_tiled_projection = layer_index >= 2u;
    std::vector<uint16_t> selected_input_bf16;
    if (use_tiled_projection) {
        selected_input_bf16.reserve(input_rmsnorm_run.gpu_output.size());
        for (float value : input_rmsnorm_run.gpu_output) {
            selected_input_bf16.push_back(qrt_float_to_bf16(value));
        }
    }
    run->gpu_output.assign(run->output_elements, 0.0f);
    const std::vector<unsigned int> validation_rows = selected_rows(rows);
    std::vector<uint16_t> resident_validation_weight_rows;
    if (use_resident_device_weights &&
        !(g_qwen36_mtp_tensor_namespace_active
              ? read_dense_weight_rows_for_validation(
                    model_dir,
                    run->location,
                    rows,
                    QRT_QWEN36_HIDDEN_SIZE,
                    validation_rows,
                    &resident_validation_weight_rows,
                    std::string(failure_prefix) +
                        "_resident_weight_validation_host_read",
                    &run->failure_stage,
                    &run->failure
                )
              : copy_decode_resident_dense_weight_rows_for_validation(
                    resident_device_weights,
                    rows,
                    QRT_QWEN36_HIDDEN_SIZE,
                    validation_rows,
                    &resident_validation_weight_rows,
                    std::string(failure_prefix) +
                        "_resident_weight_validation_d2h",
                    &run->failure_stage,
                    &run->failure
                ))) {
        return false;
    }
    run->resident_validation_weight_bytes = static_cast<uint64_t>(
        resident_validation_weight_rows.size() * sizeof(uint16_t)
    );
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=validation_weights_ready"
            << " projection=" << name
            << " validation_bytes="
            << run->resident_validation_weight_bytes
            << " validation_source="
            << (use_resident_device_weights ? "direct_file" : "full_host")
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }

    const bool use_decode_projection_weight_cache =
        !use_resident_device_weights &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_EXACT_DECODE_PROJECTION_WEIGHT_CACHE"
        ) &&
        use_tiled_projection &&
        layer_index >= 2u &&
        run->selected_token_count == 1u;

    const uint16_t *device_weights = resident_device_weights;
    uint16_t *transient_device_weights = nullptr;
    float *device_input = nullptr;
    uint16_t *device_input_bf16 = nullptr;
    float *device_output = nullptr;
    bool decode_projection_weight_cache_hit = false;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 scalar_block(kThreads);
    const dim3 scalar_grid(rows, static_cast<unsigned int>(run->selected_token_count));
    const dim3 tiled_block(kThreadTileRows, kThreadTileTokens);
    const bool use_qkv_token_tile64 =
        use_tiled_projection &&
        rows == kQkvRows &&
        run->selected_token_count <= kSelectedProjectionTileTokens64;
    const bool use_qkv_token_tile128 =
        use_tiled_projection &&
        rows == kQkvRows &&
        run->selected_token_count > kSelectedProjectionTileTokens64 &&
        run->selected_token_count <= kSelectedProjectionTileTokens128;
    const bool use_qkv_token_tile192 =
        use_tiled_projection &&
        rows == kQkvRows &&
        run->selected_token_count > kSelectedProjectionTileTokens128 &&
        run->selected_token_count <= kSelectedProjectionTileTokens192;
    const unsigned int selected_projection_tile_tokens =
        use_qkv_token_tile64
            ? kSelectedProjectionTileTokens64
            : (use_qkv_token_tile128
                   ? kSelectedProjectionTileTokens128
                   : (use_qkv_token_tile192 ? kSelectedProjectionTileTokens192 : kTileTokens));
    const dim3 tiled_grid(
        (rows + kTileRows - 1u) / kTileRows,
        (static_cast<unsigned int>(run->selected_token_count) + kTileTokens - 1u) /
            kTileTokens
    );
    const dim3 selected_tiled_grid(
        (rows + kTileRows - 1u) / kTileRows,
        (static_cast<unsigned int>(run->selected_token_count) +
            selected_projection_tile_tokens - 1u) /
            selected_projection_tile_tokens
    );
    auto launch_selected_projection = [&]() {
        if (use_tiled_projection) {
            if (use_qkv_token_tile64) {
                hipLaunchKernelGGL(
                    HIP_KERNEL_NAME(selected_bf16_projection_dot2_tiled_token_kernel<kSelectedProjectionTileTokens64>),
                    selected_tiled_grid,
                    tiled_block,
                    0,
                    0,
                    device_weights,
                    device_input_bf16,
                    device_output,
                    rows,
                    static_cast<unsigned int>(run->selected_token_count)
                );
            } else if (use_qkv_token_tile128) {
                hipLaunchKernelGGL(
                    HIP_KERNEL_NAME(selected_bf16_projection_dot2_tiled_token_kernel<kSelectedProjectionTileTokens128>),
                    selected_tiled_grid,
                    tiled_block,
                    0,
                    0,
                    device_weights,
                    device_input_bf16,
                    device_output,
                    rows,
                    static_cast<unsigned int>(run->selected_token_count)
                );
            } else if (use_qkv_token_tile192) {
                hipLaunchKernelGGL(
                    HIP_KERNEL_NAME(selected_bf16_projection_dot2_tiled_token_kernel<kSelectedProjectionTileTokens192>),
                    selected_tiled_grid,
                    tiled_block,
                    0,
                    0,
                    device_weights,
                    device_input_bf16,
                    device_output,
                    rows,
                    static_cast<unsigned int>(run->selected_token_count)
                );
            } else {
                hipLaunchKernelGGL(
                    selected_bf16_projection_dot2_tiled_kernel,
                    tiled_grid,
                    tiled_block,
                    0,
                    0,
                    device_weights,
                    device_input_bf16,
                    device_output,
                    rows,
                    static_cast<unsigned int>(run->selected_token_count)
                );
            }
        } else {
            hipLaunchKernelGGL(
                selected_float_projection_kernel,
                scalar_grid,
                scalar_block,
                0,
                0,
                device_weights,
                device_input,
                device_output,
                rows,
                static_cast<unsigned int>(run->selected_token_count)
            );
        }
    };
    const std::string alloc_weights_stage = std::string("hipMalloc(") + failure_prefix + "_weights)";
    const std::string alloc_input_stage = std::string("hipMalloc(") + failure_prefix + "_input)";
    const std::string alloc_output_stage = std::string("hipMalloc(") + failure_prefix + "_output)";
    const std::string copy_weights_stage = std::string("hipMemcpy(") + failure_prefix + "_weights)";
    const std::string copy_input_stage = std::string("hipMemcpy(") + failure_prefix + "_input)";
    const std::string memset_output_stage = std::string("hipMemset(") + failure_prefix + "_output)";
    const std::string warmup_launch_stage = std::string("warmup_kernel_launch_") + failure_prefix + "_prefill_phase";
    const std::string warmup_sync_stage = std::string("warmup_sync_") + failure_prefix + "_prefill_phase";
    const std::string event_start_create_stage = std::string("hipEventCreate(start_") + failure_prefix + "_prefill_phase)";
    const std::string event_stop_create_stage = std::string("hipEventCreate(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_start_record_stage = std::string("hipEventRecord(start_") + failure_prefix + "_prefill_phase)";
    const std::string timed_launch_stage = std::string("timed_kernel_launch_") + failure_prefix + "_prefill_phase";
    const std::string event_stop_record_stage = std::string("hipEventRecord(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_stop_sync_stage = std::string("hipEventSynchronize(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_elapsed_stage = std::string("hipEventElapsedTime_") + failure_prefix + "_prefill_phase";
    const std::string copy_output_stage = std::string("hipMemcpy(") + failure_prefix + "_output)";

    if (use_resident_device_weights) {
        // The resident shard arena owns this exact raw BF16 tensor view.
    } else if (use_decode_projection_weight_cache) {
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        if (!get_or_store_decode_projection_device_weight_cache_entry(
                run->tensor_name,
                run->weights.data(),
                run->weight_bytes,
                run->weight_hash,
                &device_weights,
                &decode_projection_weight_cache_hit,
                &run->failure
            )) {
            run->failure_stage =
                std::string(failure_prefix) + "_decode_projection_weight_cache";
            goto cleanup;
        }
    } else if (!check_hip(
                   hipMalloc(
                       reinterpret_cast<void **>(&transient_device_weights),
                       run->weight_bytes
                   ),
                   alloc_weights_stage,
                   &run->failure_stage,
                   &run->failure
               )) {
        goto cleanup;
    } else {
        device_weights = transient_device_weights;
    }

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), alloc_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (use_tiled_projection) {
        if (!check_hip(
                hipMalloc(
                    reinterpret_cast<void **>(&device_input_bf16),
                    selected_input_bf16.size() * sizeof(uint16_t)
                ),
                alloc_input_stage,
                &run->failure_stage,
                &run->failure
            )) {
            goto cleanup;
        }
    } else if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_input), input_rmsnorm_run.output_bytes), alloc_input_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=device_allocations_ready"
            << " projection=" << name
            << " output_bytes=" << run->output_bytes
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    if ((!use_resident_device_weights &&
         !use_decode_projection_weight_cache &&
         !check_hip(
             hipMemcpy(
                 transient_device_weights,
                 run->weights.data(),
                 run->weight_bytes,
                 hipMemcpyHostToDevice
             ),
             copy_weights_stage,
             &run->failure_stage,
             &run->failure
         )) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), memset_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (use_tiled_projection) {
        if (!check_hip(
                hipMemcpy(
                    device_input_bf16,
                    selected_input_bf16.data(),
                    selected_input_bf16.size() * sizeof(uint16_t),
                    hipMemcpyHostToDevice
                ),
                copy_input_stage,
                &run->failure_stage,
                &run->failure
            )) {
            goto cleanup;
        }
    } else if (!check_hip(hipMemcpy(device_input, input_rmsnorm_run.gpu_output.data(), input_rmsnorm_run.output_bytes, hipMemcpyHostToDevice), copy_input_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=inputs_published"
            << " projection=" << name
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        launch_selected_projection();
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            warmup_launch_stage,
            warmup_sync_stage,
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=warmup_contract_ready"
            << " projection=" << name
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }

    if (!check_hip(hipEventCreate(&start), event_start_create_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), event_stop_create_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), event_start_record_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kSelectedProjectionTimedIterations; ++iter) {
        launch_selected_projection();
    }
    if (!check_hip(hipGetLastError(), timed_launch_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), event_stop_record_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), event_stop_sync_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), event_elapsed_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
        run->timing_fallback_used = true;
        const auto wall_start = std::chrono::steady_clock::now();
        for (int iter = 0; iter < kSelectedProjectionTimedIterations; ++iter) {
            launch_selected_projection();
        }
        if (!check_hip(hipGetLastError(), std::string("fallback_timed_kernel_launch_") + failure_prefix + "_prefill_phase", &run->failure_stage, &run->failure) ||
            !check_hip(hipDeviceSynchronize(), std::string("fallback_timed_sync_") + failure_prefix + "_prefill_phase", &run->failure_stage, &run->failure)) {
            goto cleanup;
        }
        const auto wall_stop = std::chrono::steady_clock::now();
        run->elapsed_ms = static_cast<float>(
            std::chrono::duration<double, std::milli>(wall_stop - wall_start).count()
        );
        if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
            run->failure_stage = std::string("timing_") + failure_prefix + "_prefill_phase";
            run->failure = "selected projection fallback timing was negative or non-finite";
            goto cleanup;
        }
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), copy_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (g_qwen36_mtp_tensor_namespace_active) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_selected_projection_stage"
            << " stage=output_d2h_ready"
            << " projection=" << name
            << " elapsed_ms=" << run->elapsed_ms
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
    }
    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (size_t selected_index = 0; selected_index < run->selected_token_count; ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            for (size_t validation_index = 0u;
                 validation_index < validation_rows.size();
                 ++validation_index) {
                const unsigned int row = validation_rows[validation_index];
                const uint16_t *reference_row_weights =
                    use_resident_device_weights
                    ? resident_validation_weight_rows.data() +
                          validation_index *
                              static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)
                    : run->weights.data() +
                          static_cast<size_t>(row) *
                              static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
                const float reference =
                    use_tiled_projection
                        ? selected_bf16_projection_cpu_row_value(
                              reference_row_weights,
                              selected_input_bf16,
                              selected_index
                          )
                        : selected_float_projection_cpu_row_value(
                              reference_row_weights,
                              input_rmsnorm_run.gpu_output,
                              selected_index
                          );
                const size_t output_index = selected_index * static_cast<size_t>(rows) + row;
                const float gpu = run->gpu_output[output_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->input_hash = qrt_fnv1a64_f32(
            input_rmsnorm_run.gpu_output.data(),
            input_rmsnorm_run.gpu_output.size()
        );
        run->weight_hash = use_resident_device_weights
            ? UINT64_C(0)
            : qrt_fnv1a64_update_bytes(
                  UINT64_C(1469598103934665603),
                  run->weights.data(),
                  static_cast<size_t>(run->weight_bytes)
              );
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kSelectedProjectionTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) / (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kSelectedProjectionTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = std::string("correctness_") + failure_prefix + "_prefill_phase";
            run->failure = "selected CPU/HIP projection boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_input_bf16);
    free_device(device_input);
    free_device(transient_device_weights);
    return run->failure_stage.empty() && run->correctness_pass;
}

#ifdef QRT_HAS_ROCBLAS
bool check_rocblas(
    rocblas_status status,
    const std::string &stage,
    std::string *failure_stage,
    std::string *failure
) {
    if (status == rocblas_status_success) {
        return true;
    }
    if (failure_stage != nullptr) {
        *failure_stage = stage;
    }
    if (failure != nullptr) {
        *failure = "rocblas status " + std::to_string(static_cast<int>(status));
    }
    return false;
}

struct ThreadRocblasHandle {
    rocblas_handle handle = nullptr;
    hipStream_t stream = nullptr;
    bool stream_known = false;
    uint64_t stream_binding_requests = UINT64_C(0);
    uint64_t stream_binding_api_calls = UINT64_C(0);
    uint64_t stream_binding_cache_hits = UINT64_C(0);

    ~ThreadRocblasHandle() {
        if (handle != nullptr) {
            (void)rocblas_destroy_handle(handle);
        }
    }
};

struct ThreadRocblasStreamBindingStats {
    uint64_t requests = UINT64_C(0);
    uint64_t api_calls = UINT64_C(0);
    uint64_t cache_hits = UINT64_C(0);
};

ThreadRocblasHandle &thread_rocblas_handle_state() {
    thread_local ThreadRocblasHandle state;
    return state;
}

ThreadRocblasStreamBindingStats thread_rocblas_stream_binding_stats() {
    const ThreadRocblasHandle &state = thread_rocblas_handle_state();
    return ThreadRocblasStreamBindingStats{
        state.stream_binding_requests,
        state.stream_binding_api_calls,
        state.stream_binding_cache_hits
    };
}

rocblas_status set_thread_rocblas_stream(
    rocblas_handle handle,
    hipStream_t stream
) {
    ThreadRocblasHandle &state = thread_rocblas_handle_state();
    ++state.stream_binding_requests;
    const bool cache_requested = env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_DECODE_ROCBLAS_STREAM_BINDING_CACHE"
    );
    if (cache_requested && handle != nullptr && handle == state.handle &&
        state.stream_known && state.stream == stream) {
        ++state.stream_binding_cache_hits;
        return rocblas_status_success;
    }
    ++state.stream_binding_api_calls;
    const rocblas_status status = rocblas_set_stream(handle, stream);
    if (status == rocblas_status_success && handle == state.handle) {
        state.stream = stream;
        state.stream_known = true;
    }
    return status;
}

bool get_thread_rocblas_handle(
    rocblas_handle *out_handle,
    std::string *failure_stage,
    std::string *failure
) {
    if (out_handle == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage = "rocblas_handle_contract";
        }
        if (failure != nullptr) {
            *failure = "rocBLAS handle output pointer is null";
        }
        return false;
    }
    ThreadRocblasHandle &state = thread_rocblas_handle_state();
    if (state.handle == nullptr) {
        if (!check_rocblas(
                rocblas_create_handle(&state.handle),
                "rocblas_create_handle",
                failure_stage,
                failure
            )) {
            return false;
        }
        if (!check_rocblas(
                rocblas_set_pointer_mode(
                    state.handle,
                    rocblas_pointer_mode_host
                ),
                "rocblas_set_pointer_mode",
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    *out_handle = state.handle;
    return true;
}

#ifdef QRT_ENABLE_ROCBLAS_Q1_MOE_BATCHED
bool prewarm_q1_moe_rocblas_batched(
    Qwen36ResidentDecodeActivationWorkspace *workspace,
    const char *timing_scope,
    std::string *failure_stage,
    std::string *failure
) {
    const bool include_shared = env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_ROCBLAS_SHARED_BATCH"
    );
    const unsigned int w13_batch_count = include_shared
        ? kQ1MoeRocblasSharedW13BatchCount
        : kQ1MoeRocblasW13BatchCount;
    const unsigned int w2_batch_count = include_shared
        ? kQ1MoeRocblasSharedW2BatchCount
        : kQ1MoeRocblasW2BatchCount;
    if (workspace == nullptr ||
        workspace->q1_moe_priority_stream == nullptr ||
        !workspace->q1_moe_priority_stream_ready ||
        timing_scope == nullptr || timing_scope[0] == '\0' ||
        workspace->device_norm_bf16 == nullptr ||
        workspace->device_wide[0] == nullptr ||
        workspace->device_wide[1] == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "qwen36_resident_decode_q1_moe_rocblas_prewarm_workspace";
        }
        if (failure != nullptr) {
            *failure = "resident q1 rocBLAS prewarm workspace is incomplete";
        }
        return false;
    }
    const WholeRepeatedRoutedMatrixWeightEntry *weights = nullptr;
    for (const WholeRepeatedRoutedMatrixWeightEntry &entry :
         g_whole_repeated_routed_matrix_weights) {
        if (entry.layer_index >= 2u && entry.device_gate_up != nullptr &&
            entry.device_down != nullptr) {
            weights = &entry;
            break;
        }
    }
    constexpr size_t kProjectionElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    constexpr uint64_t kMinimumGateUpBytes =
        static_cast<uint64_t>(kQ1MoeRocblasW13BatchCount) *
        kProjectionElements * sizeof(uint16_t);
    constexpr uint64_t kMinimumDownBytes =
        static_cast<uint64_t>(kQ1MoeRocblasW2BatchCount) *
        kProjectionElements * sizeof(uint16_t);
    if (weights == nullptr || weights->gate_up_bytes < kMinimumGateUpBytes ||
        weights->down_bytes < kMinimumDownBytes) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "qwen36_resident_decode_q1_moe_rocblas_prewarm_weights";
        }
        if (failure != nullptr) {
            *failure = "resident q1 rocBLAS prewarm weights are unavailable";
        }
        return false;
    }

    const uint64_t start_ns = qrt_now_ns();
    hipStream_t stream = workspace->q1_moe_priority_stream;
    uint16_t *prewarm_activated = reinterpret_cast<uint16_t *>(
        workspace->device_wide[0]
    );
    uint16_t *prewarm_outputs = reinterpret_cast<uint16_t *>(
        workspace->device_wide[1]
    );
    unsigned char *pointer_scratch = reinterpret_cast<unsigned char *>(
        prewarm_activated +
        3u * (QRT_QWEN36_EXPERTS_PER_TOKEN + 1u) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    const uint16_t **device_a_ptrs =
        reinterpret_cast<const uint16_t **>(pointer_scratch);
    const uint16_t **device_b_ptrs = reinterpret_cast<const uint16_t **>(
        pointer_scratch +
        kQ1MoeRocblasSharedW13BatchCount * sizeof(void *)
    );
    uint16_t **device_d_ptrs = reinterpret_cast<uint16_t **>(
        pointer_scratch +
        2u * kQ1MoeRocblasSharedW13BatchCount * sizeof(void *)
    );
    std::array<const uint16_t *, kQ1MoeRocblasSharedW13BatchCount>
        host_a{};
    std::array<const uint16_t *, kQ1MoeRocblasSharedW13BatchCount>
        host_b{};
    std::array<uint16_t *, kQ1MoeRocblasSharedW13BatchCount> host_d{};
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const uint16_t *expert_gate_up = weights->device_gate_up +
            static_cast<size_t>(route) *
                QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
        const unsigned int gate_index = 2u * route;
        const unsigned int up_index = gate_index + 1u;
        host_a[gate_index] = expert_gate_up;
        host_a[up_index] = expert_gate_up + kProjectionElements;
        host_b[gate_index] = workspace->device_norm_bf16;
        host_b[up_index] = workspace->device_norm_bf16;
        host_d[gate_index] = prewarm_outputs +
            static_cast<size_t>(gate_index) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        host_d[up_index] = prewarm_outputs +
            static_cast<size_t>(up_index) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    }
    if (include_shared) {
        host_a[kQ1MoeRocblasW13BatchCount] = host_a[0];
        host_a[kQ1MoeRocblasW13BatchCount + 1u] = host_a[1];
        host_b[kQ1MoeRocblasW13BatchCount] =
            workspace->device_norm_bf16;
        host_b[kQ1MoeRocblasW13BatchCount + 1u] =
            workspace->device_norm_bf16;
        host_d[kQ1MoeRocblasW13BatchCount] = prewarm_outputs +
            static_cast<size_t>(kQ1MoeRocblasW13BatchCount) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        host_d[kQ1MoeRocblasW13BatchCount + 1u] = prewarm_outputs +
            static_cast<size_t>(kQ1MoeRocblasW13BatchCount + 1u) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    }
    auto upload_pointer_tables = [&](size_t count) {
        return check_hip(
                   hipMemcpyAsync(
                       device_a_ptrs,
                       host_a.data(),
                       count * sizeof(host_a[0]),
                       hipMemcpyHostToDevice,
                       stream
                   ),
                   "qwen36_resident_decode_q1_moe_rocblas_prewarm_a_ptrs",
                   failure_stage,
                   failure
               ) &&
            check_hip(
                hipMemcpyAsync(
                    device_b_ptrs,
                    host_b.data(),
                    count * sizeof(host_b[0]),
                    hipMemcpyHostToDevice,
                    stream
                ),
                "qwen36_resident_decode_q1_moe_rocblas_prewarm_b_ptrs",
                failure_stage,
                failure
            ) &&
            check_hip(
                hipMemcpyAsync(
                    device_d_ptrs,
                    host_d.data(),
                    count * sizeof(host_d[0]),
                    hipMemcpyHostToDevice,
                    stream
                ),
                "qwen36_resident_decode_q1_moe_rocblas_prewarm_d_ptrs",
                failure_stage,
                failure
            );
    };
    if (!check_hip(
            hipMemsetAsync(
                workspace->device_norm_bf16,
                0,
                QRT_QWEN36_HIDDEN_SIZE * sizeof(uint16_t),
                stream
            ),
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_input",
            failure_stage,
            failure
        ) ||
        !check_hip(
            hipMemsetAsync(
                prewarm_activated,
                0,
                (QRT_QWEN36_EXPERTS_PER_TOKEN +
                    (include_shared ? 1u : 0u)) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE * sizeof(uint16_t),
                stream
            ),
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_activated",
            failure_stage,
            failure
        ) ||
        !upload_pointer_tables(w13_batch_count)) {
        return false;
    }

    rocblas_handle handle = nullptr;
    if (!get_thread_rocblas_handle(&handle, failure_stage, failure) ||
        !check_rocblas(
            set_thread_rocblas_stream(handle, stream),
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_set_stream",
            failure_stage,
            failure
        )) {
        return false;
    }
    const float alpha = 1.0f;
    const float beta = 0.0f;
    const rocblas_status w13_status = rocblas_gemm_batched_ex(
        handle,
        rocblas_operation_transpose,
        rocblas_operation_none,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        1,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        &alpha,
        device_a_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        device_b_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        &beta,
        device_d_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        device_d_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        static_cast<rocblas_int>(w13_batch_count),
        rocblas_datatype_f32_r,
        rocblas_gemm_algo_solution_index,
        kQ1MoeRocblasW13SolutionIndex,
        rocblas_gemm_flags_none
    );
    if (!check_rocblas(
            w13_status,
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_w13",
            failure_stage,
            failure
        )) {
        (void)set_thread_rocblas_stream(handle, nullptr);
        return false;
    }

    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        host_a[route] = weights->device_down +
            static_cast<size_t>(route) *
                QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        host_b[route] = prewarm_activated +
            static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        host_d[route] = prewarm_outputs +
            static_cast<size_t>(route) * QRT_QWEN36_HIDDEN_SIZE;
    }
    if (include_shared) {
        host_a[kQ1MoeRocblasW2BatchCount] = host_a[0];
        host_b[kQ1MoeRocblasW2BatchCount] = prewarm_activated +
            static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        host_d[kQ1MoeRocblasW2BatchCount] = prewarm_outputs +
            static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                QRT_QWEN36_HIDDEN_SIZE;
    }
    if (!upload_pointer_tables(w2_batch_count)) {
        (void)set_thread_rocblas_stream(handle, nullptr);
        return false;
    }
    const rocblas_status w2_status = rocblas_gemm_batched_ex(
        handle,
        rocblas_operation_transpose,
        rocblas_operation_none,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        1,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        &alpha,
        device_a_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        device_b_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE),
        &beta,
        device_d_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        device_d_ptrs,
        rocblas_datatype_bf16_r,
        static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
        static_cast<rocblas_int>(w2_batch_count),
        rocblas_datatype_f32_r,
        rocblas_gemm_algo_solution_index,
        kQ1MoeRocblasW2SolutionIndex,
        rocblas_gemm_flags_none
    );
    const hipError_t sync_status = hipStreamSynchronize(stream);
    const rocblas_status restore_status =
        set_thread_rocblas_stream(handle, nullptr);
    if (!check_rocblas(
            w2_status,
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_w2",
            failure_stage,
            failure
        ) ||
        !check_hip(
            sync_status,
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_sync",
            failure_stage,
            failure
        ) ||
        !check_rocblas(
            restore_status,
            "qwen36_resident_decode_q1_moe_rocblas_prewarm_restore_stream",
            failure_stage,
            failure
        )) {
        return false;
    }
    const uint64_t elapsed_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
    ++workspace->q1_moe_rocblas_prewarm_count;
    workspace->q1_moe_rocblas_prewarm_elapsed_ns += elapsed_ns;
    workspace->q1_moe_rocblas_prewarm_ready = true;
    std::cerr
        << "BATCH_MARK qwen36_resident_decode_q1_moe_rocblas_prewarm"
        << " requested=1 active=1 pass=1"
        << " source_layer=" << weights->layer_index
        << " w13_solution_index=" << kQ1MoeRocblasW13SolutionIndex
        << " w2_solution_index=" << kQ1MoeRocblasW2SolutionIndex
        << " w13_batch_count=" << w13_batch_count
        << " w2_batch_count=" << w2_batch_count
        << " shared_batch=" << (include_shared ? 1 : 0)
        << " elapsed_ms="
        << (static_cast<double>(elapsed_ns) / 1000000.0)
        << " timing_scope=" << timing_scope
        << " dflash_active=0 mtp_active=0"
        << std::endl;
    return true;
}

bool ensure_q1_moe_rocblas_model_load_prewarm(
    std::string *failure_stage,
    std::string *failure
) {
    const bool full_rocblas_requested = env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_ROCBLAS_BATCHED"
    );
    const bool row_parallel_shared_hybrid_requested =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_0626_ROW_PARALLEL_BF16"
        ) &&
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_ROCBLAS_SHARED_BATCH"
        );
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_TRITON_0626_SELECTED"
        )) {
        bool loaded = false;
        if (env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_VLLM_TRITON"
            )) {
            hipFunction_t w13_function = nullptr;
            hipFunction_t silu_and_mul_function = nullptr;
            hipFunction_t w2_weighted_function = nullptr;
            hipFunction_t route_sum_function = nullptr;
            loaded = load_q1_moe_vllm_triton_functions(
                &w13_function,
                &silu_and_mul_function,
                &w2_weighted_function,
                &route_sum_function,
                failure_stage,
                failure
            );
        } else {
            hipFunction_t gate_up_function = nullptr;
            hipFunction_t down_function = nullptr;
            loaded = load_q1_moe_triton_0626_functions(
                &gate_up_function,
                &down_function,
                failure_stage,
                failure
            );
        }
        if (!loaded) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_TRITON_0626_QKV"
        )) {
        hipFunction_t qkv_function = nullptr;
        if (!load_q1_full_attention_triton_0626_qkv_function(
                &qkv_function,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    const unsigned int triton_0626_prefix_tokens =
        raw_env_flag_enabled("QRT_QWEN36_Q65536_COLD_PROBE")
            ? kQ65536ColdProbePrefillTokens
            : (raw_env_flag_enabled("QRT_QWEN36_Q32768_COLD_PROBE")
                   ? kQ32768ColdProbePrefillTokens
                   : (raw_env_flag_enabled("QRT_QWEN36_Q16384_COLD_PROBE")
                   ? kQ16384ColdProbePrefillTokens
                   : kRetainedPrefillTokens));
    const unsigned int triton_0626_prefix_private_tail_tokens =
        env_u32_or_default(
            "QRT_QWEN36_WHOLE_PROVIDER_PREFIX_CACHE_SUFFIX_TOKENS",
            0u
        ) +
        env_u32_or_default(
            "QRT_QWEN36_WHOLE_PROVIDER_PREFIX_CACHE_OUTPUT_TOKENS",
            1u
        );
    const unsigned int triton_0626_cold_output_tokens =
        env_u32_or_default(
            "QRT_QWEN36_WHOLE_PROVIDER_OUTPUT_TOKEN_CAPACITY",
            1u
        );
    const unsigned int triton_0626_required_tail_tokens =
        triton_0626_cold_output_tokens >
                triton_0626_prefix_private_tail_tokens
            ? triton_0626_cold_output_tokens
            : triton_0626_prefix_private_tail_tokens;
    const unsigned int triton_0626_preload_tail_tokens =
        triton_0626_required_tail_tokens >
                kQ1FullAttentionTriton0626MediumTailTokens
            ? kQ1FullAttentionTriton0626ProductTailTokens
            : (triton_0626_required_tail_tokens >
                       kQ1FullAttentionTriton0626ShortTailTokens
                   ? kQ1FullAttentionTriton0626MediumTailTokens
                   : kQ1FullAttentionTriton0626ShortTailTokens);
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_TRITON_0626_QK"
        )) {
        hipFunction_t qk_function = nullptr;
        if (!load_q1_full_attention_triton_0626_qk_function_variant(
                triton_0626_prefix_tokens,
                kQ1FullAttentionTriton0626ShortTailTokens,
                &qk_function,
                failure_stage,
                failure
            )) {
            return false;
        }
        if (triton_0626_preload_tail_tokens >
                kQ1FullAttentionTriton0626ShortTailTokens &&
            !load_q1_full_attention_triton_0626_qk_function_variant(
                triton_0626_prefix_tokens,
                triton_0626_preload_tail_tokens,
                &qk_function,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_FULL_ATTENTION_TRITON_0626_PV"
        )) {
        hipFunction_t pv_function = nullptr;
        if (!load_q1_full_attention_triton_0626_pv_function_variant(
                triton_0626_prefix_tokens,
                kQ1FullAttentionTriton0626ShortTailTokens,
                &pv_function,
                failure_stage,
                failure
            )) {
            return false;
        }
        if (triton_0626_preload_tail_tokens >
                kQ1FullAttentionTriton0626ShortTailTokens &&
            !load_q1_full_attention_triton_0626_pv_function_variant(
                triton_0626_prefix_tokens,
                triton_0626_preload_tail_tokens,
                &pv_function,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_TRITON_0626_QKVZ_AB"
        )) {
        hipFunction_t qkvz_ab_function = nullptr;
        const bool direct_f32 = env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_LINEAR_PERSISTENT_DIRECT_F32"
        );
        const unsigned int default_warps =
            q1_linear_triton_0626_qkvz_ab_default_warps();
        if (!load_q1_linear_triton_0626_qkvz_ab_function(
                direct_f32,
                default_warps,
                0u,
                &qkvz_ab_function,
                failure_stage,
                failure
            )) {
            return false;
        }
        const uint64_t alt_layer_mask =
            q1_linear_triton_0626_qkvz_ab_alt_layer_mask();
        const unsigned int alt_warps =
            q1_linear_triton_0626_qkvz_ab_alt_warps();
        if (alt_layer_mask != UINT64_C(0) && alt_warps != default_warps &&
            !load_q1_linear_triton_0626_qkvz_ab_function(
                direct_f32,
                alt_warps,
                0u,
                &qkvz_ab_function,
                failure_stage,
                failure
            )) {
            return false;
        }
        const uint64_t alt2_layer_mask =
            q1_linear_triton_0626_qkvz_ab_alt2_layer_mask();
        const unsigned int alt2_warps =
            q1_linear_triton_0626_qkvz_ab_alt2_warps();
        if (alt2_layer_mask != UINT64_C(0) &&
            !load_q1_linear_triton_0626_qkvz_ab_function(
                direct_f32,
                alt2_warps,
                1u,
                &qkvz_ab_function,
                failure_stage,
                failure
            )) {
            return false;
        }
        const uint64_t overlay_layer_mask =
            q1_linear_triton_0626_qkvz_ab_overlay_layer_mask();
        const unsigned int overlay_warps =
            q1_linear_triton_0626_qkvz_ab_overlay_warps();
        if (overlay_layer_mask != UINT64_C(0) &&
            !load_q1_linear_triton_0626_qkvz_ab_function(
                direct_f32,
                overlay_warps,
                2u,
                &qkvz_ab_function,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_TRITON_0626_OUTPUT_MATVEC"
        )) {
        hipFunction_t output_matvec_function = nullptr;
        if (!load_q1_triton_0626_output_matvec_function(
                &output_matvec_function,
                failure_stage,
                failure
            )) {
            return false;
        }
    }
    if (!full_rocblas_requested &&
        !row_parallel_shared_hybrid_requested) {
        return true;
    }
    if (g_q1_moe_rocblas_model_load_prewarm_ready) {
        return true;
    }
    if (!env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_Q1_MOE_PRIORITY_STREAM"
        )) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "qwen36_resident_decode_q1_moe_rocblas_model_load_dependency";
        }
        if (failure != nullptr) {
            *failure = "model-load rocBLAS prewarm requires priority stream";
        }
        return false;
    }

    void *norm_allocation = nullptr;
    void *wide0_allocation = nullptr;
    void *wide1_allocation = nullptr;
    hipStream_t stream = nullptr;
    auto cleanup = [&]() {
        if (stream != nullptr) {
            (void)hipStreamDestroy(stream);
            stream = nullptr;
        }
        free_device(wide1_allocation);
        free_device(wide0_allocation);
        free_device(norm_allocation);
        wide1_allocation = nullptr;
        wide0_allocation = nullptr;
        norm_allocation = nullptr;
    };
    if (!check_hip(
            qrt_descriptor_device_malloc(
                &norm_allocation,
                QRT_QWEN36_HIDDEN_SIZE * sizeof(uint16_t)
            ),
            "qwen36_resident_decode_q1_moe_rocblas_model_load_norm",
            failure_stage,
            failure
        ) ||
        !check_hip(
            qrt_descriptor_device_malloc(
                &wide0_allocation,
                kQwen36ResidentDecodeActivationWideBytes
            ),
            "qwen36_resident_decode_q1_moe_rocblas_model_load_wide0",
            failure_stage,
            failure
        ) ||
        !check_hip(
            qrt_descriptor_device_malloc(
                &wide1_allocation,
                kQwen36ResidentDecodeActivationWideBytes
            ),
            "qwen36_resident_decode_q1_moe_rocblas_model_load_wide1",
            failure_stage,
            failure
        )) {
        cleanup();
        return false;
    }
    int priority_least = 0;
    int priority_greatest = 0;
    if (!check_hip(
            hipDeviceGetStreamPriorityRange(
                &priority_least,
                &priority_greatest
            ),
            "qwen36_resident_decode_q1_moe_rocblas_model_load_priority_range",
            failure_stage,
            failure
        ) ||
        !check_hip(
            hipStreamCreateWithPriority(
                &stream,
                hipStreamNonBlocking,
                priority_greatest
            ),
            "qwen36_resident_decode_q1_moe_rocblas_model_load_stream",
            failure_stage,
            failure
        )) {
        cleanup();
        return false;
    }
    Qwen36ResidentDecodeActivationWorkspace workspace;
    workspace.device_norm_bf16 = static_cast<uint16_t *>(norm_allocation);
    workspace.device_wide[0] = static_cast<float *>(wide0_allocation);
    workspace.device_wide[1] = static_cast<float *>(wide1_allocation);
    workspace.q1_moe_priority_stream = stream;
    workspace.q1_moe_priority_stream_requested = true;
    workspace.q1_moe_priority_stream_ready = true;
    const bool pass = prewarm_q1_moe_rocblas_batched(
        &workspace,
        "model_engine_load_preload",
        failure_stage,
        failure
    );
    if (pass) {
        g_q1_moe_rocblas_model_load_prewarm_count =
            workspace.q1_moe_rocblas_prewarm_count;
        g_q1_moe_rocblas_model_load_prewarm_elapsed_ns =
            workspace.q1_moe_rocblas_prewarm_elapsed_ns;
        g_q1_moe_rocblas_model_load_prewarm_ready =
            workspace.q1_moe_rocblas_prewarm_ready;
    }
    cleanup();
    return pass && g_q1_moe_rocblas_model_load_prewarm_ready;
}
#endif
#endif

#ifdef QRT_ENABLE_ROCBLAS_DECODE_PROJECTIONS
bool descriptor_decode_rocblas_projection_enabled(
    const Layer1InputRmsnormRun &input_rmsnorm_run,
    unsigned int layer_index
) {
    return env_flag_enabled(
               "QRT_PREFILL_DESCRIPTOR_BATCH_ROCBLAS_DECODE_PROJECTIONS"
           ) &&
        layer_index >= 2u &&
        input_rmsnorm_run.selected_token_count == 1u;
}

bool run_descriptor_decode_rocblas_projection_step(
    const Layer1InputRmsnormRun &input_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    unsigned int layer_index,
    qrt_qwen36_tensor_kind_t tensor_kind,
    const char *name,
    const char *stage,
    unsigned int rows,
    const char *failure_prefix,
    Layer1SelectedProjectionRun *run
) {
    (void)prefill_tokens;
    if (run == nullptr) {
        return false;
    }
    run->name = name;
    run->stage = stage;
    run->weight_bytes = static_cast<uint64_t>(rows) *
                        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
                        sizeof(uint16_t);
    run->selected_token_ids = input_rmsnorm_run.selected_token_ids;
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = run->selected_token_count * static_cast<size_t>(rows);
    run->output_bytes = run->output_elements * sizeof(float);

    if (!input_rmsnorm_run.correctness_pass ||
        input_rmsnorm_run.gpu_output.size() !=
            run->selected_token_count * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE) ||
        run->selected_token_count != 1u) {
        run->failure_stage = std::string(failure_prefix) + "_rocblas_input_contract";
        run->failure =
            "rocBLAS decode projection requires one selected RMSNorm output token";
        return false;
    }
    if (!tensor_name_for_layer_kind(
            layer_index,
            tensor_kind,
            &run->tensor_name,
            &run->failure
        )) {
        run->failure_stage =
            std::string("tensor_name_") + failure_prefix + "_rocblas_decode_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage =
            std::string("locate_") + failure_prefix + "_rocblas_decode_phase";
        return false;
    }
    if (run->location.data_end < run->location.data_begin ||
        run->location.data_end - run->location.data_begin != run->weight_bytes) {
        run->failure_stage =
            std::string("shape_") + failure_prefix + "_rocblas_decode_phase";
        run->failure = "rocBLAS decode projection tensor does not match expected byte shape";
        return false;
    }
    if (!read_safetensors_bytes(
            model_dir,
            run->location,
            0,
            run->weight_bytes,
            &run->weights,
            &run->failure
        )) {
        run->failure_stage =
            std::string("read_") + failure_prefix + "_rocblas_decode_phase";
        return false;
    }

    std::vector<uint16_t> selected_input_bf16;
    selected_input_bf16.reserve(input_rmsnorm_run.gpu_output.size());
    for (float value : input_rmsnorm_run.gpu_output) {
        selected_input_bf16.push_back(qrt_float_to_bf16(value));
    }
    run->gpu_output.assign(run->output_elements, 0.0f);
    run->weight_hash = qrt_fnv1a64_update_bytes(
        UINT64_C(1469598103934665603),
        run->weights.data(),
        static_cast<size_t>(run->weight_bytes)
    );

    const uint16_t *device_weights = nullptr;
    bool weight_cache_hit = false;
    uint16_t *device_input_bf16 = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    rocblas_handle handle = nullptr;
    const std::string prefix = std::string(failure_prefix) + "_rocblas";
    const size_t input_bytes = selected_input_bf16.size() * sizeof(uint16_t);
    const dim3 round_block(kThreads);
    const dim3 round_grid(
        static_cast<unsigned int>(
            (run->output_elements + static_cast<size_t>(kThreads) - 1u) /
            static_cast<size_t>(kThreads)
        )
    );

    if (!get_or_store_decode_projection_device_weight_cache_entry(
            run->tensor_name,
            run->weights.data(),
            run->weight_bytes,
            run->weight_hash,
            &device_weights,
            &weight_cache_hit,
            &run->failure
        )) {
        run->failure_stage = prefix + "_device_weight_cache";
        goto cleanup;
    }
    if (!check_hip(
            qrt_descriptor_device_malloc(
                reinterpret_cast<void **>(&device_input_bf16),
                input_bytes
            ),
            "hipMalloc(" + prefix + "_input)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            qrt_descriptor_device_malloc(
                reinterpret_cast<void **>(&device_output),
                run->output_bytes
            ),
            "hipMalloc(" + prefix + "_output)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMemcpy(
                device_input_bf16,
                selected_input_bf16.data(),
                input_bytes,
                hipMemcpyHostToDevice
            ),
            "hipMemcpy(" + prefix + "_input)",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMemset(device_output, 0, run->output_bytes),
            "hipMemset(" + prefix + "_output)",
            &run->failure_stage,
            &run->failure
        ) ||
        !get_thread_rocblas_handle(
            &handle,
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(
            hipEventCreate(&start),
            "hipEventCreate(start_" + prefix + ")",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipEventCreate(&stop),
            "hipEventCreate(stop_" + prefix + ")",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipEventRecord(start, 0),
            "hipEventRecord(start_" + prefix + ")",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    {
        const float alpha = 1.0f;
        const float beta = 0.0f;
        if (!check_rocblas(
                rocblas_gemm_ex(
                    handle,
                    rocblas_operation_transpose,
                    rocblas_operation_none,
                    static_cast<rocblas_int>(rows),
                    static_cast<rocblas_int>(run->selected_token_count),
                    static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
                    &alpha,
                    device_weights,
                    rocblas_datatype_bf16_r,
                    static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
                    device_input_bf16,
                    rocblas_datatype_bf16_r,
                    static_cast<rocblas_int>(QRT_QWEN36_HIDDEN_SIZE),
                    &beta,
                    device_output,
                    rocblas_datatype_f32_r,
                    static_cast<rocblas_int>(rows),
                    device_output,
                    rocblas_datatype_f32_r,
                    static_cast<rocblas_int>(rows),
                    rocblas_datatype_f32_r,
                    rocblas_gemm_algo_standard,
                    0,
                    0
                ),
                "rocblas_gemm_ex(" + prefix + ")",
                &run->failure_stage,
                &run->failure
            )) {
            goto cleanup;
        }
        hipLaunchKernelGGL(
            round_f32_outputs_to_bf16_kernel,
            round_grid,
            round_block,
            0,
            0,
            device_output,
            run->output_elements
        );
    }
    if (!check_hip(
            hipGetLastError(),
            "round_kernel_launch_" + prefix,
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipEventRecord(stop, 0),
            "hipEventRecord(stop_" + prefix + ")",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipEventSynchronize(stop),
            "hipEventSynchronize(stop_" + prefix + ")",
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipEventElapsedTime(&run->elapsed_ms, start, stop),
            "hipEventElapsedTime_" + prefix,
            &run->failure_stage,
            &run->failure
        ) ||
        !check_hip(
            hipMemcpy(
                run->gpu_output.data(),
                device_output,
                run->output_bytes,
                hipMemcpyDeviceToHost
            ),
            "hipMemcpy(" + prefix + "_output)",
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (size_t selected_index = 0;
             selected_index < run->selected_token_count;
             ++selected_index) {
            const unsigned int token = run->selected_token_ids[selected_index];
            for (unsigned int row : selected_rows(rows)) {
                const float reference = selected_bf16_projection_cpu_value(
                    run->weights.data(),
                    selected_input_bf16,
                    selected_index,
                    row
                );
                const size_t output_index =
                    selected_index * static_cast<size_t>(rows) + row;
                const float gpu = run->gpu_output[output_index];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->selected_token_ids_hash = qrt_fnv1a64_bytes(
            run->selected_token_ids.data(),
            run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
        );
        run->input_hash = qrt_fnv1a64_f32(
            input_rmsnorm_run.gpu_output.data(),
            input_rmsnorm_run.gpu_output.size()
        );
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->avg_ms =
            static_cast<double>(run->elapsed_ms) /
            static_cast<double>(kSelectedProjectionTimedIterations);
        run->selected_tokens_per_second =
            run->avg_ms > 0.0
                ? static_cast<double>(run->selected_token_count) /
                      (run->avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kSelectedProjectionTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = "correctness_" + prefix;
            run->failure =
                "rocBLAS decode projection boundary exceeded selected CPU tolerance";
        }
    }

    std::cerr << "BATCH_MARK rocblas_decode_projection layer="
              << layer_index
              << " tensor=" << run->tensor_name
              << " rows=" << rows
              << " selected_tokens=" << run->selected_token_count
              << " cache_hit=" << (weight_cache_hit ? 1 : 0)
              << " elapsed_ms=" << run->elapsed_ms
              << " max_abs_diff=" << run->max_abs_diff
              << std::endl;

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_input_bf16);
    return run->failure_stage.empty() && run->correctness_pass;
}
#endif

bool run_descriptor_decode_selected_projection_step(
    const Layer1InputRmsnormRun &input_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    unsigned int layer_index,
    qrt_qwen36_tensor_kind_t tensor_kind,
    const char *name,
    const char *stage,
    unsigned int rows,
    const char *failure_prefix,
    Layer1SelectedProjectionRun *run,
    bool prefer_resident_device_weight = false
) {
#ifdef QRT_ENABLE_ROCBLAS_DECODE_PROJECTIONS
    if (descriptor_decode_rocblas_projection_enabled(
            input_rmsnorm_run,
            layer_index
        )) {
        return run_descriptor_decode_rocblas_projection_step(
            input_rmsnorm_run,
            model_dir,
            prefill_tokens,
            layer_index,
            tensor_kind,
            name,
            stage,
            rows,
            failure_prefix,
            run
        );
    }
#else
    (void)layer_index;
#endif
    return run_layer1_selected_projection(
        input_rmsnorm_run,
        model_dir,
        prefill_tokens,
        layer_index,
        tensor_kind,
        name,
        stage,
        rows,
        failure_prefix,
        run,
        prefer_resident_device_weight
    );
}

