bool run_selected_conv_qkv_window(
    unsigned int layer_index,
    const std::vector<unsigned int> &target_token_ids,
    const char *name,
    const char *stage,
    const char *failure_prefix,
    const Layer1SelectedProjectionRun &window_qkv_run,
    const OutputResidualRun &window_output_residual_run,
    const Layer1InputRmsnormRun &window_input_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    double window_materialization_avg_ms,
    Layer1ConvWindowRun *run
) {
    (void)prefill_tokens;
    run->name = name;
    run->stage = stage;
    run->target_token_ids = target_token_ids;
    run->window_token_ids = window_qkv_run.selected_token_ids;
    run->target_token_count = run->target_token_ids.size();
    run->window_token_count = run->window_token_ids.size();
    run->weight_bytes = static_cast<uint64_t>(kQkvRows) *
                        static_cast<uint64_t>(kConvKernel) *
                        sizeof(uint16_t);
    run->output_elements = run->target_token_count * static_cast<size_t>(kQkvRows);
    run->output_bytes = run->output_elements * sizeof(float);
    run->window_materialization_avg_ms = window_materialization_avg_ms;

    if (!window_qkv_run.correctness_pass ||
        window_qkv_run.gpu_output.size() != run->window_token_count * static_cast<size_t>(kQkvRows) ||
        run->target_token_count == 0 ||
        run->window_token_count == 0) {
        run->failure_stage = std::string(failure_prefix) + "_input_contract";
        run->failure = "window QKV projection output is missing or has unexpected shape";
        return false;
    }
    if (!build_conv_source_window_indices(run->target_token_ids, run->window_token_ids, &run->source_window_indices)) {
        run->failure_stage = std::string("source_window_indices_") + failure_prefix + "_prefill_phase";
        run->failure = "selected window tokens do not cover causal conv_qkv sources";
        return false;
    }
    if (!tensor_name_for_layer_kind(layer_index, QRT_QWEN36_TENSOR_LINEAR_ATTN_CONV, &run->tensor_name, &run->failure)) {
        run->failure_stage = std::string("tensor_name_") + failure_prefix + "_prefill_phase";
        return false;
    }
    if (!locate_tensor(model_dir, run->tensor_name, &run->location, &run->failure)) {
        run->failure_stage = std::string("locate_") + failure_prefix + "_prefill_phase";
        return false;
    }
    if (!read_safetensors_bytes(model_dir, run->location, 0, run->weight_bytes, &run->weights, &run->failure)) {
        run->failure_stage = std::string("read_") + failure_prefix + "_prefill_phase";
        return false;
    }
    run->gpu_output.assign(run->output_elements, 0.0f);

    float *device_qkv = nullptr;
    uint16_t *device_weights = nullptr;
    uint32_t *device_source_indices = nullptr;
    float *device_output = nullptr;
    hipEvent_t start{};
    hipEvent_t stop{};
    const dim3 block(kThreads);
    const dim3 grid((kQkvRows + kThreads - 1u) / kThreads, static_cast<unsigned int>(run->target_token_count));
    const std::string alloc_input_stage = std::string("hipMalloc(") + failure_prefix + "_input)";
    const std::string alloc_weights_stage = std::string("hipMalloc(") + failure_prefix + "_weights)";
    const std::string alloc_source_stage = std::string("hipMalloc(") + failure_prefix + "_source_indices)";
    const std::string alloc_output_stage = std::string("hipMalloc(") + failure_prefix + "_output)";
    const std::string copy_input_stage = std::string("hipMemcpy(") + failure_prefix + "_input)";
    const std::string copy_weights_stage = std::string("hipMemcpy(") + failure_prefix + "_weights)";
    const std::string copy_source_stage = std::string("hipMemcpy(") + failure_prefix + "_source_indices)";
    const std::string memset_output_stage = std::string("hipMemset(") + failure_prefix + "_output)";
    const std::string warmup_launch_stage = std::string("warmup_kernel_launch_") + failure_prefix + "_prefill_phase";
    const std::string warmup_sync_stage = std::string("warmup_sync_") + failure_prefix + "_prefill_phase";
    const std::string event_start_create_stage = std::string("hipEventCreate(start_") + failure_prefix + "_prefill_phase)";
    const std::string event_stop_create_stage = std::string("hipEventCreate(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_start_record_stage = std::string("hipEventRecord(start_") + failure_prefix + "_prefill_phase)";
    const std::string timed_launch_stage = std::string("timed_kernel_launch_") + failure_prefix + "_prefill_phase";
    const std::string event_stop_record_stage = std::string("hipEventRecord(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_stop_sync_stage = std::string("hipEventSynchronize(stop_") + failure_prefix + "_prefill_phase)";
    const std::string event_elapsed_stage = std::string("hipEventElapsedTime_") + failure_prefix + "_prefill_phase";
    const std::string copy_output_stage = std::string("hipMemcpy(") + failure_prefix + "_output)";

    if (!check_hip(hipMalloc(reinterpret_cast<void **>(&device_qkv), window_qkv_run.output_bytes), alloc_input_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_weights), run->weight_bytes), alloc_weights_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_source_indices), run->source_window_indices.size() * sizeof(uint32_t)), alloc_source_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMalloc(reinterpret_cast<void **>(&device_output), run->output_bytes), alloc_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!check_hip(hipMemcpy(device_qkv, window_qkv_run.gpu_output.data(), window_qkv_run.output_bytes, hipMemcpyHostToDevice), copy_input_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_weights, run->weights.data(), run->weight_bytes, hipMemcpyHostToDevice), copy_weights_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMemcpy(device_source_indices, run->source_window_indices.data(), run->source_window_indices.size() * sizeof(uint32_t), hipMemcpyHostToDevice), copy_source_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipMemset(device_output, 0, run->output_bytes), memset_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }

    for (int iter = 0; iter < kWarmupIterations; ++iter) {
        hipLaunchKernelGGL(
            selected_conv_qkv_window_kernel,
            grid,
            block,
            0,
            0,
            device_qkv,
            device_weights,
            device_source_indices,
            device_output,
            static_cast<unsigned int>(run->target_token_count),
            0u,
            nullptr,
            nullptr,
            0u,
            nullptr
        );
    }
    if (!check_warmup_completion(
            hipGetLastError(),
            warmup_launch_stage,
            warmup_sync_stage,
            &run->failure_stage,
            &run->failure
        )) {
        goto cleanup;
    }

    if (!check_hip(hipEventCreate(&start), event_start_create_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventCreate(&stop), event_stop_create_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(start, 0), event_start_record_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    for (int iter = 0; iter < kTimedIterations; ++iter) {
        hipLaunchKernelGGL(
            selected_conv_qkv_window_kernel,
            grid,
            block,
            0,
            0,
            device_qkv,
            device_weights,
            device_source_indices,
            device_output,
            static_cast<unsigned int>(run->target_token_count),
            0u,
            nullptr,
            nullptr,
            0u,
            nullptr
        );
    }
    if (!check_hip(hipGetLastError(), timed_launch_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventRecord(stop, 0), event_stop_record_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventSynchronize(stop), event_stop_sync_stage, &run->failure_stage, &run->failure) ||
        !check_hip(hipEventElapsedTime(&run->elapsed_ms, start, stop), event_elapsed_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
        run->timing_fallback_used = true;
        const auto wall_start = std::chrono::steady_clock::now();
        for (int iter = 0; iter < kTimedIterations; ++iter) {
            hipLaunchKernelGGL(
                selected_conv_qkv_window_kernel,
                grid,
                block,
                0,
                0,
                device_qkv,
                device_weights,
                device_source_indices,
                device_output,
                static_cast<unsigned int>(run->target_token_count),
                0u,
                nullptr,
                nullptr,
                0u,
                nullptr
            );
        }
        if (!check_hip(hipGetLastError(), std::string("fallback_timed_kernel_launch_") + failure_prefix + "_prefill_phase", &run->failure_stage, &run->failure) ||
            !check_hip(hipDeviceSynchronize(), std::string("fallback_timed_sync_") + failure_prefix + "_prefill_phase", &run->failure_stage, &run->failure)) {
            goto cleanup;
        }
        const auto wall_stop = std::chrono::steady_clock::now();
        run->elapsed_ms = static_cast<float>(
            std::chrono::duration<double, std::milli>(wall_stop - wall_start).count()
        );
        if (!std::isfinite(run->elapsed_ms) || run->elapsed_ms < 0.0f) {
            run->failure_stage = std::string("timing_") + failure_prefix + "_prefill_phase";
            run->failure = "selected conv_qkv window fallback timing was negative or non-finite";
            goto cleanup;
        }
    }
    if (!check_hip(hipMemcpy(run->gpu_output.data(), device_output, run->output_bytes, hipMemcpyDeviceToHost), copy_output_stage, &run->failure_stage, &run->failure)) {
        goto cleanup;
    }
    {
        std::vector<float> selected_reference;
        std::vector<float> selected_gpu;
        for (size_t target_index = 0; target_index < run->target_token_count; ++target_index) {
            const unsigned int token = run->target_token_ids[target_index];
            for (unsigned int row : selected_rows(kQkvRows)) {
                const float reference = selected_conv_window_cpu_value(
                    window_qkv_run.gpu_output,
                    run->weights.data(),
                    run->source_window_indices,
                    target_index,
                    row
                );
                const float gpu = run->gpu_output[target_index * static_cast<size_t>(kQkvRows) + row];
                const float diff = std::fabs(reference - gpu);
                run->samples.push_back({token, row, reference, gpu, diff});
                selected_reference.push_back(reference);
                selected_gpu.push_back(gpu);
                if (run->checked_values == 0 || diff > run->max_abs_diff) {
                    run->max_abs_diff = diff;
                }
                ++run->checked_values;
            }
        }
        run->selected_reference_hash =
            qrt_fnv1a64_f32(selected_reference.data(), selected_reference.size());
        run->selected_gpu_hash =
            qrt_fnv1a64_f32(selected_gpu.data(), selected_gpu.size());
        run->target_token_ids_hash = qrt_fnv1a64_bytes(
            run->target_token_ids.data(),
            run->target_token_ids.size() * sizeof(run->target_token_ids[0])
        );
        run->window_token_ids_hash = qrt_fnv1a64_bytes(
            run->window_token_ids.data(),
            run->window_token_ids.size() * sizeof(run->window_token_ids[0])
        );
        run->source_window_indices_hash = qrt_fnv1a64_bytes(
            run->source_window_indices.data(),
            run->source_window_indices.size() * sizeof(run->source_window_indices[0])
        );
        run->qkv_window_input_hash =
            qrt_fnv1a64_f32(window_qkv_run.gpu_output.data(), window_qkv_run.gpu_output.size());
        run->weight_hash = qrt_fnv1a64_update_bytes(
            UINT64_C(1469598103934665603),
            run->weights.data(),
            static_cast<size_t>(run->weight_bytes)
        );
        run->gpu_output_hash =
            qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
        run->window_output_residual_hash = qrt_fnv1a64_f32(
            window_output_residual_run.gpu_output.data(),
            window_output_residual_run.gpu_output.size()
        );
        run->window_input_rmsnorm_hash = qrt_fnv1a64_f32(
            window_input_rmsnorm_run.gpu_output.data(),
            window_input_rmsnorm_run.gpu_output.size()
        );
        run->conv_avg_ms = static_cast<double>(run->elapsed_ms) / static_cast<double>(kTimedIterations);
        run->phase_total_avg_ms = run->window_materialization_avg_ms + run->conv_avg_ms;
        run->selected_tokens_per_second =
            run->phase_total_avg_ms > 0.0
                ? static_cast<double>(run->target_token_count) / (run->phase_total_avg_ms / 1000.0)
                : 0.0;
        run->correctness_pass =
            run->checked_values > 0 &&
            std::isfinite(run->max_abs_diff) &&
            run->max_abs_diff <= kTolerance;
        if (!run->correctness_pass) {
            run->failure_stage = std::string("correctness_") + failure_prefix + "_prefill_phase";
            run->failure = "selected CPU/HIP conv_qkv window boundary exceeded tolerance";
        }
    }

cleanup:
    destroy_event(stop);
    destroy_event(start);
    free_device(device_output);
    free_device(device_source_indices);
    free_device(device_weights);
    free_device(device_qkv);
    return run->failure_stage.empty() && run->correctness_pass;
}

bool run_layer1_conv_qkv_window_for_targets(
    const std::vector<unsigned int> &target_token_ids,
    const Layer1SelectedProjectionRun &window_qkv_run,
    const OutputResidualRun &window_output_residual_run,
    const Layer1InputRmsnormRun &window_input_rmsnorm_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    double window_materialization_avg_ms,
    Layer1ConvWindowRun *run
) {
    return run_selected_conv_qkv_window(
        1u,
        target_token_ids,
        "layer1_conv_qkv_window",
        "layer1_selected_conv_qkv_window_prefill_phase",
        "layer1_conv_qkv_window",
        window_qkv_run,
        window_output_residual_run,
        window_input_rmsnorm_run,
        model_dir,
        prefill_tokens,
        window_materialization_avg_ms,
        run
    );
}

