bool emit_qwen36_exact_arbitrary_layer_output_trace(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    const float *device_output,
    std::string *failure_stage,
    std::string *failure
) {
    if (!dump_qwen36_exact_arbitrary_full_bf16_value_surface(
            "QRT_QWEN36_FULL_LAYER_COMBINED_DUMP_PATH",
            "QRT_QWEN36_FULL_LAYER_COMBINED_DUMP_LAYER",
            "QRT_QWEN36_FULL_LAYER_COMBINED_DUMP_TOKENS",
            "layer_combined",
            layer_index,
            prefill_tokens,
            device_output,
            static_cast<size_t>(prefill_tokens) *
                QRT_QWEN36_HIDDEN_SIZE,
            failure_stage,
            failure
        )) {
        return false;
    }
    if (!raw_env_flag_enabled(
            "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE"
        )) {
        return true;
    }
    if (prefill_tokens == 0u || device_output == nullptr ||
        failure_stage == nullptr || failure == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "exact_arbitrary_layer_output_trace_contract";
        }
        if (failure != nullptr) {
            *failure =
                "exact-arbitrary layer output tracing requires a valid device output";
        }
        return false;
    }
    const unsigned int trace_position = env_u32_or_default(
        "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE_POSITION",
        prefill_tokens - 1u
    );
    if (trace_position >= prefill_tokens) {
        *failure_stage =
            "exact_arbitrary_layer_output_trace_position";
        *failure =
            "exact-arbitrary layer output trace position exceeds the active prefill shape";
        return false;
    }
    std::array<float, QRT_QWEN36_HIDDEN_SIZE> terminal_hidden{};
    const size_t terminal_offset =
        static_cast<size_t>(trace_position) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const hipError_t copy_status = hipMemcpy(
        terminal_hidden.data(),
        device_output + terminal_offset,
        terminal_hidden.size() * sizeof(float),
        hipMemcpyDeviceToHost
    );
    if (copy_status != hipSuccess) {
        *failure_stage =
            "exact_arbitrary_layer_output_trace_copy";
        *failure = hipGetErrorString(copy_status);
        return false;
    }
    double sum = 0.0;
    double sum_sq = 0.0;
    float minimum = std::numeric_limits<float>::infinity();
    float maximum = -std::numeric_limits<float>::infinity();
    for (float value : terminal_hidden) {
        if (!std::isfinite(value)) {
            *failure_stage =
                "exact_arbitrary_layer_output_trace_nonfinite";
            *failure =
                "exact-arbitrary layer output trace contains a non-finite value";
            return false;
        }
        minimum = (std::min)(minimum, value);
        maximum = (std::max)(maximum, value);
        sum += static_cast<double>(value);
        sum_sq += static_cast<double>(value) *
            static_cast<double>(value);
    }
    std::ostringstream marker;
    marker << std::setprecision(
                  std::numeric_limits<double>::max_digits10
              )
           << "BATCH_MARK qwen36_exact_arbitrary_layer_output_trace"
           << " layer=" << layer_index
           << " prefill_tokens=" << prefill_tokens
           << " trace_position=" << trace_position
           << " hidden_size=" << terminal_hidden.size()
           << " min=" << minimum
           << " max=" << maximum
           << " mean="
           << (sum / static_cast<double>(terminal_hidden.size()))
           << " rms="
           << std::sqrt(
                  sum_sq /
                  static_cast<double>(terminal_hidden.size())
              )
           << " fnv1a64="
           << hex_u64(
                  qrt_fnv1a64_f32(
                      terminal_hidden.data(),
                      terminal_hidden.size()
                  )
              )
           << " f32_bits=" << std::hex << std::setfill('0');
    for (size_t index = 0u; index < terminal_hidden.size(); ++index) {
        if (index != 0u) {
            marker << ',';
        }
        uint32_t bits = 0u;
        std::memcpy(&bits, &terminal_hidden[index], sizeof(bits));
        marker << std::setw(8) << bits;
    }
    marker << " diagnostic_only=1 numerical_correctness_claimed=0";
    std::cerr << marker.str() << std::endl;
    return true;
}

bool emit_qwen36_exact_arbitrary_final_norm_boundary_trace(
    const char *stage,
    unsigned int prefill_tokens,
    const std::vector<unsigned int> &selected_token_ids,
    const float *device_rows,
    std::string *failure_stage,
    std::string *failure
) {
    if (!raw_env_flag_enabled(
            "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE"
        )) {
        return true;
    }
    if (stage == nullptr || prefill_tokens == 0u ||
        selected_token_ids.empty() || device_rows == nullptr ||
        failure_stage == nullptr || failure == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "exact_arbitrary_final_norm_boundary_trace_contract";
        }
        if (failure != nullptr) {
            *failure =
                "final-norm boundary tracing requires selected device rows";
        }
        return false;
    }
    const unsigned int trace_position = env_u32_or_default(
        "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE_POSITION",
        prefill_tokens - 1u
    );
    const auto selected = std::find(
        selected_token_ids.begin(),
        selected_token_ids.end(),
        trace_position
    );
    if (selected == selected_token_ids.end()) {
        std::cerr
            << "BATCH_MARK qwen36_exact_arbitrary_final_norm_boundary_trace"
            << " stage=" << stage
            << " prefill_tokens=" << prefill_tokens
            << " trace_position=" << trace_position
            << " selected=0 diagnostic_only=1"
            << " numerical_correctness_claimed=0"
            << std::endl;
        return true;
    }
    const size_t selected_index = static_cast<size_t>(
        std::distance(selected_token_ids.begin(), selected)
    );
    std::array<float, QRT_QWEN36_HIDDEN_SIZE> host_row{};
    const hipError_t copy_status = hipMemcpy(
        host_row.data(),
        device_rows +
            selected_index * static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE),
        host_row.size() * sizeof(host_row[0u]),
        hipMemcpyDeviceToHost
    );
    if (copy_status != hipSuccess) {
        *failure_stage =
            "exact_arbitrary_final_norm_boundary_trace_copy";
        *failure = hipGetErrorString(copy_status);
        return false;
    }
    double sum_sq = 0.0;
    for (float value : host_row) {
        if (!std::isfinite(value)) {
            *failure_stage =
                "exact_arbitrary_final_norm_boundary_trace_nonfinite";
            *failure =
                "final-norm boundary trace contains a non-finite value";
            return false;
        }
        sum_sq += static_cast<double>(value) *
            static_cast<double>(value);
    }
    std::ostringstream marker;
    marker
        << std::setprecision(std::numeric_limits<double>::max_digits10)
        << "BATCH_MARK qwen36_exact_arbitrary_final_norm_boundary_trace"
        << " stage=" << stage
        << " prefill_tokens=" << prefill_tokens
        << " trace_position=" << trace_position
        << " selected=1 selected_index=" << selected_index
        << " rms="
        << std::sqrt(sum_sq / static_cast<double>(host_row.size()))
        << " fnv1a64="
        << hex_u64(qrt_fnv1a64_f32(host_row.data(), host_row.size()))
        << " f32_bits=" << std::hex << std::setfill('0');
    for (size_t index = 0u; index < host_row.size(); ++index) {
        if (index != 0u) {
            marker << ',';
        }
        uint32_t bits = 0u;
        std::memcpy(&bits, &host_row[index], sizeof(bits));
        marker << std::setw(8) << bits;
    }
    marker << " diagnostic_only=1 numerical_correctness_claimed=0";
    std::cerr << marker.str() << std::endl;
    return true;
}

bool qwen36_all_norm_capture_active(unsigned int tokens) {
    const char *prefix = std::getenv("QRT_QWEN36_ALL_NORM_DUMP_PREFIX");
    return prefix != nullptr && prefix[0] != '\0' &&
        tokens == env_u32_or_default("QRT_QWEN36_ALL_NORM_DUMP_TOKENS", 0u);
}

bool dump_qwen36_selected_full_stage(
    unsigned int layer,
    unsigned int tokens,
    const char *surface,
    const void *device_values,
    bool source_bf16,
    size_t row_width,
    std::string *failure_stage,
    std::string *failure
) {
    const bool all_norm = qwen36_all_norm_capture_active(tokens) &&
        surface != nullptr &&
        (std::strcmp(surface, "input_rmsnorm") == 0 ||
         std::strcmp(surface, "post_attention_rmsnorm") == 0);
    const char *prefix = std::getenv(all_norm
        ? "QRT_QWEN36_ALL_NORM_DUMP_PREFIX"
        : "QRT_QWEN36_FULL_STAGE_DUMP_PREFIX");
    if (!all_norm && (prefix == nullptr || prefix[0] == '\0' ||
        layer != env_u32_or_default("QRT_QWEN36_FULL_STAGE_DUMP_LAYER", UINT_MAX) ||
        tokens != env_u32_or_default("QRT_QWEN36_FULL_STAGE_DUMP_TOKENS", 0u))) {
        return true;
    }
    if (failure_stage == nullptr || failure == nullptr) {
        return false;
    }
    const auto reject = [&](const char *reason) {
        *failure_stage = "selected_full_stage_dump";
        *failure = reason;
        return false;
    };
    if (tokens == 0u || tokens > 8192u || row_width == 0u ||
        row_width > 9216u || surface == nullptr || device_values == nullptr ||
        (all_norm && (layer >= QRT_QWEN36_LAYER_COUNT || row_width != QRT_QWEN36_HIDDEN_SIZE))) {
        return reject("full stage capture requires a bounded prefill surface");
    }
    const std::string label(surface);
    if (label.empty() || label.find_first_not_of(
            "abcdefghijklmnopqrstuvwxyz0123456789_") != std::string::npos) {
        return reject("invalid full stage capture label");
    }
    const size_t elements = static_cast<size_t>(tokens) * row_width;
    const size_t bytes = elements * sizeof(uint16_t);
    const size_t maximum_bytes = all_norm ? size_t{3} << 30 : size_t{768} << 20;
    // This observer is entered by the serialized native prefill owner. Its
    // accounting covers every selected surface in the process, including
    // duplicate stage/boundary observations, instead of bounding each alone.
    struct Accounting {
        size_t bytes = 0u;
        unsigned int files = 0u;
        double copy_seconds = 0.0;
        std::chrono::steady_clock::time_point start;
    };
    static Accounting scopes[2];
    Accounting &accounting = scopes[all_norm ? 1u : 0u];
    auto &captured_bytes = accounting.bytes;
    auto &captured_files = accounting.files;
    auto &capture_start = accounting.start;
    const auto copy_start = std::chrono::steady_clock::now();
    if (captured_files == 0u) {
        capture_start = std::chrono::steady_clock::now();
    }
    if (captured_files >= (all_norm ? 80u : 24u) || bytes > maximum_bytes - captured_bytes) {
        return reject("aggregate full stage capture ceiling exceeded");
    }
    const std::string path = std::string(prefix) +
        (all_norm ? "-layer" + std::to_string(layer) : "") +
        "-" + label + "-bf16.bin";
    std::ifstream existing(path, std::ios::binary);
    if (existing.good()) {
        return reject("refusing to overwrite a full stage capture");
    }
    std::ofstream output(path, std::ios::binary | std::ios::trunc);
    if (!output) {
        return reject("cannot create full stage capture");
    }
    constexpr size_t kChunkElements = size_t{1} << 18;
    std::vector<uint16_t> bf16((std::min)(elements, kChunkElements));
    std::vector<float> f32(source_bf16 ? 0u : bf16.size());
    for (size_t begin = 0u; begin < elements; begin += kChunkElements) {
        // All-layer observation spans the bounded model run. Account only
        // observer work there; inference time between layers is not copy time.
        const double seconds = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - (all_norm ? copy_start : capture_start)).count();
        if ((all_norm ? accounting.copy_seconds + seconds : seconds) > (all_norm ? 60.0 : 30.0)) {
            return reject("aggregate full stage capture deadline exceeded");
        }
        const size_t count = (std::min)(elements - begin, kChunkElements);
        const hipError_t status = source_bf16
            ? hipMemcpy(bf16.data(),
                        static_cast<const uint16_t *>(device_values) + begin,
                        count * sizeof(uint16_t), hipMemcpyDeviceToHost)
            : hipMemcpy(f32.data(),
                        static_cast<const float *>(device_values) + begin,
                        count * sizeof(float), hipMemcpyDeviceToHost);
        if (status != hipSuccess) {
            return reject(hipGetErrorString(status));
        }
        if (!source_bf16) {
            for (size_t item = 0u; item < count; ++item) {
                bf16[item] = qrt_float_to_bf16(f32[item]);
            }
        }
        output.write(reinterpret_cast<const char *>(bf16.data()),
                     static_cast<std::streamsize>(count * sizeof(uint16_t)));
        if (!output) {
            return reject("full stage capture write failed");
        }
    }
    output.close();
    if (!output) {
        return reject("full stage capture close failed");
    }
    captured_bytes += bytes;
    ++captured_files;
    accounting.copy_seconds += std::chrono::duration<double>(
        std::chrono::steady_clock::now() - copy_start).count();
    std::cerr << "BATCH_MARK selected_full_stage_dump layer=" << layer
              << " surface=" << surface << " tokens=" << tokens
              << " row_width=" << row_width << " bytes=" << bytes
              << " aggregate_bytes=" << captured_bytes
              << " files=" << captured_files
              << " source_bf16=" << (source_bf16 ? 1 : 0)
              << " all_layer_norms=" << (all_norm ? 1 : 0)
              << " observer_copy_seconds=" << accounting.copy_seconds
              << " diagnostic_only=1 numerical_correctness_claimed=0"
              << std::endl;
    return true;
}

bool emit_qwen36_exact_arbitrary_layer_boundary_trace(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    const char *surface,
    const float *device_output,
    std::string *failure_stage,
    std::string *failure
) {
    if (qwen36_all_norm_capture_active(prefill_tokens) &&
        !dump_qwen36_selected_full_stage(layer_index, prefill_tokens, surface,
            device_output, false, QRT_QWEN36_HIDDEN_SIZE, failure_stage, failure)) {
        return false;
    }
    if (!raw_env_flag_enabled(
            "QRT_QWEN36_EXACT_ARBITRARY_LAYER_BOUNDARY_TRACE"
        )) {
        return true;
    }
    if (prefill_tokens == 0u || surface == nullptr ||
        device_output == nullptr || failure_stage == nullptr ||
        failure == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage =
                "exact_arbitrary_layer_boundary_trace_contract";
        }
        if (failure != nullptr) {
            *failure =
                "exact-arbitrary layer boundary tracing requires a valid device surface";
        }
        return false;
    }
    if (!qwen36_all_norm_capture_active(prefill_tokens) && !dump_qwen36_selected_full_stage(
            layer_index, prefill_tokens, surface, device_output, false,
            QRT_QWEN36_HIDDEN_SIZE, failure_stage, failure)) {
        return false;
    }
    std::array<float, QRT_QWEN36_HIDDEN_SIZE> terminal_hidden{};
    const unsigned int trace_position = env_u32_or_default(
        "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE_POSITION",
        prefill_tokens - 1u
    );
    if (trace_position >= prefill_tokens) {
        *failure_stage = "exact_arbitrary_layer_boundary_trace_position";
        *failure = "selected trace position exceeds the active prefill shape";
        return false;
    }
    const size_t terminal_offset =
        static_cast<size_t>(trace_position) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const hipError_t copy_status = hipMemcpy(
        terminal_hidden.data(),
        device_output + terminal_offset,
        terminal_hidden.size() * sizeof(float),
        hipMemcpyDeviceToHost
    );
    if (copy_status != hipSuccess) {
        *failure_stage =
            "exact_arbitrary_layer_boundary_trace_copy";
        *failure = hipGetErrorString(copy_status);
        return false;
    }
    double sum = 0.0;
    double sum_sq = 0.0;
    float minimum = std::numeric_limits<float>::infinity();
    float maximum = -std::numeric_limits<float>::infinity();
    for (float value : terminal_hidden) {
        if (!std::isfinite(value)) {
            *failure_stage =
                "exact_arbitrary_layer_boundary_trace_nonfinite";
            *failure =
                "exact-arbitrary layer boundary trace contains a non-finite value";
            return false;
        }
        minimum = (std::min)(minimum, value);
        maximum = (std::max)(maximum, value);
        sum += static_cast<double>(value);
        sum_sq += static_cast<double>(value) *
            static_cast<double>(value);
    }
    std::ostringstream marker;
    marker << std::setprecision(
                  std::numeric_limits<double>::max_digits10
              )
           << "BATCH_MARK qwen36_exact_arbitrary_layer_boundary_trace"
           << " layer=" << layer_index
           << " surface=" << surface
           << " prefill_tokens=" << prefill_tokens
           << " terminal_position=" << trace_position
           << " trace_position=" << trace_position
           << " hidden_size=" << terminal_hidden.size()
           << " min=" << minimum
           << " max=" << maximum
           << " mean="
           << (sum / static_cast<double>(terminal_hidden.size()))
           << " rms="
           << std::sqrt(
                  sum_sq /
                  static_cast<double>(terminal_hidden.size())
              )
           << " fnv1a64="
           << hex_u64(
                  qrt_fnv1a64_f32(
                      terminal_hidden.data(),
                      terminal_hidden.size()
                  )
              )
           << " f32_bits=" << std::hex << std::setfill('0');
    for (size_t index = 0u; index < terminal_hidden.size(); ++index) {
        if (index != 0u) {
            marker << ',';
        }
        uint32_t bits = 0u;
        std::memcpy(&bits, &terminal_hidden[index], sizeof(bits));
        marker << std::setw(8) << bits;
    }
    marker << " diagnostic_only=1 numerical_correctness_claimed=0";
    std::cerr << marker.str() << std::endl;
    return true;
}

bool emit_qwen36_exact_arbitrary_output_residual_trace(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    const OutputResidualRun &output_residual,
    std::string *failure_stage,
    std::string *failure
) {
    if (!raw_env_flag_enabled(
            "QRT_QWEN36_EXACT_ARBITRARY_LAYER_BOUNDARY_TRACE"
        ) ||
        layer_index != env_u32_or_default(
            "QRT_QWEN36_EXACT_ARBITRARY_LAYER_BOUNDARY_TRACE_LAYER",
            UINT_MAX
        )) {
        return true;
    }
    const size_t expected_elements =
        static_cast<size_t>(prefill_tokens) *
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const size_t expected_bytes = expected_elements * sizeof(float);
    const uint64_t token_hash = token_ids_hash_or_compute(
        output_residual.selected_token_ids_hash,
        output_residual.selected_token_ids
    );
    float *device_output = nullptr;
    const bool resident_surface =
        output_residual.correctness_pass &&
        output_residual.output_elements == expected_elements &&
        output_residual.output_bytes == expected_bytes &&
        token_ids_are_zero_based_prefix(
            output_residual.selected_token_ids,
            prefill_tokens
        ) &&
        borrow_descriptor_resident_layer_stack_surface(
            DescriptorResidentLayerSurfaceKind::kOutputHidden,
            layer_index,
            token_hash,
            expected_bytes,
            "exact_arbitrary_output_residual_trace",
            &device_output
        );
    if (!resident_surface || device_output == nullptr) {
        std::cerr
            << "BATCH_MARK qwen36_exact_arbitrary_layer_boundary_trace"
            << " layer=" << layer_index
            << " surface=output_residual"
            << " prefill_tokens=" << prefill_tokens
            << " selected=0 resident_surface=0"
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
        return true;
    }
    return emit_qwen36_exact_arbitrary_layer_boundary_trace(
        layer_index,
        prefill_tokens,
        "output_residual",
        device_output,
        failure_stage,
        failure
    );
}

bool emit_qwen36_exact_arbitrary_linear_stage_trace(
    unsigned int layer_index,
    unsigned int prefill_tokens,
    const char *surface,
    const float *device_output,
    size_t row_width,
    std::string *failure_stage,
    std::string *failure
) {
    const unsigned int selected_layer = env_u32_or_default(
        "QRT_QWEN36_EXACT_ARBITRARY_LINEAR_STAGE_TRACE_LAYER",
        UINT_MAX
    );
    if (selected_layer != layer_index) {
        return true;
    }
    if (prefill_tokens == 0u || surface == nullptr ||
        device_output == nullptr || row_width == 0u ||
        failure_stage == nullptr || failure == nullptr) {
        if (failure_stage != nullptr) {
            *failure_stage = "exact_arbitrary_linear_stage_trace_contract";
        }
        if (failure != nullptr) {
            std::ostringstream detail;
            detail
                << "exact-arbitrary linear stage tracing requires a valid "
                   "device row"
                << ": surface=" << (surface == nullptr ? "null" : surface)
                << " exact_path="
                << (qwen36_exact_arbitrary_product_path_enabled(prefill_tokens)
                        ? 1
                        : 0)
                << " prefill_tokens=" << prefill_tokens
                << " device_output=" << (device_output == nullptr ? 0 : 1)
                << " row_width=" << row_width
                << " failure_stage=" << (failure_stage == nullptr ? 0 : 1)
                << " failure=" << (failure == nullptr ? 0 : 1);
            *failure = detail.str();
        }
        return false;
    }
    if (!dump_qwen36_selected_full_stage(
            layer_index, prefill_tokens, surface, device_output, false,
            row_width, failure_stage, failure)) {
        return false;
    }
    std::vector<float> terminal(row_width, 0.0f);
    const unsigned int trace_position = env_u32_or_default(
        "QRT_QWEN36_EXACT_ARBITRARY_LAYER_OUTPUT_TRACE_POSITION",
        prefill_tokens - 1u
    );
    if (trace_position >= prefill_tokens) {
        *failure_stage = "exact_arbitrary_linear_stage_trace_position";
        *failure = "selected trace position exceeds the active prefill shape";
        return false;
    }
    const size_t terminal_offset =
        static_cast<size_t>(trace_position) * row_width;
    const hipError_t copy_status = hipMemcpy(
        terminal.data(),
        device_output + terminal_offset,
        terminal.size() * sizeof(float),
        hipMemcpyDeviceToHost
    );
    if (copy_status != hipSuccess) {
        *failure_stage = "exact_arbitrary_linear_stage_trace_copy";
        *failure = hipGetErrorString(copy_status);
        return false;
    }
    std::ostringstream marker;
    marker << "BATCH_MARK qwen36_exact_arbitrary_linear_stage_trace"
           << " layer=" << layer_index
           << " surface=" << surface
           << " prefill_tokens=" << prefill_tokens
           << " terminal_position=" << trace_position
           << " trace_position=" << trace_position
           << " row_width=" << row_width
           << " f32_bits=" << std::hex << std::setfill('0');
    for (size_t index = 0u; index < terminal.size(); ++index) {
        if (index != 0u) {
            marker << ',';
        }
        uint32_t bits = 0u;
        std::memcpy(&bits, &terminal[index], sizeof(bits));
        marker << std::setw(8) << bits;
    }
    marker << " diagnostic_only=1 numerical_correctness_claimed=0";
    std::cerr << marker.str() << std::endl;
    return true;
}

