        run->failure =
            "compact BF16 attention requires an exact q8192/q65536 Triton or q8192/q16384/q32768/q65536/q131072/q262144 CK provider, whole full-attention layer provider, resident BF16 matrix provider, and matching hipBLASLt QKV projection";
        std::cerr << "BATCH_MARK full_attention_ck_compact_bf16_rejected"
                  << " layer=" << descriptor.layer_index
                  << " exact_q8192=" << (triton_hsaco_exact_shape ? 1 : 0)
                  << " exact_q16384="
                  << (ck_fmha_q16384_exact_shape ? 1 : 0)
                  << " exact_q32768="
                  << (ck_fmha_q32768_exact_shape ? 1 : 0)
                  << " exact_q65536="
                  << (ck_fmha_q65536_exact_shape ? 1 : 0)
                  << " exact_q131_context="
                  << (ck_fmha_q131_context_exact_shape ? 1 : 0)
                  << " external_provider="
                  << (use_triton_hsaco_full_attention_provider ? 1 : 0)
                  << " ck=" << (use_ck_fmha_full_attention_provider ? 1 : 0)
                  << " whole=" << (whole_full_attention_layer_provider ? 1 : 0)
                  << " resident_bf16="
                  << (use_resident_bf16_matrix_provider ? 1 : 0)
                  << " qkv_hipblaslt="
                  << (use_resident_full_attention_qkv_projection ? 1 : 0)
                  << std::endl;
