bool materialize_prefill_output_residual_for_tokens(
    unsigned int layer_index,
    const PostAttentionRmsnormRun &layer0_post_attention_rmsnorm_run,
    const MoeRouterRun &layer0_moe_router_run,
    const ResidualHiddenRun &layer0_residual_hidden_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    const std::vector<unsigned int> &token_ids,
    OutputResidualRun *run,
    double *avg_ms,
    std::string *failure_stage,
    std::string *failure
);

bool materialize_prefill_output_residual_for_tokens(
    unsigned int layer_index,
    const PostAttentionRmsnormRun &layer0_post_attention_rmsnorm_run,
    const MoeRouterRun &layer0_moe_router_run,
    const ResidualHiddenRun &layer0_residual_hidden_run,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    const std::vector<unsigned int> &token_ids,
    OutputResidualRun *run,
    double *avg_ms,
    std::string *failure_stage,
    std::string *failure
) {
    *avg_ms = 0.0;
    if (token_ids.empty()) {
        *failure_stage = "empty_token_materialization_request";
        *failure = "prefill output residual materialization received no target tokens";
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }
    if (layer_index == 1u) {
        return materialize_layer1_output_residual_for_tokens(
            layer0_post_attention_rmsnorm_run,
            layer0_moe_router_run,
            layer0_residual_hidden_run,
            model_dir,
            prefill_tokens,
            token_ids,
            run,
            avg_ms,
            failure_stage,
            failure
        );
    }
    if (layer_index == 0u || layer_index >= QRT_QWEN36_LAYER_COUNT) {
        *failure_stage = "unsupported_prefill_output_residual_materialization_layer";
        *failure = "prefill output residual materialization received an unsupported layer index";
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }

    if ((layer_index % 4u) == 3u) {
        OutputResidualRun previous_output_residual;
        PrefillFullAttentionBatchLayerRun helper;
        double previous_avg_ms = 0.0;
        if (!materialize_prefill_output_residual_for_tokens(
                layer_index - 1u,
                layer0_post_attention_rmsnorm_run,
                layer0_moe_router_run,
                layer0_residual_hidden_run,
                model_dir,
                prefill_tokens,
                token_ids,
                &previous_output_residual,
                &previous_avg_ms,
                failure_stage,
                failure
            )) {
            run->failure_stage = *failure_stage;
            run->failure = *failure;
            return false;
        }
        const RepeatedPrefillLayerDescriptor descriptor =
            full_attention_prefill_layer_descriptor(layer_index);
        if (!run_full_attention_prefill_layer_helper_for_targets(
                descriptor,
                token_ids,
                previous_output_residual,
                layer0_post_attention_rmsnorm_run,
                layer0_moe_router_run,
                layer0_residual_hidden_run,
                model_dir,
                prefill_tokens,
                &helper
            )) {
            if (!capture_failure_from_run(helper, failure_stage, failure)) {
                *failure_stage =
                    "layer" + std::to_string(layer_index) +
                    "_full_attention_output_residual_materialization_prefill_phase";
                *failure = "selected full-attention output residual materialization failed";
            }
            run->failure_stage = *failure_stage;
            run->failure = *failure;
            return false;
        }
        *run = helper.output_residual;
        *avg_ms = previous_avg_ms + full_attention_prefill_layer_helper_avg_ms(helper);
        return true;
    }

    const std::vector<unsigned int> previous_window_token_ids =
        selected_window_tokens_for_targets(token_ids);
    OutputResidualRun previous_window_output_residual;
    OutputResidualRun previous_target_output_residual;
    RepeatedPrefillLayerHelperRun helper;
    double previous_window_avg_ms = 0.0;
    if (!materialize_prefill_output_residual_for_tokens(
            layer_index - 1u,
            layer0_post_attention_rmsnorm_run,
            layer0_moe_router_run,
            layer0_residual_hidden_run,
            model_dir,
            prefill_tokens,
            previous_window_token_ids,
            &previous_window_output_residual,
            &previous_window_avg_ms,
            failure_stage,
            failure
        )) {
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }
    const std::string target_slice_name =
        "layer" + std::to_string(layer_index - 1u) + "_target_output_residual_slice";
    const std::string target_slice_stage =
        "layer" + std::to_string(layer_index - 1u) +
        "_target_output_residual_slice_prefill_phase";
    if (!slice_output_residual_for_tokens(
            previous_window_output_residual,
            token_ids,
            target_slice_name.c_str(),
            target_slice_stage.c_str(),
            &previous_target_output_residual,
            failure_stage,
            failure
        )) {
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }
    const RepeatedPrefillLayerDescriptor descriptor =
        repeated_prefill_layer_descriptor(layer_index);
    if (!run_repeated_prefill_layer_helper_for_targets(
            descriptor,
            token_ids,
            previous_target_output_residual,
            layer0_post_attention_rmsnorm_run,
            layer0_moe_router_run,
            layer0_residual_hidden_run,
            model_dir,
            prefill_tokens,
            &helper,
            &previous_window_output_residual,
            previous_window_avg_ms
        )) {
        if (!capture_failure_from_run(helper, failure_stage, failure)) {
            *failure_stage =
                "layer" + std::to_string(layer_index) +
                "_output_residual_materialization_prefill_phase";
            *failure = "selected repeated output residual materialization failed";
        }
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }
    *run = helper.output_residual_window;
    *avg_ms = previous_window_avg_ms + repeated_prefill_layer_helper_avg_ms(helper);
    return true;
}

bool run_prefill_linear_attention_descriptor_batch_probe(
    const OutputResidualRun &layer1_selected_output_residual_run,
    const PostAttentionRmsnormRun &layer0_post_attention_rmsnorm_run,
    const MoeRouterRun &layer0_moe_router_run,
    const ResidualHiddenRun &layer0_residual_hidden_run,
    const Layer0PreResidualStageRuns *layer0_source_stage_runs,
    const std::string &model_dir,
    unsigned int prefill_tokens,
    bool real_prompt_input_surface,
    bool skip_synthetic_validation_continuation,
    PrefillLinearAttentionDescriptorBatchRun *run,
    const Gb10PromptFixture *real_prompt_fixture = nullptr,
    const std::vector<unsigned int> *final_target_tokens_override = nullptr
) {
    *run = PrefillLinearAttentionDescriptorBatchRun{};
    const bool descriptor_product_continuation =
        skip_synthetic_validation_continuation && !real_prompt_input_surface;
    ScopedDescriptorProductCombinedMoeBf16Handoff combined_moe_handoff_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_CANONICALIZE_COMBINED_MOE")
    );
    ScopedDescriptorProductRoutedOutputCpuBf16Handoff routed_output_handoff_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_CANONICALIZE_ROUTED_OUTPUT_CPU_BF16")
    );
    ScopedDescriptorProductRoutedOutputGpuF32GridHandoff routed_output_f32_grid_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_CANONICALIZE_ROUTED_OUTPUT_GPU_F32_GRID")
    );
    ScopedDescriptorProductRoutedScaleAfterDown routed_scale_after_down_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_ROUTED_SCALE_AFTER_DOWN")
    );
    ScopedDescriptorProductRoutedCpuReferenceArithmetic routed_cpu_arithmetic_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_ROUTED_CPU_REFERENCE_ARITHMETIC")
    );
    ScopedDescriptorProductRoutedOriginalRouteOrder routed_route_order_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_ROUTED_ORIGINAL_ROUTE_ORDER")
    );
    ScopedDescriptorProductRoutedDisableFma routed_disable_fma_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_ROUTED_DISABLE_FMA")
    );
    ScopedDescriptorProductParallelRoutedPack parallel_routed_pack_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_PARALLEL_ROUTED_PACK")
    );
    ScopedDescriptorProductParallelRoutedCpuReference parallel_routed_cpu_reference_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_PARALLEL_ROUTED_CPU_REFERENCE")
    );
    ScopedDescriptorProductParallelSharedCpuReference parallel_shared_cpu_reference_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_PARALLEL_SHARED_CPU_REFERENCE")
    );
    ScopedDescriptorProductCpuExactSharedExpert cpu_exact_shared_expert_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_CPU_EXACT_SHARED_EXPERT")
    );
    ScopedDescriptorProductSharedDeviceExactCombinedMoeBackend
        shared_device_exact_combined_moe_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_SHARED_DEVICE_EXACT_COMBINED_MOE_BACKEND"
            )
        );
    ScopedDescriptorProductSharedDeviceCpuOrderCombinedMoeBackend
        shared_device_cpu_order_combined_moe_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_SHARED_DEVICE_CPU_ORDER_COMBINED_MOE_BACKEND"
            )
        );
    ScopedDescriptorProductSharedDeviceGb10CombinedMoeBackend
        shared_device_gb10_combined_moe_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_SHARED_DEVICE_GB10_COMBINED_MOE_BACKEND"
            )
        );
    ScopedDescriptorProductResidentBf16MatrixProvider
        resident_bf16_matrix_provider_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_BF16_MATRIX_PROVIDER"
            )
        );
    ScopedDescriptorProductTrustExactRoutedGpuHandoff trusted_routed_gpu_handoff_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_TRUST_EXACT_ROUTED_GPU_HANDOFF")
    );
    ScopedDescriptorProductNoStoreRoutedWeightCache no_store_routed_weight_cache_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_NO_STORE_ROUTED_WEIGHT_CACHE")
    );
    ScopedDescriptorProductCompactDeviceRoutedLayout compact_device_layout_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_COMPACT_DEVICE_ROUTED_LAYOUT")
    );
    ScopedDescriptorProductGroupedExactRoutedBackend grouped_exact_routed_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_GROUPED_EXACT_ROUTED_BACKEND")
    );
    ScopedDescriptorProductWholeSelectedMoeExactBackend whole_selected_moe_exact_scope(
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_WHOLE_SELECTED_MOE_EXACT_BACKEND")
    );
    ScopedDescriptorProductWholeSelectedMoeF32WeightBackend
        whole_selected_moe_f32_weight_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_WHOLE_SELECTED_MOE_F32_WEIGHT_BACKEND"
            )
        );
    ScopedDescriptorProductWholeSelectedMoeEndpointBf16Backend
        whole_selected_moe_endpoint_bf16_scope(
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_WHOLE_SELECTED_MOE_ENDPOINT_BF16_BACKEND"
            )
        );
    const bool resident_layer_stack_carrier_requested =
        descriptor_product_continuation &&
        env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_LAYER_STACK_CARRIER");
    ScopedDescriptorProductResidentLayerStackCarrier
        resident_layer_stack_carrier_product_scope(
            resident_layer_stack_carrier_requested
        );
    ScopedDescriptorProductResidentLayerStackSourceLayout
        resident_layer_stack_source_layout_scope(
            resident_layer_stack_carrier_requested &&
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_LAYER_STACK_SOURCE_LAYOUT"
            )
        );
    ScopedDescriptorProductResidentLayerStackSourceLayoutHostShadow
        resident_layer_stack_source_layout_host_shadow_scope(
            resident_layer_stack_carrier_requested &&
            descriptor_product_continuation &&
            env_flag_enabled(
                "QRT_PREFILL_DESCRIPTOR_BATCH_RESIDENT_LAYER_STACK_SOURCE_LAYOUT_HOST_SHADOW"
            )
        );
    // Construct the pool before the carrier so exceptional unwinding releases
    // carrier-held pointers before destroying their backing allocation pool.
    ScopedDescriptorProductDeviceAllocationReuse device_allocation_reuse_scope(
        descriptor_product_continuation &&
        (!env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_DISABLE_DEVICE_ALLOC_POOL") ||
         qwen36_whole_layer_provider_requested())
    );
    ScopedDescriptorResidentLayerStackCarrierRuntime
        resident_layer_stack_carrier_runtime_scope(
            resident_layer_stack_carrier_requested &&
            !descriptor_resident_layer_stack_carrier_active()
        );
    ScopedDescriptorProductSkipMoeSubphaseProfile moe_subphase_profile_scope(
        descriptor_product_continuation &&
        !env_flag_enabled("QRT_PREFILL_DESCRIPTOR_BATCH_PROFILE_MOE_SUBPHASES")
    );
    ScopedDescriptorProductSkipRoutedExpertWarmup routed_expert_warmup_scope(
        descriptor_product_continuation
    );
    const bool first_full_attention_full_history =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_FIRST_FULL_ATTENTION_FULL_HISTORY"
        );
    const bool all_full_attention_full_history =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_ALL_FULL_ATTENTION_FULL_HISTORY"
        );
    const bool allow_brute_full_history_replay =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_ALLOW_BRUTE_FULL_HISTORY_REPLAY"
        );
    const bool enable_resident_history_carrier =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_ENABLE_RESIDENT_HISTORY_CARRIER"
        );
    const bool q8192_structural_history_guard =
        all_full_attention_full_history &&
        prefill_tokens >= kRetainedPrefillTokens &&
        !allow_brute_full_history_replay &&
        !enable_resident_history_carrier;
    const uint64_t batch_start_ns = qrt_now_ns();
    run->real_prompt_input_surface = real_prompt_input_surface;
    run->output_boundary = "layer1_output_residual";
    run->next_unclosed_boundary = "layer2_output_residual";
    run->layers.reserve(QRT_QWEN36_LAYER_COUNT);
    run->full_attention_layers.reserve(QRT_QWEN36_LAYER_COUNT / 4u);
    if (enable_resident_history_carrier) {
        std::cerr
            << "BATCH_MARK resident_history_carrier_enabled prefill_tokens="
            << prefill_tokens
            << " all_full_attention_full_history="
            << (all_full_attention_full_history ? 1 : 0)
            << std::endl;
    }
    if (real_prompt_input_surface && real_prompt_fixture == nullptr) {
        run->failure_stage = "gb10_real_prompt_fixture_contract";
        run->failure =
            "real prompt input surface requested without a matching gb10 prompt fixture";
        run->next_unclosed_boundary = "real_prompt_token_ids";
        return false;
    }

    if (descriptor_product_continuation) {
        run->synthetic_prefill_surface_skipped = true;
    } else {
        const uint64_t real_prompt_surface_start_ns = qrt_now_ns();
        run->real_prompt_surface_attempted = true;
        if (!run_real_prompt_token_embedding_prefill_surface(
                model_dir,
                *real_prompt_fixture,
                &run->real_prompt_surface
            )) {
            run->real_prompt_surface_wall_clock_ns =
                qrt_elapsed_ns(real_prompt_surface_start_ns, qrt_now_ns());
            if (!capture_failure_from_run(
                    run->real_prompt_surface,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->failure_stage = "real_prompt_token_embedding_prefill_surface";
                run->failure =
                    "real prompt token-embedding prefill surface failed without a stage-specific failure";
            }
            run->next_unclosed_boundary =
                run->real_prompt_surface.next_unclosed_boundary.empty()
                    ? "real_prompt_token_embedding_prefill_surface"
                    : run->real_prompt_surface.next_unclosed_boundary;
            return false;
        }
        run->real_prompt_surface_wall_clock_ns =
            qrt_elapsed_ns(real_prompt_surface_start_ns, qrt_now_ns());
    }

    auto append_layer = [&](unsigned int layer_index) -> PrefillLinearAttentionBatchLayerRun & {
        run->layers.push_back(PrefillLinearAttentionBatchLayerRun{});
        PrefillLinearAttentionBatchLayerRun &layer = run->layers.back();
        layer.layer_index = layer_index;
        layer.helper.descriptor = repeated_prefill_layer_descriptor(layer_index);
        return layer;
    };
    auto fail_from_helper = [&](const RepeatedPrefillLayerHelperRun &candidate) -> void {
        if (!capture_failure_from_run(candidate, &run->failure_stage, &run->failure)) {
            run->failure_stage =
                "prefill_linear_attention_descriptor_batch_layer" +
                std::to_string(candidate.descriptor.layer_index);
            run->failure = "linear-attention descriptor batch helper failed without a stage-specific failure";
        }
    };

    struct CachedOutputResidual {
        unsigned int layer_index = 0;
        std::vector<unsigned int> token_ids;
        OutputResidualRun output_residual;
        double materialization_avg_ms = 0.0;
    };
    std::vector<CachedOutputResidual> output_residual_cache;
    auto token_set_contains_all =
        [](const std::vector<unsigned int> &source, const std::vector<unsigned int> &requested) -> bool {
            return token_set_contains_all_fast(source, requested);
        };
    auto cache_output_residual =
        [&](unsigned int layer_index, const OutputResidualRun &output_residual, double materialization_avg_ms) {
            if (!output_residual.correctness_pass) {
                return;
            }
            for (CachedOutputResidual &entry : output_residual_cache) {
                if (entry.layer_index == layer_index && entry.token_ids == output_residual.selected_token_ids) {
                    entry.output_residual = output_residual;
                    entry.materialization_avg_ms = materialization_avg_ms;
                    return;
                }
            }
            CachedOutputResidual entry;
            entry.layer_index = layer_index;
            entry.token_ids = output_residual.selected_token_ids;
            entry.output_residual = output_residual;
            entry.materialization_avg_ms = materialization_avg_ms;
            output_residual_cache.push_back(entry);
        };
    auto prune_output_residual_cache_for_resident_history =
        [&](unsigned int keep_layer_index) {
            output_residual_cache.erase(
                std::remove_if(
                    output_residual_cache.begin(),
                    output_residual_cache.end(),
                    [&](const CachedOutputResidual &entry) {
                        return entry.layer_index != keep_layer_index;
                    }
                ),
                output_residual_cache.end()
            );
        };
    std::function<bool(unsigned int, const std::vector<unsigned int> &, OutputResidualRun *, double *)>
        materialize_cached_output_residual;
    materialize_cached_output_residual =
        [&](unsigned int layer_index,
            const std::vector<unsigned int> &token_ids,
            OutputResidualRun *output_residual,
            double *materialization_avg_ms) -> bool {
            *materialization_avg_ms = 0.0;
            if (token_ids.empty()) {
                run->failure_stage = "empty_cached_output_residual_materialization_request";
                run->failure = "cached prefill output residual materialization received no target tokens";
                output_residual->failure_stage = run->failure_stage;
                output_residual->failure = run->failure;
                return false;
            }
            for (const CachedOutputResidual &entry : output_residual_cache) {
                if (entry.layer_index == layer_index && entry.token_ids == token_ids) {
                    *output_residual = entry.output_residual;
                    *materialization_avg_ms = entry.materialization_avg_ms;
                    return true;
                }
            }
            for (const CachedOutputResidual &entry : output_residual_cache) {
                if (entry.layer_index != layer_index ||
                    !token_set_contains_all(entry.output_residual.selected_token_ids, token_ids)) {
                    continue;
                }
                const std::string slice_name =
                    "layer" + std::to_string(layer_index) + "_cached_output_residual_slice";
                const std::string slice_stage =
                    "layer" + std::to_string(layer_index) +
                    "_cached_output_residual_slice_prefill_phase";
                const bool device_only_source =
                    output_residual_device_only_full_prefix(
                        entry.output_residual,
                        layer_index,
                        prefill_tokens
                    ) ||
                    q262144_bf16_output_handoff_matches(
                        layer_index,
                        entry.output_residual,
                        prefill_tokens
                    );
                const bool slice_ok = device_only_source
                    ? materialize_device_output_residual_rows_for_tokens(
                          layer_index,
                          prefill_tokens,
                          entry.output_residual,
                          token_ids,
                          slice_name.c_str(),
                          slice_stage.c_str(),
                          output_residual,
                          &run->failure_stage,
                          &run->failure
                      )
                    : slice_output_residual_for_tokens(
                          entry.output_residual,
                          token_ids,
                          slice_name.c_str(),
                          slice_stage.c_str(),
                          output_residual,
                          &run->failure_stage,
                          &run->failure
                      );
                if (!slice_ok) {
                    return false;
                }
                *materialization_avg_ms = entry.materialization_avg_ms;
                cache_output_residual(layer_index, *output_residual, *materialization_avg_ms);
                return true;
            }
            if (layer_index == 1u) {
                const bool product_frontier_digest_required =
                    token_ids.size() <=
                    static_cast<size_t>(
                        kLayer3FullAttentionMaxSelectedTokens);
                run->layer1_frontier_attempted = true;
                if (!materialize_layer1_output_residual_for_tokens(
                        layer0_post_attention_rmsnorm_run,
                        layer0_moe_router_run,
                        layer0_residual_hidden_run,
                        model_dir,
                        prefill_tokens,
                        token_ids,
                        output_residual,
                        materialization_avg_ms,
                        &run->failure_stage,
                        &run->failure,
                        product_frontier_digest_required
                            ? &run->layer1_frontier
                            : nullptr,
                        product_frontier_digest_required
                            ? layer0_source_stage_runs
                            : nullptr
                    )) {
                    return false;
                }
                cache_output_residual(layer_index, *output_residual, 0.0);
                *materialization_avg_ms = 0.0;
                return true;
            }
            if (layer_index == 0u || layer_index >= QRT_QWEN36_LAYER_COUNT) {
                run->failure_stage = "unsupported_cached_output_residual_materialization_layer";
                run->failure = "cached prefill output residual materialization received an unsupported layer index";
                output_residual->failure_stage = run->failure_stage;
                output_residual->failure = run->failure;
                return false;
            }
            if ((layer_index % 4u) == 3u) {
                OutputResidualRun previous_output_residual;
                PrefillFullAttentionBatchLayerRun helper;
                double previous_avg_ms = 0.0;
                if (q8192_structural_history_guard &&
                    token_ids.size() >
                        static_cast<size_t>(
                            kLayer3FullAttentionMaxSelectedTokens)) {
                    run->failure_stage =
                        "structural_full_attention_history_state_carrier_missing";
                    run->failure =
                        "q8192 all-history materialization would enter the killed brute recursive full-stack replay path for layer" +
                        std::to_string(layer_index) + " with " +
                        std::to_string(token_ids.size()) +
                        " target/history tokens; wire a resident all-token GPU prefill history carrier or set QRT_PREFILL_DESCRIPTOR_BATCH_ALLOW_BRUTE_FULL_HISTORY_REPLAY=1 for a bounded route-kill diagnostic";
                    output_residual->failure_stage = run->failure_stage;
                    output_residual->failure = run->failure;
                    return false;
                }
                if (!materialize_cached_output_residual(
                        layer_index - 1u,
                        token_ids,
                        &previous_output_residual,
                        &previous_avg_ms
                    )) {
                    output_residual->failure_stage = run->failure_stage;
                    output_residual->failure = run->failure;
                    return false;
                }
                if (!run_full_attention_prefill_layer_helper_for_targets(
                        full_attention_prefill_layer_descriptor(layer_index),
                        token_ids,
                        previous_output_residual,
                        layer0_post_attention_rmsnorm_run,
                        layer0_moe_router_run,
                        layer0_residual_hidden_run,
                        model_dir,
                        prefill_tokens,
                        &helper,
                        (all_full_attention_full_history &&
                         token_ids.size() >
                             static_cast<size_t>(
                                 kLayer3FullAttentionMaxSelectedTokens))
                            ? &previous_output_residual
                            : nullptr
                    )) {
                    if (!capture_failure_from_run(helper, &run->failure_stage, &run->failure)) {
                        run->failure_stage =
                            "layer" + std::to_string(layer_index) +
                            "_cached_full_attention_output_residual_materialization_prefill_phase";
                        run->failure = "cached selected full-attention output residual materialization failed";
                    }
                    output_residual->failure_stage = run->failure_stage;
                    output_residual->failure = run->failure;
                    return false;
                }
                *output_residual = helper.output_residual;
                *materialization_avg_ms =
                    previous_avg_ms + full_attention_prefill_layer_helper_avg_ms(helper);
                cache_output_residual(layer_index, *output_residual, *materialization_avg_ms);
                return true;
            }

            const std::vector<unsigned int> previous_window_token_ids =
                selected_window_tokens_for_targets(token_ids);
            OutputResidualRun previous_window_output_residual;
            OutputResidualRun previous_target_output_residual;
            RepeatedPrefillLayerHelperRun helper;
            double previous_window_avg_ms = 0.0;
            if (!materialize_cached_output_residual(
                    layer_index - 1u,
                    previous_window_token_ids,
                    &previous_window_output_residual,
                    &previous_window_avg_ms
                )) {
                output_residual->failure_stage = run->failure_stage;
                output_residual->failure = run->failure;
                return false;
            }
            const std::string target_slice_name =
                "layer" + std::to_string(layer_index - 1u) + "_cached_target_output_residual_slice";
            const std::string target_slice_stage =
                "layer" + std::to_string(layer_index - 1u) +
                "_cached_target_output_residual_slice_prefill_phase";
            if (!slice_output_residual_for_tokens(
                    previous_window_output_residual,
                    token_ids,
                    target_slice_name.c_str(),
                    target_slice_stage.c_str(),
                    &previous_target_output_residual,
                    &run->failure_stage,
                    &run->failure
                )) {
                output_residual->failure_stage = run->failure_stage;
                output_residual->failure = run->failure;
                return false;
            }
            if (!run_repeated_prefill_layer_helper_for_targets(
                    repeated_prefill_layer_descriptor(layer_index),
                    token_ids,
                    previous_target_output_residual,
                    layer0_post_attention_rmsnorm_run,
                    layer0_moe_router_run,
                    layer0_residual_hidden_run,
                    model_dir,
                    prefill_tokens,
                    &helper,
                    &previous_window_output_residual,
                    previous_window_avg_ms
                )) {
                if (!capture_failure_from_run(helper, &run->failure_stage, &run->failure)) {
                    run->failure_stage =
                        "layer" + std::to_string(layer_index) +
                        "_cached_output_residual_materialization_prefill_phase";
                    run->failure = "cached selected repeated output residual materialization failed";
                }
                output_residual->failure_stage = run->failure_stage;
                output_residual->failure = run->failure;
                return false;
            }
            *output_residual = helper.output_residual_window;
            *materialization_avg_ms =
                previous_window_avg_ms + repeated_prefill_layer_helper_avg_ms(helper);
            cache_output_residual(layer_index, *output_residual, *materialization_avg_ms);
            return true;
        };
    auto run_full_attention_layer =
        [&](unsigned int layer_index,
            const std::vector<unsigned int> &target_tokens,
            const OutputResidualRun &previous_output_residual,
            const OutputResidualRun *history_previous_output_residual = nullptr) -> bool {
            run->full_attention_layers.push_back(PrefillFullAttentionBatchLayerRun{});
            PrefillFullAttentionBatchLayerRun &layer = run->full_attention_layers.back();
            if (!run_full_attention_prefill_layer_helper_for_targets(
                    full_attention_prefill_layer_descriptor(layer_index),
                    target_tokens,
                    previous_output_residual,
                    layer0_post_attention_rmsnorm_run,
                    layer0_moe_router_run,
                    layer0_residual_hidden_run,
                    model_dir,
                    prefill_tokens,
                    &layer,
                    history_previous_output_residual
                )) {
                if (!capture_failure_from_run(layer, &run->failure_stage, &run->failure)) {
                    run->failure_stage =
                        "prefill_descriptor_batch_layer" +
                        std::to_string(layer_index) +
                        "_full_attention";
                    run->failure = "full-attention helper failed without a stage-specific failure";
                }
                run->next_unclosed_boundary =
                    "layer" + std::to_string(layer_index) + "_full_attention_prefill";
                return false;
            }
            run->output_boundary =
                "layer" + std::to_string(layer_index) + "_full_attention_output_residual";
            if (!emit_qwen36_exact_arbitrary_output_residual_trace(
                    layer_index,
                    prefill_tokens,
                    layer.output_residual,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->next_unclosed_boundary = run->output_boundary;
                return false;
            }
            record_selected_moe_layer_surface_for_batch(
                run,
                layer.layer_index,
                layer.block_kind,
                layer.routed_expert,
                layer.shared_expert,
                layer.output_residual
            );
            cache_output_residual(layer_index, layer.output_residual, full_attention_prefill_layer_helper_avg_ms(layer));
            return true;
        };

    auto full_attention_product_history_tokens =
        [&](const std::vector<unsigned int> &target_tokens) -> std::vector<unsigned int> {
            if (target_tokens.empty()) {
                return {};
            }
            unsigned int max_target = 0u;
            for (unsigned int token : target_tokens) {
                if (token > max_target) {
                    max_target = token;
                }
            }
            if (max_target >= prefill_tokens) {
                max_target = prefill_tokens - 1u;
            }
            std::vector<unsigned int> history_tokens;
            history_tokens.reserve(static_cast<size_t>(max_target) + 1u);
            for (unsigned int token = 0u; token <= max_target; ++token) {
                history_tokens.push_back(token);
            }
            return history_tokens;
        };

    auto attach_layer1_frontier_from_output_residual =
        [&](const OutputResidualRun &output_residual) -> void {
            if (!output_residual.correctness_pass ||
                output_residual.selected_token_ids.empty() ||
                output_residual.gpu_output.size() !=
                    output_residual.selected_token_ids.size() *
                        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
                return;
            }
            run->layer1_frontier_attempted = true;
            run->layer1_frontier = Layer1FrontierRun{};
            run->layer1_frontier.target_token_ids =
                output_residual.selected_token_ids;
            run->layer1_frontier.source_window_token_ids =
                selected_window_tokens_for_targets(
                    run->layer1_frontier.target_token_ids
                );
            run->layer1_frontier.output_residual = output_residual;
            run->layer1_frontier.target_token_ids_hash = fnv1a64_bytes_seeded(
                run->layer1_frontier.target_token_ids.data(),
                run->layer1_frontier.target_token_ids.size() *
                    sizeof(run->layer1_frontier.target_token_ids[0])
            );
            run->layer1_frontier.source_window_token_ids_hash =
                fnv1a64_bytes_seeded(
                    run->layer1_frontier.source_window_token_ids.data(),
                    run->layer1_frontier.source_window_token_ids.size() *
                        sizeof(run->layer1_frontier.source_window_token_ids[0])
                );
            run->layer1_frontier.output_selected_token_ids_hash =
                output_residual.selected_token_ids_hash;
            run->layer1_frontier.product_path_compatible_token_count =
                run->layer1_frontier.target_token_ids.size();
            run->layer1_frontier.product_path_digest_valid =
                product_path_compatible_layer1_frontier_digest(
                    run->layer1_frontier.target_token_ids,
                    output_residual.gpu_output,
                    &run->layer1_frontier
                         .product_path_compatible_digest_fnv1a64,
                    &run->layer1_frontier
                         .product_path_compatible_last_output_fnv1a64,
                    &run->layer1_frontier
                         .product_path_compatible_hidden_value_count
                );
            run->layer1_frontier.correctness_pass =
                run->layer1_frontier.product_path_digest_valid;
        };

    const bool q262144_bf16_layer1_frontier =
        descriptor_product_continuation &&
        q262144_bf16_output_handoff_matches(
            1u,
            layer1_selected_output_residual_run,
            prefill_tokens
        );
    const bool resident_device_layer1_frontier =
        descriptor_product_continuation &&
        env_flag_enabled(
            "QRT_QWEN36_WHOLE_PROVIDER_FUSED_LAYER_STACK"
        ) &&
        ((env_flag_enabled(
              "QRT_QWEN36_WHOLE_PROVIDER_ENDPOINT_BF16_GB10_BOUNDARY"
          ) &&
          output_residual_device_only_full_prefix(
              layer1_selected_output_residual_run,
              1u,
              prefill_tokens
          )) ||
         q262144_bf16_layer1_frontier);
    const uint64_t layer1_cache_start_ns = qrt_now_ns();
    cache_output_residual(1u, layer1_selected_output_residual_run, 0.0);
    run->descriptor_layer1_cache_wall_clock_ns =
        qrt_elapsed_ns(layer1_cache_start_ns, qrt_now_ns());
    const uint64_t layer1_frontier_attach_start_ns = qrt_now_ns();
    if (resident_device_layer1_frontier) {
        run->layer1_frontier_attempted = true;
        run->layer1_frontier.target_token_ids =
            layer1_selected_output_residual_run.selected_token_ids;
        run->layer1_frontier.source_window_token_ids =
            layer1_selected_output_residual_run.selected_token_ids;
        run->layer1_frontier.output_residual =
            layer1_selected_output_residual_run;
        run->layer1_frontier.target_token_ids_hash =
            layer1_selected_output_residual_run.selected_token_ids_hash;
        run->layer1_frontier.source_window_token_ids_hash =
            layer1_selected_output_residual_run.selected_token_ids_hash;
        run->layer1_frontier.output_selected_token_ids_hash =
            layer1_selected_output_residual_run.selected_token_ids_hash;
        run->layer1_frontier.product_path_compatible_token_count =
            layer1_selected_output_residual_run.selected_token_count;
        run->layer1_frontier.product_path_compatible_hidden_value_count =
            layer1_selected_output_residual_run.output_elements;
        run->layer1_frontier.product_path_digest_valid = false;
        run->layer1_frontier.correctness_pass = true;
        std::cerr
            << "BATCH_MARK descriptor_resident_layer1_frontier_attach"
            << " tokens="
            << layer1_selected_output_residual_run.selected_token_count
            << " output_bytes="
            << layer1_selected_output_residual_run.output_bytes
            << " carrier="
            << (q262144_bf16_layer1_frontier
                    ? "q262144_bf16_workspace"
                    : "resident_f32")
            << " diagnostic_hash=elided"
            << " numerical_correctness_claimed=0"
            << std::endl;
    } else {
        attach_layer1_frontier_from_output_residual(
            layer1_selected_output_residual_run
        );
    }
    run->descriptor_layer1_frontier_attach_wall_clock_ns =
        qrt_elapsed_ns(layer1_frontier_attach_start_ns, qrt_now_ns());

    const uint64_t segment_plan_start_ns = qrt_now_ns();
    const bool layer39_q1_kv8192_target_plan_requested = env_flag_enabled(
        "QRT_PREFILL_DESCRIPTOR_BATCH_LAYER39_Q1_KV8192"
    );
    const bool explicit_final_targets_present =
        final_target_tokens_override != nullptr &&
        !final_target_tokens_override->empty();
    const bool explicit_final_targets_are_q1 =
        explicit_final_targets_present &&
        final_target_tokens_override->size() ==
            kLayer39Q1Kv8192TargetCount &&
        final_target_tokens_override->front() == prefill_tokens - 1u;
    const bool use_layer39_q1_kv8192_target_plan =
        layer39_q1_kv8192_target_plan_requested &&
        qwen36_layer39_q1_kv8192_target_plan_shape_enabled(prefill_tokens) &&
        (!explicit_final_targets_present || explicit_final_targets_are_q1);
    const unsigned int reported_final_target =
        use_layer39_q1_kv8192_target_plan
            ? prefill_tokens - 1u
            : (explicit_final_targets_present
                   ? final_target_tokens_override->back()
                   : prefill_tokens - 1u);
    if (layer39_q1_kv8192_target_plan_requested) {
        const char *reason = "active";
        if (!qwen36_layer39_q1_kv8192_target_plan_shape_enabled(
                       prefill_tokens
                   )) {
            reason = "terminal_target_plan_shape_inactive";
        } else if (explicit_final_targets_present &&
                   !explicit_final_targets_are_q1) {
            reason = "explicit_final_targets_not_q1";
        }
        std::cerr
            << "BATCH_MARK layer39_q1_kv8192_target_plan"
            << " active="
            << (use_layer39_q1_kv8192_target_plan ? 1 : 0)
            << " prefill_tokens=" << prefill_tokens
            << " target_tokens="
            << (use_layer39_q1_kv8192_target_plan
                    ? kLayer39Q1Kv8192TargetCount
                    : (explicit_final_targets_present
                           ? final_target_tokens_override->size()
                           : selected_tokens(prefill_tokens).size()))
            << " final_target=" << reported_final_target
            << " source="
            << (explicit_final_targets_are_q1
                    ? "caller_override"
                    : (use_layer39_q1_kv8192_target_plan
                           ? "environment_override"
                           : "unchanged"))
            << " reason=" << reason
            << std::endl;
    }
    const std::vector<unsigned int> repeated_target_tokens =
        use_layer39_q1_kv8192_target_plan
            ? std::vector<unsigned int>{
                  prefill_tokens - 1u
              }
            : (explicit_final_targets_present
                   ? *final_target_tokens_override
                   : selected_tokens(prefill_tokens));
    std::vector<unsigned int> stack_target_tokens = repeated_target_tokens;
    if (enable_resident_history_carrier) {
        stack_target_tokens.clear();
        stack_target_tokens.reserve(prefill_tokens);
        for (unsigned int token = 0u; token < prefill_tokens; ++token) {
            stack_target_tokens.push_back(token);
        }
        std::cerr
            << "BATCH_MARK resident_history_carrier_stack_targets"
            << " final_tokens=" << repeated_target_tokens.size()
            << " stack_tokens=" << stack_target_tokens.size()
            << std::endl;
    }
    const OutputResidualRun *selected_previous_output_residual = nullptr;
    auto repeated_segment_initial_previous_tokens =
        [&](unsigned int first_layer_index,
            unsigned int last_layer_index,
            const std::vector<unsigned int> &final_target_tokens) -> std::vector<unsigned int> {
            if (first_layer_index > last_layer_index || final_target_tokens.empty()) {
                return {};
            }
            std::vector<unsigned int> layer_frontier = final_target_tokens;
            for (unsigned int layer_index = last_layer_index; layer_index > first_layer_index; --layer_index) {
                layer_frontier = selected_window_tokens_for_targets(layer_frontier);
            }
            return selected_window_tokens_for_targets(layer_frontier);
        };
    auto run_repeated_segment =
        [&](unsigned int first_layer_index,
            unsigned int last_layer_index,
            const std::vector<unsigned int> &final_target_tokens,
            const OutputResidualRun *initial_previous_output_residual_override = nullptr,
            double initial_previous_output_residual_materialization_avg_ms = 0.0) -> bool {
            if (first_layer_index > last_layer_index || final_target_tokens.empty()) {
                run->failure_stage = "prefill_repeated_segment_frontier_contract";
                run->failure = "repeated segment received an empty or invalid token frontier";
                return false;
            }
            const size_t layer_count =
                static_cast<size_t>(last_layer_index - first_layer_index + 1u);
            std::vector<std::vector<unsigned int>> layer_target_tokens(layer_count);
            layer_target_tokens.back() = final_target_tokens;
            for (size_t reverse_index = layer_count - 1u; reverse_index > 0u; --reverse_index) {
                layer_target_tokens[reverse_index - 1u] =
                    selected_window_tokens_for_targets(layer_target_tokens[reverse_index]);
            }

            OutputResidualRun previous_output_residual_buffer;
            double previous_output_residual_materialization_avg_ms = 0.0;
            const std::vector<unsigned int> initial_previous_tokens =
                selected_window_tokens_for_targets(layer_target_tokens.front());
            if (initial_previous_output_residual_override != nullptr) {
                const size_t expected_elements =
                    initial_previous_tokens.size() *
                    static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
                const bool initial_previous_host_available =
                    initial_previous_output_residual_override->gpu_output.size() ==
                    expected_elements;
                const bool initial_previous_device_only =
                    output_residual_device_only_full_prefix(
                        *initial_previous_output_residual_override,
                        first_layer_index - 1u,
                        prefill_tokens
                    );
                if (!initial_previous_output_residual_override->correctness_pass ||
                    initial_previous_output_residual_override->selected_token_ids != initial_previous_tokens ||
                    (!initial_previous_host_available &&
                     !initial_previous_device_only)) {
                    run->failure_stage =
                        "layer" + std::to_string(first_layer_index) +
                        "_initial_feedforward_window_previous_output_residual_contract";
                    run->failure =
                        "repeated segment received an initial previous-layer output residual override with mismatched token ids, shape, or correctness";
                    run->next_unclosed_boundary =
                        "layer" + std::to_string(first_layer_index) + "_window_previous_output_residual";
                    return false;
                }
                previous_output_residual_buffer = *initial_previous_output_residual_override;
                previous_output_residual_materialization_avg_ms =
                    initial_previous_output_residual_materialization_avg_ms;
            } else {
                if (!materialize_cached_output_residual(
                        first_layer_index - 1u,
                        initial_previous_tokens,
                        &previous_output_residual_buffer,
                        &previous_output_residual_materialization_avg_ms
                    )) {
                    run->next_unclosed_boundary =
                        "layer" + std::to_string(first_layer_index) + "_window_previous_output_residual";
                    return false;
                }
            }

            for (size_t layer_offset = 0; layer_offset < layer_count; ++layer_offset) {
                const unsigned int layer_index =
                    first_layer_index + static_cast<unsigned int>(layer_offset);
                const std::vector<unsigned int> &target_tokens =
                    layer_target_tokens[layer_offset];
                const std::vector<unsigned int> window_tokens =
                    selected_window_tokens_for_targets(target_tokens);

                OutputResidualRun window_previous_output_residual;
                double window_previous_materialization_avg_ms = 0.0;
                if (previous_output_residual_buffer.selected_token_ids == window_tokens) {
                    window_previous_output_residual = previous_output_residual_buffer;
                    window_previous_materialization_avg_ms =
                        previous_output_residual_materialization_avg_ms;
                } else if (token_set_contains_all(
                        previous_output_residual_buffer.selected_token_ids,
                        window_tokens
                    )) {
                    const std::string slice_name =
                        "layer" + std::to_string(layer_index - 1u) +
                        "_feedforward_window_output_residual_slice";
                    const std::string slice_stage =
                        "layer" + std::to_string(layer_index - 1u) +
                        "_feedforward_window_output_residual_slice_prefill_phase";
                    if (!slice_output_residual_for_tokens(
                            previous_output_residual_buffer,
                            window_tokens,
                            slice_name.c_str(),
                            slice_stage.c_str(),
                            &window_previous_output_residual,
                            &run->failure_stage,
                            &run->failure
                        )) {
                        run->next_unclosed_boundary =
                            "layer" + std::to_string(layer_index) + "_window_previous_output_residual";
                        return false;
                    }
                    window_previous_materialization_avg_ms =
                        previous_output_residual_materialization_avg_ms;
                } else {
                    run->failure_stage =
                        "layer" + std::to_string(layer_index) +
                        "_feedforward_window_previous_output_residual_contract";
                    run->failure =
                        "feed-forward repeated segment did not have the previous-layer window residual in its buffer";
                    run->next_unclosed_boundary =
                        "layer" + std::to_string(layer_index) + "_window_previous_output_residual";
                    return false;
                }

                OutputResidualRun selected_previous_output_residual_buffer;
                const OutputResidualRun *selected_previous_for_layer = &window_previous_output_residual;
                if (window_previous_output_residual.selected_token_ids != target_tokens) {
                    const std::string slice_name =
                        "layer" + std::to_string(layer_index - 1u) +
                        "_feedforward_target_output_residual_slice";
                    const std::string slice_stage =
                        "layer" + std::to_string(layer_index - 1u) +
                        "_feedforward_target_output_residual_slice_prefill_phase";
                    if (!slice_output_residual_for_tokens(
                            window_previous_output_residual,
                            target_tokens,
                            slice_name.c_str(),
                            slice_stage.c_str(),
                            &selected_previous_output_residual_buffer,
                            &run->failure_stage,
                            &run->failure
                        )) {
                        run->next_unclosed_boundary =
                            "layer" + std::to_string(layer_index) + "_input_output_residual";
                        return false;
                    }
                    selected_previous_for_layer = &selected_previous_output_residual_buffer;
                }

                PrefillLinearAttentionBatchLayerRun &layer = append_layer(layer_index);
                layer.window_previous_override_used = true;
                if (!run_repeated_prefill_layer_helper_for_targets(
                        repeated_prefill_layer_descriptor(layer_index),
                        target_tokens,
                        *selected_previous_for_layer,
                        layer0_post_attention_rmsnorm_run,
                        layer0_moe_router_run,
                        layer0_residual_hidden_run,
                        model_dir,
                        prefill_tokens,
                        &layer.helper,
                        &window_previous_output_residual,
                        window_previous_materialization_avg_ms
                )) {
                    fail_from_helper(layer.helper);
                    std::cerr
                        << "BATCH_MARK repeated_fail layer=" << layer_index
                        << " stage=" << run->failure_stage
                        << " failure=" << run->failure << std::endl;
                    run->next_unclosed_boundary =
                        "layer" + std::to_string(layer_index) + "_output_residual";
                    return false;
                }
                run->output_boundary = "layer" + std::to_string(layer_index) + "_output_residual";
                run->next_unclosed_boundary =
                    "layer" + std::to_string(layer_index + 1u) + "_output_residual";
                record_selected_moe_layer_surface_for_batch(
                    run,
                    layer.layer_index,
                    layer.block_kind,
                    layer.helper.routed_expert_window,
                    layer.helper.shared_expert_window,
                    layer.helper.output_residual_window
                );
                selected_previous_output_residual = &layer.helper.output_residual_window;
                cache_output_residual(
                    layer_index,
                    layer.helper.output_residual_window,
                    repeated_prefill_layer_helper_avg_ms(layer.helper)
                );
                previous_output_residual_buffer = layer.helper.output_residual_window;
                previous_output_residual_materialization_avg_ms = 0.0;
            }
            if (qwen36_whole_repeated_layer_provider_requested() &&
                prefill_tokens >= kRetainedPrefillTokens) {
                const bool defer_segment_sync = env_flag_enabled(
                    "QRT_PREFILL_DESCRIPTOR_BATCH_DEFER_REPEATED_SEGMENT_SYNC"
                );
                if (!defer_segment_sync) {
                    if (!check_hip(
                            hipDeviceSynchronize(),
                            "whole_repeated_layer_provider_segment_sync",
                            &run->failure_stage,
                            &run->failure
                        )) {
                        run->next_unclosed_boundary =
                            "layer" + std::to_string(last_layer_index) +
                            "_whole_repeated_layer_provider";
                        return false;
                    }
                }
                std::cerr
                    << "BATCH_MARK whole_repeated_layer_provider_segment_done"
                    << " first_layer=" << first_layer_index
                    << " last_layer=" << last_layer_index
                    << " layers=" << layer_count
                    << " target_tokens=" << final_target_tokens.size()
                    << " fixed_weight_entries="
                    << g_whole_repeated_layer_fixed_weights.size()
                    << " fixed_weight_bytes="
                    << g_whole_repeated_layer_fixed_weight_bytes
                    << " routed_matrix_layers="
                    << g_whole_repeated_routed_matrix_weights.size()
                    << " sync="
                    << (defer_segment_sync ? "deferred" : "immediate")
                    << std::endl;
            }
            return true;
        };
    struct DescriptorBatchSegment {
        unsigned int repeated_first_layer = 0;
        unsigned int repeated_last_layer = 0;
        unsigned int full_attention_layer = 0;
    };
    std::vector<DescriptorBatchSegment> batch_segments;
    if (kDescriptorBatchFinalLayer < 3u ||
        kDescriptorBatchFinalLayer >= QRT_QWEN36_LAYER_COUNT) {
        run->failure_stage = "prefill_descriptor_batch_final_layer_contract";
        run->failure = "descriptor batch final layer must be a valid layer at or after the first full-attention block";
        return false;
    }
    const bool final_layer_is_full_attention = (kDescriptorBatchFinalLayer % 4u) == 3u;
    const unsigned int last_full_attention_layer =
        final_layer_is_full_attention
            ? kDescriptorBatchFinalLayer
            : kDescriptorBatchFinalLayer - ((kDescriptorBatchFinalLayer + 1u) % 4u);
    for (unsigned int full_attention_layer = 3u;
         full_attention_layer <= last_full_attention_layer;
         full_attention_layer += 4u) {
        DescriptorBatchSegment segment;
        segment.repeated_first_layer =
            full_attention_layer == 3u ? 2u : full_attention_layer - 3u;
        segment.repeated_last_layer = full_attention_layer - 1u;
        segment.full_attention_layer = full_attention_layer;
        batch_segments.push_back(segment);
    }
    if (batch_segments.empty()) {
        run->failure_stage = "prefill_descriptor_batch_segment_contract";
        run->failure = "descriptor batch did not produce any full-attention segments";
        return false;
    }

    std::vector<unsigned int> final_full_attention_target_tokens = stack_target_tokens;
    unsigned int final_repeated_first_layer = 0;
    unsigned int final_repeated_last_layer = 0;
    if (!final_layer_is_full_attention) {
        final_repeated_first_layer = last_full_attention_layer + 1u;
        final_repeated_last_layer = kDescriptorBatchFinalLayer;
        if (final_repeated_first_layer > final_repeated_last_layer ||
            (final_repeated_first_layer % 4u) == 3u ||
            (final_repeated_last_layer % 4u) == 3u) {
            run->failure_stage = "prefill_descriptor_batch_final_repeated_segment_contract";
            run->failure = "descriptor batch final repeated segment must not include a full-attention layer";
            return false;
        }
        final_full_attention_target_tokens =
            repeated_segment_initial_previous_tokens(
                final_repeated_first_layer,
                final_repeated_last_layer,
                stack_target_tokens
            );
        if (final_full_attention_target_tokens.empty()) {
            run->failure_stage = "prefill_descriptor_batch_final_repeated_frontier_contract";
            run->failure = "descriptor batch final repeated segment produced an empty previous full-attention frontier";
            run->next_unclosed_boundary =
                "layer" + std::to_string(final_repeated_first_layer) +
                "_window_previous_output_residual";
            return false;
        }
    }

    std::vector<std::vector<unsigned int>> segment_target_tokens(batch_segments.size());
    segment_target_tokens.back() = final_full_attention_target_tokens;
    for (size_t segment_index = batch_segments.size() - 1u; segment_index > 0u; --segment_index) {
        const DescriptorBatchSegment &next_segment = batch_segments[segment_index];
        segment_target_tokens[segment_index - 1u] =
            repeated_segment_initial_previous_tokens(
                next_segment.repeated_first_layer,
                next_segment.repeated_last_layer,
                segment_target_tokens[segment_index]
            );
    }
    for (size_t segment_index = 0; segment_index < segment_target_tokens.size(); ++segment_index) {
        if (segment_target_tokens[segment_index].empty()) {
            run->failure_stage = "prefill_descriptor_batch_frontier_contract";
            run->failure = "descriptor batch frontier planning produced an empty token set";
            run->next_unclosed_boundary =
                "layer" +
                std::to_string(batch_segments[segment_index].repeated_first_layer) +
                "_window_previous_output_residual";
            return false;
        }
    }
    std::vector<std::vector<unsigned int>> segment_full_attention_target_tokens =
        segment_target_tokens;
    const bool q262144_terminal_full_prefix_attention =
        final_layer_is_full_attention &&
        maximum_context_streamed_prefill_tokens(prefill_tokens);
    const bool final_full_prefix_attention =
        q262144_terminal_full_prefix_attention ||
        (final_layer_is_full_attention &&
         qwen36_final_layer_full_prefix_requested(prefill_tokens));
    if (final_layer_is_full_attention &&
        !final_full_prefix_attention) {
        segment_full_attention_target_tokens.back() = repeated_target_tokens;
    }
    if (final_full_prefix_attention) {
        if (!token_ids_are_zero_based_prefix(
                segment_full_attention_target_tokens.back(),
                prefill_tokens
            )) {
            run->failure_stage =
                "q262144_terminal_full_attention_target_contract";
            run->failure =
                "terminal full-attention must retain the complete "
                "zero-based BF16 prefix so layer-39 K/V can be captured";
            return false;
        }
        std::cerr
            << (q262144_terminal_full_prefix_attention
                    ? "BATCH_MARK q262144_terminal_full_attention_plan"
                    : "BATCH_MARK full_prefix_terminal_full_attention_plan")
            << " layer=" << kDescriptorBatchFinalLayer
            << " target_tokens="
            << segment_full_attention_target_tokens.back().size()
            << " terminal_output_tokens=" << repeated_target_tokens.size()
            << " carrier=bf16_workspace"
            << " numerical_correctness_claimed=0"
            << std::endl;
    }
    for (size_t segment_index = 0;
         segment_index < segment_full_attention_target_tokens.size();
         ++segment_index) {
        if (segment_full_attention_target_tokens[segment_index].empty()) {
            run->failure_stage = "prefill_descriptor_batch_full_attention_target_contract";
            run->failure =
                "descriptor batch full-attention target planning produced an empty token set";
            run->next_unclosed_boundary =
                "layer" +
                std::to_string(batch_segments[segment_index].full_attention_layer) +
                "_full_attention_output_residual";
            return false;
        }
    }

    const uint64_t descriptor_layer_stack_start_ns = qrt_now_ns();
    run->descriptor_segment_plan_wall_clock_ns =
        qrt_elapsed_ns(segment_plan_start_ns, descriptor_layer_stack_start_ns);
    run->descriptor_pre_stack_wall_clock_ns =
        qrt_elapsed_ns(batch_start_ns, descriptor_layer_stack_start_ns);
    const OutputResidualRun *initial_previous_output_residual = nullptr;
    OutputResidualRun resident_history_previous_output_residual;
    {
        ScopedLayerStackWallClockBuckets stack_bucket_scope(
            &run->layer_stack_wall_clock_buckets
        );
        for (size_t segment_index = 0; segment_index < batch_segments.size(); ++segment_index) {
            const DescriptorBatchSegment &segment = batch_segments[segment_index];
            const std::vector<unsigned int> &target_tokens = segment_target_tokens[segment_index];
            const std::vector<unsigned int> &full_attention_target_tokens =
                segment_full_attention_target_tokens[segment_index];
            std::cerr << "BATCH_MARK repeated_start first_layer="
                      << segment.repeated_first_layer
                      << " last_layer=" << segment.repeated_last_layer
                      << " target_tokens=" << target_tokens.size() << std::endl;
            run->next_unclosed_boundary =
                "layer" + std::to_string(segment.repeated_first_layer) + "_output_residual";
            const uint64_t repeated_segment_start_ns = qrt_now_ns();
            const bool repeated_segment_ok = run_repeated_segment(
                    segment.repeated_first_layer,
                    segment.repeated_last_layer,
                    target_tokens,
                    initial_previous_output_residual
            );
            const uint64_t repeated_segment_elapsed_ns =
                qrt_elapsed_ns(repeated_segment_start_ns, qrt_now_ns());
            run->repeated_segments_wall_clock_ns += repeated_segment_elapsed_ns;
            run->repeated_segment_call_count += 1u;
            if (repeated_segment_elapsed_ns >
                run->slowest_repeated_segment_wall_clock_ns) {
                run->slowest_repeated_segment_wall_clock_ns =
                    repeated_segment_elapsed_ns;
                run->slowest_repeated_segment_first_layer =
                    segment.repeated_first_layer;
                run->slowest_repeated_segment_last_layer =
                    segment.repeated_last_layer;
                run->slowest_repeated_segment_target_token_count =
                    target_tokens.size();
            }
            if (!repeated_segment_ok) {
                return false;
            }
            std::cerr << "BATCH_MARK repeated_done first_layer="
                      << segment.repeated_first_layer
                      << " last_layer=" << segment.repeated_last_layer
                      << " output_boundary=" << run->output_boundary << std::endl;
            run->next_unclosed_boundary =
                "layer" + std::to_string(segment.full_attention_layer) +
                "_full_attention_output_residual";
            std::cerr << "BATCH_MARK full_attention_start layer="
                      << segment.full_attention_layer
                      << " target_tokens=" << full_attention_target_tokens.size()
                      << " repeated_target_tokens=" << target_tokens.size()
                      << std::endl;
            OutputResidualRun full_history_previous_output_residual;
            OutputResidualRun full_attention_selected_previous_output_residual;
            const OutputResidualRun *history_previous_output_residual = nullptr;
            const bool segment_full_history =
                enable_resident_history_carrier ||
                all_full_attention_full_history ||
                (first_full_attention_full_history &&
                 segment.full_attention_layer == 3u);
            if (segment_full_history) {
                const std::vector<unsigned int> history_tokens =
                    full_attention_product_history_tokens(full_attention_target_tokens);
                double full_history_materialization_avg_ms = 0.0;
                if (enable_resident_history_carrier &&
                    selected_previous_output_residual != nullptr &&
                    selected_previous_output_residual->selected_token_ids ==
                        history_tokens) {
                    history_previous_output_residual =
                        selected_previous_output_residual;
                    std::cerr
                        << "BATCH_MARK full_attention_full_history_previous_carrier"
                        << " layer=" << segment.full_attention_layer
                        << " history_tokens=" << history_tokens.size()
                        << " target_tokens=" << full_attention_target_tokens.size()
                        << std::endl;
                } else {
                    std::cerr
                        << "BATCH_MARK full_attention_full_history_previous_start layer="
                        << segment.full_attention_layer
                        << " history_tokens=" << history_tokens.size()
                        << " target_tokens=" << full_attention_target_tokens.size()
                        << std::endl;
                    if (!materialize_cached_output_residual(
                            segment.full_attention_layer - 1u,
                            history_tokens,
                            &full_history_previous_output_residual,
                            &full_history_materialization_avg_ms
                        )) {
                        run->next_unclosed_boundary =
                            "layer" +
                            std::to_string(segment.full_attention_layer) +
                            "_full_attention_full_history_previous_output_residual";
                        return false;
                    }
                    std::cerr
                        << "BATCH_MARK full_attention_full_history_previous_done layer="
                        << segment.full_attention_layer
                        << " history_tokens=" << history_tokens.size()
                        << " avg_ms=" << full_history_materialization_avg_ms
                        << std::endl;
                    history_previous_output_residual =
                        &full_history_previous_output_residual;
                }
            }
            if (selected_previous_output_residual == nullptr) {
                run->failure_stage =
                    "layer" + std::to_string(segment.full_attention_layer) +
                    "_selected_previous_output_residual_contract";
                run->failure =
                    "descriptor batch full-attention layer is missing the selected previous output residual";
                run->next_unclosed_boundary =
                    "layer" + std::to_string(segment.full_attention_layer) +
                    "_full_attention_input_output_residual";
                return false;
            }
            const OutputResidualRun *selected_previous_for_full_attention =
                selected_previous_output_residual;
            if (selected_previous_output_residual->selected_token_ids !=
                full_attention_target_tokens) {
                const std::string slice_name =
                    "layer" +
                    std::to_string(segment.full_attention_layer - 1u) +
                    "_full_attention_target_output_residual_slice";
                const std::string slice_stage =
                    "layer" +
                    std::to_string(segment.full_attention_layer - 1u) +
                    "_full_attention_target_output_residual_slice_prefill_phase";
                const unsigned int source_layer =
                    segment.full_attention_layer - 1u;
                const bool device_only_source =
                    output_residual_device_only_full_prefix(
                        *selected_previous_output_residual,
                        source_layer,
                        prefill_tokens
                    ) ||
                    q262144_bf16_output_handoff_matches(
                        source_layer,
                        *selected_previous_output_residual,
                        prefill_tokens
                    );
                const bool slice_ok = device_only_source
                    ? materialize_device_output_residual_rows_for_tokens(
                          source_layer,
                          prefill_tokens,
                          *selected_previous_output_residual,
                          full_attention_target_tokens,
                          slice_name.c_str(),
                          slice_stage.c_str(),
                          &full_attention_selected_previous_output_residual,
                          &run->failure_stage,
                          &run->failure
                      )
                    : slice_output_residual_for_tokens(
                          *selected_previous_output_residual,
                          full_attention_target_tokens,
                          slice_name.c_str(),
                          slice_stage.c_str(),
                          &full_attention_selected_previous_output_residual,
                          &run->failure_stage,
                          &run->failure
                      );
                if (!slice_ok) {
                    run->next_unclosed_boundary =
                        "layer" + std::to_string(segment.full_attention_layer) +
                        "_full_attention_input_output_residual";
                    return false;
                }
                selected_previous_for_full_attention =
                    &full_attention_selected_previous_output_residual;
            }
            const uint64_t full_attention_start_ns = qrt_now_ns();
            const bool full_attention_ok = run_full_attention_layer(
                    segment.full_attention_layer,
                    full_attention_target_tokens,
                    *selected_previous_for_full_attention,
                    history_previous_output_residual
            );
            const uint64_t full_attention_elapsed_ns =
                qrt_elapsed_ns(full_attention_start_ns, qrt_now_ns());
            run->full_attention_layers_wall_clock_ns += full_attention_elapsed_ns;
            run->full_attention_layer_call_count += 1u;
            if (full_attention_elapsed_ns >
                run->slowest_full_attention_layer_wall_clock_ns) {
                run->slowest_full_attention_layer_wall_clock_ns =
                    full_attention_elapsed_ns;
                run->slowest_full_attention_layer = segment.full_attention_layer;
                run->slowest_full_attention_target_token_count =
                    full_attention_target_tokens.size();
            }
            if (!full_attention_ok) {
                return false;
            }
            std::cerr << "BATCH_MARK full_attention_done layer="
                      << segment.full_attention_layer
                      << " output_boundary=" << run->output_boundary << std::endl;
            if (enable_resident_history_carrier) {
                if (segment.full_attention_layer < kDescriptorBatchFinalLayer) {
                    resident_history_previous_output_residual =
                        std::move(run->full_attention_layers.back().output_residual);
                    initial_previous_output_residual =
                        &resident_history_previous_output_residual;
                    prune_output_residual_cache_for_resident_history(
                        segment.full_attention_layer
                    );
                } else {
                    initial_previous_output_residual = nullptr;
                    prune_output_residual_cache_for_resident_history(
                        segment.full_attention_layer
                    );
                }
                release_vector_capacity(&run->layers);
                release_vector_capacity(&run->full_attention_layers);
                run->layers.reserve(QRT_QWEN36_LAYER_COUNT);
                run->full_attention_layers.reserve(QRT_QWEN36_LAYER_COUNT / 4u);
                selected_previous_output_residual = nullptr;
                std::cerr
                    << "BATCH_MARK resident_history_carrier_trim layer="
                    << segment.full_attention_layer
                    << " cached_residuals=" << output_residual_cache.size()
                    << std::endl;
            } else {
                initial_previous_output_residual =
                    &run->full_attention_layers.back().output_residual;
            }
        }

        if (!final_layer_is_full_attention) {
            std::cerr << "BATCH_MARK final_repeated_start first_layer="
                      << final_repeated_first_layer
                      << " last_layer=" << final_repeated_last_layer
                      << " target_tokens=" << stack_target_tokens.size() << std::endl;
            run->next_unclosed_boundary =
                "layer" + std::to_string(final_repeated_first_layer) + "_output_residual";
            const uint64_t final_repeated_start_ns = qrt_now_ns();
            const bool final_repeated_ok = run_repeated_segment(
                    final_repeated_first_layer,
                    final_repeated_last_layer,
                    stack_target_tokens,
                    initial_previous_output_residual
                );
            const uint64_t final_repeated_elapsed_ns =
                qrt_elapsed_ns(final_repeated_start_ns, qrt_now_ns());
            run->repeated_segments_wall_clock_ns += final_repeated_elapsed_ns;
            run->repeated_segment_call_count += 1u;
            if (final_repeated_elapsed_ns >
                run->slowest_repeated_segment_wall_clock_ns) {
                run->slowest_repeated_segment_wall_clock_ns =
                    final_repeated_elapsed_ns;
                run->slowest_repeated_segment_first_layer =
                    final_repeated_first_layer;
                run->slowest_repeated_segment_last_layer =
                    final_repeated_last_layer;
                run->slowest_repeated_segment_target_token_count =
                    stack_target_tokens.size();
            }
            if (!final_repeated_ok) {
                return false;
            }
            std::cerr << "BATCH_MARK final_repeated_done first_layer="
                      << final_repeated_first_layer
                      << " last_layer=" << final_repeated_last_layer
                      << " output_boundary=" << run->output_boundary << std::endl;
        }
    }
    run->descriptor_layer_stack_wall_clock_ns =
        qrt_elapsed_ns(descriptor_layer_stack_start_ns, qrt_now_ns());
    std::cerr << "BATCH_MARK descriptor_layer_stack_done elapsed_ns="
              << run->descriptor_layer_stack_wall_clock_ns
              << " repeated_ns=" << run->repeated_segments_wall_clock_ns
              << " full_attention_ns="
              << run->full_attention_layers_wall_clock_ns
              << " repeated_calls=" << run->repeated_segment_call_count
              << " full_attention_calls="
              << run->full_attention_layer_call_count << std::endl;
    if (env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_PROFILE_RESIDENT_LINEAR_STACK_SYNC"
        )) {
        const LayerStackWallClockBuckets &buckets =
            run->layer_stack_wall_clock_buckets;
        std::cerr << "BATCH_MARK descriptor_layer_stack_bucket_profile";
        for (size_t index = 0u; index < kLayerStackWallBucketCount; ++index) {
            const LayerStackWallBucket bucket =
                static_cast<LayerStackWallBucket>(index);
            std::cerr << " " << layer_stack_wall_bucket_name(bucket)
                      << "_ms="
                      << (static_cast<double>(buckets.elapsed_ns[index]) /
                          1000000.0)
                      << " " << layer_stack_wall_bucket_name(bucket)
                      << "_calls=" << buckets.call_count[index]
                      << " " << layer_stack_wall_bucket_name(bucket)
                      << "_host_bytes="
                      << buckets.host_materialized_output_bytes[index]
                      << " " << layer_stack_wall_bucket_name(bucket)
                      << "_host_stages="
                      << buckets.host_materialized_stage_count[index];
        }
        std::cerr
            << " full_attention_resident_core_calls="
            << buckets.full_attention_resident_core_call_count
            << " full_attention_resident_core_weight_load_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_weight_load_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_device_alloc_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_device_alloc_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_h2d_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_h2d_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_kernel_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_kernel_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_d2h_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_d2h_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_free_ms="
            << (static_cast<double>(
                    buckets.full_attention_resident_core_free_ns
                ) /
                1000000.0)
            << " full_attention_resident_core_weight_read_bytes="
            << buckets.full_attention_resident_core_weight_read_bytes
            << " full_attention_resident_core_device_alloc_bytes="
            << buckets.full_attention_resident_core_device_alloc_bytes
            << " full_attention_resident_core_h2d_bytes="
            << buckets.full_attention_resident_core_h2d_bytes
            << " full_attention_resident_core_d2h_bytes="
            << buckets.full_attention_resident_core_d2h_bytes
            << " full_attention_resident_core_score_scratch_calls="
            << buckets.full_attention_resident_core_score_scratch_call_count
            << " full_attention_resident_core_score_scratch_bytes="
            << buckets.full_attention_resident_core_score_scratch_bytes
            << std::endl;
    }

    if (kDescriptorBatchFinalLayer + 1u >= QRT_QWEN36_LAYER_COUNT) {
        const uint64_t post_stack_start_ns = qrt_now_ns();
        OutputResidualRun final_output_residual;
        double final_output_residual_materialization_avg_ms = 0.0;
        run->next_unclosed_boundary = "final_norm";
        const uint64_t final_materialization_start_ns = qrt_now_ns();
        std::cerr
            << "BATCH_MARK post_stack_stage_start stage=final_output_residual_materialization"
            << " layer=" << kDescriptorBatchFinalLayer
            << " target_tokens=" << repeated_target_tokens.size() << std::endl;
        if (!materialize_cached_output_residual(
                kDescriptorBatchFinalLayer,
                repeated_target_tokens,
                &final_output_residual,
                &final_output_residual_materialization_avg_ms
            )) {
            run->final_output_residual_materialization_wall_clock_ns =
                qrt_elapsed_ns(final_materialization_start_ns, qrt_now_ns());
            std::cerr
                << "BATCH_MARK post_stack_stage_done stage=final_output_residual_materialization"
                << " status=fail elapsed_ns="
                << run->final_output_residual_materialization_wall_clock_ns
                << std::endl;
            run->next_unclosed_boundary = "final_norm_input_residual";
            return false;
        }
        run->final_output_residual_materialization_wall_clock_ns =
            qrt_elapsed_ns(final_materialization_start_ns, qrt_now_ns());
        std::cerr
            << "BATCH_MARK post_stack_stage_done stage=final_output_residual_materialization"
            << " status=ok elapsed_ns="
            << run->final_output_residual_materialization_wall_clock_ns
            << std::endl;
        run->final_norm_attempted = true;
        const uint64_t final_norm_start_ns = qrt_now_ns();
        std::cerr << "BATCH_MARK post_stack_stage_start stage=final_norm"
                  << std::endl;
        if (ScopedQwen36PrefixBatchSuffix::active && final_output_residual.gpu_output.empty()) {
            // An exact cache-key hit preserves the GPU-only carrier. The
            // ordinary terminal corridor accepts one such row; suffix teacher
            // predictions require the actual complete set of normalized rows.
            OutputResidualRun materialized;
            if (!materialize_device_output_residual_rows_for_tokens(
                    kDescriptorBatchFinalLayer, prefill_tokens, final_output_residual,
                    repeated_target_tokens, "prefix_batch_final_output", "prefix_batch_final_output_copy",
                    &materialized, &run->failure_stage, &run->failure)) {
                run->next_unclosed_boundary = "final_norm_input_residual";
                return false;
            }
            final_output_residual = std::move(materialized);
        }
        if (!run_final_norm(
                final_output_residual,
                model_dir,
                prefill_tokens,
                &run->final_norm
            )) {
            std::cerr << "BATCH_MARK post_stack_stage_done stage=final_norm"
                      << " status=fail elapsed_ns="
                      << qrt_elapsed_ns(final_norm_start_ns, qrt_now_ns())
                      << std::endl;
            if (!capture_failure_from_run(
                    run->final_norm,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->failure_stage = "final_norm_prefill_phase";
                run->failure = "final norm failed without a stage-specific failure";
            }
            run->next_unclosed_boundary = "final_norm";
            return false;
        }
        std::cerr << "BATCH_MARK post_stack_stage_done stage=final_norm"
                  << " status=ok elapsed_ns="
                  << qrt_elapsed_ns(final_norm_start_ns, qrt_now_ns())
                  << std::endl;
        run->output_boundary = "final_norm";
        run->next_unclosed_boundary = "lm_head";
        run->lm_head_attempted = true;
        const uint64_t lm_head_start_ns = qrt_now_ns();
        const bool continuous_long_context_lm_head_probe =
            resident_continuous_long_context_provider_requested(
                prefill_tokens
            );
        const char *const lm_head_probe_token_ids_env =
            continuous_long_context_lm_head_probe
                ? "QRT_QWEN36_CONTINUOUS_LONG_CONTEXT_LM_HEAD_PROBE_TOKEN_IDS"
                : "QRT_QWEN36_EXACT_ARBITRARY_LM_HEAD_PROBE_TOKEN_IDS";
        std::vector<uint32_t> lm_head_probe_token_ids;
        if ((continuous_long_context_lm_head_probe ||
             qwen36_exact_arbitrary_product_path_enabled(prefill_tokens)) &&
            !parse_gb10_teacher_forced_continuation_env(
                lm_head_probe_token_ids_env,
                &lm_head_probe_token_ids,
                &run->failure
            )) {
            run->failure_stage =
                "prefill_lm_head_probe_tokens";
            run->next_unclosed_boundary = "lm_head";
            return false;
        }
        std::cerr << "BATCH_MARK post_stack_stage_start stage=lm_head"
                  << std::endl;
        if (!run_lm_head(
                run->final_norm,
                model_dir,
                prefill_tokens,
                &run->lm_head,
                lm_head_probe_token_ids.empty()
                    ? nullptr
                    : &lm_head_probe_token_ids
            )) {
            std::cerr << "BATCH_MARK post_stack_stage_done stage=lm_head"
                      << " status=fail elapsed_ns="
                      << qrt_elapsed_ns(lm_head_start_ns, qrt_now_ns())
                      << std::endl;
            if (!capture_failure_from_run(
                    run->lm_head,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->failure_stage = "lm_head_prefill_phase";
                run->failure = "lm_head failed without a stage-specific failure";
            }
            run->next_unclosed_boundary = "lm_head";
            return false;
        }
        std::cerr << "BATCH_MARK post_stack_stage_done stage=lm_head"
                  << " status=ok elapsed_ns="
                  << qrt_elapsed_ns(lm_head_start_ns, qrt_now_ns())
                  << std::endl;
        if (!capture_qwen36_prefix_batch_terminal(run->final_norm, model_dir, prefill_tokens,
                &run->failure_stage, &run->failure)) {
            run->next_unclosed_boundary = "lm_head";
            return false;
        }
        run->output_boundary = "lm_head";
        run->next_unclosed_boundary = "sampler";
        run->sampler_attempted = true;
        const uint64_t sampler_start_ns = qrt_now_ns();
        std::cerr << "BATCH_MARK post_stack_stage_start stage=sampler"
                  << std::endl;
        if (!run_sampler(
                run->lm_head,
                prefill_tokens,
                &run->sampler
            )) {
            std::cerr << "BATCH_MARK post_stack_stage_done stage=sampler"
                      << " status=fail elapsed_ns="
                      << qrt_elapsed_ns(sampler_start_ns, qrt_now_ns())
                      << std::endl;
            if (!capture_failure_from_run(
                    run->sampler,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->failure_stage = "sampler_prefill_phase";
                run->failure = "sampler failed without a stage-specific failure";
            }
            run->next_unclosed_boundary = "sampler";
            return false;
        }
        std::cerr << "BATCH_MARK post_stack_stage_done stage=sampler"
                  << " status=ok elapsed_ns="
                  << qrt_elapsed_ns(sampler_start_ns, qrt_now_ns())
                  << std::endl;
        if (continuous_long_context_lm_head_probe ||
            !lm_head_probe_token_ids.empty()) {
            const size_t selected_rows =
                run->lm_head.selected_token_count;
            const bool topk_shape_valid =
                selected_rows != 0u &&
                run->lm_head.gpu_topk_ids.size() ==
                    run->lm_head.gpu_topk_logits.size() &&
                run->lm_head.gpu_topk_ids.size() % selected_rows == 0u;
            const size_t topk = topk_shape_valid
                ? run->lm_head.gpu_topk_ids.size() / selected_rows
                : 0u;
            const auto terminal_it = std::find(
                run->lm_head.selected_token_ids.begin(),
                run->lm_head.selected_token_ids.end(),
                prefill_tokens - 1u
            );
            const bool terminal_row_valid =
                terminal_it != run->lm_head.selected_token_ids.end();
            const size_t terminal_row = terminal_row_valid
                ? static_cast<size_t>(std::distance(
                      run->lm_head.selected_token_ids.begin(),
                      terminal_it
                  ))
                : 0u;
            const size_t topk_base = terminal_row * topk;
            const size_t probe_count =
                run->lm_head.probe_token_ids.size();
            const bool probe_shape_valid =
                run->lm_head.gpu_probe_logits.size() ==
                    selected_rows * probe_count;
            std::ostringstream marker;
            marker << std::setprecision(
                          std::numeric_limits<float>::max_digits10
                      )
                   << (continuous_long_context_lm_head_probe
                           ? "BATCH_MARK continuous_long_context_lm_head_diagnostic"
                           : "BATCH_MARK qwen36_exact_arbitrary_lm_head_probe")
                   << " prefill_tokens=" << prefill_tokens
                   << " terminal_target=" << (prefill_tokens - 1u)
                   << " selected_rows=" << selected_rows
                   << " terminal_row=" << terminal_row
                   << " terminal_row_valid="
                   << (terminal_row_valid ? 1 : 0)
                   << " topk_count=" << topk
                   << " topk_shape_valid="
                   << (topk_shape_valid ? 1 : 0);
            if (topk_shape_valid && terminal_row_valid && topk != 0u) {
                marker << " topk_ids=";
                for (size_t slot = 0u; slot < topk; ++slot) {
                    if (slot != 0u) {
                        marker << ',';
                    }
                    marker << run->lm_head.gpu_topk_ids[topk_base + slot];
                }
                marker << " topk_logits=";
                for (size_t slot = 0u; slot < topk; ++slot) {
                    if (slot != 0u) {
                        marker << ',';
                    }
                    marker << run->lm_head.gpu_topk_logits[topk_base + slot];
                }
            }
            marker << " probe_count=" << probe_count
                   << " probe_shape_valid="
                   << (probe_shape_valid ? 1 : 0);
            if (probe_shape_valid && terminal_row_valid &&
                probe_count != 0u) {
                const size_t probe_base = terminal_row * probe_count;
                marker << " probe_ids=";
                for (size_t slot = 0u; slot < probe_count; ++slot) {
                    if (slot != 0u) {
                        marker << ',';
                    }
                    marker << run->lm_head.probe_token_ids[slot];
                }
                marker << " probe_logits=";
                for (size_t slot = 0u; slot < probe_count; ++slot) {
                    if (slot != 0u) {
                        marker << ',';
                    }
                    marker << run->lm_head.gpu_probe_logits[
                        probe_base + slot
                    ];
                }
                auto append_probe_logits =
                    [&](const char *name,
                        const std::vector<float> &values) {
                        marker << ' ' << name << '=';
                        if (values.size() != selected_rows * probe_count) {
                            marker << "unavailable";
                            return;
                        }
                        for (size_t slot = 0u;
                             slot < probe_count;
                             ++slot) {
                            if (slot != 0u) {
                                marker << ',';
                            }
                            marker << values[probe_base + slot];
                        }
                    };
                if (run->lm_head.exact_f32_probe_active) {
                    append_probe_logits(
                        "exact_f32_probe_logits",
                        run->lm_head.exact_f32_probe_logits
                    );
                }
                if (run->lm_head.unrounded_output_probe_active) {
                    append_probe_logits(
                        "b200_unrounded_probe_logits",
                        run->lm_head.b200_unrounded_probe_logits
                    );
                    append_probe_logits(
                        "group8_unrounded_probe_logits",
                        run->lm_head.group8_unrounded_probe_logits
                    );
                    if (run->lm_head.hipblaslt_f32_heuristic_count != 0u &&
                        run->lm_head.hipblaslt_f32_heuristic_probe_logits.size() >=
                            selected_rows * probe_count) {
                        std::vector<float> heuristic0(
                            run->lm_head
                                .hipblaslt_f32_heuristic_probe_logits.begin(),
                            run->lm_head
                                .hipblaslt_f32_heuristic_probe_logits.begin() +
                                selected_rows * probe_count
                        );
                        append_probe_logits(
                            "hipblaslt_f32_heuristic0_probe_logits",
                            heuristic0
                        );
                    }
                    if (run->lm_head.rocblas_standard_f32_probe_active) {
                        append_probe_logits(
                            "rocblas_standard_f32_probe_logits",
                            run->lm_head.rocblas_standard_f32_probe_logits
                        );
                    }
                    if (run->lm_head.rocblas_solution_f32_probe_active) {
                        append_probe_logits(
                            "rocblas_solution_f32_probe_logits",
                            run->lm_head.rocblas_solution_f32_probe_logits
                        );
                    }
                }
            }
            marker << " diagnostic_only=1 numerical_correctness_claimed=0";
            std::cerr << marker.str() << std::endl;
        }
        run->output_boundary = "sampler";
        run->next_unclosed_boundary = "token_loop_validation";
        run->token_loop_validation_attempted = true;
        const uint64_t token_loop_validation_start_ns = qrt_now_ns();
        std::cerr
            << "BATCH_MARK post_stack_stage_start stage=token_loop_validation"
            << std::endl;
        if (!run_token_loop_validation(
                run->sampler,
                prefill_tokens,
                &run->token_loop_validation
            )) {
            std::cerr
                << "BATCH_MARK post_stack_stage_done stage=token_loop_validation"
                << " status=fail elapsed_ns="
                << qrt_elapsed_ns(
                       token_loop_validation_start_ns,
                       qrt_now_ns()
                   )
                << std::endl;
            if (!capture_failure_from_run(
                    run->token_loop_validation,
                    &run->failure_stage,
                    &run->failure
                )) {
                run->failure_stage = "token_loop_validation_prefill_phase";
                run->failure =
                    "token-loop validation failed without a stage-specific failure";
            }
            run->next_unclosed_boundary = "token_loop_validation";
            return false;
        }
        std::cerr
            << "BATCH_MARK post_stack_stage_done stage=token_loop_validation"
            << " status=ok elapsed_ns="
            << qrt_elapsed_ns(token_loop_validation_start_ns, qrt_now_ns())
            << std::endl;
        run->output_boundary = "token_loop_validation";
        if (skip_synthetic_validation_continuation &&
            !real_prompt_input_surface) {
            run->synthetic_decode_one_skipped = true;
            run->output_boundary = "real_prompt_token_embedding_prefill_surface";
            run->next_unclosed_boundary = "decode_one_gb10_output_correctness";
        } else if (real_prompt_input_surface &&
                   real_prompt_fixture != nullptr &&
                   real_prompt_fixture->completion_token_count < 2u) {
            run->gb10_decode_output_correctness_attempted = true;
            DecodeOneExecutionRun no_decode_one_run;
            if (!run_gb10_decode_output_correctness(
                    real_prompt_input_surface,
                    *real_prompt_fixture,
                    run->lm_head,
                    run->token_loop_validation,
                    no_decode_one_run,
                    &run->gb10_decode_output_correctness
                )) {
                run->failure_stage =
                    run->gb10_decode_output_correctness.failure_stage;
                run->failure =
                    run->gb10_decode_output_correctness.failure;
                run->output_boundary =
                    run->gb10_decode_output_correctness.output_boundary.empty()
                        ? "real_prompt_token_embedding_prefill_surface"
                        : run->gb10_decode_output_correctness.output_boundary;
                run->next_unclosed_boundary =
                    run->gb10_decode_output_correctness.next_unclosed_boundary.empty()
                        ? "gb10_first_completion_token_correctness"
                        : run->gb10_decode_output_correctness.next_unclosed_boundary;
                return false;
            }
            run->output_boundary =
                run->gb10_decode_output_correctness.output_boundary;
            run->next_unclosed_boundary =
                run->gb10_decode_output_correctness.next_unclosed_boundary;
        } else {
            run->next_unclosed_boundary = "decode_one_validation";
            run->decode_one_validation_attempted = true;
            if (!run_decode_one_validation(
                    run->token_loop_validation,
                    run->layer1_frontier,
                    &run->decode_one_validation
                )) {
                if (!capture_failure_from_run(
                        run->decode_one_validation,
                        &run->failure_stage,
                        &run->failure
                    )) {
                    run->failure_stage = "decode_one_validation_prefill_handoff";
                    run->failure =
                        "decode-one validation failed without a stage-specific failure";
                }
                run->next_unclosed_boundary = "decode_one_validation";
                return false;
            }
            run->output_boundary = "decode_one_validation";
            run->next_unclosed_boundary = "decode_one_execution";
            run->decode_one_execution_attempted = true;
            std::vector<uint32_t> decode_one_output_head_probe_token_ids;
            if (real_prompt_input_surface &&
                real_prompt_fixture != nullptr &&
                real_prompt_fixture->completion_token_count >= 2u) {
                append_unique_u32(
                    &decode_one_output_head_probe_token_ids,
                    real_prompt_fixture->completion_token_ids[1]
                );
                append_unique_u32(
                    &decode_one_output_head_probe_token_ids,
                    real_prompt_fixture->completion_token_ids[0]
                );
                append_unique_u32(
                    &decode_one_output_head_probe_token_ids,
                    run->decode_one_validation.gpu_decode_input_token_id
                );
            }
            std::vector<uint32_t> decode_prompt_context_token_ids;
            if (real_prompt_input_surface) {
                decode_prompt_context_token_ids =
                    run->real_prompt_surface.prompt_token_ids;
            }
            if (!run_decode_one_execution(
                    run->decode_one_validation,
                    model_dir,
                    decode_one_output_head_probe_token_ids,
                    decode_prompt_context_token_ids,
                    &run->decode_one_execution
                )) {
                if (!capture_failure_from_run(
                        run->decode_one_execution,
                        &run->failure_stage,
                        &run->failure
                    )) {
                    run->failure_stage = "decode_one_execution_prefill_handoff";
                    run->failure =
                        "decode-one execution failed without a stage-specific failure";
                }
                run->next_unclosed_boundary =
                    run->decode_one_execution.next_unclosed_boundary.empty()
                        ? "decode_one_execution"
                        : run->decode_one_execution.next_unclosed_boundary;
                return false;
            }
            run->output_boundary =
                run->decode_one_execution.output_correctness_pass
                    ? "decode_one_output_correctness"
                    : "decode_one_execution";
            run->next_unclosed_boundary =
                run->decode_one_execution.next_unclosed_boundary;
            if (real_prompt_input_surface &&
                run->decode_one_execution.output_correctness_pass) {
                run->gb10_decode_output_correctness_attempted = true;
                if (!run_gb10_decode_output_correctness(
                        real_prompt_input_surface,
                        *real_prompt_fixture,
                        run->lm_head,
                        run->token_loop_validation,
                        run->decode_one_execution,
                        &run->gb10_decode_output_correctness
                    )) {
                    run->failure_stage =
                        run->gb10_decode_output_correctness.failure_stage;
                    run->failure =
                        run->gb10_decode_output_correctness.failure;
                    run->output_boundary =
                        run->gb10_decode_output_correctness.output_boundary.empty()
                            ? "real_prompt_token_embedding_prefill_surface"
                            : run->gb10_decode_output_correctness.output_boundary;
                    run->next_unclosed_boundary =
                        run->gb10_decode_output_correctness.next_unclosed_boundary.empty()
                            ? "decode_one_gb10_output_correctness"
                            : run->gb10_decode_output_correctness.next_unclosed_boundary;
                    return false;
                }
                run->output_boundary =
                    run->gb10_decode_output_correctness.output_boundary;
                run->next_unclosed_boundary =
                    run->gb10_decode_output_correctness.next_unclosed_boundary;
            }
        }
        run->post_stack_wall_clock_ns =
            qrt_elapsed_ns(post_stack_start_ns, qrt_now_ns());
        std::cerr << "BATCH_MARK post_stack_done elapsed_ns="
                  << run->post_stack_wall_clock_ns
                  << " output_boundary=" << run->output_boundary
                  << " next=" << run->next_unclosed_boundary << std::endl;
    } else {
        run->next_unclosed_boundary =
            "layer" + std::to_string(kDescriptorBatchFinalLayer + 1u) +
            "_output_residual";
    }
    if (!run->layer1_frontier_attempted ||
        (!run->layer1_frontier.product_path_digest_valid &&
         !resident_device_layer1_frontier)) {
        run->failure_stage = "layer1_frontier_product_path_digest_contract";
        run->failure =
            "prefill descriptor batch did not attach a product-path-compatible layer-1 frontier digest";
        return false;
    }
    if (!real_prompt_input_surface &&
        run->real_prompt_surface.correctness_pass &&
        run->output_boundary == "decode_one_output_correctness") {
        run->output_boundary = "real_prompt_token_embedding_prefill_surface";
        run->next_unclosed_boundary = "decode_one_gb10_output_correctness";
    }
    if (run->routed_expert_gpu_output_contract.call_count == 0u) {
        run->routed_expert_gpu_output_contract =
            prefill_descriptor_batch_routed_expert_gpu_output_contract(*run);
    }
    if (run->routed_expert_gpu_downstream_contract.call_count == 0u) {
        run->routed_expert_gpu_downstream_contract =
            prefill_descriptor_batch_routed_expert_gpu_downstream_contract(*run);
    }
    finalize_single_layer_routed_output_contract(
        &run->routed_expert_gpu_output_contract
    );
    finalize_single_layer_downstream_contract(
        &run->routed_expert_gpu_downstream_contract
    );
    finalize_selected_moe_batched_layer_surface_digest(
        &run->selected_moe_batched_surface,
        run->routed_expert_gpu_output_contract,
        run->routed_expert_gpu_downstream_contract
    );
    capture_qwen36_prefix_checkpoint_hidden(*run, prefill_tokens);
    if (!capture_qwen36_prefill_mtp_target_hidden_if_requested(
            *run,
            prefill_tokens,
            &run->failure_stage,
            &run->failure
        )) {
        run->next_unclosed_boundary =
            "qwen36_mtp_prefill_target_hidden_capture";
        return false;
    }
    run->correctness_pass = true;
    run->wall_clock_ns = qrt_elapsed_ns(batch_start_ns, qrt_now_ns());
    std::cerr << "BATCH_MARK batch_probe_done output_boundary="
              << run->output_boundary
              << " next=" << run->next_unclosed_boundary << std::endl;
    return true;
}

bool build_frontier_output_residual_from_export(
    const qrt_qwen36_layer1_frontier_buffer_export_t *frontier,
    OutputResidualRun *run,
    uint64_t *digest_fnv1a64,
    uint64_t *last_output_fnv1a64,
    std::string *failure_stage,
    std::string *failure
) {
    if (run == nullptr || digest_fnv1a64 == nullptr ||
        last_output_fnv1a64 == nullptr || failure_stage == nullptr ||
        failure == nullptr) {
        return false;
    }
    *run = OutputResidualRun{};
    *digest_fnv1a64 = UINT64_C(0);
    *last_output_fnv1a64 = UINT64_C(0);
    if (frontier == nullptr || frontier->token_ids == nullptr ||
        frontier->hidden_values == nullptr || frontier->token_count == 0u ||
        frontier->hidden_value_count !=
            frontier->token_count *
                static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE)) {
        *failure_stage = "resident_internal_frontier_export_contract";
        *failure = "resident internal continuation received an invalid frontier export";
        run->failure_stage = *failure_stage;
        run->failure = *failure;
        return false;
    }

    run->name = "resident_internal_layer1_frontier_output_residual";
    run->stage = "resident_q8192_layer1_frontier_internal_continuation";
    run->selected_token_ids.reserve(frontier->token_count);
    for (size_t token_index = 0; token_index < frontier->token_count;
         ++token_index) {
        run->selected_token_ids.push_back(
            static_cast<unsigned int>(frontier->token_ids[token_index])
        );
    }
    run->selected_token_count = run->selected_token_ids.size();
    run->output_elements = frontier->hidden_value_count;
    run->output_bytes = run->output_elements * sizeof(float);
    run->gpu_output.assign(
        frontier->hidden_values,
        frontier->hidden_values + frontier->hidden_value_count
    );
    run->selected_token_ids_hash = fnv1a64_bytes_seeded(
        run->selected_token_ids.data(),
        run->selected_token_ids.size() * sizeof(run->selected_token_ids[0])
    );
    run->gpu_output_hash =
        qrt_fnv1a64_f32(run->gpu_output.data(), run->gpu_output.size());
    run->selected_reference_hash = run->gpu_output_hash;
    run->selected_gpu_hash = run->gpu_output_hash;
    run->max_abs_diff = 0.0f;
    run->checked_values = static_cast<unsigned int>(
        std::min<size_t>(
            run->output_elements,
            (std::numeric_limits<unsigned int>::max)()
        )
    );
    run->selected_tokens_per_second = 0.0;

    size_t hidden_value_count = 0;
    const bool diagnostic_digest_computed =
        frontier->product_path != 0u &&
        product_path_compatible_layer1_frontier_digest(
            run->selected_token_ids,
            run->gpu_output,
            digest_fnv1a64,
            last_output_fnv1a64,
            &hidden_value_count
        );
    const bool hidden_values_finite = std::all_of(
        run->gpu_output.begin(),
        run->gpu_output.end(),
        [](float value) { return std::isfinite(value); }
    );
    run->correctness_pass =
        frontier->product_path != 0u &&
        hidden_value_count == frontier->hidden_value_count &&
        token_positions_are_strictly_increasing(run->selected_token_ids) &&
        hidden_values_finite;
    // The recomputed and exported float hashes remain observable, but
    // numerical reordering is not an internal correctness rejection reason.
    (void)diagnostic_digest_computed;
    if (!run->correctness_pass) {
        *failure_stage = "resident_internal_frontier_handoff_contract";
        *failure =
            "resident internal frontier export had invalid token ids, hidden shape, or non-finite values";
        run->failure_stage = *failure_stage;
        run->failure = *failure;
    }
    return run->correctness_pass;
}

void capture_qwen36_prefix_checkpoint_hidden(
    const PrefillLinearAttentionDescriptorBatchRun &batch,
    size_t prefill_tokens
) {
    auto store = g_qwen36_resident_session.prefix_checkpoints;
    if (!qwen36_resident_session_capture_is_active() ||
        store == nullptr || store->failed) {
        return;
    }
    const auto &norm = batch.final_norm;
    constexpr size_t hidden_size = QRT_QWEN36_HIDDEN_SIZE;
    if (store->owner_tokens.size() != prefill_tokens ||
        !batch.final_norm_attempted || !norm.correctness_pass ||
        !batch.token_loop_validation_attempted ||
        !batch.token_loop_validation.correctness_pass ||
        !batch.token_loop_validation.first_generated_token_valid ||
        norm.selected_token_count != norm.selected_token_ids.size() ||
        norm.gpu_output.size() != norm.selected_token_count * hidden_size) {
        store->failed = true;
        return;
    }
    for (size_t i = 0u; i < store->count; ++i) {
        auto &checkpoint = store->checkpoints[i];
        const auto row_it = std::find(
            norm.selected_token_ids.begin(), norm.selected_token_ids.end(),
            static_cast<unsigned int>(checkpoint.prefix_tokens - 1u)
        );
        if (row_it == norm.selected_token_ids.end()) {
            store->failed = true;
            return;
        }
        const size_t offset = static_cast<size_t>(
            row_it - norm.selected_token_ids.begin()
        ) * hidden_size;
        for (size_t h = 0u; h < hidden_size; ++h) {
            const float value = norm.gpu_output[offset + h];
            if (!std::isfinite(value)) {
                store->failed = true;
                return;
            }
            checkpoint.terminal_hidden[h] = value;
        }
        checkpoint.hidden_valid = true;
    }
}

bool capture_qwen36_prefill_mtp_target_hidden_if_requested(
    const PrefillLinearAttentionDescriptorBatchRun &batch,
    size_t prefill_tokens,
    std::string *failure_stage,
    std::string *failure
) {
    if (!env_flag_enabled(
            "QRT_QWEN36_Q2_MTP_PREFILL_TARGET_HIDDEN_CAPTURE"
        )) {
        return true;
    }
    const unsigned int selected_position = env_u32_or_default(
        "QRT_QWEN36_Q2_TARGET_VERIFY_POSITION",
        UINT_MAX
    );
    constexpr size_t kHidden =
        static_cast<size_t>(QRT_QWEN36_HIDDEN_SIZE);
    const size_t missing_terminal_row =
        (std::numeric_limits<size_t>::max)();
    size_t terminal_row = missing_terminal_row;
    if (prefill_tokens != 0u) {
        const auto terminal_it = std::find(
            batch.final_norm.selected_token_ids.begin(),
            batch.final_norm.selected_token_ids.end(),
            static_cast<unsigned int>(prefill_tokens - 1u)
        );
        if (terminal_it != batch.final_norm.selected_token_ids.end()) {
            terminal_row = static_cast<size_t>(
                std::distance(
                    batch.final_norm.selected_token_ids.begin(),
                    terminal_it
                )
            );
        }
    }
    const bool token_valid =
        batch.token_loop_validation_attempted &&
        batch.token_loop_validation.correctness_pass &&
        batch.token_loop_validation.first_generated_token_valid &&
        batch.token_loop_validation.gpu_first_generated_token_id <
            QRT_QWEN36_VOCAB_SIZE;
    const bool hidden_valid =
        batch.final_norm_attempted &&
        batch.final_norm.correctness_pass &&
        batch.final_norm.selected_token_count != 0u &&
        batch.final_norm.selected_token_ids.size() ==
            batch.final_norm.selected_token_count &&
        terminal_row < batch.final_norm.selected_token_count &&
        batch.final_norm.gpu_output.size() ==
            batch.final_norm.selected_token_count * kHidden;
    const bool session_valid =
        g_qwen36_resident_session_capture_active &&
        g_qwen36_resident_session.requested &&
        g_qwen36_resident_session.route_active &&
        g_qwen36_resident_session.prefix_tokens == prefill_tokens;
    if (!env_flag_enabled(
            "QRT_QWEN36_Q2_MTP_DYNAMIC_SCHEDULE_PROBE"
        ) ||
        selected_position == UINT_MAX ||
        static_cast<size_t>(selected_position) != prefill_tokens ||
        !token_valid || !hidden_valid || !session_valid ||
        failure_stage == nullptr || failure == nullptr) {
        std::cerr
            << "BATCH_MARK qwen36_mtp_prefill_target_hidden_capture"
            << " pass=0"
            << " prefill_tokens=" << prefill_tokens
            << " selected_position=" << selected_position
            << " dynamic_schedule="
            << (env_flag_enabled(
                    "QRT_QWEN36_Q2_MTP_DYNAMIC_SCHEDULE_PROBE"
                )
                    ? 1
                    : 0)
            << " token_valid=" << (token_valid ? 1 : 0)
            << " final_norm_attempted="
            << (batch.final_norm_attempted ? 1 : 0)
            << " final_norm_correctness_pass="
            << (batch.final_norm.correctness_pass ? 1 : 0)
            << " selected_token_count="
            << batch.final_norm.selected_token_count
            << " selected_token_ids="
            << batch.final_norm.selected_token_ids.size()
            << " terminal_row=" << terminal_row
            << " gpu_output_elements="
            << batch.final_norm.gpu_output.size()
            << " session_capture_active="
            << (g_qwen36_resident_session_capture_active ? 1 : 0)
            << " session_requested="
            << (g_qwen36_resident_session.requested ? 1 : 0)
            << " session_route_active="
            << (g_qwen36_resident_session.route_active ? 1 : 0)
            << " session_prefix_tokens="
            << g_qwen36_resident_session.prefix_tokens
            << " diagnostic_only=1 numerical_correctness_claimed=0"
            << std::endl;
        if (failure_stage != nullptr) {
            *failure_stage =
                "qwen36_mtp_prefill_target_hidden_capture_contract";
        }
        if (failure != nullptr) {
            *failure =
                "prefill MTP target-hidden capture requires the first dynamic target position, a terminal post-final-norm row, its sampled token, and an active resident session";
        }
        return false;
    }

    const size_t terminal_hidden_offset = terminal_row * kHidden;
    for (size_t hidden = 0u; hidden < kHidden; ++hidden) {
        g_qwen36_resident_session.mtp_target_hidden_bf16[hidden] =
            qrt_float_to_bf16(
                batch.final_norm.gpu_output[
                    terminal_hidden_offset + hidden
                ]
            );
    }
    const uint32_t output_token_id =
        batch.token_loop_validation.gpu_first_generated_token_id;
    g_qwen36_resident_session.mtp_target_hidden_position =
        prefill_tokens - 1u;
    g_qwen36_resident_session.mtp_target_hidden_output_token_id =
        output_token_id;
    g_qwen36_resident_session.mtp_target_hidden_valid = true;
    g_qwen36_resident_session.mtp_target_hidden_device_only = false;
    const uint64_t hidden_hash = qrt_fnv1a64_bytes(
        g_qwen36_resident_session.mtp_target_hidden_bf16.data(),
        g_qwen36_resident_session.mtp_target_hidden_bf16.size() *
            sizeof(
                g_qwen36_resident_session.mtp_target_hidden_bf16[0u]
            )
    );
    std::cerr
        << "BATCH_MARK qwen36_mtp_prefill_target_hidden_capture"
        << " pass=1"
        << " position=" << (prefill_tokens - 1u)
        << " first_mtp_position=" << prefill_tokens
        << " output_token=" << output_token_id
        << " selected_token_count="
        << batch.final_norm.selected_token_count
        << " terminal_row=" << terminal_row
        << " bytes=" << (kHidden * sizeof(uint16_t))
        << " hidden_fnv1a64=" << hex_u64(hidden_hash)
        << " source=prefill_terminal_post_final_norm_bf16"
        << " rounding=rne"
        << " capture_mode=q2_first_post_prefill_frontier"
        << " host_materialization=1"
        << " diagnostic_only=1 numerical_correctness_claimed=0"
        << std::endl;
    return true;
}

static qrt_status_t resident_internal_frontier_continuation_callback(
    const qrt_qwen36_layer1_frontier_buffer_export_t *frontier,
    void *user_data,
    qrt_qwen36_layer1_frontier_continuation_result_t *out_result
) {
    ResidentInternalContinuationContext *context =
        static_cast<ResidentInternalContinuationContext *>(user_data);
    uint64_t frontier_digest = UINT64_C(0);
    uint64_t frontier_last = UINT64_C(0);
    uint64_t continuation_digest = UINT64_C(1469598103934665603);
    if (out_result != nullptr) {
        *out_result = qrt_qwen36_layer1_frontier_continuation_result_t{};
    }
    if (context == nullptr || context->post_attention_rmsnorm_run == nullptr ||
        context->moe_router_run == nullptr ||
        context->residual_hidden_run == nullptr ||
        context->layer0_source_stage_runs == nullptr ||
        context->model_dir == nullptr || context->batch_run == nullptr) {
        return QRT_STATUS_INVALID_ARGUMENT;
    }

    context->attempted = true;
    const uint64_t start_ns = qrt_now_ns();
    context->status = QRT_STATUS_UNSUPPORTED;
    context->frontier_handoff_ok =
        build_frontier_output_residual_from_export(
            frontier,
            &context->frontier_output_residual,
            &frontier_digest,
            &frontier_last,
            &context->failure_stage,
            &context->failure
        );
    if (!context->frontier_handoff_ok) {
        context->wall_clock_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
        return context->status;
    }

    const std::vector<unsigned int> layer39_q1_final_target_tokens =
        env_flag_enabled(
            "QRT_PREFILL_DESCRIPTOR_BATCH_LAYER39_Q1_KV8192"
        ) &&
                qwen36_layer39_q1_kv8192_target_plan_shape_enabled(
                    context->prefill_tokens
                )
            ? std::vector<unsigned int>{
                  context->prefill_tokens - 1u
              }
            : std::vector<unsigned int>{};
    const std::vector<unsigned int> *final_target_tokens =
        !context->final_target_tokens.empty()
            ? &context->final_target_tokens
            : (layer39_q1_final_target_tokens.empty()
                   ? nullptr
                   : &layer39_q1_final_target_tokens);
    const bool batch_ok = run_prefill_linear_attention_descriptor_batch_probe(
        context->frontier_output_residual,
        *context->post_attention_rmsnorm_run,
        *context->moe_router_run,
        *context->residual_hidden_run,
        context->layer0_source_stage_runs,
        *context->model_dir,
        context->prefill_tokens,
        context->real_prompt_input_surface,
        true,
        context->batch_run,
        context->real_prompt_fixture,
        final_target_tokens
    );
    context->wall_clock_ns = qrt_elapsed_ns(start_ns, qrt_now_ns());
    if (!batch_ok) {
        context->failure_stage = context->batch_run->failure_stage;
        context->failure = context->batch_run->failure;
        context->status = QRT_STATUS_UNSUPPORTED;
        return context->status;
    }
    continuation_digest = qrt_fnv1a64_update_bytes(
        continuation_digest,
        &frontier_digest,
        sizeof(frontier_digest)
    );
    continuation_digest = qrt_fnv1a64_update_bytes(
        continuation_digest,
        &frontier_last,
        sizeof(frontier_last)
    );
    continuation_digest = qrt_fnv1a64_update_bytes(
        continuation_digest,
        &context->batch_run->lm_head.gpu_logits_hash,
        sizeof(context->batch_run->lm_head.gpu_logits_hash)
    );
    continuation_digest = qrt_fnv1a64_update_bytes(
        continuation_digest,
        &context->batch_run->sampler.gpu_sampler_hash,
        sizeof(context->batch_run->sampler.gpu_sampler_hash)
    );
    continuation_digest = qrt_fnv1a64_update_bytes(
        continuation_digest,
        &context->batch_run->token_loop_validation.gpu_loop_digest,
        sizeof(context->batch_run->token_loop_validation.gpu_loop_digest)
    );
    context->digest_fnv1a64 = continuation_digest;
    context->completed = true;
    context->status = QRT_STATUS_OK;
    if (out_result != nullptr) {
        out_result->digest_fnv1a64 = continuation_digest;
        out_result->output_token_emitted =
            context->batch_run->token_loop_validation.first_generated_token_valid
                ? 1u
                : 0u;
        out_result->output_token_id =
            context->batch_run->token_loop_validation.gpu_first_generated_token_id;
        out_result->output_logit =
            context->batch_run->token_loop_validation.gpu_first_generated_logit;
        out_result->lm_head_logits_fnv1a64 =
            context->batch_run->lm_head.gpu_logits_hash;
        out_result->sampler_fnv1a64 =
            context->batch_run->sampler.gpu_sampler_hash;
        out_result->token_loop_digest_fnv1a64 =
            context->batch_run->token_loop_validation.gpu_loop_digest;
    }
    return QRT_STATUS_OK;
}

void copy_descriptor_result_string(char *dst, size_t capacity, const std::string &src) {
    if (dst == nullptr || capacity == 0u) {
        return;
    }
    const size_t copy_count = (std::min)(capacity - 1u, src.size());
    for (size_t index = 0u; index < copy_count; ++index) {
        dst[index] = src[index];
    }
    dst[copy_count] = '\0';
}

