void print_repeated_layer_digest_rows_json(
    const PrefillLinearAttentionBatchLayerRun &layer,
    bool *first
) {
    const RepeatedPrefillLayerHelperRun &run = layer.helper;
    auto row = [&](const std::string &name,
                   const std::string &stage,
                   size_t materialized_count,
                   unsigned int checked_values,
                   float max_abs_diff,
                   uint64_t selected_reference_hash,
                   uint64_t selected_gpu_hash,
                   uint64_t output_hash,
                   double avg_ms,
                   bool correctness_pass,
                   const std::string &failure_stage,
                   const std::string &failure,
                   const std::vector<SampleDiff> *samples = nullptr,
                   float tolerance = kTolerance) {
        if (!*first) {
            std::cout << ",\n";
        }
        *first = false;
        print_compact_digest_row_json(
            layer.layer_index,
            layer.block_kind,
            name,
            stage,
            materialized_count,
            checked_values,
            max_abs_diff,
            selected_reference_hash,
            selected_gpu_hash,
            output_hash,
            avg_ms,
            correctness_pass,
            failure_stage,
            failure,
            0.0,
            0.0,
            0.0f,
            0.0f,
            samples,
            tolerance
        );
    };

    row(run.input_rmsnorm.name, run.input_rmsnorm.stage,
        run.input_rmsnorm.selected_token_count, run.input_rmsnorm.checked_values,
        run.input_rmsnorm.max_abs_diff, run.input_rmsnorm.selected_reference_hash,
        run.input_rmsnorm.selected_gpu_hash, run.input_rmsnorm.gpu_output_hash,
        run.input_rmsnorm.avg_ms, run.input_rmsnorm.correctness_pass,
        run.input_rmsnorm.failure_stage, run.input_rmsnorm.failure);
    row(run.qkv_projection.name, run.qkv_projection.stage,
        run.qkv_projection.selected_token_count, run.qkv_projection.checked_values,
        run.qkv_projection.max_abs_diff, run.qkv_projection.selected_reference_hash,
        run.qkv_projection.selected_gpu_hash, run.qkv_projection.gpu_output_hash,
        run.qkv_projection.avg_ms, run.qkv_projection.correctness_pass,
        run.qkv_projection.failure_stage, run.qkv_projection.failure,
        &run.qkv_projection.samples, kSelectedProjectionTolerance);
    row(run.z_projection.name, run.z_projection.stage,
        run.z_projection.selected_token_count, run.z_projection.checked_values,
        run.z_projection.max_abs_diff, run.z_projection.selected_reference_hash,
        run.z_projection.selected_gpu_hash, run.z_projection.gpu_output_hash,
        run.z_projection.avg_ms, run.z_projection.correctness_pass,
        run.z_projection.failure_stage, run.z_projection.failure,
        &run.z_projection.samples, kSelectedProjectionTolerance);
    row(run.a_projection.name, run.a_projection.stage,
        run.a_projection.selected_token_count, run.a_projection.checked_values,
        run.a_projection.max_abs_diff, run.a_projection.selected_reference_hash,
        run.a_projection.selected_gpu_hash, run.a_projection.gpu_output_hash,
        run.a_projection.avg_ms, run.a_projection.correctness_pass,
        run.a_projection.failure_stage, run.a_projection.failure,
        &run.a_projection.samples, kSelectedProjectionTolerance);
    row(run.b_projection.name, run.b_projection.stage,
        run.b_projection.selected_token_count, run.b_projection.checked_values,
        run.b_projection.max_abs_diff, run.b_projection.selected_reference_hash,
        run.b_projection.selected_gpu_hash, run.b_projection.gpu_output_hash,
        run.b_projection.avg_ms, run.b_projection.correctness_pass,
        run.b_projection.failure_stage, run.b_projection.failure,
        &run.b_projection.samples, kSelectedProjectionTolerance);
    row(run.window_previous_output_residual.name,
        layer.window_previous_override_used
            ? run.window_previous_output_residual.stage + "_override"
            : run.window_previous_output_residual.stage,
        run.window_previous_output_residual.selected_token_count,
        run.window_previous_output_residual.checked_values,
        run.window_previous_output_residual.max_abs_diff,
        run.window_previous_output_residual.selected_reference_hash,
        run.window_previous_output_residual.selected_gpu_hash,
        run.window_previous_output_residual.gpu_output_hash,
        run.window_previous_materialization_avg_ms,
        run.window_previous_output_residual.correctness_pass,
        run.window_previous_output_residual.failure_stage,
        run.window_previous_output_residual.failure);
    row(run.window_input_rmsnorm.name, run.window_input_rmsnorm.stage,
        run.window_input_rmsnorm.selected_token_count, run.window_input_rmsnorm.checked_values,
        run.window_input_rmsnorm.max_abs_diff, run.window_input_rmsnorm.selected_reference_hash,
        run.window_input_rmsnorm.selected_gpu_hash, run.window_input_rmsnorm.gpu_output_hash,
        run.window_input_rmsnorm.avg_ms, run.window_input_rmsnorm.correctness_pass,
        run.window_input_rmsnorm.failure_stage, run.window_input_rmsnorm.failure);
    row(run.window_qkv_projection.name, run.window_qkv_projection.stage,
        run.window_qkv_projection.selected_token_count, run.window_qkv_projection.checked_values,
        run.window_qkv_projection.max_abs_diff, run.window_qkv_projection.selected_reference_hash,
        run.window_qkv_projection.selected_gpu_hash, run.window_qkv_projection.gpu_output_hash,
        run.window_qkv_projection.avg_ms, run.window_qkv_projection.correctness_pass,
        run.window_qkv_projection.failure_stage, run.window_qkv_projection.failure,
        &run.window_qkv_projection.samples, kSelectedProjectionTolerance);
    row(run.conv_window.name, run.conv_window.stage,
        run.conv_window.target_token_count, run.conv_window.checked_values,
        run.conv_window.max_abs_diff, run.conv_window.selected_reference_hash,
        run.conv_window.selected_gpu_hash, run.conv_window.gpu_output_hash,
        run.conv_window.phase_total_avg_ms, run.conv_window.correctness_pass,
        run.conv_window.failure_stage, run.conv_window.failure);
    row(run.postconv_window.name, run.postconv_window.stage,
        run.postconv_window.target_token_count, run.postconv_window.checked_values,
        run.postconv_window.max_abs_diff, run.postconv_window.selected_reference_hash,
        run.postconv_window.selected_gpu_hash, run.postconv_window.gpu_output_hash,
        run.postconv_window.avg_ms, run.postconv_window.correctness_pass,
        run.postconv_window.failure_stage, run.postconv_window.failure);
    row(run.gate_window.name, run.gate_window.stage,
        run.gate_window.target_token_count, run.gate_window.checked_values,
        run.gate_window.max_abs_diff, run.gate_window.selected_reference_hash,
        run.gate_window.selected_gpu_hash, run.gate_window.gpu_output_hash,
        run.gate_window.avg_ms, run.gate_window.correctness_pass,
        run.gate_window.failure_stage, run.gate_window.failure);
    row(run.core_window.name, run.core_window.stage,
        run.core_window.target_token_count, run.core_window.checked_values,
        run.core_window.max_abs_diff, run.core_window.selected_reference_hash,
        run.core_window.selected_gpu_hash, run.core_window.gpu_output_hash,
        run.core_window.avg_ms, run.core_window.correctness_pass,
        run.core_window.failure_stage, run.core_window.failure);
    row(run.gated_rmsnorm_window.name, run.gated_rmsnorm_window.stage,
        run.gated_rmsnorm_window.target_token_count, run.gated_rmsnorm_window.checked_values,
        run.gated_rmsnorm_window.max_abs_diff, run.gated_rmsnorm_window.selected_reference_hash,
        run.gated_rmsnorm_window.selected_gpu_hash, run.gated_rmsnorm_window.gpu_output_hash,
        run.gated_rmsnorm_window.avg_ms, run.gated_rmsnorm_window.correctness_pass,
        run.gated_rmsnorm_window.failure_stage, run.gated_rmsnorm_window.failure);
    row(run.out_projection_window.name, run.out_projection_window.stage,
        run.out_projection_window.target_token_count, run.out_projection_window.checked_values,
        run.out_projection_window.max_abs_diff, run.out_projection_window.selected_reference_hash,
        run.out_projection_window.selected_gpu_hash, run.out_projection_window.gpu_output_hash,
        run.out_projection_window.avg_ms, run.out_projection_window.correctness_pass,
        run.out_projection_window.failure_stage, run.out_projection_window.failure);
    row(run.residual_hidden_window.name, run.residual_hidden_window.stage,
        run.residual_hidden_window.target_token_count, run.residual_hidden_window.checked_values,
        run.residual_hidden_window.max_abs_diff, run.residual_hidden_window.selected_reference_hash,
        run.residual_hidden_window.selected_gpu_hash, run.residual_hidden_window.gpu_output_hash,
        run.residual_hidden_window.avg_ms, run.residual_hidden_window.correctness_pass,
        run.residual_hidden_window.failure_stage, run.residual_hidden_window.failure);
    row(run.post_attention_rmsnorm_window.name, run.post_attention_rmsnorm_window.stage,
        run.post_attention_rmsnorm_window.target_token_count,
        run.post_attention_rmsnorm_window.checked_values,
        run.post_attention_rmsnorm_window.max_abs_diff,
        run.post_attention_rmsnorm_window.selected_reference_hash,
        run.post_attention_rmsnorm_window.selected_gpu_hash,
        run.post_attention_rmsnorm_window.gpu_output_hash,
        run.post_attention_rmsnorm_window.avg_ms,
        run.post_attention_rmsnorm_window.correctness_pass,
        run.post_attention_rmsnorm_window.failure_stage,
        run.post_attention_rmsnorm_window.failure);
    const float moe_router_max_abs_diff =
        run.moe_router_window.max_logit_abs_diff >
                run.moe_router_window.max_topk_weight_abs_diff
            ? run.moe_router_window.max_logit_abs_diff
            : run.moe_router_window.max_topk_weight_abs_diff;
    row(run.moe_router_window.name, run.moe_router_window.stage,
        run.moe_router_window.target_token_count,
        run.moe_router_window.checked_logit_values + run.moe_router_window.checked_topk_values,
        moe_router_max_abs_diff,
        run.moe_router_window.selected_logits_reference_hash,
        run.moe_router_window.selected_logits_gpu_hash,
        run.moe_router_window.gpu_logits_hash,
        run.moe_router_window.avg_ms,
        run.moe_router_window.correctness_pass,
        run.moe_router_window.failure_stage,
        run.moe_router_window.failure);
    if (!*first) {
        std::cout << ",\n";
    }
    *first = false;
    print_compact_digest_row_json(
        layer.layer_index,
        layer.block_kind,
        run.routed_expert_window.name,
        run.routed_expert_window.stage,
        run.routed_expert_window.selected_token_count,
        run.routed_expert_window.checked_values,
        run.routed_expert_window.max_abs_diff,
        run.routed_expert_window.selected_reference_hash,
        run.routed_expert_window.selected_gpu_hash,
        run.routed_expert_window.gpu_output_hash,
        run.routed_expert_window.avg_ms,
        run.routed_expert_window.correctness_pass,
        run.routed_expert_window.failure_stage,
        run.routed_expert_window.failure,
        run.routed_expert_window.gate_up_avg_ms,
        run.routed_expert_window.down_avg_ms,
        run.routed_expert_window.gate_up_elapsed_ms,
        run.routed_expert_window.down_elapsed_ms
    );
    row(run.shared_expert_window.name, run.shared_expert_window.stage,
        run.shared_expert_window.selected_token_count,
        run.shared_expert_window.checked_combined_values,
        run.shared_expert_window.max_combined_abs_diff,
        run.shared_expert_window.selected_combined_reference_hash,
        run.shared_expert_window.selected_combined_gpu_hash,
        run.shared_expert_window.gpu_combined_output_hash,
        run.shared_expert_window.avg_ms,
        run.shared_expert_window.correctness_pass,
        run.shared_expert_window.failure_stage,
        run.shared_expert_window.failure);
    row(run.output_residual_window.name, run.output_residual_window.stage,
        run.output_residual_window.selected_token_count,
        run.output_residual_window.checked_values,
        run.output_residual_window.max_abs_diff,
        run.output_residual_window.selected_reference_hash,
        run.output_residual_window.selected_gpu_hash,
        run.output_residual_window.gpu_output_hash,
        run.output_residual_window.avg_ms,
        run.output_residual_window.correctness_pass,
        run.output_residual_window.failure_stage,
        run.output_residual_window.failure);
}

