void print_lm_head_digest_row_json(
    const LmHeadRun &run,
    bool *first
) {
    if (!*first) {
        std::cout << ",\n";
    }
    *first = false;
    const size_t checked_total = run.checked_values + run.checked_topk_values;
    const float max_abs_diff =
        run.max_abs_diff > run.max_topk_logit_abs_diff
            ? run.max_abs_diff
            : run.max_topk_logit_abs_diff;
    print_compact_digest_row_json(
        QRT_QWEN36_LAYER_COUNT,
        "output_head",
        run.name,
        run.stage,
        run.selected_token_count,
        static_cast<unsigned int>(checked_total),
        max_abs_diff,
        run.selected_reference_hash,
        run.selected_gpu_hash,
        run.gpu_logits_hash,
        run.avg_ms,
        run.correctness_pass,
        run.failure_stage,
        run.failure,
        0.0,
        0.0,
        0.0f,
        0.0f,
        &run.logit_samples,
        kSelectedProjectionTolerance
    );
}

