void print_full_attention_layer_digest_rows_json(
    const PrefillFullAttentionBatchLayerRun &layer,
    bool *first
) {
    const PrefillFullAttentionBatchLayerRun &run = layer;
    auto row = [&](const std::string &name,
                   const std::string &stage,
                   size_t materialized_count,
                   unsigned int checked_values,
                   float max_abs_diff,
                   uint64_t selected_reference_hash,
                   uint64_t selected_gpu_hash,
                   uint64_t output_hash,
                   double avg_ms,
                   bool correctness_pass,
                   const std::string &failure_stage,
                   const std::string &failure,
                   const std::vector<SampleDiff> *samples = nullptr,
                   float tolerance = kTolerance) {
        if (!*first) {
            std::cout << ",\n";
        }
        *first = false;
        print_compact_digest_row_json(
            layer.layer_index,
            layer.block_kind,
            name,
            stage,
            materialized_count,
            checked_values,
            max_abs_diff,
            selected_reference_hash,
            selected_gpu_hash,
            output_hash,
            avg_ms,
            correctness_pass,
            failure_stage,
            failure,
            0.0,
            0.0,
            0.0f,
            0.0f,
            samples,
            tolerance
        );
    };

    row(run.input_rmsnorm.name, run.input_rmsnorm.stage,
        run.input_rmsnorm.selected_token_count, run.input_rmsnorm.checked_values,
        run.input_rmsnorm.max_abs_diff, run.input_rmsnorm.selected_reference_hash,
        run.input_rmsnorm.selected_gpu_hash, run.input_rmsnorm.gpu_output_hash,
        run.input_rmsnorm.avg_ms, run.input_rmsnorm.correctness_pass,
        run.input_rmsnorm.failure_stage, run.input_rmsnorm.failure);
    row(run.qkv_projection.name, run.qkv_projection.stage,
        run.qkv_projection.selected_token_count, run.qkv_projection.checked_values,
        run.qkv_projection.max_abs_diff, run.qkv_projection.selected_reference_hash,
        run.qkv_projection.selected_gpu_hash, run.qkv_projection.gpu_output_hash,
        run.qkv_projection.avg_ms, run.qkv_projection.correctness_pass,
        run.qkv_projection.failure_stage, run.qkv_projection.failure,
        &run.qkv_projection.samples, kSelectedProjectionTolerance);
    row(run.qk_norm.name, run.qk_norm.stage,
        run.qk_norm.selected_token_count, run.qk_norm.checked_values,
        run.qk_norm.max_abs_diff, run.qk_norm.selected_reference_hash,
        run.qk_norm.selected_gpu_hash, run.qk_norm.gpu_output_hash,
        run.qk_norm.avg_ms, run.qk_norm.correctness_pass,
        run.qk_norm.failure_stage, run.qk_norm.failure);
    row(run.rope.name, run.rope.stage,
        run.rope.selected_token_count, run.rope.checked_values,
        run.rope.max_abs_diff, run.rope.selected_reference_hash,
        run.rope.selected_gpu_hash, run.rope.gpu_output_hash,
        run.rope.avg_ms, run.rope.correctness_pass,
        run.rope.failure_stage, run.rope.failure);
    row(run.score_value.name, run.score_value.stage,
        run.score_value.selected_token_count, run.score_value.checked_values,
        run.score_value.max_abs_diff, run.score_value.selected_reference_hash,
        run.score_value.selected_gpu_hash, run.score_value.gpu_output_hash,
        run.score_value.avg_ms, run.score_value.correctness_pass,
        run.score_value.failure_stage, run.score_value.failure);
    row(run.output_projection.name, run.output_projection.stage,
        run.output_projection.selected_token_count, run.output_projection.checked_values,
        run.output_projection.max_abs_diff, run.output_projection.selected_reference_hash,
        run.output_projection.selected_gpu_hash, run.output_projection.gpu_output_hash,
        run.output_projection.avg_ms, run.output_projection.correctness_pass,
        run.output_projection.failure_stage, run.output_projection.failure);
    row(run.residual_hidden.name, run.residual_hidden.stage,
        run.residual_hidden.target_token_count, run.residual_hidden.checked_values,
        run.residual_hidden.max_abs_diff, run.residual_hidden.selected_reference_hash,
        run.residual_hidden.selected_gpu_hash, run.residual_hidden.gpu_output_hash,
        run.residual_hidden.avg_ms, run.residual_hidden.correctness_pass,
        run.residual_hidden.failure_stage, run.residual_hidden.failure);
    row(run.post_attention_rmsnorm.name, run.post_attention_rmsnorm.stage,
        run.post_attention_rmsnorm.target_token_count,
        run.post_attention_rmsnorm.checked_values,
        run.post_attention_rmsnorm.max_abs_diff,
        run.post_attention_rmsnorm.selected_reference_hash,
        run.post_attention_rmsnorm.selected_gpu_hash,
        run.post_attention_rmsnorm.gpu_output_hash,
        run.post_attention_rmsnorm.avg_ms,
        run.post_attention_rmsnorm.correctness_pass,
        run.post_attention_rmsnorm.failure_stage,
        run.post_attention_rmsnorm.failure);
    const float moe_router_max_abs_diff =
        run.moe_router.max_logit_abs_diff >
                run.moe_router.max_topk_weight_abs_diff
            ? run.moe_router.max_logit_abs_diff
            : run.moe_router.max_topk_weight_abs_diff;
    row(run.moe_router.name, run.moe_router.stage,
        run.moe_router.target_token_count,
        run.moe_router.checked_logit_values + run.moe_router.checked_topk_values,
        moe_router_max_abs_diff,
        run.moe_router.selected_logits_reference_hash,
        run.moe_router.selected_logits_gpu_hash,
        run.moe_router.gpu_logits_hash,
        run.moe_router.avg_ms,
        run.moe_router.correctness_pass,
        run.moe_router.failure_stage,
        run.moe_router.failure);
    if (!*first) {
        std::cout << ",\n";
    }
    *first = false;
    print_compact_digest_row_json(
        layer.layer_index,
        layer.block_kind,
        run.routed_expert.name,
        run.routed_expert.stage,
        run.routed_expert.selected_token_count,
        run.routed_expert.checked_values,
        run.routed_expert.max_abs_diff,
        run.routed_expert.selected_reference_hash,
        run.routed_expert.selected_gpu_hash,
        run.routed_expert.gpu_output_hash,
        run.routed_expert.avg_ms,
        run.routed_expert.correctness_pass,
        run.routed_expert.failure_stage,
        run.routed_expert.failure,
        run.routed_expert.gate_up_avg_ms,
        run.routed_expert.down_avg_ms,
        run.routed_expert.gate_up_elapsed_ms,
        run.routed_expert.down_elapsed_ms
    );
    row(run.shared_expert.name, run.shared_expert.stage,
        run.shared_expert.selected_token_count,
        run.shared_expert.checked_combined_values,
        run.shared_expert.max_combined_abs_diff,
        run.shared_expert.selected_combined_reference_hash,
        run.shared_expert.selected_combined_gpu_hash,
        run.shared_expert.gpu_combined_output_hash,
        run.shared_expert.avg_ms,
        run.shared_expert.correctness_pass,
        run.shared_expert.failure_stage,
        run.shared_expert.failure);
    row(run.output_residual.name, run.output_residual.stage,
        run.output_residual.selected_token_count,
        run.output_residual.checked_values,
        run.output_residual.max_abs_diff,
        run.output_residual.selected_reference_hash,
        run.output_residual.selected_gpu_hash,
        run.output_residual.gpu_output_hash,
        run.output_residual.avg_ms,
        run.output_residual.correctness_pass,
        run.output_residual.failure_stage,
        run.output_residual.failure);
}

void print_layer_stack_wall_clock_buckets_json(
    const LayerStackWallClockBuckets &buckets,
    const char *item_indent
) {
    for (size_t index = 0; index < kLayerStackWallBucketCount; ++index) {
        const LayerStackWallBucket bucket =
            static_cast<LayerStackWallBucket>(index);
        const double wall_clock_ms =
            static_cast<double>(buckets.elapsed_ns[index]) / 1000000.0;
        std::cout << item_indent
                  << "{ \"name\": \"" << layer_stack_wall_bucket_name(bucket)
                  << "\", \"wall_clock_ms\": " << wall_clock_ms
                  << ", \"call_count\": " << buckets.call_count[index]
                  << ", \"host_materialized_output_bytes\": "
                  << buckets.host_materialized_output_bytes[index]
                  << ", \"host_materialized_stage_count\": "
                  << buckets.host_materialized_stage_count[index]
                  << " }";
        if (index + 1u < kLayerStackWallBucketCount) {
            std::cout << ",";
        }
        std::cout << "\n";
    }
}

uint64_t layer_stack_bucket_elapsed_ns(
    const LayerStackWallClockBuckets &buckets,
    LayerStackWallBucket bucket
) {
    if (bucket == LayerStackWallBucket::kCount) {
        return UINT64_C(0);
    }
    return buckets.elapsed_ns[static_cast<size_t>(bucket)];
}

unsigned int layer_stack_bucket_call_count(
    const LayerStackWallClockBuckets &buckets,
    LayerStackWallBucket bucket
) {
    if (bucket == LayerStackWallBucket::kCount) {
        return 0u;
    }
    return buckets.call_count[static_cast<size_t>(bucket)];
}

LayerStackWallBucket dominant_layer_stack_wall_bucket(
    const LayerStackWallClockBuckets &buckets
) {
    LayerStackWallBucket dominant = LayerStackWallBucket::kCount;
    uint64_t dominant_ns = UINT64_C(0);
    for (size_t index = 0u; index < kLayerStackWallBucketCount; ++index) {
        if (buckets.elapsed_ns[index] > dominant_ns) {
            dominant_ns = buckets.elapsed_ns[index];
            dominant = static_cast<LayerStackWallBucket>(index);
        }
    }
    return dominant;
}

double ns_to_ms(uint64_t elapsed_ns) {
    return static_cast<double>(elapsed_ns) / 1000000.0;
}

void print_routed_expert_gpu_output_layer_diagnostics_json(
    const RoutedExpertGpuOutputContractSummary &summary,
    const char *item_indent
) {
    bool printed = false;
    for (size_t layer_index = 0u; layer_index < QRT_QWEN36_LAYER_COUNT;
         ++layer_index) {
        if (summary.layer_checked_value_count[layer_index] == 0u) {
            continue;
        }
        if (printed) {
            std::cout << ",\n";
        }
        printed = true;
        std::cout << item_indent
                  << "{ \"layer_index\": " << layer_index
                  << ", \"checked_value_count\": "
                  << summary.layer_checked_value_count[layer_index]
                  << ", \"mismatch_count\": "
                  << summary.layer_mismatch_count[layer_index]
                  << ", \"first_diff_element_index\": "
                  << summary.layer_first_diff_element_index[layer_index]
                  << ", \"first_diff_token_id\": "
                  << summary.layer_first_diff_token_id[layer_index]
                  << ", \"first_diff_hidden_index\": "
                  << summary.layer_first_diff_hidden_index[layer_index]
                  << ", \"first_diff_cpu_bits\": \""
                  << hex_u32(summary.layer_first_diff_cpu_bits[layer_index])
                  << "\", \"first_diff_gpu_bits\": \""
                  << hex_u32(summary.layer_first_diff_gpu_bits[layer_index])
                  << "\", \"first_diff_ulp_distance\": "
                  << summary.layer_first_diff_ulp_distance[layer_index]
                  << ", \"max_ulp_distance\": "
                  << summary.layer_max_ulp_distance[layer_index]
                  << ", \"ulp_buckets\": { ";
        for (size_t bucket_index = 0u;
             bucket_index < QRT_QWEN36_ROUTED_OUTPUT_ULP_BUCKET_COUNT;
             ++bucket_index) {
            if (bucket_index != 0u) {
                std::cout << ", ";
            }
            std::cout << "\"" << routed_output_ulp_bucket_name(bucket_index)
                      << "\": "
                      << summary.layer_ulp_bucket_counts[
                             layer_index *
                                 QRT_QWEN36_ROUTED_OUTPUT_ULP_BUCKET_COUNT +
                             bucket_index
                         ];
        }
        std::cout << " } }";
    }
    if (printed) {
        std::cout << "\n";
    }
}

