    uint64_t input_surface_digest_fnv1a64 = 0u;
    uint64_t token_embedding_digest_fnv1a64 = 0u;
    uint64_t cache_payload_digest_fnv1a64 = 0u;
    uint64_t output_tokens_hash = 0u;
    size_t emitted_output_count = 0u;
    size_t remaining_output_count = 0u;
    size_t decode_position = 0u;
    size_t cache_token_count = 0u;
