    size_t planned_decode_token_count = 0u;
    unsigned int first_layer_index = 0u;
    unsigned int last_layer_index = 0u;
    uint64_t context_digest_fnv1a64 = 0u;
    uint64_t digest_fnv1a64 = 0u;
