    DescriptorDecodeAutoregressiveLoopRun output_head_step;
    size_t previous_output_count = 0u;
    size_t previous_decode_count = 0u;
    size_t previous_position = 0u;
    size_t next_position = 0u;
    size_t next_cache_token_count = 0u;
    uint32_t sampled_token_id = 0u;
    uint64_t next_output_tokens_hash = UINT64_C(0);
    uint64_t next_token_loop_digest = UINT64_C(0);
    uint64_t next_state_digest = UINT64_C(0);
    uint64_t next_cache_digest = UINT64_C(0);
    uint64_t next_token_embedding_hash = UINT64_C(0);
